local function lph_generic_for(t, state)
	if type(t) ~= "table" then
		return
	end
	local key = state
	while true do
		key = next(t, key)
		if key == nil then
			return
		end
		local entry = t[key]
		coroutine.yield(key, entry, entry)
	end
end
local function unpack(t, first, last)
	if type(t) ~= "table" then
		t = {}
	end
	return table.unpack(t, first, last)
end
