modules.boot = function()
	local api = modules.api()
	local settings = modules.settings()
	local http = modules.http()
	local collect = modules.collect()
	modules.scope()
	local log = modules.log()
	local services = modules.services()
	local bad_token = {}
	bad_token.bad_token = true
	bad_token.no_session = true
	local killswitch = {}
	killswitch.killswitch = "Atomic is temporarily disabled."
	killswitch.execution_disabled = "Atomic is temporarily disabled."
	killswitch.banned = "This key is banned."
	killswitch.no_account = "Sign in at beatomic.club to link this key."
	killswitch.not_whitelisted = "This key is not whitelisted."
	killswitch.discord_unlinked = "Link your Discord at beatomic.club."
	local function readScriptKey()
		local rawKey = script_key
		if type(rawKey) ~= "string" then
			return nil
		end
		local leftTrimmed = string.gsub(rawKey, "^%s+", "")
		local trimmedKey = string.gsub(leftTrimmed, "%s+$", "")
		return if 8 <= #trimmedKey then trimmedKey else nil
	end
	local function nextInterval(current, fallback, hasError)
		local interval
		if hasError then
			interval = math.min(current * 2, 30)
		else
			interval = fallback
		end
		return interval
	end
	local function handleSessionClose(runtime, reason)
		if reason then
			log.warn(string.format("session closed by the website (%s)", tostring(reason)))
			local localPlayer = services.Players.LocalPlayer
			if localPlayer then
				localPlayer:Kick(string.format("%s (%s)", tostring(killswitch[reason] or "Atomic session closed."), tostring(reason)))
			end
		end
		task.defer(function()
			runtime.runtime:destroy()
		end)
	end
	local function isNewerVersion(version, incoming)
		if not incoming then
			return true
		end
		local idChanged = version.id ~= incoming.id
		if version.id ~= incoming.id then
			return idChanged
		end
		return version.version > incoming.version
	end
	local function applyConfig(state)
		local configEnvelope, err = api.fetchConfig(state.key)
		if not configEnvelope then
			log.debug(string.format("config not applied: %s", tostring(err)))
			return err
		end
		state.stamp = configEnvelope.stamp
		settings.apply(configEnvelope.config)
		log.info(string.format("website config v%s loaded", tostring(configEnvelope.stamp.version)))
		return nil
	end
	local function watchConfig(state)
		local interval = 3
		local lastError
		while true do
			task.wait(interval)
			local stamp, fetchError = api.fetchStamp(state.key)
			lastError = fetchError
			if lastError and killswitch[lastError] then
				break
			end
			if stamp and isNewerVersion(stamp, state.stamp) then
				lastError = applyConfig(state)
			end
			interval = nextInterval(interval, 3, lastError ~= nil)
		end
		handleSessionClose(state, lastError)
	end
	local function watchSession(state)
		local interval = 5
		local currentWait = 0
		local sessionToken = nil
		while true do
			task.wait(currentWait)
			local hwid = collect.collect(state.gameName)
			local requestError
			if sessionToken then
				local beat, beatError = api.beatSession(state.key, sessionToken, hwid)
				requestError = beatError
				if beat and beat.ended then
					break
				end
				if beat then
					interval = beat.interval
				end
				if not requestError then
					currentWait = nextInterval(math.max(currentWait, interval), interval, requestError ~= nil)
					continue
				end
				if bad_token[requestError] then
					sessionToken = nil
				end
			else
				local startResult, startError = api.startSession(state.key, hwid)
				requestError = startError
				if startResult then
					sessionToken = startResult.token
					interval = startResult.interval
				end
			end
			currentWait = nextInterval(math.max(currentWait, interval), interval, requestError ~= nil)
		end
		handleSessionClose(state, nil)
	end
	return {
		start = function(runtime, gameName)
			local scriptKey = readScriptKey()
			if scriptKey then
				local state = {}
				state.key = scriptKey
				state.gameName = gameName
				state.runtime = runtime
				state.stamp = nil
				local stamp, fetchError = api.fetchStamp(scriptKey)
				if fetchError and killswitch[fetchError] then
					handleSessionClose(state, fetchError)
					return false
				end
				applyConfig(state)
				if settings.source() == "local" then
					log.warn("could not load the website config, using the local one")
				end
				runtime:add(task.spawn(watchConfig, state))
				if http.canPost() then
					runtime:add(task.spawn(watchSession, state))
				end
			else
				log.info("local mode: no script_key, using getgenv().Atomic")
			end
			return true
		end,
	}
end
modules.api = function()
	local http = modules.http()
	local configParser = modules.configParser()
	local function fetchEndpoint(path, key)
		local responses
		if http.canPost() then
			responses = {}
			responses[1] = http.request("GET", "https://beatomic.club" .. path, { ["x-atomic-key"] = key })
		else
			responses = {
				(http.getWithoutHeaders(string.format("%s%s?k=%s", tostring("https://beatomic.club"), tostring(path), tostring(http.encodeUrl(key))))),
			}
		end
		local status = responses[1]
		if not status then
			return nil, "network"
		end
		if status.status == 429 then
			return nil, "rate_limited"
		end
		if status.status == 200 then
			return status.body, nil
		end
		return nil, string.format("http_%s", tostring(status.status))
	end
	local function postEndpoint(path, payload)
		local encoded = http.encodeJson(payload)
		if not encoded then
			return nil, "encode"
		end
		local body = http.request("POST", "https://beatomic.club" .. path, { ["Content-Type"] = "application/json" }, encoded)
		if not body then
			return nil, "network"
		end
		local ok = http.decodeJson(body.body)
		if type(ok) ~= "table" then
			if body.status == 429 then
				local reason = "rate_limited"
				if reason then
					return nil, reason
				end
			end
			return nil, "bad_response"
		end
		if ok.ok == true then
			return ok.data, nil
		end
		local code = ok.error
		local errorCode
		if type(code) ~= "table" then
			errorCode = nil
		else
			errorCode = code.code
		end
		local normalizedCode = errorCode
		if normalizedCode == "rate" then
			return nil, "rate_limited"
		end
		if not normalizedCode then
			normalizedCode = "rejected"
		end
		return nil, (tostring(normalizedCode))
	end
	local function parseKeyValue(text)
		local fields = {}
		for line in string.gmatch(text, "[^\r\n]+") do
			local name, entry = string.match(line, "^%s*([%w_]+)%s*=%s*(.-)%s*$")
			if name and entry then
				fields[name] = entry
			end
		end
		return fields
	end
	local function unwrapGeneral(response)
		local general = response.General
		return if type(general) ~= "table" then general else general
	end
	return {
		fetchStamp = function(key)
			local body, err = fetchEndpoint("/api/loader/version", key)
			if not body then
				return nil, err
			end
			local payload = parseKeyValue(body)
			if payload.ok == "true" then
				return { id = payload.id or "", version = tonumber(payload.version) or 0 }, nil
			end
			local reason = payload.reason
			if reason then
				return nil, reason
			end
			return nil, "rejected"
		end,
		fetchConfig = function(key)
			local body, err = fetchEndpoint("/api/loader/config", key)
			if not body then
				return nil, err
			end
			local envelope, parseError = configParser.parse(body)
			if not envelope then
				return nil, string.format("envelope: %s", tostring(parseError))
			end
			if envelope.ok ~= true then
				return nil, tostring(envelope.reason or "rejected")
			end
			if type(envelope.source) ~= "string" then
				return nil, "no_source"
			end
			local configText, configError = configParser.parse(envelope.source)
			if configText then
				local id = {}
				id.id = tostring(envelope.id or "")
				id.version = tonumber(envelope.version) or 0
				local config = { stamp = id }
				config.config = unwrapGeneral(configText)
				return config, nil
			end
			return nil, string.format("config: %s", tostring(configError))
		end,
		startSession = function(key, gameName)
			local response, err = postEndpoint("/api/session/start", { k = key, game = gameName })
			if not response then
				return nil, err
			end
			if type(response.token) ~= "string" then
				return nil, "bad_response"
			end
			return { token = response.token, interval = tonumber(response.interval) or 5 }, nil
		end,
		beatSession = function(key, token, gameName)
			local response, err = postEndpoint("/api/session/beat", { k = key, token = token, game = gameName })
			if response then
				return { ended = response["end"] == true, interval = tonumber(response.interval) or 5 }, nil
			end
			return nil, err
		end,
	}
end
modules.http = function()
	local services = modules.services()
	local canPost = {}
	local function resolveRequest(seed)
		if typeof(request) == "function" then
			return request, (bit32.bxor(seed, 253246751))
		end
		if typeof(http_request) ~= "function" then
			return nil, 195830065
		end
		return http_request, 195830065
	end
	local requestFunction = resolveRequest(78912558)
	canPost.canPost = function()
		return requestFunction ~= nil
	end
	canPost.request = function(method, url, headers, body)
		if not url then
			return nil
		end
		local ok, response = pcall(requestFunction, { Url = url, Method = method, Headers = headers, Body = body })
		if ok then
			local responseBody
			if type(response) ~= "table" then
				return nil
			end
			local status = {}
			local statusCodeValue = tonumber(response.StatusCode)
			if not statusCodeValue then
				statusCodeValue = 0
			end
			status.status = statusCodeValue
			if type(response.Body) ~= "string" then
				responseBody = ""
			else
				responseBody = response.Body
			end
			status.body = responseBody
			return status
		end
		return nil
	end
	canPost.getWithoutHeaders = function(url)
		local ok, body = pcall(function()
			return game:HttpGet(url, true)
		end)
		if not ok then
			return nil
		end
		if type(body) ~= "string" then
			return nil
		end
		return { status = 200, body = body }
	end
	canPost.encodeUrl = function(text)
		return services.HttpService:UrlEncode(text)
	end
	canPost.encodeJson = function(payload)
		local ok, encoded = pcall(services.HttpService.JSONEncode, services.HttpService, payload)
		return if ok then encoded else nil
	end
	canPost.decodeJson = function(text)
		local ok, decoded = pcall(services.HttpService.JSONDecode, services.HttpService, text)
		return if ok then decoded else nil
	end
	return canPost
end
