				return nil
			end
			local lowered = string.lower(name)
			local iterator = coroutine.wrap(lph_generic_for)
			iterator(name, nil, nil)
			local nextEntry = iterator
			while true do
				local active, _, rule = nextEntry()
				if not active then
					break
