		local remoteFunction = replicatedStorage2:FindFirstChild("RemoteFunction")
		if remoteFunction and remoteFunction:FindFirstChild("RemoteFunction") then
			return true
		end
		return findChildOfClass(replicatedStorage2:FindFirstChild("MainRemotes"), "InvokeServer", "RemoteFunction") ~= nil
	end
	local function hasMainRemotesLayout()
		local replicatedStorage3 = services.ReplicatedStorage
		local remoteFunction = findChildOfClass(replicatedStorage3:FindFirstChild("RemoteFunction"), "RemoteFunction", "RemoteFunction")
		local mainRemotes = replicatedStorage3:FindFirstChild("MainRemotes")
		local mainRemoteEvent = findChildOfClass(mainRemotes, "MainRemoteEvent", "RemoteEvent")
		local invokeServer = findChildOfClass(mainRemotes, "InvokeServer", "RemoteFunction")
		local hasAll = remoteFunction ~= nil
		if remoteFunction ~= nil then
			hasAll = mainRemoteEvent ~= nil
			if not (mainRemoteEvent ~= nil) then
				return invokeServer ~= nil
			end
		end
		return hasAll
	end
	local function hasGameRemotesLayout()
		local replicatedStorage4 = services.ReplicatedStorage
		if findChildOfClass(replicatedStorage4:FindFirstChild("GameRemotes"), "MainGameEvent", "RemoteEvent") then
			return true
		end
		return findChildOfClass(replicatedStorage4:FindFirstChild("MainRemotes"), "MainRemoteEvent", "RemoteEvent") ~= nil and not hasRemoteFunctionLayout()
	end
	local function hasMainEventRemote()
		return findChildOfClass(services.ReplicatedStorage, "MainEvent", "RemoteEvent") ~= nil
	end
	local function hasSpreadMode()
		return type(rawget(globals.shared(), "SpreadMode")) == "string"
