		if hasModules then
			hasModules = findChildOfClass(weapons, "ClientHitboxes", "ModuleScript") ~= nil
			if hasModules then
				hasModules = findChildOfClass(replicatedStorage5, "Controls", "ModuleScript") ~= nil
				if hasModules then
