			return "urban"
		end
		if hasMainEventRemote() and hasSpreadMode() then
			return "das"
		end
		family = matchFamilyFromName(game.Name)
		if not family then
			family = matchFamilyFromName(resolveGameName())
			if not family then
				if hasMainEventLayout() then
					return "hc"
				end
				if hasMainRemotesLayout() then
