end
modules.globals = function()
	local globals = {}
	local function getEnvironmentTable()
		if typeof(getrenv) ~= "function" then
			return nil
		end
		local ok, env = pcall(getrenv)
		return if ok and type(env) == "table" then env else nil
	end
	local function getFromEnvironment(key)
		local env = getEnvironmentTable()
		if env then
			env = env[key]
		end
		return if type(env) ~= "table" then nil else env
	end
	local globalsTable
	globals.globals = function()
		local cached = globalsTable
		if cached then
			return cached
		end
		local tableValue = getFromEnvironment("_G")
		if not tableValue then
			return _G
		end
		globalsTable = tableValue
		return tableValue
	end
	local sharedTable
	globals.shared = function()
		local cached = sharedTable
		if cached then
			return cached
		end
		local tableValue = getFromEnvironment("shared")
		if not tableValue then
			return shared
		end
		sharedTable = tableValue
		return tableValue
	end
	globals.flag = function(name)
		local flag = globals.globals()[name]
		return flag ~= nil and flag ~= false
	end
	return globals
end
