modules.urbanFramework = function()
	local urbanGame = modules.urbanGame()
	local scope = modules.scope()
	local mod_open = modules.open()
	local services = modules.services()
	modules.silentAimFov()
	local localPlayer = services.Players.LocalPlayer
	local isReadyCheck = nil
	return {
		isReady = function()
			local check = isReadyCheck
			return check ~= nil and check()
		end,
		start = function(scope, config)
			if scope:isDestroyed() then
				return function()
					return false
				end
			end
			local enabled = true
			local ready = nil
			local pendingRefresh = nil
			local trackedCharacter = nil
			local characterScope = nil
			local mainScope = scope.new()
			local refresh = nil
			local function tryOpen()
				if enabled then
					local current = ready
					if current and urbanGame.isCurrent(current.context) then
						return current.ready()
					end
					ready = nil
					if current then
						current.destroy()
					end
					local character = localPlayer.Character
					local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui")
					if playerGui then
						local isA = playerGui:FindFirstChild("F")
						if character then
							if not isA then
								return false
							end
							if not isA:IsA("LocalScript") then
								return false
							end
							ready = mod_open.open(character, isA, config, refresh)
							return ready ~= nil and ready.ready()
						end
					elseif character then
						return false
					end
				end
				return false
			end
			refresh = function()
				if not enabled then
					return
				end
				if pendingRefresh then
					return
				end
				pendingRefresh = task.defer(function()
					services.RunService.Heartbeat:Wait()
					pendingRefresh = nil
					tryOpen()
				end)
			end
			local function trackCharacter(character)
				if trackedCharacter == character then
					return
				end
				if characterScope then
					characterScope:destroy()
				end
				trackedCharacter = character
				local characterTaskScope = scope.new()
				characterScope = characterTaskScope
				characterTaskScope:add(character.DescendantAdded:Connect(refresh))
				characterTaskScope:add(character.DescendantRemoving:Connect(refresh))
			end
			mainScope:add(localPlayer.CharacterAdded:Connect(function(character)
				trackCharacter(character)
				refresh()
			end))
			mainScope:add(localPlayer.CharacterRemoving:Connect(refresh))
			mainScope:add(localPlayer.DescendantAdded:Connect(refresh))
			mainScope:add(localPlayer.DescendantRemoving:Connect(refresh))
			mainScope:add(services.ReplicatedStorage.DescendantAdded:Connect(refresh))
			mainScope:add(services.ReplicatedStorage.DescendantRemoving:Connect(refresh))
			mainScope:add(services.Workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(refresh))
			mainScope:add(function()
				enabled = false
				if pendingRefresh then
					pcall(task.cancel, pendingRefresh)
					pendingRefresh = nil
				end
				if not characterScope then
					if ready then
						ready.destroy()
						ready = nil
					end
					return
				end
				characterScope:destroy()
				characterScope = nil
				if ready then
					ready.destroy()
					ready = nil
				end
			end)
			scope:add(mainScope)
			local function checkReady()
				return enabled and ready ~= nil and ready.ready()
			end
			isReadyCheck = checkReady
			mainScope:add(function()
				if isReadyCheck == checkReady then
					isReadyCheck = nil
				end
			end)
			if localPlayer.Character then
				trackCharacter(localPlayer.Character)
			end
			refresh()
			return function()
				local opened = tryOpen()
				local current = ready
				if opened then
					opened = current ~= nil
					if current ~= nil then
						return (current.rebind())
					end
				end
				return opened
			end
		end,
	}
end
