modules.cursor = function()
	local settings = modules.settings()
	local services = modules.services()
	local rayHitsBox = {}
	local function reciprocal(number)
		if 0 <= number and number < 1e-8 then
			return 1e30
		end
		if number < 0 and -1e-8 < number then
			return -1e30
		end
		return 1 / number
	end
	rayHitsBox.rayHitsBox = function(origin, direction, cframe, size)
		local localOrigin = cframe:PointToObjectSpace(origin)
		local localDirection = cframe:VectorToObjectSpace(direction)
		local halfSize = size * 0.5
		local inverseX = origin(localDirection.X)
		local inverseY = origin(localDirection.Y)
		local inverseZ = origin(localDirection.Z)
		local tMinX = (-halfSize.X - localOrigin.X) * inverseX
		local tMaxX = (halfSize.X - localOrigin.X) * inverseX
		local tMinY = (-halfSize.Y - localOrigin.Y) * inverseY
		local tMaxY = (halfSize.Y - localOrigin.Y) * inverseY
		local tMinZ = (-halfSize.Z - localOrigin.Z) * inverseZ
		local tMaxZ = (halfSize.Z - localOrigin.Z) * inverseZ
		local tNear = math.max(math.min(tMinX, tMaxX), math.min(tMinY, tMaxY), math.min(tMinZ, tMaxZ))
		local tFar = math.min(math.max(tMinX, tMaxX), math.max(tMinY, tMaxY), math.max(tMinZ, tMaxZ))
		return tFar >= 0 and tNear <= tFar
	end
	rayHitsBox.cursorRay = function()
		local mouseLocation = services.UserInputService:GetMouseLocation()
		return services.Workspace.CurrentCamera:ViewportPointToRay(mouseLocation.X, mouseLocation.Y)
	end
	rayHitsBox.cursorHits = function(object, size)
		local ray = rayHitsBox.cursorRay()
		return rayHitsBox.rayHitsBox(ray.Origin, ray.Direction, object.CFrame, size)
	end
	rayHitsBox.read = function(...)
		local enabled = settings.table(...)
		if not enabled then
			return nil
		end
		if enabled.Enabled ~= true then
			return nil
		end
		local size = enabled.Size
		if type(size) ~= "table" then
			return nil
		end
		local x = size.X
		local y = size.Y
		local z = size.Z
		if type(x) ~= "number" then
			return nil
		end
		if type(y) ~= "number" then
			return nil
		end
		if type(z) ~= "number" then
			return nil
		end
		return Vector3.new(x, y, z)
	end
	return rayHitsBox
end
