	local cache = {}
	local function getIndicators(context)
		local cached = cache[context.runtime]
		if cached then
			return cached
		end
		local indicators = {}
		indicators.indicators = {}
		cache[context.runtime] = indicators
		context.runtime:add(function()
			if indicators.fragment then
				indicators.fragment:destroy()
				indicators.fragment = nil
			end
			for _, cleanup in indicators.indicators do
				cleanup.cleanup()
			end
			table.clear(indicators.indicators)
			cache[context.runtime] = nil
		end)
		return indicators
	end
	local function trackTween(scope, tween)
		scope:add(tween)
		scope:add(function()
			tween:Cancel()
		end)
	end
	local function findDamageText(root)
		local dmgindicator = root:FindFirstChild("dmgindicator")
		if dmgindicator then
			local frame = dmgindicator:FindFirstChild("frame")
			if frame then
				local dmgtext = frame:FindFirstChild("dmgtext")
				if dmgtext and dmgtext:IsA("TextLabel") then
					return dmgtext
				end
			end
		end
		return nil
	end
	local function logDamage(context)
		return "handle", "MenuIsOpen"
	end
	local function playFade(indicators, scopeModule, label, cloned)
		local fadeEntry = indicators.indicators[scopeModule]
		local fadeScope, cleanupEntry
		if not fadeEntry then
			fadeScope = scopeModule.new()
			cleanupEntry = {}
			cleanupEntry.cleanup = function()
				fadeScope:destroy()
			end
			if cloned then
				fadeScope:add(scopeModule)
			end
			fadeScope:add(function()
				if not cleanupEntry.fade then
					return
				end
				cleanupEntry.fade:destroy()
				cleanupEntry.fade = nil
			end)
			indicators.indicators[scopeModule] = cleanupEntry
			fadeEntry = cleanupEntry
		end
		if fadeEntry.fade then
			fadeScope = fadeEntry.fade
			fadeScope:destroy()
		end
		fadeScope = scopeModule.new()
		fadeEntry.fade = fadeScope
		label.TextTransparency = 0
		label.TextStrokeTransparency = 0
		local tweenService = services.TweenService
		local create = tweenService.Create
		local opacity = 1
		local completed = create(tweenService, label, tweenInfo, { TextStrokeTransparency = 1, TextTransparency = opacity })
		trackTween(fadeScope, completed)
		cleanupEntry = fadeEntry
		fadeScope:add(completed.Completed:Connect(function()
			if indicators.indicators[scopeModule] ~= cleanupEntry then
				return
			end
			if label.TextStrokeTransparency ~= 1 then
				return
			end
			indicators.indicators[scopeModule] = nil
			scopeModule:Destroy()
			cleanupEntry.cleanup()
		end))
		completed:Play()
	end
	local function findOrCloneDamagePart(root)
		local dmgpart = root:FindFirstChild("dmgpart")
		if dmgpart and dmgpart:IsA("BasePart") then
			return dmgpart, false
		end
		local assets = services.ReplicatedStorage:FindFirstChild("Assets")
		if assets then
			local template = assets:FindFirstChild("dmgpart")
			if template then
				if not template:IsA("BasePart") then
					return nil, false
				end
				local clone = template:Clone()
				clone.Parent = root
				local parent = root.Parent
				if parent then
					clone:SetAttribute("owner", parent.Name)
				end
				clone.Position = root.Position
				return clone, true
			end
		end
		return nil, false
	end
	return {
		show = function(context, object, amount)
			if context.runtime:isDestroyed() then
				return
			end
			if not (math.abs(amount) < math.huge) then
				return
			end
			local parent = object.Parent
			local name = object.Name
			if parent and parent:IsA("Accessory") then
				name = parent.Name
				parent = parent.Parent
			end
			if parent then
				local humanoid = parent:FindFirstChild("Humanoid")
				if not humanoid then
					return
				end
				if not humanoid:IsA("Humanoid") then
					return
				end
				local indicatorState = amount(context)
				local displayName = tostring(humanoid.DisplayName)
				local partName = tostring(name)
				local packed = table.pack("Tagged %s's %s for %s", displayName, partName, tostring(amount))
				logDamage(context, indicatorState, string.format(unpack(packed, 1, packed.n)))
				if context.player:GetAttribute("DamageInd") ~= true then
					return
				end
				local upperTorso = parent:FindFirstChild("UpperTorso")
				if not upperTorso then
					return
				end
				if not upperTorso:IsA("BasePart") then
					return
				end
				if displayName then
					local damagePart, cloned = findOrCloneDamagePart(upperTorso)
					if not damagePart then
						return
					end
					local textLabel = findDamageText(damagePart)
					if textLabel then
						local previous
						if cloned then
							previous = 0
						else
							previous = tonumber(textLabel.Text) or 0
						end
						textLabel.Text = tostring(math.round((previous + amount) * 10) / 10)
						damagePart.Position = upperTorso.Position
						playFade(indicatorState, damagePart, textLabel, cloned)
						return
					end
					if cloned then
						damagePart:Destroy()
					end
				end
			end
		end,
	}
end
