		if ammoCount ~= nil then
			aim.ammoText.Text = tostring(ammoCount)
		end
		aim.food.Visible = state.food ~= nil
		local foodCount = readNumberValue(state.food and state.food:FindFirstChild("Chomps"))
		if foodCount ~= nil then
			aim.foodText.Text = tostring(foodCount)
		end
		aim.health.Size = UDim2.fromScale(context.humanoid.Health / context.humanoid.MaxHealth * 0.95, 0.83)
		local armor = context.character:GetAttribute("Armor")
		if type(armor) == "number" then
			aim.armor.Size = UDim2.fromScale(armor / 200 * 0.95, 0.83)
		end
	end
	return {
		step = function(context, state, getHit)
			local aim = input.get(context.gui)
			if not aim then
				return
			end
			if context.runtime:isDestroyed() then
				return
			end
			local tool = context.character:FindFirstChildOfClass("Tool")
			state.gun = nil
			state.food = nil
			local health = context.humanoid.Health
			local speedScale = 1
			if health < 50 then
				speedScale = health / 80 + 0.4
			end
			context.humanoid.WalkSpeed = (state.sprintBonus + 16 + computeSlowdown(context, state) + state.crouchBonus) * speedScale
			sendMouse(context, state, aim, getHit)
			updateCrosshair(context, state, aim)
			state.sprinting = state.shift or state.keepSprint
			state.sprintBonus = 0
			if state.sprinting then
				state.sprintBonus = 6
			end
			context.humanoid.JumpPower = 48
			if state.jumpLocked then
				context.humanoid.JumpPower = 0
			end
			detectWeapon(context, state, tool)
			updateCrouch(context, state, aim)
			updateBars(context, state, aim)
		end,
	}
end
modules.serverHop = function()
	modules.urbanGame()
	local services = modules.services()
	local timers = modules.timers()
	modules.newState()
	local input = modules.input()
	local reload = {}
	reload.reload = function(context, state)
		local tool = state.gun
		if tool then
			local rl = tool:FindFirstChild("rl")
			if rl and rl:IsA("RemoteEvent") then
				rl:FireServer()
			end
		end
	end
	local function tryStomp(context, state)
		if state.stompPending then
			return
		end
		if context.runtime:isDestroyed() then
			return
		end
		state.stompPending = true
		local rootPart = context.character:FindFirstChild("HumanoidRootPart")
		local raycastParams = RaycastParams.new()
		raycastParams.FilterDescendantsInstances = { context.character }
		raycastParams.FilterType = Enum.RaycastFilterType.Exclude
		local rayResult
		if rootPart and rootPart:IsA("BasePart") then
			rayResult = services.Workspace:Raycast(rootPart.Position, Vector3.new(0, -8, 0), raycastParams)
		else
			rayResult = nil
		end
		local hit = rayResult
		if hit then
			local model = hit.Instance:FindFirstAncestorOfClass("Model")
			if model then
				if model:FindFirstChildOfClass("Humanoid") then
				end
				state.stompPending = false
				return
			end
		end
		state.stompPending = false
	end
	local function handleInput(context, state, inputObject, isTyping)
		local keyCode = inputObject.KeyCode
		if keyCode == Enum.KeyCode.LeftShift then
			state.shift = true
		elseif not (keyCode ~= Enum.KeyCode.LeftControl or isTyping) then
			state.control = true
		end
		if keyCode == Enum.KeyCode.R then
			reload.reload(context, state)
		elseif keyCode == Enum.KeyCode.ButtonX then
			reload.reload(context, state)
		elseif keyCode ~= Enum.KeyCode.E or isTyping then
			if keyCode == Enum.KeyCode.DPadDown then
				isTyping(context, state)
			elseif keyCode == Enum.KeyCode.ButtonL2 then
				context.cam.Value = true
			elseif keyCode == Enum.KeyCode.ButtonB then
				state.control = not state.control
			elseif keyCode == Enum.KeyCode.ButtonL3 then
				state.shift = not state.shift
			end
		else
			isTyping(context, state)
		end
	end
	local function onJump(context, state)
		local injected = context.player:FindFirstChild("Injected")
		if injected then
			return
		end
		local now = os.clock()
		if 2 < now - state.jumpAt then
			state.jumps = 0
		end
		state.jumps = state.jumps + 1
		local jumpState = state(25, injected)
		if 4 < jumpState.jumps and not jumpState.jumpLocked then
			jumpState.jumpLocked = true
			timers.delay(context.runtime, 1.5, function()
				jumpState.jumpLocked = false
			end)
		end
	end
	reload.start = function(context, state)
		local userInputService = services.UserInputService
		state.shift = userInputService:IsKeyDown(Enum.KeyCode.LeftShift)
		local focusedTextBox = userInputService:GetFocusedTextBox()
		state.control = userInputService:IsKeyDown(Enum.KeyCode.LeftControl) and focusedTextBox == nil
		local seen = {}
		local function onDescendantAdded(object)
			if seen[object] then
				return
			end
			local parent = object.Parent
			if not parent then
				return
			end
			if object:IsA("TextButton") and parent.Name == "e1" then
				local parent2 = parent.Parent
				if not parent2 then
					return
				end
				local parent3 = parent2.Parent
				if parent2.Name ~= "ScrollingFrame" then
					return
				end
				if not parent3 then
					return
				end
				if parent3.Name ~= "Settings" then
					return
				end
				if parent3.Parent ~= context.gui then
					return
				end
				seen[object] = true
				local function syncKeepSprint()
					state.keepSprint = object.Text == "On"
				end
				syncKeepSprint()
				context.runtime:add(object:GetPropertyChangedSignal("Text"):Connect(syncKeepSprint))
			elseif object:IsA("GuiButton") and parent.Name == "mobile ppl" and parent.Parent == context.gui then
				seen[object] = true
				local mode = 505714608
				mode = 103869371
				context.runtime:add(object.Activated:Connect(function()
					if object.Name == "croch" then
						state.control = not state.control
					elseif object.Name == "run" then
						state.shift = not state.shift
					elseif object.Name == "stomp" then
						mode(context, state)
					else
						local name = object.Name
						if mode ~= 70298307 and name == "rl" then
							reload.reload(context, state)
						end
					end
				end))
			else
				if not (object:IsA("GuiButton") and object.Name == "MouseLock" and parent.Name == "BottomLeft" and parent.Parent == context.gui) then
					return
				end
				seen[object] = true
				context.runtime:add(object.Activated:Connect(function()
					context.cam.Value = not context.cam.Value
					context.gunMode.Value = not context.gunMode.Value
				end))
			end
		end
		for _, descendant in context.gui:GetDescendants() do
			onDescendantAdded(descendant)
		end
		context.runtime:add(context.gui.DescendantAdded:Connect(onDescendantAdded))
		context.runtime:add(userInputService.InputBegan:Connect(function(inputObject, gameProcessed)
			handleInput(context, state, inputObject, gameProcessed)
		end))
		context.runtime:add(userInputService.InputEnded:Connect(function(inputObject)
			if inputObject.KeyCode == Enum.KeyCode.LeftShift then
				state.shift = false
			elseif inputObject.KeyCode == Enum.KeyCode.LeftControl then
				state.control = false
			elseif inputObject.KeyCode == Enum.KeyCode.ButtonL2 then
				context.cam.Value = false
			end
		end))
		context.runtime:add(userInputService.WindowFocused:Connect(function()
			state.unfocused = false
		end))
		context.runtime:add(userInputService.WindowFocusReleased:Connect(function()
			state.unfocused = true
		end))
		context.runtime:add(context.humanoid.Jumping:Connect(function()
			onJump(context, state)
		end))
		context.runtime:add(context.player.Chatted:Connect(function(message)
			local fovMatch = string.match(message, "%d+")
			local currentCamera = services.Workspace.CurrentCamera
			if not (string.sub(message, 1, 6) ~= "/e fov" or not fovMatch or not currentCamera) then
				currentCamera.FieldOfView = math.clamp(tonumber(fovMatch) or 70, 70, 120)
			end
		end))
		context.runtime:add(function()
			input.release(context.gui)
		end)
	end
	return reload
end
modules.timers = function()
	modules.scope()
	return {
		delay = function(scope, delaySeconds, threadSets)
			if scope:isDestroyed() then
				return nil
			end
			local threads = threadSets[scope]
			local newThreads
			if not threads then
				newThreads = {}
				threadSets[scope] = newThreads
				scope:add(function()
					threadSets[scope] = nil
					for thread in newThreads do
						newThreads[thread] = nil
						if coroutine.running() ~= thread then
							pcall(task.cancel, thread)
						end
					end
				end)
				threads = newThreads
			end
			local activeThreads = threads
			local thread = nil
			thread = task.delay(delaySeconds, function()
				if thread then
					activeThreads[thread] = nil
				end
				if not scope:isDestroyed() then
					threads()
				end
			end)
			activeThreads[thread] = true
			return thread
		end,
	}
end
modules.silentAimFov = function()
	local body = modules.body()
	local checks = modules.checks()
	local settings = modules.settings()
	modules.mouseHook()
	local cursor = modules.cursor()
	local queries = modules.queries()
	modules.scope()
	local keybind = modules.keybind()
	local visibility = modules.visibility()
	local hoodGame = modules.hoodGame()
	local prediction = modules.prediction()
	local targeting = modules.targeting()
	local services = modules.services()
	local closestPoint = modules.closestPoint()
	local localPlayer = services.Players.LocalPlayer
	local mouse = localPlayer:GetMouse()
	local function isFiniteVector(vector)
		return math.abs(vector.X) < math.huge and math.abs(vector.Y) < math.huge and math.abs(vector.Z) < math.huge
	end
	local function openTargetRay(character, origin)
		if origin then
			local vector = mouse.Hit.Position - origin
			if 0 < vector.Magnitude then
				return queries.open(character, "SilentAim", Ray.new(origin, vector.Unit), true)
			end
		end
		return queries.open(character, "SilentAim", cursor.cursorRay(), false)
	end
	local function findVisiblePoint(character, shooter, origin)
		local first = openTargetRay(character, origin)
		if not settings.bool(false, "Main", "Feature Checks", "Visible") then
			local point = nil
			if first.first then
				point = first.first.point
			end
			queries.close(first)
			return point
		end
		if not origin then
			origin = cursor.cursorRay().Origin
		end
		visibility.open()
		local part = queries.next(first)
		local position
		while true do
			position = nil
			if not part then
				break
			end
			local converged = closestPoint.converge(part.part, part.point, origin)
			local object = visibility.reaches(origin, converged, shooter, character)
			if object then
				position = object.Position
				break
			end
			part = queries.next(first)
		end
		local queryApi
		while true do
			visibility.close()
			queryApi = queries
			break
		end
		queryApi.close(first)
		return position
	end
	local function applyPrediction(point, part, origin, shooter, character)
		local lead = prediction.generic("SilentAim", part.AssemblyLinearVelocity)
		if lead == Vector3.zero then
			return point
		end
		local predicted = point + lead
		if settings.bool(false, "Main", "Feature Checks", "Visible") and not visibility.isClear(origin, predicted, shooter, character) then
			return point
		end
		return predicted
	end
	return {
		new = function(section)
			local activation = keybind.activation(section, "Combat", "SilentAim", "Activation")
			return function(rawAimOrigin)
				if not (rawAimOrigin and not isFiniteVector(rawAimOrigin)) then
					if not settings.bool(false, "Combat", "SilentAim", "Enabled") then
						return nil, nil
					end
					if not activation.isActive() then
						return nil, nil
					end
					local gameAdapter = hoodGame.current()
					local character = localPlayer.Character
					if not gameAdapter then
						return nil, nil
					end
					if not character then
						return nil, nil
					end
					if not gameAdapter.isReady(character) then
						return nil, nil
					end
					if not gameAdapter.equipped(character) then
						return nil, nil
					end
					local target = targeting.current()
					local targetCharacter, aimOrigin
					if target then
						targetCharacter = target.Character
						if targetCharacter then
							local rootPart = body.root(targetCharacter)
							if rootPart then
								if rawAimOrigin then
									aimOrigin = rawAimOrigin
								else
									aimOrigin = cursor.cursorRay().Origin
								end
								if not checks.passes("Feature Checks", target, aimOrigin) then
									return nil, nil
								end
								local fov = cursor.read("Combat", "SilentAim", "FOV")
								if fov and not cursor.cursorHits(rootPart, fov) then
									return nil, nil
								end
								local hitPoint = aimOrigin(targetCharacter, character, rawAimOrigin)
								if not hitPoint then
									return nil, nil
								end
								local predicted = rootPart(hitPoint, rootPart, aimOrigin, character, targetCharacter)
								if targetCharacter(predicted) then
									return predicted, target
								end
							end
							return nil, nil
						end
					else
						targetCharacter = target
					end
					local targetRoot = targetCharacter
					if not target then
						return nil, nil
					end
					if not targetCharacter then
						return nil, nil
					end
					if not targetRoot then
						return nil, nil
					end
					if rawAimOrigin then
						aimOrigin = rawAimOrigin
					else
						aimOrigin = cursor.cursorRay().Origin
					end
					if not checks.passes("Feature Checks", target, aimOrigin) then
						return nil, nil
					end
					local fov = cursor.read("Combat", "SilentAim", "FOV")
					if fov and not cursor.cursorHits(targetRoot, fov) then
						return nil, nil
					end
					local hitPoint = aimOrigin(targetCharacter, character, rawAimOrigin)
					if not hitPoint then
						return nil, nil
					end
					local predicted = targetRoot(hitPoint, targetRoot, aimOrigin, character, targetCharacter)
					if targetCharacter(predicted) then
						return predicted, target
					end
				end
				return nil, nil
			end
		end,
	}
end
modules.body = function()
	local moduleRegistry = modules
	local currentAdapter = moduleRegistry.hoodGame()
	local services = modules.services()
	local partCache = setmetatable({}, { __mode = "k" })
	local bodyApi = {}
	local bodyPartNames = {
		"Head",
		"UpperTorso",
		"LowerTorso",
		"LeftUpperArm",
		"LeftLowerArm",
		"LeftHand",
		"RightUpperArm",
		"RightLowerArm",
		"RightHand",
		"LeftUpperLeg",
		"LeftLowerLeg",
		"LeftFoot",
		"RightUpperLeg",
		"RightLowerLeg",
		"RightFoot",
	}
	if moduleRegistry then
		bodyApi.PARTS = table.freeze(bodyPartNames)
		bodyApi.part = function(character, partName)
			local cached = partCache[character]
			local found
			if cached then
				found = cached[partName]
				if found and found.Parent == character then
					return found
				end
			else
				found = cached
			end
			local part = character:FindFirstChild(partName)
			if not part then
				if found and cached then
					cached[partName] = nil
				end
				return nil
			end
			if not part:IsA("BasePart") then
				if found and cached then
					cached[partName] = nil
				end
				return nil
			end
			if cached then
				cached[partName] = part
			else
				local newEntry = {}
				newEntry[partName] = part
				partCache[character] = newEntry
			end
			return part
		end
		bodyApi.root = function(character)
			return bodyApi.part(character, "HumanoidRootPart")
		end
	end
	bodyApi.isKnocked = function(character)
		local adapter = currentAdapter.current()
		if adapter then
			return adapter.isKnocked(character)
		end
		local bodyEffects = character:FindFirstChild("BodyEffects")
		if bodyEffects then
			bodyEffects = bodyEffects:FindFirstChild("K.O")
		end
		return bodyEffects ~= nil and bodyEffects:IsA("BoolValue") and bodyEffects.Value
	end
	bodyApi.isDead = function(character)
		local bodyEffects = character:FindFirstChild("BodyEffects")
		if bodyEffects then
			local dead = bodyEffects:FindFirstChild("Dead")
			if dead and dead:IsA("BoolValue") and dead.Value then
				return true
			end
		end
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		local noHumanoid = humanoid == nil
		if humanoid == nil then
			return noHumanoid
		end
		return humanoid.Health <= 0
	end
	bodyApi.hasForceField = function(character)
		return character:FindFirstChildOfClass("ForceField") ~= nil
	end
	bodyApi.vehicle = function(character)
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if humanoid then
			local seatPart = humanoid.SeatPart
			if seatPart then
				local parent = seatPart.Parent
				local vehicleModel = nil
				if parent then
					while not parent:IsA("Workspace") do
						if parent:IsA("Model") then
							vehicleModel = parent
						end
						parent = parent.Parent
						if not parent then
							break
						end
					end
				end
				return if vehicleModel ~= character then vehicleModel else nil
			end
		end
		return nil
	end
	bodyApi.ownerOf = function(object)
		local ancestor = object.Parent
		if ancestor then
			while not ancestor:IsA("Workspace") do
				if ancestor:IsA("Model") then
					local owner = services.Players:GetPlayerFromCharacter(ancestor)
					if owner then
						return owner, ancestor
					end
				end
				ancestor = ancestor.Parent
				if not ancestor then
					break
				end
			end
		end
		return nil, nil
	end
	return bodyApi
end
modules.hoodGame = function()
	modules.scope()
	local activeGame = nil
	return {
		current = function()
			return activeGame
		end,
		start = function(scope, adapter)
			if not scope:isDestroyed() then
				adapter = adapter
				scope:add(function()
					if adapter == adapter then
						adapter = nil
					end
				end)
			end
		end,
	}
end
modules.checks = function()
	local moduleRegistry = modules
	local bodyModule = moduleRegistry.body
	local bodyApi
	if moduleRegistry then
		bodyApi = bodyModule()
	end
	modules.settings()
	modules.crew()
	modules.currentGame()
	local visibility = modules.visibility()
	modules.services()
	local visibilityCache = setmetatable({}, { __mode = "k" })
	local isVisible = {}
	local function checkVisibleParts(origin, shooter, character)
		local parts = bodyApi.PARTS
		local partCount = #parts
		local startIndex = character[character] or 1
		visibility.open()
		local index = 0
		local lastIndex = partCount - 1
		local current = index - 1
		while true do
			local nextIndex = current + 1
			if not (nextIndex <= lastIndex) then
				break
			end
			current = nextIndex
			local partIndex = (startIndex + nextIndex - 1) % partCount + 1
			local object = bodyApi.part(character, parts[partIndex])
			if object and visibility.reaches(origin, object.Position, shooter, character) then
				visibility.close()
				character[character] = partIndex
				return true
			end
		end
		visibility.close()
		return false
	end
	isVisible.isVisible = function(origin, shooter, character)
		local now = os.clock()
		local cached = visibilityCache[character]
		if cached and cached.shooter == shooter and (cached.origin - origin).Magnitude < 0.5 and now - cached.at < 0.016666666666666666 then
			return cached.isVisible
		end
		local visible = checkVisibleParts(origin, shooter, character)
		if cached then
			cached.origin = origin
			cached.shooter = shooter
			cached.at = now
			cached.isVisible = visible
		else
			visibilityCache[character] = { origin = origin, shooter = shooter, at = now, isVisible = visible }
		end
		return visible
	end
	isVisible.passes = function()
		return "GetDescendants", 0.25
	end
	return isVisible
end
modules.crew = function()
	local gameAdapter = modules.hoodGame()
	local allyCache = setmetatable({}, { __mode = "k" })
	local function readValue(instance)
		if instance and instance:IsA("ValueBase") then
			return instance.Value
		end
		return nil
	end
	local function readCrewTag(character)
		local information = character:FindFirstChild("Information")
		if information then
			local crew = information:FindFirstChild("Crew")
			if crew then
				local tag = readValue(crew)
				if tag ~= "" then
					return tag
				end
				return nil
			end
		end
		return nil
	end
	local function computeAlly(firstPlayer, secondPlayer)
		local firstMatchId = firstPlayer:GetAttribute("RankedMatchId")
		local secondMatchId = secondPlayer:GetAttribute("RankedMatchId")
		if not (firstMatchId ~= nil or secondMatchId ~= nil) then
			local firstData = firstPlayer:FindFirstChild("DataFolder")
			local dataFolder = secondPlayer:FindFirstChild("DataFolder")
			if not firstData then
				return false
			end
			if not dataFolder then
				return false
			end
			local firstCrew = readCrewTag(firstData)
			if firstCrew ~= nil and firstCrew == readCrewTag(dataFolder) then
				return true
			end
			local firstOfficer = readValue(firstData:FindFirstChild("Officer")) == 1
			if not firstOfficer then
				return firstOfficer
			end
			return readValue(dataFolder:FindFirstChild("Officer")) == 1
		end
		local firstTeam = firstPlayer:GetAttribute("RankedTeam")
		local isAlly = type(firstMatchId) == "string"
		if isAlly then
			isAlly = firstMatchId ~= ""
			if firstMatchId ~= "" then
				isAlly = firstMatchId == secondMatchId
				if firstMatchId == secondMatchId then
					if firstTeam ~= 1 then
						isAlly = firstTeam == 2
						if not (firstTeam == 2) then
							return isAlly
						end
					end
				end
			end
		end
		return isAlly
	end
	return {
		isAlly = function(selfPlayer, otherPlayer)
			local adapter = gameAdapter.current()
			if adapter and adapter.isAlly then
				return adapter.isAlly(selfPlayer, otherPlayer)
			end
			local now = os.clock()
			local cached = allyCache[otherPlayer]
			if cached and cached.me == selfPlayer and now - cached.at < 0.5 then
				return cached.isAlly
			end
			local ally = computeAlly(selfPlayer, otherPlayer)
			if cached then
				cached.at = now
				cached.me = selfPlayer
				cached.isAlly = ally
			else
				allyCache[otherPlayer] = { at = now, me = selfPlayer, isAlly = ally }
			end
			return ally
		end,
	}
end
