modules.keybind = function()
	local settingsModule = modules.settings()
	modules.scope()
	local services = modules.services()
	local mouseButtons = {}
	mouseButtons.MouseButton1 = Enum.UserInputType.MouseButton1
	mouseButtons.MouseButton2 = Enum.UserInputType.MouseButton2
	mouseButtons.MouseButton3 = Enum.UserInputType.MouseButton3
	local keyCodes = {}
	for _, enumItem in Enum.KeyCode:GetEnumItems() do
		keyCodes[enumItem.Name] = enumItem
	end
	local activationCache = {}
	local matches = {}
	matches.matches = function(input, keyName)
		local button = mouseButtons[keyName]
		if button then
			return input.UserInputType == button
		end
		local keyCode = keyCodes[keyName]
		return keyCode ~= nil and input.KeyCode == keyCode
	end
	matches.onPress = function(scope, keyGetter, onPressed)
		scope:add(services.UserInputService.InputBegan:Connect(function(input, gameProcessed)
			local key = keyGetter()
			if not (gameProcessed or not key or not matches.matches(input, key)) then
				onPressed()
			end
		end))
	end
	matches.activation = function(scope, ...)
		local args = table.pack(...)
		local path = {}
		table.move(args, 1, args.n, 1, path)
		local cacheKey = table.concat(path, "\000")
		local cached = activationCache[cacheKey]
		if cached then
			return cached
		end
		local isHeld = false
		local isToggled = false
		local function readSettings()
			local enabled = settingsModule.table(table.unpack(path))
			if not enabled then
				return nil, false
			end
			if enabled.Enabled == false then
				return nil, false
			end
			local settingsTable = enabled.Settings
			if type(settingsTable) ~= "table" then
				return enabled, true
			end
			return settingsTable, true
		end
		local function readKey()
			local key = readSettings()
			if key then
				key = key.Key
			end
			if type(key) ~= "string" then
				return nil
			end
			return key
		end
		matches.onPress(scope, readKey, function()
			isHeld = true
			isToggled = not isToggled
		end)
		scope:add(services.UserInputService.InputEnded:Connect(function(input)
			local key = readKey()
			if key and matches.matches(input, key) then
				isHeld = false
			end
		end))
		local isActive = {}
		isActive.isActive = function()
			local settingsTable, enabled = readSettings()
			if not enabled then
				return true
			end
			if not settingsTable then
				return true
			end
			if settingsTable.Type == "Hold" then
				return isHeld
			end
			if settingsTable.Type ~= "Toggle" then
				return true
			end
			return isToggled
		end
		activationCache[cacheKey] = isActive
		scope:add(function()
			if activationCache[cacheKey] == isActive then
				activationCache[cacheKey] = nil
			end
		end)
		return isActive
	end
	return matches
end
