			end
		end
		local fromDepth, toDepth = cornerDepth[bestFrom], cornerDepth[bestTo]
		local t, ax, ay, az = bestT * fromDepth / ((1 - bestT) * toDepth + bestT * fromDepth), cornerOffset(half, bestFrom)
		local bx, by, bz = cornerOffset(half, bestTo)
		return ax + (bx - ax) * t, ay + (by - ay) * t, az + (bz - az) * t, math.atan(math.sqrt(bestSquared)), fromDepth + (toDepth - fromDepth) * t
