	local function nearestBehind(half)
		local centerLocal, directionLocal = Vector3.new(relX * rightX + relY * rightY + relZ * rightZ, relX * upX + relY * upY + relZ * upZ, relX * backX + relY * backY + relZ * backZ), Vector3.new(unitX * rightX + unitY * rightY + unitZ * rightZ, unitX * upX + unitY * upY + unitZ * upZ, unitX * backX + unitY * backY + unitZ * backZ)
		local best = boxEdges.nearest(centerLocal, half, directionLocal)
		local localX, localY, localZ = best.X, best.Y, best.Z
		local x, y, z = rightX * localX + upX * localY + backX * localZ, rightY * localX + upY * localY + backY * localZ, rightZ * localX + upZ * localY + backZ * localZ
		local crossX, crossY, crossZ, along = unitY * z - unitZ * y, unitZ * x - unitX * z, unitX * y - unitY * x, x * unitX + y * unitY + z * unitZ
		return x, y, z, math.atan2(math.sqrt(crossX * crossX + crossY * crossY + crossZ * crossZ), along), along
