		local testHalf = nativeHalf or half
		local ok, lengthSquared = isUsable(testHalf, direction)
		if not ok or not setBox(frame, origin) then
			return Vector3.zero, math.huge, 0
		end
		if nativeHalf then
			local nativeNear = clipBox(nativeHalf, direction.X, direction.Y, direction.Z)
			if nativeNear and nativeNear > 0 then
				return origin + direction * nativeNear, 0, nativeNear
			end
			if not isUsable(half, direction) then
