		if not isUsable(half, direction) or not setBox(frame, origin) then
			return nil, nil
		end
		return clipBox(half, direction.X, direction.Y, direction.Z)
	end
	geometry.onPart = function(part, scale, ray)
		return geometry.onBox(part.CFrame, part.Size * (0.5 * scale), ray.Origin, ray.Direction)
	end
