end
modules.boxEdges = function()
	local SIGNS, dirX, dirY, dirZ, bestX, bestY, bestZ = { -1, 1 }, 0, 0, 0, 0, 0, 0
	local bestCosine, boxEdges = -math.huge, {}
	local function consider(x, y, z)
		local lengthSquared = x * x + y * y + z * z
		local cosine = if lengthSquared > 0 then (dirX * x + dirY * y + dirZ * z) / math.sqrt(lengthSquared) else 1
		if cosine > bestCosine then
			bestX, bestY, bestZ, bestCosine = x, y, z, cosine
		end
	end
	local function edgesAlongX(center, half)
		local low, high = center.X - half.X, center.X + half.X
		for _, signY in SIGNS do
			local y = center.Y + half.Y * signY
			for _, signZ in SIGNS do
				local z = center.Z + half.Z * signZ
				local slope = dirY * y + dirZ * z
				if slope ~= 0 then
					local x = dirX * (y * y + z * z) / slope
					if x > low and x < high then
						consider(x, y, z)
					end
				end
			end
		end
	end
	local function edgesAlongY(center, half)
		local low, high = center.Y - half.Y, center.Y + half.Y
		for _, signX in SIGNS do
			local x = center.X + half.X * signX
			for _, signZ in SIGNS do
				local z = center.Z + half.Z * signZ
				local slope = dirX * x + dirZ * z
				if slope ~= 0 then
					local y = dirY * (x * x + z * z) / slope
					if y > low and y < high then
						consider(x, y, z)
					end
				end
			end
		end
	end
	local function edgesAlongZ(center, half)
		local low, high = center.Z - half.Z, center.Z + half.Z
		for _, signX in SIGNS do
			local x = center.X + half.X * signX
			for _, signY in SIGNS do
				local y = center.Y + half.Y * signY
				local slope = dirX * x + dirY * y
				if slope ~= 0 then
					local z = dirZ * (x * x + y * y) / slope
					if z > low and z < high then
						consider(x, y, z)
					end
				end
			end
		end
	end
	boxEdges.nearest = function(center, half, direction)
		dirX, dirY, dirZ = direction.X, direction.Y, direction.Z
		bestCosine = -math.huge
		for _, signX in SIGNS do
			local x = center.X + half.X * signX
			for _, signY in SIGNS do
				local y = center.Y + half.Y * signY
				for _, signZ in SIGNS do
					consider(x, y, center.Z + half.Z * signZ)
				end
			end
		end
		edgesAlongX(center, half)
		edgesAlongY(center, half)
		edgesAlongZ(center, half)
		return Vector3.new(bestX, bestY, bestZ)
	end
	return boxEdges
end
modules.hitboxExpander = function()
	local body = modules.body()
	local tracked = setmetatable({}, { __mode = "k" })
	local version = 0
	local hitboxes = {}
	hitboxes.NAME = "AtomicHB"
	hitboxes.version = function()
		return version
	end
	hitboxes.isExpander = function(instance)
		return instance ~= nil and instance.Name == "AtomicHB" and instance:IsA("BasePart")
	end
	hitboxes.expander = function(character)
		local atomicHB = character:FindFirstChild("AtomicHB")
		if atomicHB and atomicHB:IsA("BasePart") then
			return atomicHB
		end
		return nil
	end
	hitboxes.track = function(part)
		if not tracked[part] then
			tracked[part] = true
			version = version + 1
		end
	end
	hitboxes.untrack = function(part)
		if tracked[part] then
			tracked[part] = nil
			version = version + 1
		end
	end
	hitboxes.appendExcept = function(list, exceptPart)
		for object in list do
			local parent = object.Parent
			if parent and parent ~= exceptPart then
				table.insert(list, object)
			end
		end
	end
	hitboxes.remap = function(object)
		if not object then
			return object
		end
		if not hitboxes.isExpander(object) then
			return object
		end
		local parent = object.Parent
		if not (parent and parent:IsA("Model")) then
			return nil
		end
		local rootPart = body.root(parent)
		if rootPart then
			return rootPart
		end
		return (body.part(parent, "UpperTorso"))
	end
	return hitboxes
end
modules.queries = function()
	local body = modules.body()
