		for slot = 1, slots, 1 do
			records[slot] = {
				part = nil,
				slot = slot,
				frame = CFrame.identity,
				half = Vector3.zero,
				nativeHalf = nil,
				point = Vector3.zero,
				gap = math.huge,
				depth = 0,
				score = 1,
				solved = false,
				valid = false,
				emitted = false,
