modules.cone = function()
	return {
		score = function(center, half, origin, unit)
			local dx, dy, dz, halfX, halfY, halfZ = center.X - origin.X, center.Y - origin.Y, center.Z - origin.Z, half.X, half.Y, half.Z
			local distanceSquared, radiusSquared = dx * dx + dy * dy + dz * dz, halfX * halfX + halfY * halfY + halfZ * halfZ
			if halfX < 0 or halfY < 0 or halfZ < 0 or not (radiusSquared < distanceSquared) or not (distanceSquared < math.huge) then
				return 1
			end
			local along = dx * unit.X + dy * unit.Y + dz * unit.Z
			local acrossSquared = math.max(0, distanceSquared - along * along)
			if along >= 0 and acrossSquared <= radiusSquared then
				return 1
			end
			local cosine = (along * math.sqrt(distanceSquared - radiusSquared) + math.sqrt(acrossSquared * radiusSquared)) / distanceSquared
			if cosine ~= cosine then
				return 1
			end
			return math.clamp(cosine + 1e-12, -1, 1)
		end,
	}
end
modules.hitLocation = function()
	local body = modules.body()
	local geometry = modules.geometry()
	local settings = modules.settings()
	local cursor = modules.cursor()
	local preference = modules.preference()
	local hitboxes, hitLocation = modules.hitboxExpander(), {}
	local function putFirst(list, part, poseOf)
		if not part then
			return
		end
		for index, entry in list do
			if entry.part == part then
				table.remove(list, index)
				table.insert(list, 1, entry)
				return
			end
		end
		local position = part.Position
		local point = if poseOf then poseOf(part).Position else position
		table.insert(list, 1, { part = part, point = point, gap = 0, depth = 0 })
	end
	local function setEntry(list, index, part, point, gap, depth)
		local entry = list[index]
		if entry then
			entry.part = part
			entry.point = point
			entry.gap = gap
			entry.depth = depth
		else
			list[index] = { part = part, point = point, gap = gap, depth = depth }
		end
	end
	local function truncate(list, count)
		for index = #list, count + 1, -1 do
			list[index] = nil
		end
	end
