		return settings.string("Closest Point", "Combat", section, "Hit Location", "Part") == "Closest Point"
	end
	hitLocation.scale = function(section)
		return math.clamp(settings.number(0.5, "Combat", section, "Hit Location", "Closest Point", "Scale"), 0, 1)
	end
	local function measure(part, scale, origin, direction, withNative, poseOf)
		local frame, size
		if poseOf then
			frame, size = poseOf(part)
		else
			frame, size = part.CFrame, part.Size
		end
		local nativeHalf = if withNative then size * 0.5 else nil
		local point, gap, depth = geometry.onBox(frame, size * (0.5 * scale), origin, direction, nativeHalf)
		return point, gap, depth, frame.Position
	end
