		local mode = settings.string("Closest Point", "Combat", section, "Hit Location", "Part")
		local isClosestPoint = mode == "Closest Point"
		local scale, withNative, origin, direction, list, partNames, count = if isClosestPoint then hitLocation.scale(section) else 1, isBarrel and isClosestPoint, ray.Origin, ray.Direction, reuse or {}, body.PARTS, 0
