modules.preference = function()
	local byCursor, byBarrel = {}, {}
	local preference = {
		switchMargin = 0.004,
		less = function(a, b)
			if a.gap ~= b.gap then
				return a.gap < b.gap
			end
			return a.depth < b.depth
		end,
		held = function(section, isBarrel)
			if isBarrel then
				return byBarrel[section]
			end
			return byCursor[section]
		end,
		remember = function(section, isBarrel, part)
			if isBarrel then
				byBarrel[section] = part
			else
				byCursor[section] = part
			end
		end,
		promote = function(list, heldPart)
			local first = list[1]
