modules.resolver = function()
	local geometry = modules.geometry()
	local preference = modules.preference()
	modules.unnamed_M()
	local resolver = {}
	local function same(value)
		return value
	end
	local function insertReady(query, record)
		local ready, low = query.ready, 1
		local high = #ready
		while low <= high do
			local middle = math.floor((low + high) * 0.5)
			if preference.less(same(record), same(ready[middle])) then
				high = middle - 1
			else
				low = middle + 1
			end
		end
		table.insert(ready, low, record)
	end
	local function solve(query, record)
		if record.solved then
			return
		end
		record.point, record.gap, record.depth = geometry.onBox(record.frame, record.half, query.origin, query.direction, record.nativeHalf)
		record.solved = true
		record.valid = record.gap >= 0 and record.gap < math.huge and record.depth > -math.huge and record.depth < math.huge
		if record.valid and record.slot <= query.bodyCount and not query.isComplete then
			insertReady(query, record)
		end
