	local function solveAll(query)
		query.isComplete = true
		table.clear(query.ready)
		local sorted, bodyCount = query.sorted, query.bodyCount
		for slot = 1, bodyCount, 1 do
			local record = query.records[slot]
			solve(query, record)
			if record.valid then
				table.insert(sorted, same(record))
			end
		end
		table.sort(sorted, preference.less)
		preference.promote(sorted, query.held)
		if query.count > query.bodyCount then
			local expander = query.records[query.count]
			solve(query, expander)
			if expander.valid then
				table.insert(sorted, same(expander))
			end
		end
	end
	local function nextSorted(query)
		local sorted = query.sorted
		while query.sortedIndex < #sorted do
			query.sortedIndex = query.sortedIndex + 1
			local record = sorted[query.sortedIndex]
			if not record.emitted then
				return record
			end
		end
		return nil
	end
	local function nextUnsolved(query)
		while query.boundIndex <= #query.bounds do
			local record = query.bounds[query.boundIndex]
			if not record.solved then
				return record
			end
			query.boundIndex = query.boundIndex + 1
		end
		return nil
	end
	local function isTied(query, record)
		local second = query.ready[2]
		return second ~= nil and second.gap == record.gap and second.depth == record.depth
	end
	local function nextClosest(query)
