		while bound do
			if best and bound.score < math.cos(math.min(math.pi, best.gap + 2e-6)) then
				break
			end
			if #query.ordered > 0 then
				solveAll(query)
				return nextSorted(query)
			end
			solve(query, bound)
			best = query.ready[1]
			bound = nextUnsolved(query)
		end
		if best and isTied(query, best) then
			solveAll(query)
			return nextSorted(query)
		end
		return best
	end
	local function preferHeld(query, best)
		if best.gap <= 0 or not query.held or query.held == best.part then
