		end
		for slot = 1, query.bodyCount, 1 do
			local record = query.records[slot]
			if record.part == query.held then
				solve(query, record)
				if record.valid and record.gap - best.gap < preference.switchMargin then
					return record
				end
				break
			end
		end
		return best
