	resolver.advance = function(query)
		local eager = query.eager
		if eager then
			query.eagerIndex = query.eagerIndex + 1
			return eager[query.eagerIndex]
		end
		local best = nil
		if query.isComplete then
			best = nextSorted(query)
		else
			local found = nextClosest(query)
			best = found and (if #query.ordered == 0 then if query.isComplete then found else preferHeld(query, found) else found)
		end
		if best and #query.ordered == 0 and best.part then
			preference.remember(query.section, query.isBarrel, best.part)
		end
		if not best and query.count > query.bodyCount and not query.isComplete then
			local expander = query.records[query.count]
			solve(query, expander)
			best = if expander.valid then if expander.emitted then best else expander else best
		end
		if not best then
			return nil
		end
		best.emitted = true
		if not query.isComplete then
			for index, record in query.ready do
				if record == best then
					table.remove(query.ready, index)
					break
				end
			end
		end
		local candidate = same(best)
		table.insert(query.ordered, candidate)
		return candidate
	end
