	local function isAutomatic()
		return settings.string("Manual", "Main", "Selection", "Mode") == "Automatic"
	end
	local function rootFor(candidate)
		if candidate == localPlayer then
			return nil
		end
		return targetRules.root(candidate)
	end
	local function candidateSource()
		if useManualList then
			return manualPlayers
		end
		return services.Players:GetPlayers()
	end
	local function addScreenCandidate(screenPoints, candidate, worldPosition, mouseX, mouseY)
		local point, onScreen = screenPoints:WorldToViewportPoint(worldPosition)
		if not onScreen then
			return
		end
		local deltaX = point.X - mouseX
		local deltaY = point.Y - mouseY
		local index = #mouseX + 1
		mouseX[index] = candidate
		mouseY[index] = math.sqrt(deltaX * deltaX + deltaY * deltaY)
	end
	local function addCandidate(camera, candidate, fov, mouseLocation, ray)
		local rootPart = rootFor(candidate)
		if rootPart and not (fov and not (ray and cursor.rayHitsBox(ray.Origin, ray.Direction, rootPart.CFrame, fov))) then
			addScreenCandidate(screenPoints, candidate, rootPart.Position, mouseLocation.X, mouseLocation.Y)
