	local function refreshCandidates(camera, fov)
		table.clear(screenPoints)
		table.clear(distances)
		local mouseLocation = services.UserInputService:GetMouseLocation()
		local ray = nil
		if fov then
			ray = camera:ViewportPointToRay(mouseLocation.X, mouseLocation.Y)
		end
		for _, candidate in candidateSource() do
			addCandidate(camera, candidate, fov, mouseLocation, ray)
		end
		local models = currentGame.current()
		if not (models and models.models) then
			return
		end
		for _, modelCandidate in models.models() do
			addCandidate(camera, modelCandidate, fov, mouseLocation, ray)
		end
	end
	local function byDistance(a, b)
