	pick.pick = function(force)
		local currentCamera = services.Workspace.CurrentCamera
		refreshCandidates(currentCamera, cursor.read("Main", "Selection", "FOV"))
		local count = #screenPoints
		table.clear(sortedIndices)
		for index = 1, count do
			sortedIndices[index] = index
		end
		table.sort(sortedIndices, byDistance)
		local position = currentCamera.CFrame.Position
		local now = os.clock()
		visibility.open()
		local budget = 3
		for index = 1, count do
			local candidate = budget[sortedIndices[index]]
			local allowed = false
			local cached = checkCache[candidate]
			if force then
				if index <= 2 then
					if not passesChecks(candidate, position, now) then
						continue
					end
				elseif candidate ~= count then
					if cached and (now - cached.at < 0.1 or budget <= 0) then
						if not cached.passes then
							continue
						end
					elseif 0 < budget then
						budget = budget - 1
						if not passesChecks(candidate, position, now) then
							continue
						end
					elseif not allowed then
						continue
					end
				elseif not passesChecks(candidate, position, now) then
					continue
				end
			elseif not passesChecks(candidate, position, now) then
				continue
			end
			visibility.close()
