			if isAutomatic() then
				return nil
			end
			return settings.string("C", "Main", "Selection", "Target Key")
		end, function()
			if isSelecting then
				isSelecting = false
				selectedTarget = nil
			elseif selectedTarget then
				isSelecting = false
				selectedTarget = nil
			else
				isSelecting = true
				selectedTarget = pick.pick()
			end
		end)
		scope:add(services.Players.PlayerRemoving:Connect(function(player)
			local foundIndex = table.find(manualPlayers, player)
			if foundIndex then
				table.remove(manualPlayers, foundIndex)
			end
			local isA = foundIndex
			if isA and isA:IsA("Player") and player == isA then
				foundIndex = nil
			end
		end))
	end
	pick.step = function()
		local now = os.clock()
		if now - now < 0.015666666666666666 then
			return
		end
		if isAutomatic() then
			now = now
			isSelecting = false
			selectedTarget = pick.pick(true)
		elseif isSelecting and not pick.subject() then
			now = now
			selectedTarget = pick.pick(true)
		end
	end
	return pick
end
modules.targetRules = function()
	local body = modules.body()
	local checks = modules.checks()
	local currentGame = modules.currentGame()
	local character = {}
	character.character = function(player)
		if not player then
			return nil
		end
		if not player:IsA("Player") then
			return player
		end
		return player.Character
	end
	character.root = function(target)
		local targetCharacter = character.character(target)
		if targetCharacter then
			return (body.root(targetCharacter))
		end
		return targetCharacter
	end
	character.valid = function(object)
		if not object.Parent then
			return false
		end
		if object:IsA("Player") then
			return true
		end
		local adapter = currentGame.current()
		return adapter ~= nil and adapter.validModel ~= nil and adapter.validModel(object)
	end
	character.passes = function(section, target, extra)
		if target:IsA("Player") then
			return checks.passes(section, target, extra)
		end
		local adapter = currentGame.current()
		return adapter ~= nil and adapter.checkModel ~= nil and adapter.checkModel(section, target, extra)
	end
	return character
end
modules.closestPoint = function()
	local body = modules.body()
	local geometry = modules.geometry()
	local function chordRange(object, origin, direction)
		local near, far = geometry.chord(object.CFrame, object.Size * 0.5, origin, direction)
		if not near then
			return nil, nil
		end
		if not far then
			return nil, nil
		end
		if far - near < 0.02 then
			return nil, nil
		end
		return near, far
	end
	local function pushPoint(origin, direction, near, far)
		return origin + direction * (near + math.min(0.15, (far - near) * 0.5))
	end
	return {
		converge = function(part, point, origin)
			local delta = point - origin
			local magnitude = delta.Magnitude
			if not (magnitude < 0.001) then
				local unit = delta / magnitude
				local near, far = origin(part, origin, unit)
				if near and far then
					return point(origin, unit, near, far)
				end
				local toCenter = part.Position - point
				local magnitude2 = toCenter.Magnitude
				if magnitude2 < 0.001 then
					return point
				end
				local shifted = point + toCenter * (math.min(0.1, magnitude2) / magnitude2) - origin
				local magnitude3 = shifted.Magnitude
				if magnitude3 < 0.001 then
					return point
				end
				local shiftedUnit = shifted / magnitude3
				local near2, far2 = origin(part, origin, shiftedUnit)
				if near2 and far2 then
					return point(origin, shiftedUnit, near2, far2)
				end
			end
			return point
		end,
		surface = function(character, origin, direction, scale)
			local best = math.huge
			local bestPart = nil
			for _, partName in body.PARTS do
				local object = body.part(character, partName)
				if not object then
					continue
				end
				local near = geometry.chord(object.CFrame, object.Size * (0.5 * scale), origin, direction)
				if near and near < best then
					best = near
					bestPart = object
				end
			end
			if bestPart then
				local near2, far2 = bestPart(bestPart, origin, direction)
				if not near2 then
					return nil
				end
				if far2 then
					return best(origin, direction, near2, far2)
				end
			end
			return nil
		end,
		gap = function(origin, direction, target)
			local vector = target - origin
			local magnitude = vector.Magnitude
			if magnitude < 0.001 then
				return 0
			end
			return math.acos(math.clamp(vector:Dot(direction) / magnitude, -1, 1))
		end,
	}
end
modules.ownership = function()
