	return {
		claim = function(object, scope)
			local existing = owners[object]
			if scope:isDestroyed() then
				return false
			end
			if existing and existing ~= scope and not existing:isDestroyed() then
				return false
			end
			owners[object] = scope
			return true
		end,
		isOwner = function(object, scope)
			return owners[object] == scope
		end,
		has = function(object)
			local owner = owners[object]
			local hasOwner = owner ~= nil
			if owner ~= nil then
				local destroyed = owner:isDestroyed()
				hasOwner = not destroyed
				if not destroyed then
					return object.Parent ~= nil
				end
			end
			return hasOwner
		end,
		release = function(object, scope)
			if owners[object] == scope then
				owners[object] = nil
			end
		end,
	}
end
