			local adapter = currentGame.current()
			local priority
			if adapter then
				priority = adapter.aimAssist
			else
				priority = adapter
			end
			local renderPriority = Enum.RenderPriority.Camera.Value + 1
			if priority then
				renderPriority = priority.priority
			end
			services.RunService:BindToRenderStep("AtomicAimAssist", renderPriority, function(deltaTime)
