modules.mouseAim = function()
	local easing = modules.easing()
	local currentGame = modules.currentGame()
	local services = modules.services()
	local function stringOrFallback(value, fallback)
		if type(value) ~= "string" then
			return fallback
		end
		return value
	end
	local function readEasing(method)
		return easing.style(stringOrFallback(method["Easing Style"], "Linear")), easing.direction(stringOrFallback(method["Easing Direction"], "InOut"))
	end
	local function snappinessOf(method)
		local snappiness = method.Snappiness
		if type(snappiness) ~= "number" then
			snappiness = 0.08
		elseif snappiness ~= snappiness then
			snappiness = 0.08
		else
			local magnitude = math.abs(snappiness)
			if math.huge <= magnitude then
				snappiness = 0.08
			end
		end
		return math.clamp(snappiness, 0, 1)
	end
	local function easeAmount(deltaTime, target, method)
		if not (0 < deltaTime) then
			return 0
		end
		if not (deltaTime < math.huge) then
			return 0
		end
		local snappiness = snappinessOf(method)
		if snappiness <= 0 then
		end
		if 1 <= snappiness then
			deltaTime = nil
			return 1
		end
		local style, direction = readEasing(method)
		if deltaTime ~= target or style ~= style or direction ~= direction or target ~= snappiness then
			deltaTime = target
			snappiness = 0
			style = style
			direction = direction
			target = snappiness
			method = easing.value(0, style, direction)
		end
		local speed = deltaTime * 60
		if snappiness < 1 then
			local previous = snappiness
			snappiness = math.min(1, snappiness + speed * snappiness)
			local eased = easing.value(snappiness, style, direction)
			speed = speed + (eased - method - (snappiness - previous)) / snappiness
			method = eased
		end
		return math.clamp(1 - (1 - snappiness) ^ speed, -1, 2)
	end
	local function steerCamera(object, target, amount)
		local cframe = object.CFrame
		local position = cframe.Position
		local vector = target - position
		if vector.Magnitude < 0.0001 then
			return
		end
		local lookVector = cframe.LookVector
		local steered = lookVector:Lerp(vector.Unit, amount)
		if steered.Magnitude < 0.0001 then
			return
		end
		local unit = steered.Unit
		if not (1 - lookVector:Dot(unit) < 1e-8) then
			object.CFrame = CFrame.lookAt(position, position + unit)
		end
	end
	local function moveMouse(camera, target, amount)
		local point, onScreen = camera:WorldToViewportPoint(target)
		if not onScreen then
			return
		end
		local mouseLocation = services.UserInputService:GetMouseLocation()
		local deltaX = (point.X - mouseLocation.X) * amount
		local deltaY = (point.Y - mouseLocation.Y) * amount
		if deltaX * deltaX + deltaY * deltaY < 0.25 then
			return
		end
		local active, inactive = pcall(isrbxactive)
		if not (active and inactive == false) then
			pcall(mousemoverel, deltaX, deltaY)
		end
	end
	return {
		release = function()
			local adapter = currentGame.current()
			if adapter and adapter.aimAssist then
				adapter.aimAssist.release()
			end
		end,
		step = function(deltaTime, target, aimPoint, method)
			local amount = easeAmount(deltaTime, target, method)
			if amount == 0 then
				return
			end
			local adapter = currentGame.current()
			if adapter and adapter.aimAssist then
				if not adapter.aimAssist.steer(aimPoint, amount, deltaTime, method.Method == "Mouse") then
					amount = nil
				end
			else
				local currentCamera = services.Workspace.CurrentCamera
				if method.Method == "Mouse" then
					moveMouse(currentCamera, aimPoint, amount)
				else
					steerCamera(currentCamera, aimPoint, amount)
				end
			end
		end,
	}
end
modules.easing = function()
	local services = modules.services()
	local styles = {}
	for _, enumItem in Enum.EasingStyle:GetEnumItems() do
		styles[string.lower(enumItem.Name)] = enumItem
	end
	local directions = {}
	for _, enumItem in Enum.EasingDirection:GetEnumItems() do
		directions[string.lower(enumItem.Name)] = enumItem
	end
	local normalizedNames = {}
	local function normalizeName(name)
		local cached = normalizedNames[name]
		if cached then
			return cached
		end
		local normalized = string.lower((string.gsub(name, "%s+", "")))
		normalizedNames[name] = normalized
		return normalized
	end
	return {
		style = function(name)
			if name then
				local style = styles[normalizeName(name)]
				if style then
					return style
				end
			end
			return Enum.EasingStyle.Linear
		end,
		direction = function(name)
			if name then
				local direction = directions[normalizeName(name)]
				if direction then
					return direction
				end
			end
			return Enum.EasingDirection.InOut
		end,
		value = function(progress, style, direction)
			return services.TweenService:GetValue(math.clamp(progress, 0, 1), style, direction)
		end,
	}
end
