		local maxResidual = 0
		local firstIndex = startIndex - 1
		local finalIndex = sampleCount - 1
		local endIndex = finalIndex + 0
		for index = firstIndex + 1, endIndex do
			local slotIndex = history.slot(samples, index)
			maxResidual = math.max(maxResidual, (samples.positions[slotIndex] * horizontal - basePosition - intercept - velocity * (samples.times[slotIndex] - baseTime)).Magnitude)
