		end
		if referenceMagnitude < 0.001 then
			return false
		end
		local speedRatio = magnitude / referenceMagnitude
		return speedRatio >= 0.5 and speedRatio <= 2 and vector.Unit:Dot(reference.Unit) > 0.85
	end
