		if samples.count < index + 2 then
			return nil
		end
		local firstSlot = history.slot(samples, index)
		local secondSlot = history.slot(samples, index + 1)
		local deltaTime = samples.times[firstSlot] - samples.times[secondSlot]
		if deltaTime <= 0 then
