			local cursor = nextIndex
			scanIndex = nextIndex
			while true do
				local slotIndex = history.slot(samples, cursor)
				if 0.3 < now - samples.times[slotIndex] and 3 <= sampleCount then
					finished = -1
					break
				end
				local relativeTime = samples.times[slotIndex] - baseTime
				local weight = 1 / (cursor + 1)
				local position = samples.positions[slotIndex] * horizontal
				weightSum = weightSum + weight
				weightedTimeSum = weightedTimeSum + weight * relativeTime
				weightedTimeSquaredSum = weightedTimeSquaredSum + weight * relativeTime * relativeTime
