	local function detectArc(samples)
		local count = 0
		for index = 0, samples.count - 1 do
			local slotIndex = history.slot(samples, index)
			local sampleTime = samples.times[slotIndex]
			if not (count == 0 or recentTimes[count] - sampleTime >= 0.02499999) then
