modules.antiAimDetect = function()
	local history = modules.unnamed_aa()
	local horizontal = history.HORIZONTAL
	return {
		detect = function(samples, now)
			if samples.count < 6 then
				return nil, Vector3.zero
			end
			local sumDisplacement = Vector3.zero
			local sumPositions = Vector3.zero
			local flips = 0
			local measured = 0
			local sampleCount = 0
			local lastIndex = samples.count - 2
			local pathLength = 0
			local unit = nil
			local lastDirection = 0
			local firstIndex = sampleCount - 1
			local endIndex = lastIndex + 0
			local scanIndex = firstIndex
			local finished
			repeat
				local nextIndex = scanIndex + 1
				if not (nextIndex <= endIndex) then
					break
				end
				local cursor = nextIndex
				scanIndex = nextIndex
				while true do
					local slotA = history.slot(samples, cursor)
					local slotB = history.slot(samples, cursor + 1)
					if 0.45 < now - samples.times[slotB] then
						finished = -1
						break
					end
					local displacement = (samples.positions[slotA] - samples.positions[slotB]) * horizontal
					local magnitude = displacement.Magnitude
					sumDisplacement = sumDisplacement + displacement
					pathLength = pathLength + magnitude
					sumPositions = sumPositions + samples.positions[slotA] * horizontal
					measured = cursor + 1
					if not (0.05 < magnitude) then
						break
					end
					if not unit then
						unit = displacement.Unit
					end
					local projection = displacement:Dot(unit)
					local direction
					if 0 < projection then
						direction = 1
					else
						if not (projection < 0) then
							local following = scanIndex + 1
							if not (following <= endIndex) then
								finished = -1
								break
							end
							cursor = following
							scanIndex = following
							continue
						end
						direction = -1
					end
					if lastDirection ~= 0 then
						if direction ~= lastDirection then
							flips = flips + 1
							if direction == 0 then
								break
							end
						elseif direction == 0 then
							local following = scanIndex + 1
							if not (following <= endIndex) then
								finished = -1
								break
							end
							cursor = following
							scanIndex = following
							continue
						end
					elseif direction == 0 then
						local following = scanIndex + 1
						if not (following <= endIndex) then
							finished = -1
							break
						end
						cursor = following
						scanIndex = following
						continue
					end
					lastDirection = direction
					local following = scanIndex + 1
					if not (following <= endIndex) then
						finished = -1
						break
					end
					cursor = following
					scanIndex = following
				end
			until finished == -1
			if measured + 1 < 6 then
				return nil, Vector3.zero
			end
			if pathLength < 0.001 then
				return nil, Vector3.zero
			end
			if 0.5 < sumDisplacement.Magnitude / pathLength then
				return nil, Vector3.zero
			end
			if flips < 2 then
				return nil, Vector3.zero
			end
			return null_stub()
		end,
	}
end
modules.ping = function()
	modules.scope()
	local services = modules.services()
	local samples = {}
	samples[1] = 0
	samples[2] = 0
	samples[3] = 0
	local sampleCount = 0
	local writeIndex = 0
	local smoothedPing = nil
	local lastSource = nil
	local lastSampleAt = 0
	local running = false
	local function readStatsPing()
		local network = services.Stats:FindFirstChild("Network")
		if network then
			local serverStatsItem = network:FindFirstChild("ServerStatsItem")
			if serverStatsItem then
				local dataPing = serverStatsItem:FindFirstChild("Data Ping")
				if dataPing then
					if dataPing:IsA("StatsItem") then
						local ok, pingValue = pcall(dataPing.GetValue, dataPing)
						if ok and type(pingValue) == "number" and 0 < pingValue then
							return pingValue / 1000
						end
					end
					return nil
				end
			end
		end
		return nil
	end
	local function samplePing()
		local statsPing = readStatsPing()
		if statsPing then
			return statsPing, true
		end
		return services.Players.LocalPlayer:GetNetworkPing() * 2, false
	end
	local function resetSamples()
		sampleCount = 0
		writeIndex = 0
		smoothedPing = nil
	end
	local function medianSample()
		if sampleCount < 3 then
			return samples[sampleCount]
		end
		local first = samples[1]
		local second = samples[2]
		return math.max(math.min(first, second), math.min(math.max(first, second), samples[3]))
	end
	local function recordSample()
		local pingValue, isStats = samplePing()
		local now = os.clock()
		if isStats ~= lastSource then
			resetSamples()
		elseif 0.5 < now - lastSampleAt then
			resetSamples()
		end
		lastSource = isStats
		lastSampleAt = now
		if not pingValue then
			return
		end
		writeIndex = writeIndex % 3 + 1
		sampleCount = math.min(sampleCount + 1, 3)
		samples[writeIndex] = pingValue
		local median = medianSample()
		local previous = median
		if previous then
			smoothedPing = median + (median - previous) * 0.3
		else
			smoothedPing = median
		end
	end
	return {
		start = function(scope)
			if running then
				return
			end
			running = true
			scope:add(function()
				running = false
			end)
			scope:add(task.spawn(function()
				local active = running
				while active do
					recordSample()
					task.wait(0.1)
					active = running
				end
			end))
		end,
		roundTrip = function()
			local currentPing = smoothedPing
			if not smoothedPing then
				currentPing = samplePing()
				if not currentPing then
					return 0
				end
			end
			return currentPing
		end,
	}
end
modules.unnamed_af = function()
	local history = modules.unnamed_aa()
	local horizontal = history.HORIZONTAL
	local update = {}
	local function fitSpeedGain(samples, startCount, endCount)
		local sumDisplacement = Vector3.zero
		local sumReported = Vector3.zero
		local lastIndex = endCount - 1
		local crossSum = 0
		local reportedSqSum = 0
		local displacementSqSum = 0
		local firstIndex = startCount - 1
		local finalIndex = lastIndex + 0
		local scanIndex = firstIndex
		while true do
			local nextIndex = scanIndex + 1
			if not (nextIndex <= finalIndex) then
				break
			end
			local cursor = nextIndex
			scanIndex = nextIndex
			while true do
				local slotA = history.slot(samples, cursor)
				local slotB = history.slot(samples, cursor + 1)
				local deltaTime = samples.times[slotA] - samples.times[slotB]
				if not (0 < deltaTime) then
					break
				end
				local displacement = (samples.positions[slotA] - samples.positions[slotB]) * horizontal
				local reported = samples.reported[slotA] * horizontal * deltaTime
				crossSum = crossSum + displacement:Dot(reported)
				reportedSqSum = reportedSqSum + reported:Dot(reported)
				displacementSqSum = displacementSqSum + displacement:Dot(displacement)
				sumDisplacement = sumDisplacement + displacement
				sumReported = sumReported + reported
				local following = scanIndex + 1
				if following <= finalIndex then
					cursor = following
					scanIndex = following
					continue
				end
				if reportedSqSum < 1e-6 then
					return nil, 0, sumDisplacement, sumReported
				end
				if displacementSqSum < 1e-6 then
					return nil, 0, sumDisplacement, sumReported
				end
				local gain = crossSum / reportedSqSum
				return gain, 1 - (displacementSqSum - 2 * gain * crossSum + gain * gain * reportedSqSum) / displacementSqSum, sumDisplacement, sumReported
			end
		end
		if reportedSqSum < 1e-6 then
			return nil, 0, sumDisplacement, sumReported
		end
		if displacementSqSum < 1e-6 then
			return nil, 0, sumDisplacement, sumReported
		end
		local gain = crossSum / reportedSqSum
		return gain, 1 - (displacementSqSum - 2 * gain * crossSum + gain * gain * reportedSqSum) / displacementSqSum, sumDisplacement, sumReported
	end
	local function hasConsistentSpeed(samples)
		if samples.count < 5 then
			return nil
		end
		local newestTime = samples.times[history.slot(samples, 0)]
		local count = 1
		for index = 1, samples.count - 1 do
			local delta = newestTime - samples.times[history.slot(samples, index)]
			if 0.16 < delta then
				break
			end
			count = index + 1
		end
		if count < 5 then
			return nil
		end
		if newestTime - samples.times[history.slot(samples, count - 1)] < 0.1 then
			return nil
		end
		local midpoint = math.floor(count / 2)
		local firstGain, firstFit = fitSpeedGain(samples, 0, midpoint)
		local secondGain, secondFit = fitSpeedGain(samples, midpoint, count - 1)
		if not firstGain then
			return nil
		end
		if not secondGain then
			return nil
		end
		if firstFit < 0.95 then
			return nil
		end
		if secondFit < 0.95 then
			return nil
		end
		return null_stub(unpack(nil, 1, null_stub.n))
	end
	update.update = function(state, deltaTime)
		local gainDelta = hasConsistentSpeed(state)
		if gainDelta then
			state.isSpeedTrusted = true
			state.speedGain = state.speedGain + (gainDelta - state.speedGain) * (1 - math.exp(-deltaTime / 0.06))
		end
	end
	update.isHonest = function(state)
		local trusted = state.isSpeedTrusted
		local untrusted = not trusted
		if trusted then
			return math.abs(state.speedGain - 1) <= 0.25
		end
		return untrusted
	end
	update.corrected = function(state, velocity)
		if not state.isSpeedTrusted then
			return velocity, 0.5
		end
		local confidence = 0.25
		if update.isHonest(state) then
			confidence = 0.5
		end
		return velocity * state.speedGain, confidence
	end
	return update
end
modules.unnamed_ag = function()
	return {
		horizon = "Atomic",
		accelerationModel = false,
		trajectoryRake = true,
		holdTick = false,
	}
end
modules.unnamed_ai = function()
	local function semiProfile(seed, muzzleOffset)
		local profile = { mode = "Semi", muzzleOffset = muzzleOffset, aimDistance = 200 }
		profile.fixedCooldown = nil
		profile.extraCooldown = 0
		return bit32.bxor(seed, 204996473), profile
	end
	local function shotgunProfile(offset, extraCooldown)
		local profile = {}
		profile.mode = "Shotgun"
		profile.muzzleOffset = offset
		profile.aimDistance = 200
		profile.fixedCooldown = nil
		profile.extraCooldown = extraCooldown
		return profile
	end
	local function automaticProfile(offset)
		local profile = { mode = "Automatic", muzzleOffset = offset }
		profile.aimDistance = 200
		profile.fixedCooldown = 0.6
		profile.extraCooldown = 0
		return profile
	end
	local profiles = {}
	local revolverArgs = table.pack(CFrame.new(-1, 0.4, 0))
	local factory = semiProfile
	local revolverCount = revolverArgs.n
	revolverArgs.n = 2 + revolverCount - 1
	table.move(revolverArgs, 1, revolverCount, 2, revolverArgs)
	revolverArgs[1] = 228018738
	local revolverSeed, revolver = factory(unpack(revolverArgs, 1, revolverArgs.n))
	profiles["[Revolver]"] = revolver
	local cframeFactory = CFrame.new
	local glockSeed
	repeat
		local deagleArgs = table.pack(cframeFactory(0, 0.382, -1.568))
		local deagleFactory = semiProfile
		local deagleCount = deagleArgs.n
		deagleArgs.n = 2 + deagleCount - 1
		table.move(deagleArgs, 1, deagleCount, 2, deagleArgs)
		deagleArgs[1] = 228018738
		local _, deagle = deagleFactory(unpack(deagleArgs, 1, deagleArgs.n))
		profiles["[Deagle]"] = deagle
		local glockArgs = table.pack(CFrame.new(0.6, 0.25, 0))
		local glockFactory = semiProfile
		local glockCount = glockArgs.n
		glockArgs.n = 2 + glockCount - 1
		table.move(glockArgs, 1, glockCount, 2, glockArgs)
		glockArgs[1] = 228018738
		glockSeed, profiles["[Glock]"] = glockFactory(unpack(glockArgs, 1, glockArgs.n))
		local silencerArgs = table.pack(CFrame.new(0, 0.4, 1.3))
		local silencerFactory = semiProfile
		local silencerCount = silencerArgs.n
		silencerArgs.n = 2 + silencerCount - 1
		table.move(silencerArgs, 1, silencerCount, 2, silencerArgs)
		silencerArgs[1] = 228018738
		local silencerSeed, silencer = silencerFactory(unpack(silencerArgs, 1, silencerArgs.n))
		cframeFactory = silencerSeed
		profiles["[Silencer]"] = silencer
	until revolverSeed + 17131091 ~= 347924091
	local rifle = {}
	rifle.mode = "Semi"
	rifle.muzzleOffset = CFrame.new(0, 0.25, 2.5)
	rifle.aimDistance = 50
	rifle.fixedCooldown = 1.3095
	rifle.extraCooldown = 0
	profiles["[Rifle]"] = rifle
	profiles["[TacticalShotgun]"] = shotgunProfile(CFrame.new(0, 0.25, -2.5), 0)
	profiles["[Shotgun]"] = {
		mode = "Shotgun",
		muzzleOffset = CFrame.new(0, 0.25, 2.5),
		aimDistance = 200,
		fixedCooldown = 1.2,
		extraCooldown = 0,
	}
	profiles["[Double-Barrel SG]"] = shotgunProfile(CFrame.new(0, 0.35, -2.2), 0.05)
	profiles["[AUG]"] = {
		mode = "Burst",
		muzzleOffset = CFrame.new(-0.1, 0.4, 1.8),
		aimDistance = 200,
		fixedCooldown = nil,
		extraCooldown = 0,
	}
	profiles["[SMG]"] = automaticProfile(CFrame.new(0, 1, 0.5))
	profiles["[P90]"] = automaticProfile(CFrame.new(0, 0.2, -1.7))
	profiles["[AR]"] = automaticProfile(CFrame.new(2, 0.35, 0))
	profiles["[SilencerAR]"] = automaticProfile(CFrame.new(2.5, 0.35, 0))
	profiles["[AK47]"] = automaticProfile(CFrame.new(-0.1, 0.5, -2.5))
	profiles["[LMG]"] = automaticProfile(CFrame.new(0, 0.7, -3.8))
	profiles["[DrumGun]"] = automaticProfile(CFrame.new(0, 0.4, 2.4))
	local flintlock = {}
	if glockSeed == 27309387 then
		flintlock.mode = "Semi"
		flintlock.muzzleOffset = CFrame.new(0, 0.382, -1.568)
		flintlock.aimDistance = 200
		flintlock.fixedCooldown = nil
		flintlock.extraCooldown = 0
		flintlock.blasts = true
		profiles["[Flintlock]"] = flintlock
		return {
			COOLDOWN_PADDING = 0.0095,
			FIXED_AMMO_PLACE_ID = 88976059384565,
			FIXED_AMMO = 5,
			profile = function(name)
				return profiles[name]
			end,
			muzzle = function(tool, object, profile)
				local default = tool:FindFirstChild("Default")
				if default then
					local mesh = default:FindFirstChild("Mesh")
					if mesh then
						local muzzle = mesh:FindFirstChild("Muzzle")
						if muzzle and muzzle:IsA("Attachment") then
							return muzzle.WorldPosition
						end
					end
				end
				return (object.CFrame * profile.muzzleOffset).Position
			end,
		}
	end
end
modules.avatar = function()
	local body = modules.body()
	local settings = modules.settings()
	local bodyPacks = modules.bodyPacks()
	local meshWriter = modules.meshWriter()
	local hoodGame = modules.hoodGame()
	local services = modules.services()
	local mod_item = modules.unnamed_am()
	local mod_apply = modules.unnamed_an()
	modules.unnamed_o()
	local localPlayer = services.Players.LocalPlayer
	local trackedCharacter = nil
	local currentKey = nil
	local function isEnabled(settingName)
		return settings.bool(false, "Character", "Avatar Changer", "Settings", settingName)
	end
	local function isCharacterReady(character)
		local dialect = hoodGame.current()
		local fullyLoaded = character:FindFirstChild("FULLY_LOADED_CHAR") ~= nil
		if dialect then
			if dialect.isReady(character) then
				if not character:FindFirstChild("Animate") then
					return false
				end
				for _, partName in body.PARTS do
					if not body.part(character, partName) then
						return false
					end
				end
				return body.root(character) ~= nil
			end
		elseif fullyLoaded then
			if not character:FindFirstChild("Animate") then
				return false
			end
			for _, partName in body.PARTS do
				if not body.part(character, partName) then
					return false
				end
			end
			return body.root(character) ~= nil
		end
		return false
	end
	local function animationSignature(character)
		local animate = character:FindFirstChild("Animate")
		if not animate then
			return ""
		end
		local names = {}
		for _, animation in animate:GetDescendants() do
			if not animation:IsA("Animation") then
				continue
			end
			table.insert(names, string.format("%s=%s", tostring(animation:GetFullName()), tostring(animation.AnimationId)))
		end
		table.sort(names)
		return table.concat(names, ";")
	end
	local function stopAnimations(character, humanoid)
		local animate = character:FindFirstChild("Animate")
		if animate and animate:IsA("LocalScript") then
			local animator = humanoid:FindFirstChildOfClass("Animator")
			if animator then
				for _, track in animator:GetPlayingAnimationTracks() do
					local animation = track.Animation
					if animation and animation:IsDescendantOf(animate) then
						animation:Stop(0)
					end
				end
			end
			animate.Enabled = false
			task.defer(function()
				if animate.Parent == character then
					animate.Enabled = true
				end
			end)
		end
	end
	local function resolveAvatar()
		local selected = settings.string("", "Character", "Avatar Changer", "Player")
		if not settings.bool(false, "Character", "Avatar Changer", "Enabled") then
			return nil, "off"
		end
		if selected == "" then
			return nil, "off"
		end
		local ready, name = mod_item.player(selected)
		local resolved
		if ready then
			resolved = name
		else
			resolved = string.format("%s:pending", tostring(name))
		end
		return ready, resolved
	end
	local function applyAvatar(character, humanoid, model)
		local oldSignature = animationSignature(character)
		meshWriter.restore()
		if model then
			mod_apply.apply(model, character, humanoid)
		end
		if isEnabled("Skinny") then
			if model then
				model = model:FindFirstChildOfClass("Humanoid")
			end
			if not model then
				model = humanoid
			end
			bodyPacks.skinny(character, model)
		end
		if isEnabled("Headless") then
			bodyPacks.headless(character)
		end
		if isEnabled("Korblox") then
			bodyPacks.korblox(character)
		end
		if animationSignature(character) ~= oldSignature then
			stopAnimations(character, humanoid)
		end
	end
	local function statusFor(itemName)
		if not isEnabled(itemName) then
			return "off"
		end
		if mod_item.item(itemName) then
			return "on"
		end
		return "pending"
	end
	local function refreshCharacter()
		local character = localPlayer.Character
		if character ~= trackedCharacter then
			meshWriter.forget()
			trackedCharacter = character
			currentKey = nil
		end
		if character then
			if not isCharacterReady(character) then
				return
			end
			local humanoid = character:FindFirstChildOfClass("Humanoid")
			if humanoid then
				local model, avatarName = resolveAvatar()
				local nameText = tostring(avatarName)
				local skinnyText = tostring(isEnabled("Skinny"))
				local headlessText = tostring(statusFor("Headless"))
				if headlessText then
					local n = table.pack(statusFor("Korblox"))
					local args = table.pack("%s|%s|%s|%s", nameText, skinnyText, headlessText, tostring(unpack(n, 1, n.n)))
					local key = string.format(unpack(args, 1, args.n))
					if not (model ~= key or meshWriter.drifted()) then
						return
					end
					applyAvatar(character, humanoid, model)
					currentKey = key
				end
			end
		end
	end
	local function clearTrackedState()
		local character = trackedCharacter
		local humanoid
		local signature
		if character then
			humanoid = character:FindFirstChildOfClass("Humanoid")
			signature = animationSignature(character)
		else
			signature = character
		end
		meshWriter.restore()
		if character and humanoid and animationSignature(character) ~= signature then
			stopAnimations(character, humanoid)
		end
	end
	local name = {}
	name.name = "Avatar"
	name.start = function(scope)
		local elapsed = 0.5
		scope:add(services.RunService.Heartbeat:Connect(function(delta)
			elapsed = elapsed + delta
			if 0.5 <= elapsed then
				elapsed = 0
				refreshCharacter()
			end
		end))
		scope:add(scope)
	end
	return name
end
modules.bodyPacks = function()
	local body = modules.body()
	local meshWriter = modules.meshWriter()
	local mod_item = modules.unnamed_am()
	local mod_apply = modules.unnamed_an()
	local legJoints = table.freeze({
		{ part = "RightUpperLeg", joint = "RightHipRigAttachment" },
		{ part = "RightLowerLeg", joint = "RightKneeRigAttachment" },
		{ part = "RightFoot", joint = "RightAnkleRigAttachment" },
	})
	local faceAccessories = {}
	faceAccessories[Enum.AccessoryType.Eyebrow] = true
	faceAccessories[Enum.AccessoryType.Eyelash] = true
	local ignoredAccessories = table.freeze(faceAccessories)
	local function readScale(character, scaleName)
		local scale = character:FindFirstChild(scaleName)
		local scaleValue
		if scale and scale:IsA("NumberValue") and 0 < scale.Value then
			scaleValue = scale.Value
		else
			scaleValue = 1
		end
		return scaleValue
	end
	local function scaleOffset(offset, widthScale, depthScale)
		return Vector3.new(offset.X * widthScale, offset.Y, offset.Z * depthScale)
	end
	local function scaleCFrame(rotation, widthScale, depthScale)
		return rotation.Rotation + scaleOffset(rotation.Position, widthScale, depthScale)
	end
	local function measureLeg(character)
		local upperLeg = body.part(character, "RightUpperLeg")
		local lowerLeg = body.part(character, "RightLowerLeg")
		local hipAttachment
		if upperLeg then
			hipAttachment = upperLeg:FindFirstChild("RightHipRigAttachment")
			upperLeg = upperLeg:FindFirstChild("RightKneeRigAttachment")
			if lowerLeg then
				local lowerKneeAttachment = lowerLeg:FindFirstChild("RightKneeRigAttachment")
				lowerLeg = lowerLeg:FindFirstChild("RightAnkleRigAttachment")
				if hipAttachment then
					if not hipAttachment:IsA("Attachment") then
						return nil
					end
					if not upperLeg then
						return nil
					end
					if not upperLeg:IsA("Attachment") then
						return nil
					end
					if not lowerKneeAttachment then
						return nil
					end
					if not lowerKneeAttachment:IsA("Attachment") then
						return nil
					end
					if not lowerLeg then
						return nil
					end
					if lowerLeg:IsA("Attachment") then
						return (hipAttachment.Position - upperLeg.Position).Magnitude + (lowerKneeAttachment.Position - lowerLeg.Position).Magnitude
					end
				end
				return nil
			end
		else
			hipAttachment = upperLeg
			if lowerLeg then
				lowerLeg = lowerLeg:FindFirstChild("RightAnkleRigAttachment")
				return nil
			end
		end
		local ankleAttachment = lowerLeg
		if hipAttachment then
			if not hipAttachment:IsA("Attachment") then
				return nil
			end
			if not upperLeg then
				return nil
			end
			if not upperLeg:IsA("Attachment") then
				return nil
			end
			if not ankleAttachment then
				return nil
			end
			if not ankleAttachment:IsA("Attachment") then
				return nil
			end
			if not lowerLeg then
				return nil
			end
			if lowerLeg:IsA("Attachment") then
				return (hipAttachment.Position - upperLeg.Position).Magnitude + (ankleAttachment.Position - lowerLeg.Position).Magnitude
			end
		end
		return nil
	end
	local function scalePosition(rotation, scale)
		return rotation.Rotation + rotation.Position * scale
	end
	local function makeKorbloxPart(part, scale)
		local shell = part:Clone()
		shell:ClearAllChildren()
		for _, surfaceAppearance in part:GetChildren() do
			if surfaceAppearance:IsA("SurfaceAppearance") then
				surfaceAppearance:Clone().Parent = shell
			end
		end
		shell.Name = "AtomicKorblox"
		shell.Size = part.Size * scale
		shell.Anchored = false
		shell.CanCollide = false
		shell.CanQuery = false
		shell.CanTouch = false
		shell.Massless = true
		return shell
	end
	return {
		skinny = function(character, humanoid)
			local widthScale = math.min(1, 0.52 / readScale(humanoid, "BodyWidthScale"))
			local depthScale = math.min(1, 0.52 / readScale(humanoid, "BodyDepthScale"))
			if 1 <= widthScale and 1 <= depthScale then
				return
			end
			local affectedParts = {}
			local parts = body.PARTS
			local iterator = coroutine.wrap(lph_generic_for)
			iterator(parts, nil, nil)
			local nextEntry = iterator
			while true do
				local active, _, partName = nextEntry()
				if not active then
					break
				end
				local part
				if partName ~= "Head" then
					part = body.part(character, partName)
				else
					part = nil
				end
				if not part then
					continue
				end
				affectedParts[part] = true
				meshWriter.write(part, "Size", scaleOffset(part.Size, widthScale, depthScale))
				for _, attachment in part:GetChildren() do
					if not attachment:IsA("Attachment") then
						continue
					end
					meshWriter.write(attachment, "CFrame", scaleCFrame(attachment.CFrame, widthScale, depthScale))
				end
			end
			for _, joint in character:GetDescendants() do
				if not joint:IsA("JointInstance") then
					continue
				end
				local part0 = joint.Part0
				local part1 = joint.Part1
				if part0 and affectedParts[part0] then
					meshWriter.write(part0, "C0", scaleCFrame(part0.C0, widthScale, depthScale))
				end
				if not part1 then
					continue
				end
				if not affectedParts[part1] then
					continue
				end
				meshWriter.write(part0, "C1", scaleCFrame(part0.C1, widthScale, depthScale))
			end
		end,
		headless = function(character)
			local sourceItem = mod_item.item("Headless")
			local sourceHead
			if sourceItem then
				sourceHead = body.part(sourceItem, "Head")
			else
				sourceHead = sourceItem
			end
			local head = body.part(character, "Head")
			if not sourceHead then
				return false
			end
			if not head then
				return false
			end
			if sourceHead:IsA("MeshPart") and head:IsA("MeshPart") and mod_apply.mesh(head, sourceHead) ~= nil then
				meshWriter.write(head, "TextureID", sourceHead.TextureID)
			else
				meshWriter.write(head, "Transparency", 1)
			end
			for _, child in head:GetChildren() do
				if child:IsA("Decal") then
					meshWriter.detach(child)
				elseif child:IsA("FaceControls") then
					meshWriter.detach(child)
				end
			end
			for _, accessory in character:GetChildren() do
				if accessory:IsA("Accessory") and ignoredAccessories[accessory.AccessoryType] then
					meshWriter.detach(accessory)
				end
			end
			return true
		end,
		korblox = function(character)
			local sourceModel = mod_item.item("Korblox")
			local sourceLength
			if sourceModel then
				sourceLength = measureLeg(sourceModel)
			else
				sourceLength = sourceModel
			end
			local targetLength = measureLeg(character)
			if not sourceModel then
				return false
			end
			if not sourceLength then
				return false
			end
			if not targetLength then
				return false
			end
			if sourceLength <= 0 then
				return false
			end
			local scale = targetLength / sourceLength
			for _, jointSpec in sourceModel do
				local sourcePart = body.part(sourceModel, jointSpec.part)
				local targetPart = body.part(character, jointSpec.part)
				local sourceJoint
				if sourcePart then
					sourceJoint = sourcePart:FindFirstChild(jointSpec.joint)
					if targetPart then
						local targetJoint = targetPart:FindFirstChild(jointSpec.joint)
						if targetPart and sourceJoint and sourceJoint:IsA("Attachment") and targetJoint and targetJoint:IsA("Attachment") then
							local shell = makeKorbloxPart(sourcePart, scale)
							local inverse = scaleCFrame(sourceJoint.CFrame, scale)
							shell.CFrame = targetPart.CFrame * targetJoint.CFrame * inverse:Inverse()
							local weld = Instance.new("Weld")
							weld.Part0 = targetPart
							weld.Part1 = shell
							weld.C0 = targetJoint.CFrame
							weld.C1 = inverse
							weld.Parent = shell
							meshWriter.attach(shell, character)
							meshWriter.write(targetPart, "Transparency", 1)
						end
						continue
					end
				else
					sourceJoint = sourcePart
					if targetPart then
						continue
					end
				end
				if not sourcePart then
					continue
				end
				if not (targetPart and sourceJoint and sourceJoint:IsA("Attachment") and targetPart and targetPart:IsA("Attachment")) then
					continue
				end
				local shell = makeKorbloxPart(sourcePart, scale)
				local inverse = scaleCFrame(sourceJoint.CFrame, scale)
				shell.CFrame = targetPart.CFrame * targetPart.CFrame * inverse:Inverse()
				local fallbackWeld = Instance.new("Weld")
				fallbackWeld.Part0 = targetPart
				fallbackWeld.Part1 = shell
				fallbackWeld.C0 = targetPart.CFrame
				fallbackWeld.C1 = inverse
				fallbackWeld.Parent = shell
				meshWriter.attach(shell, character)
				meshWriter.write(targetPart, "Transparency", 1)
			end
			return true
		end,
	}
end
modules.meshWriter = function()
	local allChanges = {}
	local changesByObject = {}
	local templates = {}
	local detached = {}
	local attached = {}
	local undos = {}
	local function readProperty(object, property)
		local ok, propertyValue = pcall(function()
			return object[property]
		end)
		local wrapped
		if ok then
			wrapped = { propertyValue }
		else
			wrapped = { nil }
		end
		return wrapped[1]
	end
	local function writeProperty(object, property, newValue)
		pcall(function()
			object[property] = newValue
		end)
	end
	local function tryApplyMesh(target, mesh)
		return (pcall(function()
			target:ApplyMesh(mesh)
		end))
	end
	local function emptyClone(clone)
		local shell = clone:Clone()
		shell:ClearAllChildren()
		return shell
	end
	local function clearAll()
		table.clear(allChanges)
		table.clear(changesByObject)
		table.clear(templates)
		table.clear(detached)
		table.clear(attached)
		table.clear(undos)
	end
	return {
		write = function(object, property, newValue)
			local objectChanges = changesByObject[object]
			if not objectChanges then
				objectChanges = {}
				changesByObject[object] = objectChanges
			end
			local change = objectChanges[property]
			if not change then
				change = { object = object, property = property, original = readProperty(object, property), written = nil }
				objectChanges[property] = change
				table.insert(allChanges, change)
			end
			writeProperty(object, property, newValue)
			change.written = readProperty(object, property)
		end,
		mesh = function(meshPart, source)
			local existing = templates[meshPart]
			if existing then
				local destroy = existing.template
				if not (tryApplyMesh(meshPart, source) and meshPart.MeshId == source.MeshId) then
					if destroy then
						destroy:Destroy()
					end
					return false
				end
				if destroy then
					templates[meshPart] = { template = destroy, written = meshPart.MeshId }
				else
					existing.written = meshPart.MeshId
				end
			else
				local clone = emptyClone(meshPart)
				if not (tryApplyMesh(meshPart, source) and meshPart.MeshId == source.MeshId) then
					if clone then
						clone:Destroy()
					end
					return false
				end
				if clone then
					templates[meshPart] = { template = clone, written = meshPart.MeshId }
				end
				return true
			end
			return true
		end,
		detach = function(object)
			local parent = object.Parent
			if parent then
				table.insert(detached, { instance = object, parent = parent })
				object.Parent = nil
			end
		end,
		attach = function(object, parent)
			object.Parent = parent
			table.insert(attached, object)
		end,
		track = function(object)
			table.insert(attached, object)
		end,
		undo = function(key, undoFn)
			if not undos[key] then
				undos[key] = undoFn
			end
		end,
		restore = function()
			local attachedCount = #attached
			local start = 1
			local step = -1 + 0
			local count = attachedCount - step
			local index = start + 0
			local final = count + step
			if final >= index then
				local cursor = final
				local loop = final
				while true do
					attached[cursor]:Destroy()
					local nextCursor = loop + step
					if not (nextCursor >= index) then
						break
					end
					cursor = nextCursor
					loop = nextCursor
				end
			end
			for meshPart, record in templates do
				if meshPart.MeshId == record.written then
					tryApplyMesh(meshPart, record.template)
				end
				record.template:Destroy()
			end
			local changeCount = #allChanges
			local first = 1
			local delta = -1 + 0
			local remaining = changeCount - delta
			local lower = first + 0
			local upper = remaining
			local done
			repeat
				local nextIndex = upper + delta
				if not (nextIndex >= lower) then
					break
				end
				local cursor = nextIndex
				upper = nextIndex
				while true do
					local change = allChanges[cursor]
					if readProperty(change.object, change.property) ~= change.written then
						break
					end
					writeProperty(change.object, change.property, change.original)
					local following = upper + delta
					if not (following >= lower) then
						done = -1
						break
					end
					cursor = following
					upper = following
				end
			until done == -1
			local detachDone = nil
			local detachCount = #detached
			local detachStep = -1 + 0
			local detachRemaining = detachCount - detachStep
			repeat
				local position = detachRemaining + detachStep
				if detachStep <= 0 then
					if not (position >= 1) then
						break
					end
				elseif not (position <= 1) then
					break
				end
				local cursor = position
				detachRemaining = position
				while true do
					local record = detached[cursor]
					if record.instance.Parent ~= nil then
						break
					end
					if record.parent.Parent ~= nil then
						record.instance.Parent = record.parent
					end
					local following = detachRemaining + detachStep
					if detachStep <= 0 then
						if not (following >= 1) then
							detachDone = -1
							break
						end
					elseif not (following <= 1) then
						detachDone = -1
						break
					end
					cursor = following
					detachRemaining = following
				end
			until detachDone == -1
			for _, undoFn in undos do
				pcall(undoFn)
			end
			clearAll()
		end,
		forget = function()
			for _, record in templates do
				record.template:Destroy()
			end
			for _, instance in attached do
				instance:Destroy()
			end
			clearAll()
		end,
		drifted = function()
			local changed = false
			for _, change in allChanges do
				local current = readProperty(change.object, change.property)
				if current ~= change.written then
					change.original = current
					change.written = current
					changed = true
				end
			end
			for meshPart, record in templates do
				if meshPart.MeshId == record.written then
					continue
				end
				record.template:Destroy()
				record.template = emptyClone(meshPart)
				record.written = meshPart.MeshId
				changed = true
			end
			return changed
		end,
	}
end
modules.unnamed_am = function()
	local services = modules.services()
	local profiles = {}
	profiles.Headless = { field = "Head", ids = { 134082579, 15093053680 } }
	profiles.Korblox = { field = "RightLeg", ids = { 139607718 } }
	local players = services.Players
	local cache = {}
	local pending = {}
	local failed = {}
	local function resolveUserId(name)
		local numeric = tonumber(name)
		if numeric then
			return numeric
		end
		local ok, id = pcall(players.GetUserIdFromNameAsync, players, name)
		local resolved
		if ok and type(id) == "number" then
			resolved = { id }
		else
			resolved = { nil }
		end
		return resolved[1]
	end
	local function getDescription(userId)
		local ok, description = pcall(players.GetHumanoidDescriptionFromUserIdAsync, players, userId)
		if ok and description then
			return description
		end
		local okLegacy, legacy = pcall(players.GetHumanoidDescriptionFromUserId, players, userId)
		return if okLegacy and typeof(legacy) == "Instance" then legacy else nil
	end
	local function createModel(description)
		local ok, model = pcall(players.CreateHumanoidModelFromDescriptionAsync, players, description, Enum.HumanoidRigType.R15)
		if ok and model then
			return model
		end
		local okLegacy, legacy = pcall(players.CreateHumanoidModelFromDescription, players, description, Enum.HumanoidRigType.R15)
		return if okLegacy and typeof(legacy) == "Instance" then legacy else nil
	end
	local function loadOrQueue(key, loader)
		local cached = cache[key]
		if cached then
			return cached
		end
		if pending[key] then
			return cached
		end
		local lastFailure = failed[key]
		if not (lastFailure and os.clock() - lastFailure < 15) then
			pending[key] = true
			task.spawn(function()
				local ok, loaded = pcall(loader)
				pending[key] = nil
				if ok and loaded then
					cache[key] = loaded
					failed[key] = nil
				else
					failed[key] = os.clock()
				end
			end)
		end
		return nil
	end
	return {
		player = function(name)
			local key = string.format("player:%s", tostring(string.lower(name)))
			return loadOrQueue(key, function()
				local userId = resolveUserId(name)
				if userId then
					local description = getDescription(userId)
					if description then
						return (createModel(description))
					end
				end
				return nil
			end), key
		end,
		item = function(itemName)
			local profile = profiles[itemName]
			return loadOrQueue(string.format("item:%s", tostring(itemName)), function()
				local found = nil
				for _, id in profile.ids, found do
					found = id
					local humanoidDescription = Instance.new("HumanoidDescription")
					local model
					if pcall(function()
						humanoidDescription[profile.field] = found
					end) then
						model = { (createModel(humanoidDescription)) }
					else
						model = { nil }
					end
					local created = model[1]
					humanoidDescription:Destroy()
					if created then
						return created
					end
				end
				return nil
			end)
		end,
	}
end
modules.unnamed_an = function()
	local body = modules
	local root = body.body()
	local meshWriter = modules.meshWriter()
	local surfaceClasses = table.freeze({
		SurfaceAppearance = true,
		WrapTarget = true,
		FaceControls = true,
	})
	local tableApi = table
	local shouldFreeze = not not body
	if body then
		shouldFreeze = tableApi.freeze
		tableApi = {
			Accessory = true,
			Shirt = true,
			Pants = true,
			ShirtGraphic = true,
			BodyColors = true,
		}
	end
	tableApi.CharacterMesh = true
	local classFilter = shouldFreeze(tableApi)
	local mesh = {}
	local function shouldProcess(object, isHead)
		local allowed = surfaceClasses[object.ClassName] == true
		if not (surfaceClasses[object.ClassName] == true) then
			if not isHead then
				return isHead
			end
			allowed = object:IsA("Decal")
			if allowed then
				return object.Name == "face"
			end
		end
		return allowed
	end
	mesh.mesh = function(meshPart, object)
		if meshPart.MeshId == object.MeshId then
			return object.Size
		end
		if meshWriter.mesh(meshPart, object) then
			return object.Size
		end
		meshWriter.write(meshPart, "MeshId", object.MeshId)
		if meshPart.MeshId ~= object.MeshId then
			return nil
		end
		local meshSize = meshPart.MeshSize
		local sourceMeshSize = object.MeshSize
		if sourceMeshSize.X <= 0 then
			return object.Size
		end
		if sourceMeshSize.Y <= 0 then
			return object.Size
		end
		if sourceMeshSize.Z <= 0 then
			return object.Size
		end
		return object.Size * meshSize / sourceMeshSize
	end
	local function syncChildren(source, target)
		for _, child in target:GetChildren() do
			if shouldProcess(child, target.Name == "Head") then
				meshWriter.detach(child)
			end
		end
		for _, clone in source:GetChildren() do
			if shouldProcess(clone, target.Name == "Head") then
				meshWriter.attach(clone:Clone(), target)
			end
		end
	end
	local function syncAttachments(source, target)
		for _, attachment in source:GetChildren() do
			if not attachment:IsA("Attachment") then
				continue
			end
			local existing = target:FindFirstChild(attachment.Name)
			if existing and existing:IsA("Attachment") then
				meshWriter.write(existing, "CFrame", attachment.CFrame)
			elseif not existing then
				local shell = attachment:Clone()
				shell:ClearAllChildren()
				meshWriter.attach(shell, target)
			end
		end
	end
	local function syncMotors(source, target)
		for _, motor in target:GetChildren() do
			if not motor:IsA("Motor6D") then
				continue
			end
			local existing = source:FindFirstChild(motor.Name)
			if existing and existing:IsA("Motor6D") then
				meshWriter.write(motor, "C0", existing.C0)
				meshWriter.write(motor, "C1", existing.C1)
			end
		end
	end
	local function syncPart(source, target, copyColor)
		if copyColor then
			meshWriter.write(target, "Color", source.Color)
		end
		if source:IsA("MeshPart") and target:IsA("MeshPart") then
			local size = mesh.mesh(target, source)
			if not size then
				return
			end
			meshWriter.write(target, "Size", size)
			meshWriter.write(target, "TextureID", source.TextureID)
		else
			meshWriter.write(target, "Size", source.Size)
		end
		repeat
			syncChildren(source, target)
			syncAttachments(source, target)
		until syncAttachments
		syncMotors(source, target)
	end
	local function clearAccessoryJoints(accessory)
		local handle = accessory:FindFirstChild("Handle")
		if not handle then
			return
		end
		for _, joint in handle:GetChildren() do
			if joint:IsA("JointInstance") then
				joint:Destroy()
			elseif joint:IsA("WeldConstraint") then
				joint:Destroy()
			end
		end
	end
	local function syncAccessories(source, target, humanoid)
		for _, object in target:GetChildren() do
			if classFilter[object.ClassName] then
				meshWriter.detach(object)
			end
		end
		for _, clone in source:GetChildren() do
			if not classFilter[clone.ClassName] then
				continue
			end
			local accessory = clone:Clone()
			if accessory:IsA("Accessory") then
				clearAccessoryJoints(accessory)
				if pcall(humanoid.AddAccessory, humanoid, accessory) then
					if accessory.Parent then
						meshWriter.track(accessory)
					else
						meshWriter.attach(accessory, target)
					end
				else
					meshWriter.attach(accessory, target)
				end
			else
				meshWriter.attach(accessory, target)
			end
		end
	end
	local function collectAnimations(container)
		local animations = {}
		for _, animation in container:GetChildren() do
			if animation:IsA("Animation") then
				table.insert(animations, animation)
			end
		end
		return animations
	end
	local function syncAnimationIds(sourceModel, character)
		local animate = sourceModel:FindFirstChild("Animate")
		local characterAnimate = character:FindFirstChild("Animate")
		if not (animate and characterAnimate) then
			if 6483 > 6460 then
				return
			end
		end
		local first, second, third = animate:GetChildren()
		local iterator = coroutine.wrap(lph_generic_for)
		iterator(first, second, third)
		local nextEntry = iterator
		while true do
			local active, _, child = nextEntry()
			if not active then
				break
			end
			local matches
			if child:IsA("StringValue") then
				matches = { (characterAnimate:FindFirstChild(child.Name)) }
			else
				matches = { nil }
			end
			local match = matches[1]
			if not match then
				continue
			end
			local modelAnimations = collectAnimations(child)
			for index, object in collectAnimations(match) do
				local existing = child:FindFirstChild(object.Name)
				local chosen
				if existing and existing:IsA("Animation") then
					chosen = { existing }
				else
					chosen = { modelAnimations[index] or modelAnimations[1] }
				end
				local animation = chosen[1]
				if animation and object.AnimationId ~= animation.AnimationId then
					meshWriter.write(object, "AnimationId", animation.AnimationId)
				end
			end
		end
	end
	local function syncEmotes(sourceHumanoid, targetHumanoid)
		local sourceDescription = sourceHumanoid:FindFirstChildOfClass("HumanoidDescription")
		local targetDescription = targetHumanoid:FindFirstChildOfClass("HumanoidDescription")
		if not sourceDescription or not targetDescription then
			return
		end
		local ok, emotes, equipped = pcall(function()
			return targetDescription:GetEmotes(), targetDescription:GetEquippedEmotes()
		end)
		if ok then
			meshWriter.undo("emotes", function()
				targetDescription:SetEmotes(emotes)
				targetDescription:SetEquippedEmotes(equipped)
			end)
			pcall(function()
				targetDescription:SetEmotes(sourceDescription:GetEmotes())
				targetDescription:SetEquippedEmotes((sourceDescription:GetEquippedEmotes()))
			end)
		end
	end
	mesh.apply = function(sourceModel, character, humanoid)
		local sourceHumanoid = sourceModel:FindFirstChildOfClass("Humanoid")
		local modelRoot = root.root(sourceModel)
		local characterRoot = root.root(character)
		if not sourceHumanoid then
			return
		end
		if not modelRoot then
			return
		end
		if not characterRoot then
			return
		end
		meshWriter.write(humanoid, "AutomaticScalingEnabled", false)
		local copyColor = sourceModel:FindFirstChildOfClass("BodyColors") == nil
		for _, partName in root.PARTS do
			local sourcePart = root.part(sourceModel, partName)
			local targetPart = root.part(character, partName)
			if sourcePart and targetPart then
				syncPart(sourcePart, targetPart, copyColor)
			end
		end
		meshWriter.write(humanoid, "HipHeight", sourceHumanoid.HipHeight + (modelRoot.Size.Y - characterRoot.Size.Y) / 2)
		syncAccessories(sourceModel, character, humanoid)
		syncAnimationIds(sourceModel, character)
		syncEmotes(sourceHumanoid, humanoid)
	end
	return mesh
end
modules.display = function()
	local body = modules
	local root = body.body()
	local settings = modules.settings()
	local dialectModule = modules
	local currentGameModule = not body
	local gunDialect
	if body then
		gunDialect = dialectModule.unnamed_aq()
		currentGameModule = modules.currentGame
	end
	local gameModule = currentGameModule()
	local mod_container = modules.container()
	local mod_new = modules.new()
	local keybind = modules.keybind()
	local hoodGame = modules.hoodGame()
	local targeting = modules.targeting()
	local services = modules.services()
	local configRead = modules.configRead()
	modules.unnamed_o()
	local weaponProfiles = modules.unnamed_ai()
	local defaultPosition = UDim2.new(0.5, 0, 0.5, 300)
	local white = Color3.new(1, 1, 1)
	local gray = Color3.fromRGB(150, 150, 150)
	local featureDefs = {}
	featureDefs[1] = { "silent aim", "Combat", "SilentAim" }
	featureDefs[2] = { "trigger bot", "Combat", "TriggerBot" }
	featureDefs[3] = { "aim assist", "Combat", "AimAssist" }
	featureDefs[4] = { "speed", "Character", "WalkSpeed" }
	featureDefs[5] = { "esp", "Visual", "ESP" }
	local localPlayer = services.Players.LocalPlayer
	local function colored(text, color)
		return string.format("<font color=\"#%s\">%s</font>", color:ToHex(), text)
	end
	local lines = {}
	local function formatTarget(target, distance, color)
		if not target then
			return string.format("target %s", tostring(colored("nil", color)))
		end
		local text = string.format("target %s", tostring(colored(target, color)))
		if not distance then
			return text
		end
		return text .. " " .. colored(string.format("(distance: %s)", tostring(math.floor(distance + 0.5))), color)
	end
	local function formatFeatures(sections, onColor, targetText)
		table.clear(lines)
		table.insert(lines, targetText)
		for _, section in sections do
			local features = gameModule.current()
			if not ((features == nil or features.features[section.section] == true) and settings.bool(false, section.group, section.section, "Enabled")) then
				continue
			end
			local status = colored("off", gray)
			local isSilentReady = hoodGame.current()
			local available = isSilentReady == nil
			if not (isSilentReady == nil) then
				available = section.section ~= "SilentAim"
				if not (section.section ~= "SilentAim") then
					available = isSilentReady.isSilentReady()
					if features then
						if not (features.aimAssist and section.section == "AimAssist" and available) then
							if section.activation.isActive() and available then
								status = colored("on", onColor)
							end
							local label = tostring(section.label)
							local n = table.pack("%s %s", label, tostring(status))
							local formatted = table.pack(string.format(unpack(n, 1, n.n)))
							table.insert(lines, unpack(formatted, 1, formatted.n))
							continue
						end
						available = features.aimAssist.status() == nil
					end
					if section.activation.isActive() and available then
						status = colored("on", onColor)
					end
					local label = tostring(section.label)
					local n = table.pack("%s %s", label, tostring(status))
					local formatted = table.pack(string.format(unpack(n, 1, n.n)))
					table.insert(lines, unpack(formatted, 1, formatted.n))
					continue
				end
			end
			if features and features.aimAssist and section.section == "AimAssist" and available then
				available = features.aimAssist.status() == nil
			end
			if section.activation.isActive() and available then
				status = colored("on", onColor)
			end
			local label = tostring(section.label)
			local n = table.pack("%s %s", label, tostring(status))
			local formatted = table.pack(string.format(unpack(n, 1, n.n)))
			table.insert(lines, unpack(formatted, 1, formatted.n))
		end
		return table.concat(lines, "\n")
	end
	local function readPosition(axis)
		local position = settings.get("Main", "Display", "Position", axis)
		if type(position) ~= "number" then
			return nil
		end
		if position ~= position then
			return nil
		end
		return math.clamp(position, 0, 100) / 100
	end
	local function position()
		local x = readPosition("X")
		local y = readPosition("Y")
		if x and y then
			return UDim2.fromScale(x, y)
		end
		return defaultPosition
	end
	local function resolveMuzzle(character)
		local dialect = hoodGame.current()
		if dialect then
			local weapon = dialect.equipped(character)
			local muzzle
			if weapon then
				muzzle = dialect.muzzle(weapon)
			else
				muzzle = nil
			end
			return muzzle
		end
		local tool = character:FindFirstChildOfClass("Tool")
		if not tool then
			return nil
		end
		local handle = tool:FindFirstChild("Handle")
		if not handle then
			return nil
		end
		if not handle:IsA("BasePart") then
			return nil
		end
		local muzzleFn = gunDialect.current().muzzle
		if muzzleFn then
			return muzzleFn(tool, handle)
		end
		local profile = weaponProfiles.profile(tool.Name)
		if not profile then
			return nil
		end
		return weaponProfiles.muzzle(tool, handle, profile)
	end
	local function targetDistance(target)
		local character = localPlayer.Character
		if target then
			local object = root.root(target)
			if object then
				if character then
					local dialect = gameModule.current()
					local muzzlePosition = nil
					if dialect == nil then
						muzzlePosition = resolveMuzzle(character)
					end
					if muzzlePosition then
						return (object.Position - muzzlePosition).Magnitude
					end
					local characterRoot = root.root(character)
					if characterRoot then
						return (object.Position - characterRoot.Position).Magnitude
					end
				end
				return nil
			end
		end
		return nil
	end
	return {
		name = "Display",
		start = function(scope)
			local sections = {}
			local dialect = gameModule.current()
			for _, def in featureDefs do
				if dialect and dialect.features[def[3]] ~= true then
					continue
				end
				table.insert(sections, {
					label = def[1],
					group = def[2],
					section = def[3],
					activation = keybind.activation(scope, def[2], def[3], "Activation"),
				})
			end
			local display = mod_new.new(mod_container.container())
			scope:add(function()
				display.destroy()
			end)
			local elapsed = 0.1
			scope:add(services.RunService.Heartbeat:Connect(function(delta)
				elapsed = elapsed + delta
				if elapsed < 0.1 then
					return
				end
				elapsed = 0
				local enabled = settings.bool(false, "Main", "Display", "Enabled")
				local espConfig = configRead.current()
				local primaryColor = settings.color(white, "Main", "Display", "Primary Color")
				local target = nil
				local distance = nil
				if enabled then
					local player = targeting.current()
					local character
					if player then
						character = player.Character
					else
						character = player
					end
					target = nil
					distance = targetDistance(character)
				elseif target then
					local targetColor = espConfig.targetColor
					display.update({
						isEnabled = enabled,
						title = settings.string("atomic", "Main", "Display", "Title"),
						titleColor = targetColor,
						features = formatFeatures(sections, primaryColor, formatTarget(target, distance, espConfig.targetColor)),
						position = position(),
					})
					return
				end
				display.update({
					isEnabled = enabled,
					title = settings.string("atomic", "Main", "Display", "Title"),
					titleColor = primaryColor,
					features = formatFeatures(sections, primaryColor, formatTarget(target, distance, espConfig.targetColor)),
					position = position(),
				})
			end))
		end,
	}
end
modules.unnamed_aq = function()
	modules.scope()
	local dialect = nil
	return {
		set = function(nextDialect)
			dialect = nextDialect
		end,
		current = function()
			local current = dialect
			if not current then
				error("gun dialect is not set")
			end
			return current
		end,
		spreadAxis = function(magnitude)
			local random = math.random()
			if 0.5 < random then
				return math.random() * magnitude
			end
			return -math.random() * magnitude
		end,
		serverClock = function()
			return workspace:GetServerTimeNow()
		end,
	}
end
modules.container = function()
	local services = modules.services()
	return {
		container = function()
			local ok, container = pcall(gethui)
			if ok and typeof(container) == "Instance" then
				return container
			end
			return services.Players.LocalPlayer:WaitForChild("PlayerGui")
		end,
	}
end
modules.new = function()
	local scope = modules.scope()
	local titleColor = Color3.fromRGB(240, 240, 240)
	local strokeColor = Color3.new(0, 0, 0)
	local font = Font.new("rbxasset://fonts/families/SourceSansPro.json", Enum.FontWeight.Bold, Enum.FontStyle.Normal)
	local function createLabel(parent, textSize, layoutOrder)
		local label = Instance.new("TextLabel")
		label.AutomaticSize = Enum.AutomaticSize.Y
		label.Size = UDim2.fromScale(1, 0)
		label.BackgroundTransparency = 1
		label.BorderSizePixel = 0
		label.FontFace = font
		label.TextSize = textSize
		label.TextColor3 = titleColor
		label.TextStrokeTransparency = 0.55
		label.TextStrokeColor3 = strokeColor
		label.TextXAlignment = Enum.TextXAlignment.Center
		label.TextYAlignment = Enum.TextYAlignment.Top
		label.LineHeight = 1.05
		label.Text = ""
		label.LayoutOrder = layoutOrder
		label.Parent = parent
		return label
	end
	local function addListLayout(parent)
		local layout = Instance.new("UIListLayout")
		layout.FillDirection = Enum.FillDirection.Vertical
		layout.HorizontalAlignment = Enum.HorizontalAlignment.Center
		layout.SortOrder = Enum.SortOrder.LayoutOrder
		layout.Padding = UDim.new(0, 2)
		layout.Parent = parent
	end
	return {
		new = function(parent)
			local uiScope = scope.new()
			local screenGui = Instance.new("ScreenGui")
			screenGui.IgnoreGuiInset = true
			screenGui.ResetOnSpawn = false
			screenGui.DisplayOrder = 9999
			screenGui.Enabled = false
			uiScope:add(screenGui)
			local frame = Instance.new("Frame")
			frame.AnchorPoint = Vector2.new(0.5, 0)
			frame.Size = UDim2.fromOffset(460, 0)
			frame.AutomaticSize = Enum.AutomaticSize.Y
			frame.BackgroundTransparency = 1
			frame.Parent = screenGui
			addListLayout(frame)
			local title = createLabel(frame, 15, 1)
			local features = createLabel(frame, 13, 2)
			features.RichText = true
			screenGui.Parent = parent
			return {
				update = function(state)
					if screenGui.Enabled ~= state.isEnabled then
						screenGui.Enabled = state.isEnabled
					end
					if not state.isEnabled then
						return
					end
					if frame.Position ~= state.position then
						frame.Position = state.position
					end
					if title.Text ~= state.title then
						title.Text = state.title
					end
					if title.TextColor3 ~= state.titleColor then
						title.TextColor3 = state.titleColor
					end
					if features.Text ~= state.features then
						features.Text = state.features
					end
				end,
				destroy = function()
					uiScope:destroy()
				end,
			}
		end,
	}
end
modules.configRead = function()
	local settings = modules.settings()
	local white = Color3.new(1, 1, 1)
	local red = Color3.fromRGB(255, 0, 0)
	local green = Color3.fromRGB(85, 255, 50)
	local blue = Color3.fromRGB(105, 160, 255)
	local deepBlue = Color3.fromRGB(0, 95, 255)
	local read = {}
	local function colorSetting(fallback, name, setting)
		return settings.color(fallback, "Visual", "ESP", name, "Settings", setting)
	end
	local function enabledSetting(name)
		return settings.bool(false, "Visual", "ESP", name, "Enabled")
	end
	read.read = function()
		local config = {
			name = enabledSetting("Name"),
			health = enabledSetting("Health"),
			armor = enabledSetting("Armor"),
			nameColor = colorSetting(white, "Name", "Color"),
			targetColor = colorSetting(red, "Name", "Target Color"),
			highHealth = colorSetting(green, "Health", "High Health"),
			lowHealth = colorSetting(red, "Health", "Low Health"),
			highArmor = colorSetting(blue, "Armor", "High Armor"),
			lowArmor = colorSetting(deepBlue, "Armor", "Low Armor"),
			key = "",
		}
		local parts = {}
		parts[1] = tostring(config.name)
		parts[2] = tostring(config.health)
		parts[3] = tostring(config.armor)
		parts[4] = config.nameColor:ToHex()
		parts[5] = config.targetColor:ToHex()
		parts[6] = config.highHealth:ToHex()
		parts[7] = config.lowHealth:ToHex()
		parts[8] = config.highArmor:ToHex()
		local n = table.pack(config.lowArmor:ToHex())
		table.move(n, 1, n.n, 9, parts)
		config.key = table.concat(parts, "|")
		return config
	end
	local cached = nil
	local lastRead = -math.huge
	read.current = function()
		local now = os.clock()
		local config = cached
		if config and now - lastRead < 0.05 then
			return config
		end
		local fresh = read.read()
		cached = fresh
		lastRead = now
		return fresh
	end
	return read
end
modules.esp = function()
	local settings = modules.settings()
	local currentGame = modules.currentGame()
	local mod_container = modules.container()
	local keybind = modules.keybind()
	local targeting = modules.targeting()
	local services = modules.services()
	local configRead = modules.configRead()
	local mod_new = modules.new()
	modules.unnamed_o()
	local localPlayer = services.Players.LocalPlayer
	local displays = {}
	local function removeDisplay(player)
		local display = displays[player]
		displays[player] = nil
		if display then
			display.destroy()
		end
	end
	return {
		name = "Esp",
		start = function(scope)
			local isActive = keybind.activation(scope, "Visual", "ESP", "Activation")
			local container = mod_container.container()
			local playerDetails = currentGame.current()
			local function addPlayer(player)
				if not (player ~= localPlayer) then
					return
				end
				if displays[player] then
					return
				end
				local details
				if playerDetails then
					details = playerDetails.playerDetails
				end
				displays[player] = mod_new.new(player, details, details)
			end
			for _, player in services.Players:GetPlayers() do
				addPlayer(player)
			end
			scope:add(services.Players.PlayerAdded:Connect(addPlayer))
			scope:add(services.Players.PlayerRemoving:Connect(removeDisplay))
			scope:add(function()
				for player in displays do
					removeDisplay(player)
				end
			end)
			local elapsed = 0.1
			local wasActive = true
			scope:add(services.RunService.Heartbeat:Connect(function(delta)
				elapsed = elapsed + delta
				if elapsed < 0.1 then
					return
				end
				elapsed = 0
				local enabled = settings.bool(false, "Visual", "ESP", "Enabled")
				if enabled then
					enabled = isActive.isActive()
					if enabled then
						wasActive = enabled
						local config = configRead.current()
						local target = targeting.current()
						for player, display in displays do
							display.update(config, enabled, player == target)
						end
						return
					end
				end
				if not wasActive then
					return
				end
				wasActive = enabled
				local config = configRead.current()
				local target = targeting.current()
				for player, display in displays do
					display.update(config, enabled, player == target)
				end
			end))
			if playerDetails then
				playerDetails.extendEsp(scope, displays, isActive)
			end
		end,
	}
end
modules.new = function()
	local mod_new = modules.unnamed_av()
	modules.currentGame()
	local scope = modules.scope()
	local services = modules.services()
	modules.configRead()
	local theme = modules.unnamed_aw()
	local mod_watch = modules.watch()
	local width = theme.WIDTH
	local height = theme.HEIGHT
	local gap = theme.GAP
	local offset = theme.OFFSET
	return {
		new = function(player, parent, detailed)
			local playerScope = scope.new()
			local billboardGui = Instance.new("BillboardGui")
			billboardGui.AlwaysOnTop = true
			billboardGui.LightInfluence = 0
			billboardGui.ResetOnSpawn = false
			billboardGui.MaxDistance = math.huge
			billboardGui.Size = UDim2.fromOffset(width, height + (gap + 4) * 2 + 1)
			billboardGui.StudsOffset = offset
			billboardGui.Enabled = false
			playerScope:add(billboardGui)
			local listLayout = Instance.new("UIListLayout")
			listLayout.FillDirection = Enum.FillDirection.Vertical
			listLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
			listLayout.SortOrder = Enum.SortOrder.LayoutOrder
			listLayout.Padding = UDim.new(0, gap)
			listLayout.Parent = billboardGui
			local nameLabel = theme.new(billboardGui, 1)
			nameLabel.Text = player.DisplayName
			local detailedLabel
			if detailed then
				local label = theme.new(billboardGui, 4)
				label.Visible = false
				detailedLabel = label
			else
				detailedLabel = nil
			end
			local barSize = UDim2.new(1, -2, 0, 4)
			local healthBar = mod_new.new(billboardGui, barSize, 2, true)
			local armorBar = mod_new.new(billboardGui, barSize, 3, true)
			billboardGui.Parent = parent
			local config = nil
			local configKey = ""
			local visible = false
			local attached = false
			local characterScope = nil
			local function refreshColors()
				if config then
					mod_new.paint(healthBar, config.lowHealth, config.highHealth)
					mod_new.paint(armorBar, config.lowArmor, config.highArmor)
				end
			end
			local function hide()
				attached = false
				visible = false
				billboardGui.Adornee = nil
				billboardGui.Enabled = false
			end
			local function onCharacterRemoving()
				if characterScope then
					characterScope:destroy()
					characterScope = nil
				end
				hide()
			end
			playerScope:add(onCharacterRemoving)
			local function onCharacterAdded(character)
				onCharacterRemoving()
				local charScope = scope.new()
				characterScope = charScope
				local function updateAdornee()
					if charScope:isDestroyed() then
						return
					end
					if characterScope ~= charScope then
						return
					end
					local rootPart = character:FindFirstChild("HumanoidRootPart")
					if rootPart then
						if rootPart:IsA("BasePart") then
							if character:IsDescendantOf(services.Workspace) then
								billboardGui.Adornee = rootPart
								attached = true
							else
								hide()
							end
						else
							hide()
						end
					else
						hide()
					end
				end
				charScope:add(character.ChildAdded:Connect(updateAdornee))
				charScope:add(character.ChildRemoved:Connect(updateAdornee))
				charScope:add(character.AncestryChanged:Connect(updateAdornee))
				updateAdornee()
				local watchVitals = mod_watch.watch
				local vitals = {}
				vitals.health = function(fraction)
					mod_new.set(healthBar, fraction)
					refreshColors()
				end
				vitals.armor = function(fraction)
					mod_new.set(armorBar, fraction)
					refreshColors()
				end
				watchVitals(charScope, character, vitals)
			end
			if player.Character then
				onCharacterAdded(player.Character)
			end
			playerScope:add(player.CharacterAdded:Connect(onCharacterAdded))
			playerScope:add(player.CharacterRemoving:Connect(onCharacterRemoving))
			return {
				update = function(configData, isVisible, isTarget)
					local hasDetailed = false
					local shouldShow = true
					if shouldShow then
						shouldShow = true
						if detailedLabel then
							local detailText, detailVisible = shouldShow(player)
							shouldShow = detailVisible
							hasDetailed = detailText ~= ""
							detailedLabel.Text = detailText
							detailedLabel.Visible = hasDetailed
							local _, lineCount = string.gsub(detailText, "\n", "")
							detailedLabel.Size = UDim2.new(1, 0, 0, (lineCount + 1) * height)
							local guiHeight = height + (gap + 4) * 2 + 1
							if detailText ~= "" then
								guiHeight = guiHeight + ((lineCount + 1) * height + gap)
							end
							billboardGui.Size = UDim2.fromOffset(width, guiHeight)
						end
					end
					local configChanged = configKey ~= configData.key
					if configKey ~= configData.key then
						configKey = configData.key
						config = configData
						nameLabel.Visible = configData.name
						healthBar.frame.Visible = configData.health
						armorBar.frame.Visible = configData.armor
						configChanged = nil
						refreshColors()
					end
					if isTarget ~= configChanged then
						configChanged = isTarget
						if isTarget then
							nameLabel.TextColor3 = configData.targetColor
						else
							nameLabel.TextColor3 = configData.nameColor
						end
					end
					if detailedLabel then
						detailedLabel.TextColor3 = nameLabel.TextColor3
					end
					if nameLabel.Text ~= player.DisplayName then
						nameLabel.Text = player.DisplayName
					end
					if not isVisible then
						shouldShow = isVisible
						if shouldShow ~= visible then
							visible = shouldShow
							billboardGui.Enabled = shouldShow
						end
						return
					end
					if shouldShow then
						shouldShow = attached
						if attached then
							shouldShow = configData.name or configData.health or configData.armor or hasDetailed
						end
					end
					if shouldShow ~= visible then
						visible = shouldShow
						billboardGui.Enabled = shouldShow
					end
				end,
				destroy = function()
					playerScope:destroy()
				end,
			}
		end,
	}
end
modules.unnamed_av = function()
	local services = modules.services()
	local backgroundColor = Color3.new(0, 0, 0)
	local strokeColor = Color3.new(0, 0, 0)
	local tweenInfo = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
	return {
		new = function(parent, size, layoutOrder, withStroke)
			local frame = Instance.new("Frame")
			frame.Size = size
			frame.BackgroundColor3 = backgroundColor
			frame.BackgroundTransparency = 0.35
			frame.BorderSizePixel = 0
			frame.LayoutOrder = layoutOrder
			if withStroke then
				local stroke = Instance.new("UIStroke")
				stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
				stroke.LineJoinMode = Enum.LineJoinMode.Miter
				stroke.Color = strokeColor
				stroke.Thickness = 1
				stroke.Parent = frame
			end
			frame.Parent = parent
			local fill = Instance.new("Frame")
			fill.Size = UDim2.fromScale(1, 1)
			fill.BorderSizePixel = 0
			fill.Parent = frame
			return { frame = frame, fill = fill, fraction = 1 }
		end,
		set = function(bar, newValue)
			local fraction = 0
			if newValue == newValue then
				fraction = math.clamp(newValue, 0, 1)
			end
			if fraction == bar.fraction then
				return
			end
			bar.fraction = fraction
			services.TweenService:Create(bar.fill, tweenInfo, { Size = UDim2.fromScale(fraction, 1) }):Play()
		end,
		paint = function(bar, lowColor, highColor)
			local color = lowColor:Lerp(highColor, bar.fraction)
			if bar.fill.BackgroundColor3 ~= color then
				bar.fill.BackgroundColor3 = color
			end
		end,
	}
end
modules.unnamed_aw = function()
	local font = Font.new("rbxasset://fonts/families/SourceSansPro.json", Enum.FontWeight.Heavy, Enum.FontStyle.Normal)
