modules.watch = function()
	local currentGame = modules.currentGame()
	modules.scope()
	local services = modules.services()
	local function isNumberValue(instance)
		local valid = instance ~= nil
		if instance ~= nil then
			valid = instance:IsA("IntValue")
			if not valid then
				return (instance:IsA("NumberValue"))
			end
		end
		return valid
	end
	local function maxArmor()
		local armor = services.ReplicatedStorage:FindFirstChild("MaxArmor")
		local armorValues
		if isNumberValue(armor) then
			armorValues = {}
			armorValues[1] = math.max(armor.Value, 1)
		else
			armorValues = { 100 }
		end
		return armorValues[1]
	end
	return {
		watch = function(scope, character, vitals)
			local watchVitals = currentGame.current()
			if watchVitals then
				watchVitals.watchVitals(scope, character, vitals)
			else
				scope:add(task.spawn(function()
					local humanoid = character:WaitForChild("Humanoid", 10)
					if humanoid and humanoid:IsA("Humanoid") then
						local function onHealthChanged()
							local health = humanoid.Health
							vitals.health(health / math.max(humanoid.MaxHealth, 1), health)
						end
						scope:add(humanoid.HealthChanged:Connect(onHealthChanged))
						scope:add(humanoid:GetPropertyChangedSignal("MaxHealth"):Connect(onHealthChanged))
						onHealthChanged()
						local armor = character:WaitForChild("BodyEffects", 10)
						if armor then
							armor = armor:WaitForChild("Armor", 10)
						end
						if not isNumberValue(armor) then
							vitals.armor(0, 0)
							return
						end
						local function onChanged()
							local armorValue = armor.Value
							vitals.armor(armorValue / maxArmor(), armorValue)
						end
						scope:add(armor.Changed:Connect(onChanged))
						onChanged()
					end
				end))
			end
		end,
	}
end
