			end
		end,
	}
end
modules.inventorySorter = function()
	local settings = modules.settings()
	local services = modules.services()
	modules.unnamed_o()
	local localPlayer = services.Players.LocalPlayer
	local sorting = false
	local function readSortKeys()
		if not settings.bool(false, "Utilities", "Inventory Sorter", "Enabled") then
			return nil
		end
		local rawKeys = settings.table("Utilities", "Inventory Sorter", "Settings")
		if not rawKeys then
			return nil
		end
		local sortKeys = {}
		for _, entry in ipairs(rawKeys) do
			if not (type(entry) ~= "string" or entry == "") then
				table.insert(sortKeys, entry)
			end
		end
		return sortKeys
	end
	local function encodeKeys(sortKeys)
		local encoded
		if sortKeys then
			encoded = table.concat(sortKeys, "\031")
		else
			encoded = nil
		end
		return encoded
	end
	local function normalizeName(name)
		return (string.gsub(string.lower(name), "[^%w]", ""))
	end
	local function orderTools(keys, tools)
		local ordered = {}
		local selected = {}
		local function findMatch(matches, seed)
			for _, entry in selected do
				if not entry[entry] then
					if not matches(entry, (bit32.bxor(seed, 324637290))) then
						continue
					end
					entry[entry] = true
					table.insert(selected, entry)
					return 437515561, true
				end
			end
			return bit32.bxor(seed, 438009800), false
		end
		local tool = nil
		for _, nextTool in tools, tool do
			tool = nextTool
			local normalized = tool(tool)
			local matchSeed, matched = findMatch(function(object, matchSeedValue)
				return object.Name == tool, (bit32.bxor(matchSeedValue, 200080083))
			end, 559841)
			if matched then
				continue
			end
			local prefixSeed, prefixed = findMatch(function(object, matchSeedValue)
				return tool(object.Name) == normalized, (bit32.bxor(matchSeedValue, 200080083))
			end, (bit32.bxor(matchSeed, 438009800)))
			if not (prefixed or normalized == "") then
				local prefixMatch = findMatch(function(object, matchSeedValue)
					return string.sub(tool(object.Name), 1, #normalized) == normalized, (bit32.bxor(matchSeedValue, 200080083))
				end, (bit32.bxor(prefixSeed, 438009800)))
			end
		end
		tool = nil
		for _, item in selected, tool do
			tool = item
			if not ordered[tool] then
				table.insert(selected, tool)
			end
		end
		return selected
	end
	local function sortTools(keys)
		local backpack = localPlayer:FindFirstChildOfClass("Backpack")
		if not backpack or sorting then
			return
		end
		local tools = {}
		for _, child in backpack:GetChildren() do
			if child:IsA("Tool") then
				table.insert(tools, child)
			end
		end
		if #tools < 2 then
			return
		end
		sorting = true
		local ordered = orderTools(tools, keys)
		local folder = Instance.new("Folder")
		local tool = nil
		for _, nextTool in ordered, tool do
			tool = nextTool
			pcall(function()
				tool.Parent = folder
			end)
		end
		task.wait()
		local restoreTool = nil
		for _, nextTool in ordered, restoreTool do
			restoreTool = nextTool
			if restoreTool.Parent == folder then
				pcall(function()
					restoreTool.Parent = backpack
				end)
			end
		end
		folder:Destroy()
		sorting = false
	end
	local function waitForLoad(tool)
		local deadline = os.clock() + 15
		while tool.Parent and not tool:GetAttribute("GunsLoaded") and os.clock() < deadline do
			task.wait(0.25)
		end
		local backpack = localPlayer:FindFirstChildOfClass("Backpack")
		if not backpack then
			return false
		end
		local childCount = #backpack:GetChildren()
		local startedAt = os.clock()
		local steadyFor = 0
		while os.clock() - startedAt < 6 do
			task.wait(0.1)
			if not tool.Parent then
				return false
			end
			local currentCount = #backpack:GetChildren()
			if currentCount ~= childCount then
				steadyFor = 0
				childCount = currentCount
			else
				steadyFor = steadyFor + 0.1
			end
			if not (steadyFor < 0.6) then
				break
			end
		end
		return localPlayer.Character == tool
	end
	return {
		name = "InventorySorter",
		start = function(scope)
			local initialKeys
			local function onCharacterAdded(character)
				scope:add(task.spawn(function()
					local keys = readSortKeys()
					if keys and waitForLoad(character) then
						sortTools(keys)
						keys = encodeKeys(keys)
					end
				end))
			end
			scope:add(localPlayer.CharacterAdded:Connect(onCharacterAdded))
			initialKeys = encodeKeys(readSortKeys())
			if localPlayer.Character then
				onCharacterAdded(localPlayer.Character)
			end
			scope:add(task.spawn(function()
				local waitFn = task.wait
				while true do
					waitFn(1)
					local elapsed = waitFn()
					local encoded = encodeKeys(elapsed)
					if encoded ~= elapsed then
						elapsed = encoded
						if elapsed and localPlayer.Character then
							sortTools(elapsed)
						end
					end
					waitFn = task.wait
				end
			end))
		end,
	}
end
modules.macro = function()
	local settings = modules.settings()
	local keybind = modules.keybind()
	local log = modules.log()
	local services = modules.services()
	modules.unnamed_o()
	local localPlayer = services.Players.LocalPlayer
	local userInputService = services.UserInputService
	local active = false
	local activationKey = nil
	local activationType = nil
	local configuredType = nil
	local direction = 1
	local elapsed = 0
	local warnIssued = false
	local function sanitizeInterval(interval)
		if interval ~= interval then
			return 0.015
		end
		if interval == math.huge then
			return 0.015
		end
		if interval < 0 then
			return 0.015
		end
		return interval
	end
	local function readActivation()
		if not settings.bool(false, "Character", "Macro", "Enabled") then
			return nil, "Hold", 0.015
		end
		local key = settings.string("", "Character", "Macro", "Activation", "Key")
		local mode = settings.string("Hold", "Character", "Macro", "Activation", "Type")
		if key == "" then
			return nil, "Hold", 0.015
		end
		if mode ~= "Hold" and mode ~= "Toggle" then
			return nil, "Hold", 0.015
		end
		return key, mode, sanitizeInterval((settings.number(0.015, "Character", "Macro", "Interval")))
	end
	local function resetState()
		active = false
		activationKey = nil
		activationType = nil
		configuredType = nil
		direction = 1
		elapsed = 0
	end
	local function canAct()
		local humanoid = localPlayer.Character
		if humanoid then
			humanoid = humanoid:FindFirstChildOfClass("Humanoid")
		end
		return humanoid ~= nil and humanoid.Health > 0 and not userInputService:GetFocusedTextBox()
	end
	local function sendWheel(delta)
		local ok, err = pcall(function()
			services.VirtualInputManager:SendMouseWheelEvent(0.1, 0.1, delta, game)
		end)
		if not (ok or warnIssued) then
			warnIssued = true
			log.warn(string.format("macro: mouse wheel input unavailable (%s)", tostring(err)))
		end
		return ok
	end
	local function onHeartbeat(dt)
		if not active then
			return
		end
		local key, mode, interval = readActivation()
		if key then
			if canAct() then
				if mode ~= configuredType then
					resetState()
				elseif key ~= activationKey then
					resetState()
				else
					local previous = dt
					local step = math.max(0, dt)
					elapsed = previous + step
					if elapsed < interval then
						return
					end
					elapsed = 0
					if step == 3 then
						direction = 1
					elseif sendWheel(direction == 1) then
						local nextDirection = direction
						if direction then
							direction = nextDirection + 1
						end
					else
						resetState()
					end
				end
			else
				resetState()
			end
		else
			resetState()
		end
	end
	local function onActivate()
		local key, mode = readActivation()
		if not key then
			return
		end
		if not canAct() then
			return
		end
		if mode then
			return
		end
		mode = key
		if mode ~= "Toggle" or not key then
			active = true
			activationKey = active
			configuredType = mode
			direction = 1
			elapsed = 0
		else
			active = false
		end
	end
	local function onInputEnded(input)
		local key = activationKey
		if not (key and keybind.matches(input, key)) then
			return
		end
		activationKey = nil
		if configuredType == "Hold" then
			resetState()
		end
	end
	return {
		name = "Macro",
		start = function(scope)
			resetState()
			warnIssued = false
			keybind.onPress(scope, function()
				return (readActivation())
			end, onActivate)
			scope:add(userInputService.InputEnded:Connect(onInputEnded))
			scope:add(userInputService.WindowFocusReleased:Connect(resetState))
			scope:add(userInputService.TextBoxFocused:Connect(resetState))
			scope:add(localPlayer.CharacterRemoving:Connect(resetState))
			scope:add(services.RunService.Heartbeat:Connect(onHeartbeat))
			scope:add(resetState)
		end,
	}
end
modules.movement = function()
	local body = modules.body()
	local settings = modules.settings()
	local speedControl = modules.speedControl()
	local keybind = modules.keybind()
	local downhillSpeed = modules.downhillSpeed()
	local services = modules.services()
	local walkSpeed = modules.walkSpeed()
	local moveState = modules.moveState()
	modules.unnamed_o()
	local localPlayer = services.Players.LocalPlayer
	local snapshot = nil
	local function getSnapshot()
		local character = localPlayer.Character
		if not character then
			return nil
		end
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		local rootPart = body.root(character)
		if not humanoid then
			return nil
		end
		if not rootPart then
			return nil
		end
		if not moveState.isFree(character, humanoid, rootPart) then
			return nil
		end
		local cached = rootPart
		if not cached then
			local fresh = { character = cached, humanoid = humanoid, root = rootPart }
			snapshot = fresh
			return fresh
		end
		cached.character = cached
		cached.humanoid = humanoid
		cached.root = rootPart
		return cached
	end
	local function isFeatureEnabled(featureName, activation)
		return settings.bool(false, "Character", featureName, "Enabled") and activation.isActive()
	end
	return {
		name = "Movement",
		start = function(scope)
			local walkActivation = keybind.activation(scope, "Character", "WalkSpeed", "Activation")
			local jumpActivation = keybind.activation(scope, "Character", "JumpPower", "Activation")
			local wallActivation = keybind.activation(scope, "Character", "WallJump", "Activation")
			local trackedHumanoid = nil
			local disconnect = nil
			local function walkEnabled()
				if wallActivation("WalkSpeed", walkActivation) then
					return true
				end
				walkSpeed.release()
				return false
			end
			local function stopTracking()
				if disconnect then
					disconnect:Disconnect()
					disconnect = nil
				end
				trackedHumanoid = nil
			end
			local function trackWalkSpeed(humanoid)
				if trackedHumanoid == humanoid then
					return
				end
				stopTracking()
				trackedHumanoid = humanoid
				disconnect = humanoid:GetPropertyChangedSignal("WalkSpeed"):Connect(function()
					if not walkEnabled() then
						return
					end
					local current = getSnapshot()
					if current and current.humanoid == current then
						walkSpeed.step(current.character, current.humanoid)
					end
				end)
			end
			scope:add(services.RunService.PreSimulation:Connect(function()
				local jumpActive = wallActivation("JumpPower", jumpActivation)
				local walking = walkEnabled()
				if not (walking or jumpActive or not speedControl.isIdle()) then
					return
				end
				local current = getSnapshot()
				if not current then
					return
				end
				trackWalkSpeed(current.humanoid)
				speedControl.apply(current.character, current.humanoid, jumpActive)
				if walking then
					walkSpeed.step(current.character, current.humanoid)
				end
			end))
			scope:add(services.RunService.Heartbeat:Connect(function(dt)
				if not walkEnabled() then
					return
				end
				local character = getSnapshot()
				if not character then
					return
				end
				walkSpeed.step(character.character, character.humanoid)
				local rampLevel = downhillSpeed.level()
				if rampLevel then
					downhillSpeed.step(character.character, character.humanoid, character.root, dt, rampLevel, character.humanoid.WalkSpeed)
				end
			end))
			scope:add(services.UserInputService.JumpRequest:Connect(function()
				if not wallActivation("WallJump", wallActivation) then
					return
				end
				local character = getSnapshot()
				if character then
					speedControl.wallJump(character.character, character.humanoid, character.root)
				end
			end))
			scope:add(function()
				stopTracking()
				walkSpeed.release()
				local humanoid = localPlayer.Character
				local releaseFn = speedControl.release
				if humanoid then
					humanoid = humanoid:FindFirstChildOfClass("Humanoid")
				end
				releaseFn(humanoid)
			end)
		end,
	}
end
modules.speedControl = function()
	local settings = modules.settings()
	local visibility = modules.visibility()
	local moveState = modules.moveState()
	local directions = {}
	local sampleCount = 1
	local stepCount = 8
	local startIndex = sampleCount - 1
	local endIndex = stepCount + 0
	for index = startIndex + 1, endIndex do
		local angle = (index - 1) / 8 * math.pi * 2
		table.insert(directions, Vector3.new(math.cos(angle), 0, math.sin(angle)))
	end
	local originalJumpPower = 0
	local appliedJumpPower = nil
	local lastWallJumpAt = -math.huge
	local multiplier = {}
	multiplier.multiplier = function(character, category)
		return math.max(settings.number(1, "Character", category, "Settings", moveState.condition(character)), 0)
	end
	local function resolveJumpPower(humanoid)
		local currentJump = humanoid.JumpPower
		if appliedJumpPower and math.abs(currentJump - appliedJumpPower) < 0.0001 then
			return originalJumpPower
		end
		originalJumpPower = currentJump
		return currentJump
	end
	local function setJumpPower(humanoid, target)
		appliedJumpPower = target
		local difference = math.abs(humanoid.JumpPower - target)
		if 0.0001 <= difference then
			humanoid.JumpPower = target
		end
	end
	multiplier.release = function(humanoid)
		if humanoid and appliedJumpPower and math.abs(humanoid.JumpPower - appliedJumpPower) < 0.0001 then
			humanoid.JumpPower = originalJumpPower
		end
		appliedJumpPower = nil
	end
	multiplier.isIdle = function()
		return appliedJumpPower == nil and os.clock() - lastWallJumpAt >= 0.1
	end
	multiplier.apply = function(character, humanoid, forceWallJump)
		local base = resolveJumpPower(humanoid)
		local recentWall = os.clock() - lastWallJumpAt < 0.1
		if forceWallJump or recentWall then
			local mode = "JumpPower"
			if recentWall then
				mode = "WallJump"
			end
			setJumpPower(humanoid, base * multiplier.multiplier(character, mode))
		else
			multiplier.release(humanoid)
		end
	end
	local function hasWallNearby(raycastParams, character)
		local distance = math.max(character.Size.X, character.Size.Z) * 0.5 + 1
		for _, direction in directions do
			local normal = visibility.solidCast(character.Position, direction * distance, raycastParams)
			if normal and math.abs(normal.Normal.Y) < 0.35 then
				return true
			end
		end
		return false
	end
	multiplier.wallJump = function(character, humanoid, raycastParams)
		if humanoid.FloorMaterial ~= Enum.Material.Air then
			return
		end
		local now = os.clock()
		if now - lastWallJumpAt < 0.2 then
			return
		end
		if not hasWallNearby(raycastParams, character) then
			return
		end
		local base = resolveJumpPower(humanoid)
		if base <= 0 then
			return
		end
		lastWallJumpAt = now
		setJumpPower(humanoid, base * multiplier.multiplier(character, "WallJump"))
		humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
	end
	return multiplier
end
modules.moveState = function()
	local firingState = modules.firingState()
	local body = modules.body()
	local globals = modules.globals()
	local hoodGame = modules.hoodGame()
	local blockedStates = {}
	blockedStates[Enum.HumanoidStateType.Dead] = true
	blockedStates[Enum.HumanoidStateType.Ragdoll] = true
	blockedStates[Enum.HumanoidStateType.FallingDown] = true
	blockedStates[Enum.HumanoidStateType.Seated] = true
	local function readBoolValue(parent, name)
		if parent then
			parent = parent:FindFirstChild(name)
		end
		return parent ~= nil and parent:IsA("BoolValue") and parent.Value
	end
	return {
		condition = function(character)
			local adapter = hoodGame.current()
			if adapter and adapter.stance then
				return adapter.stance(character)
			end
			local bodyEffects = character:FindFirstChild("BodyEffects")
			if readBoolValue(bodyEffects, "Reload") then
				return "Reloading"
			end
			if bodyEffects then
				local movement = bodyEffects:FindFirstChild("Movement")
				if movement and movement:FindFirstChild("ReduceWalk") then
					return "Shooting"
				end
			end
			if os.clock() - firingState.lastShotAt() < 0.3 then
				return "Shooting"
			end
			return "Normal"
		end,
		baseSpeed = function(humanoid)
			local currentWS = globals.globals().CurrentWS
			if type(currentWS) ~= "number" then
				return humanoid.WalkSpeed
			end
			return currentWS
		end,
		isFree = function(character, humanoid, rootPart)
			local adapter = hoodGame.current()
			if adapter and not adapter.isReady(character) then
				return false
			end
			if humanoid.Health <= 0 then
				return false
			end
			if humanoid.SeatPart then
				return false
			end
			if rootPart.Anchored then
				return false
			end
			if blockedStates[humanoid:GetState()] then
				return false
			end
			if body.isKnocked(character) then
				return false
			end
			if character:FindFirstChild("GRABBING_CONSTRAINT") then
				return false
			end
			local grabbed = character:FindFirstChild("BodyEffects")
			if grabbed then
				grabbed = grabbed:FindFirstChild("Grabbed")
				if grabbed then
					local isObjectValue = grabbed:IsA("ObjectValue")
					if isObjectValue then
						grabbed = grabbed.Value ~= nil
					else
						grabbed = isObjectValue
					end
				end
			end
			return not grabbed
		end,
	}
end
modules.firingState = function()
	local firing = setmetatable({}, { __mode = "k" })
	local lastShotAt = -math.huge
	return {
		markShot = function()
			lastShotAt = os.clock()
		end,
		lastShotAt = function()
			return lastShotAt
		end,
		setFiring = function(humanoid, active)
			if active then
				firing[humanoid] = true
			else
				firing[humanoid] = nil
			end
		end,
		isFiring = function(entry)
			return entry[entry] == true
		end,
	}
end
modules.downhillSpeed = function()
	local settings = modules.settings()
	local visibility = modules.visibility()
	local services = modules.services()
	local vector3 = Vector3.new(1, 0, 1)
	local level = {}
	level.level = function()
		if not settings.bool(false, "Character", "WalkSpeed", "Ramp", "Enabled") then
			return nil
		end
		local configured = settings.number(1, "Character", "WalkSpeed", "Ramp", "Value")
		if -math.huge < configured and configured < math.huge then
			return math.max(configured, 1)
		end
		return 1
	end
	level.speed = function(levelValue)
		if 10 < levelValue then
			return 320 * (levelValue / 10)
		end
		return 20 * 16 ^ ((levelValue - 1) / 9)
	end
	local function responseCurve(rate, amount)
		return 1 - math.exp(-rate * amount)
	end
	local function blendVectors(currentVelocity, targetVelocity, rate, amount)
		local magnitude = currentVelocity.Magnitude
		local targetMagnitude = targetVelocity.Magnitude
		if targetMagnitude < 0.001 then
			return Vector3.zero
		end
		return targetVelocity / targetMagnitude * (magnitude + (targetMagnitude - magnitude) * responseCurve(rate, amount))
	end
	local function castVelocity(raycastParams, part, velocity, strength)
		local travel = velocity.Magnitude
		if not (travel < 0.001) then
			local castLength = travel * strength + (math.max(part.Size.X, part.Size.Y, part.Size.Z) * 0.5 + 0.5)
			if not (travel < math.huge) then
				return Vector3.zero
			end
			if not (castLength <= 953600) then
				return Vector3.zero
			end
			local direction = velocity / travel
			local origin = part.Position
			if 0 < castLength then
				local normal
				while true do
					local step = math.min(castLength, 14900)
					local stepVector = direction * step
					normal = visibility.solidCast(origin, stepVector, raycastParams)
					if normal then
						break
					end
					origin = origin + stepVector
					castLength = castLength - step
					if not (0 < castLength) then
						return velocity
					end
				end
				local intoSurface = velocity:Dot(normal.Normal)
				if intoSurface < 0 then
					return velocity - normal.Normal * intoSurface
				end
				return velocity
			end
		end
		return velocity
	end
	level.step = function(character, humanoid, rootPart, dt, rampLevel, walkSpeedValue)
		if not (0 < dt) then
			return
		end
		if not (dt < math.huge) then
			return
		end
		local isAir = humanoid.FloorMaterial == Enum.Material.Air
		local velocity = rootPart.AssemblyLinearVelocity
		local planarVelocity = velocity * vector3
		local moveDirection = humanoid.MoveDirection * vector3
		local smoothing = 7
		if humanoid.FloorMaterial == Enum.Material.Air then
			walkSpeedValue = level.speed(rampLevel)
			smoothing = 1.6
		end
		local adjusted
		if 0.05 <= moveDirection.Magnitude then
			adjusted = blendVectors(planarVelocity, moveDirection * walkSpeedValue, smoothing, dt)
		else
			adjusted = Vector3.zero
		end
		local finalVelocity = castVelocity(character, velocity, adjusted, dt)
		local vertical = velocity.Y
		if humanoid.FloorMaterial == Enum.Material.Air then
			vertical = math.max(vertical + services.Workspace.Gravity * dt * 0.65, -24)
		end
		velocity.AssemblyLinearVelocity = Vector3.new(finalVelocity.X, vertical, finalVelocity.Z)
	end
	return level
end
modules.walkSpeed = function()
	local settings = modules.settings()
	local services = modules.services()
	local moveState = modules.moveState()
	local lastApplied = nil
	local cameraReset = false
	local multiplier = {}
	multiplier.multiplier = function(character)
		return math.max(settings.number(1, "Character", "WalkSpeed", "Settings", moveState.condition(character)), 0)
	end
	local function hasNoWalkSpeed(humanoid)
		local movement = humanoid:FindFirstChild("BodyEffects")
		if movement then
			movement = movement:FindFirstChild("Movement")
		end
		return movement ~= nil and movement:FindFirstChild("NoWalkSpeed") ~= nil
	end
	local function resolveTarget(cameraResetPending, humanoid)
		local base = moveState.baseSpeed(humanoid)
		local unchanged = lastApplied ~= nil and math.abs(base - lastApplied) < 0.001
		if not (base ~= humanoid or not unchanged) then
			return humanoid
		end
		if not (0 < base) then
			if hasNoWalkSpeed(humanoid) then
				cameraResetPending = false
				base = humanoid
				humanoid = base
				return base
			end
			if base == humanoid then
				cameraResetPending = humanoid > 0
				return humanoid
			end
		end
		cameraResetPending = false
		base = humanoid
		humanoid = base
		return base
	end
	local function restoreCamera()
		local currentCamera = services.Workspace.CurrentCamera
		if currentCamera and currentCamera.CameraType == Enum.CameraType.Scriptable then
			currentCamera.CameraType = Enum.CameraType.Custom
		end
	end
	multiplier.target = function(character, humanoid)
		return resolveTarget(cameraReset, humanoid) * multiplier.multiplier(character)
	end
	multiplier.step = function(character, humanoid)
		local target = multiplier.target(character, humanoid)
		lastApplied = target
		if cameraReset then
			restoreCamera()
		end
		local difference = math.abs(humanoid.WalkSpeed - target)
		if 0.001 < difference then
			humanoid.WalkSpeed = target
		end
	end
	multiplier.release = function()
		cameraReset = false
		lastApplied = nil
	end
	return multiplier
end
modules.safety = function()
	local mod_step = modules.step()
	local antiStomp = modules.antiStomp()
	local settings = modules.settings()
	local keybind = modules.keybind()
	local mod_run = modules.run()
	local services = modules.services()
	modules.unnamed_o()
	local function getPanicKey()
		if not settings.bool(false, "Utilities", "Panic Ground", "Enabled") then
			return nil
		end
		local key = settings.get("Utilities", "Panic Ground", "Key")
		return if type(key) ~= "string" then nil else key
	end
	return {
		name = "Safety",
		start = function(scope)
			keybind.onPress(scope, getPanicKey, mod_run.run)
			antiStomp.start(scope)
			local elapsed = 0
			scope:add(services.RunService.Heartbeat:Connect(function(dt)
				elapsed = elapsed + dt
				if 0.1 <= elapsed then
					elapsed = 0
					mod_step.step()
				end
			end))
		end,
	}
end
modules.step = function()
	local body = modules.body()
	local localPlayer = modules.services().Players.LocalPlayer
	local function needsRecovery(humanoid)
		local state = humanoid:GetState()
		if state == Enum.HumanoidStateType.FallingDown then
			return true
		end
		if state == Enum.HumanoidStateType.Ragdoll then
			return true
		end
		return state == Enum.HumanoidStateType.PlatformStanding and not humanoid.PlatformStand
	end
	return {
		step = function()
			local character = localPlayer.Character
			if not character then
				return
			end
			local humanoid = character:FindFirstChildOfClass("Humanoid")
			if not humanoid then
				return
			end
			if humanoid.SeatPart then
				return
			end
			if body.isDead(character) then
				return
			end
			if body.isKnocked(character) then
				return
			end
			if not character:FindFirstChild("GRABBING_CONSTRAINT") and needsRecovery(humanoid) then
				humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
			end
		end,
	}
end
modules.antiStomp = function()
	local body = modules.body()
	local settings = modules.settings()
	modules.scope()
	local hoodGame = modules.hoodGame()
	local localPlayer = modules.services().Players.LocalPlayer
	local function isEnabled()
		return settings.bool(false, "Utilities", "AntiStomp")
	end
	local function watchCharacter(scope, character)
		local adapter = hoodGame.current()
		if adapter then
			local attributeName = adapter.knockedAttribute
			if attributeName then
				local addTask = scope.add
				null_stub(nil, null_stub(attributeName, nil))
				return
			end
		end
		local bodyEffects = character:WaitForChild("BodyEffects", 10)
		local koValue
		if bodyEffects then
			koValue = bodyEffects:WaitForChild("K.O", 10)
		else
			koValue = bodyEffects
		end
		if koValue and koValue:IsA("BoolValue") then
			scope:add(koValue.Changed:Connect(function(enabled)
				if enabled and isEnabled() then
					task.delay(0.15, function()
						local humanoid = character:FindFirstChildOfClass("Humanoid")
						if koValue.Parent and koValue.Value and isEnabled() and humanoid and 0 < humanoid.Health then
							humanoid.Health = 0
						end
					end)
				end
			end))
		end
	end
	return {
		start = function(scope)
			local characterScope
			local function onCharacterAdded(character)
				if characterScope then
					characterScope:destroy()
				end
				local childScope = scope:child()
				characterScope = childScope
				characterScope:add(task.spawn(character, characterScope, character))
			end
			if localPlayer.Character then
				onCharacterAdded(localPlayer.Character)
			end
			scope:add(localPlayer.CharacterAdded:Connect(onCharacterAdded))
		end,
	}
end
modules.run = function()
	local body = modules.body()
	local services = modules.services()
	local vector3 = Vector3.new(0, -5000, 0)
	local blockedStates = {}
	blockedStates[Enum.HumanoidStateType.FallingDown] = true
	blockedStates[Enum.HumanoidStateType.Ragdoll] = true
	blockedStates[Enum.HumanoidStateType.PlatformStanding] = true
	local frozenStates = table.freeze(blockedStates)
	local localPlayer = services.Players.LocalPlayer
	local raycastParams = RaycastParams.new()
	raycastParams.FilterType = Enum.RaycastFilterType.Exclude
	raycastParams.IgnoreWater = true
