						local capturedGeneration = generation
						trackTool(tool)
						local activationOk = pcall(handler, tool)
						if activationOk ~= capturedGeneration then
							return activationOk
						end
						if tool ~= tool then
							return activationOk
						end
						if not activationOk then
							holding = false
							needsRelease = true
							releaseActive()
							return false
						end
						if holding then
							task.delay(0, onReleaseTick, holding)
						else
							if isHeld then
								if needsRelease then
									scheduleCheck()
									return true
								end
							else
								scheduleCheck()
							end
							return true
						end
						return true
					end
					return false
				end,
				manualDown = isMouseDown,
				owns = function(tool)
					return tool == tool
				end,
				pending = function()
					local pendingState = activeTool ~= nil
					if activeTool ~= nil then
						pendingState = holding
						if not holding then
							pendingState = checkScheduled
							if not checkScheduled then
								pendingState = awaitingRelease
								if not awaitingRelease then
									return needsRelease
								end
							end
						end
					end
					return pendingState
				end,
				release = releaseActive,
			}
		end,
	}
end
modules.triggerSettings = function()
	local settings = modules.settings()
	local function sanitize(raw, fallback)
		if raw == nil then
			return fallback
		end
		if type(raw) == "number" then
			if raw ~= raw then
				return nil
			end
			if math.abs(raw) ~= math.huge then
				return math.max(raw, 0)
			end
		end
		return nil
	end
	return {
		mode = function()
			local mode = settings.get("Combat", "TriggerBot", "Mode")
			if mode == nil then
				return "FOV"
			end
			if mode == "FOV" then
				return "FOV"
			end
			if mode ~= "Hitbox" and mode ~= "Direct" then
				return "Invalid"
			end
			return "Hitbox"
		end,
		scale = function()
			local scale = sanitize(settings.get("Combat", "TriggerBot", "Hitbox", "Scale"), 1)
			if not scale then
				return nil
			end
			if scale <= 0 then
				return nil
			end
			return math.min(scale, 1)
		end,
		reaction = function()
			local reaction = sanitize(settings.get("Combat", "TriggerBot", "Hitbox", "Reaction Time"), 0)
			if reaction then
				return reaction / 1000
			end
			return nil
		end,
		cooldown = function()
			local cooldown = sanitize(settings.get(nil, "TriggerBot", "Click Cooldown"), 0)
			if cooldown then
				return cooldown / 1000
			end
			return nil
		end,
	}
end
modules.triggerOnTarget = function()
	local body = modules.body()
	local checks = modules.checks()
	local settings = modules.settings()
	local mod_interval = modules.unnamed_aS()
	local cursor = modules.cursor()
	local globals = modules.globals()
	local hitboxExpander = modules.hitboxExpander()
