	local partCount = #body.PARTS + 1
	local localPlayer = services.Players.LocalPlayer
	local scratchA = table.create(partCount)
	local scratchB = table.create(partCount)
	local scratchC = table.create(partCount)
	local reset = {}
	local predictionSeed = 397481366
	local function getPrediction(seed)
		if not settings.bool(false, "Combat", "TriggerBot", "Prediction", "Enabled") then
			return Vector3.zero
		end
		local xSetting = settings.number(0, "Combat", "TriggerBot", "Prediction", "Settings", "X")
		local readNumber = settings.number
		local isZero
		while true do
			isZero = xSetting == 0
			if seed == 381987185 then
				break
			end
			seed = bit32.bxor(seed, 1218651139)
		end
		if not isZero then
			return prediction.generic("TriggerBot", forecast.forecast(seed).velocity)
		end
		local bucket = bit32.band(xSetting // 8, 16383)
		local unused = 0
	end
	reset.reset = function()
		table.clear(scratchA)
		table.clear(scratchB)
		table.clear(scratchC)
	end
	reset.isOnTarget = function(isActive)
		if not (settings.bool(false, "Combat", "TriggerBot", "Enabled") and isActive.isActive()) then
			reset.reset()
			return false
		end
		local mode = triggerSettings.mode()
		local currentCamera = services.Workspace.CurrentCamera
		if not (mode ~= "Invalid" and currentCamera) then
			reset.reset()
			return false
		end
		if services.UserInputService:GetFocusedTextBox() then
			reset.reset()
			return false
		end
		local player = targeting.current()
		local character
		if player then
			character = player.Character
			if character then
				local rootPart = body.root(character)
				if not (player and character and rootPart) then
					reset.reset()
					return false
				end
				local ray = cursor.cursorRay()
				if not (mode ~= "Hitbox" or hoodGame.current()) then
					if not globals.flag("MobileShiftLock") and not globals.flag("MobleAimingIn") then
						if mode == "Hitbox" then
							table.pack(getPrediction(character))
						end
						reset.reset()
						if not checks.passes("Feature Checks", player, ray.Origin) then
							return false
						end
						getPrediction(character)
					end
					local cframe = currentCamera.CFrame
					local rayConstructor = Ray.new
					local position = cframe.Position
					local lookVector = cframe.LookVector
				end
				if mode == "Hitbox" then
					table.pack(getPrediction(character))
				end
				reset.reset()
				if not checks.passes("Feature Checks", player, ray.Origin) then
					return false
				end
				getPrediction(character)
			end
		else
			character = player
		end
		local targetCharacter = character
		if not (player and character and targetCharacter) then
			reset.reset()
			return false
		end
		local ray2 = cursor.cursorRay()
		if not (mode ~= "Hitbox" or hoodGame.current()) then
			if not globals.flag("MobileShiftLock") and not globals.flag("MobleAimingIn") then
				if mode == "Hitbox" then
					table.pack(getPrediction(character))
				end
				reset.reset()
				if not checks.passes("Feature Checks", player, ray2.Origin) then
					return false
				end
				getPrediction(character)
			end
			local cframe2 = currentCamera.CFrame
			local rayConstructor2 = Ray.new
			local position2 = cframe2.Position
			local lookVector2 = cframe2.LookVector
		end
		if mode == "Hitbox" then
			table.pack(getPrediction(character))
		end
		reset.reset()
		if not checks.passes("Feature Checks", player, ray2.Origin) then
			return false
		end
		getPrediction(character)
	end
	reset.localCharacter = function()
		return localPlayer.Character
	end
	return reset
end
modules.unnamed_aS = function()
	local geometry = modules.geometry()
	local function isValidSize(size)
		return size.X > 0 and size.Y > 0 and size.Z > 0 and size.X < math.huge and size.Y < math.huge and size.Z < math.huge
	end
	return {
		interval = function(ray, part, offset, scale)
			if 0 < scale then
				if not (scale < math.huge) then
					return nil, nil
				end
				if not (math.abs(offset.X) < math.huge) then
					return nil, nil
				end
				if not (math.abs(offset.Y) < math.huge) then
					return nil, nil
				end
				if not (math.abs(offset.Z) < math.huge) then
					return nil, nil
				end
				local halfSize = part.Size * (0.5 * math.min(scale, 1))
				if not isValidSize(halfSize) then
					return nil, nil
				end
				local nearT, farT = geometry.chord(part.CFrame + offset, halfSize, ray.Origin, ray.Direction)
				if nearT and farT and 0 <= nearT and nearT <= farT then
					local huge = math
					if not (farT >= nearT and not (farT < huge.huge)) then
						return nearT, farT
					end
				end
			end
			return nil, nil
		end,
		witness = function(ray, nearT, farT, origin)
			local point = ray.Origin + ray.Direction * (nearT + (farT - nearT) * 0.5)
			return point - origin, point
		end,
	}
end
modules.weaponAdapter = function()
	modules.hoodGame()
	local ownership = modules.ownership()
	local localPlayer = modules.services().Players.LocalPlayer
	local adapter = {}
	adapter.knockedAttribute = "Knocked"
	local function getAmmoValue(tool)
		local ammo = tool:FindFirstChild("AMMO")
		if ammo and ammo:IsA("NumberValue") then
			return ammo
		end
		return nil
	end
	local function getHandle(tool)
		local handle = tool:FindFirstChild("Handle")
		if handle and handle:IsA("BasePart") then
			return handle
		end
		return nil
	end
	local function getGunEvent(tool)
		local gunEvent = tool:FindFirstChild("rl")
		if gunEvent and gunEvent:IsA("RemoteEvent") then
			return gunEvent
		end
		return nil
	end
	local function hasValidGui()
		local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui")
		if playerGui then
			local localScript = playerGui:FindFirstChild("F")
			local gui = playerGui:FindFirstChild("gui")
			if localScript then
				if not localScript:IsA("LocalScript") then
					return false
				end
				if not localScript.Enabled and not ownership.has(localScript) then
					return null_stub(nil, unpack(nil, 1, null_stub.n))
				end
				if not gui then
					return false
				end
				if not gui:IsA("ScreenGui") then
					return false
				end
				local varLib = localScript:FindFirstChild("VarLib")
				return varLib ~= nil and varLib:IsA("ModuleScript")
			end
		end
		return false
	end
	local function getGroup(part)
		local group = part:GetAttribute("group")
		if not (type(group) ~= "number" and type(group) ~= "string") then
			local numericGroup = tonumber(group)
			if numericGroup and 0 < numericGroup and numericGroup < math.huge then
				return numericGroup
			end
		end
		return nil
	end
	adapter.equipped = function(character)
		local tool = character:FindFirstChildOfClass("Tool")
		if tool and getAmmoValue(tool) and getHandle(tool) and getGunEvent(tool) then
			return tool
		end
		return nil
	end
	adapter.isReady = function(character)
		if character ~= localPlayer.Character then
			return false
		end
		if not character.Parent then
			return false
		end
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
		local bodyvalues = character:FindFirstChild("bodyvalues")
		if not humanoid then
			return false
		end
		if humanoid.Health <= 0 then
			return false
		end
		if not humanoidRootPart then
			return false
		end
		if not humanoidRootPart:IsA("BasePart") then
			return false
		end
		if not bodyvalues then
			return false
		end
		local loaded = bodyvalues:FindFirstChild("LOADED")
		local slowdownCheck = bodyvalues:FindFirstChild("slowdown check")
		return loaded ~= nil and slowdownCheck ~= nil and localPlayer:FindFirstChildOfClass("Backpack") ~= nil and hasValidGui()
	end
	adapter.isKnocked = function(character)
		return character:GetAttribute("Knocked") == true
	end
	adapter.isAlly = function(partA, partB)
		local groupA = getGroup(partA)
		return groupA ~= nil and groupA == getGroup(partB)
	end
	adapter.stance = function(character)
		if character == localPlayer.Character then
			local backpack = localPlayer:FindFirstChildOfClass("Backpack")
			if backpack and backpack:GetAttribute("IsReloading") == true then
				return "Reloading"
			end
			local bodyvalues = character:FindFirstChild("bodyvalues")
			if bodyvalues then
				local slowdownCheck = bodyvalues:FindFirstChild("slowdown check")
				if slowdownCheck and slowdownCheck:FindFirstChild("shot") then
					return "Shooting"
				end
			end
		end
		return "Normal"
	end
	adapter.canShoot = function(character, tool)
		if not adapter.isReady(character) then
			return false
		end
		if adapter.isKnocked(character) then
			return false
		end
		if tool.Parent ~= character then
			return false
		end
		local enabled = tool.Enabled
	end
	adapter.activate = function(tool)
		pcall(tool.Activate, tool)
	end
	adapter.deactivate = function(tool)
		pcall(tool.Deactivate, tool)
	end
	adapter.muzzle = function(tool)
		local handle = getHandle(tool)
		if not handle then
			return nil
		end
		local flare = handle:FindFirstChild("Flare")
		if flare and flare:IsA("Attachment") then
			return flare.WorldPosition
		end
		return handle.Position
	end
	return adapter
end
