modules.daHoodGuns = function()
	local daHoodState = modules.daHoodState()
	local mod_current = modules.unnamed_aq()
	local services = modules.services()
	local shotgunSpread = modules.shotgunSpread()
	local wallShot = modules.wallShot()
	local function getMainEvent()
		local mainEvent = services.ReplicatedStorage:FindFirstChild("MainEvent")
		return if mainEvent and mainEvent:IsA("RemoteEvent") then mainEvent else nil
	end
	return {
		name = "Da Hood",
		specificSection = nil,
		isCompensated = true,
		beamColor = nil,
		checksClientAmmo = false,
		emulatesFlintlock = true,
		localClock = os.clock,
		canShoot = daHoodState.check,
		spread = function()
			return Vector3.new(mod_current.spreadAxis(0.05), mod_current.spreadAxis(0.1), mod_current.spreadAxis(0.05))
		end,
		rollSpread = shotgunSpread.next,
		refundSpread = shotgunSpread.refund,
		wallShot = wallShot.cast,
		send = function(shotData)
			local mainEvent = getMainEvent()
			if mainEvent then
				local serverTime = shotData.serverTime
				local spreadId = shotData.spreadId
				for _, shot in shotData.shots do
					if serverTime and spreadId then
						mainEvent:FireServer("ShootGun", shotData.handle, shot.origin, shot.position, shot.instance, shot.normal, serverTime, spreadId, shot.pellet)
					elseif serverTime then
						mainEvent:FireServer("ShootGun", shotData.handle, shot.origin, shot.position, shot.instance, shot.normal, serverTime)
					else
						mainEvent:FireServer("ShootGun", shotData.handle, shot.origin, shot.position, shot.instance, shot.normal)
					end
				end
			end
		end,
		gripChanged = function()
			local mainEvent = getMainEvent()
			if mainEvent then
				mainEvent:FireServer("CHECKER_4")
			end
		end,
		start = shotgunSpread.watch,
	}
end
modules.daHoodState = function()
	local mod_play = modules.unnamed_aZ()
	local services = modules.services()
	local mod_isFxReduced = modules.unnamed_a_()
	local attributes = modules.attributes()
	local weaponNumbers = modules.weaponNumbers()
	local mod_cOOLDOWN_PADDING_0_0095 = modules.unnamed_ai()
	local gunNames = {}
	gunNames["[Deagle]"] = true
	gunNames["[Rifle]"] = true
	gunNames["[Glock]"] = true
	gunNames["[Silencer]"] = true
	local blockingParts = {}
	blockingParts[1] = "FORCEFIELD"
	blockingParts[2] = "GRABBING_CONSTRAINT"
	blockingParts[3] = "Christmas_Sock"
	blockingParts[4] = "[CarHitBox]"
	local basketballAttributes = {}
	basketballAttributes[1] = "BasketballTeam"
	basketballAttributes[2] = "BasketballZone"
	local blockingEffects = {}
	blockingEffects[1] = "Cuff"
	blockingEffects[2] = "Attacking"
	blockingEffects[3] = "K.O"
	blockingEffects[4] = "Grabbed"
	blockingEffects[5] = "Dead"
	local blockingReloadStates = {}
	blockingReloadStates[1] = "K.O"
	blockingReloadStates[2] = "Grabbed"
	blockingReloadStates[3] = "Reload"
	blockingReloadStates[4] = "Dead"
	local isFixedAmmoPlace = game.PlaceId == mod_cOOLDOWN_PADDING_0_0095.FIXED_AMMO_PLACE_ID
	local function serverTime()
		return services.Workspace:GetServerTimeNow()
	end
	local localClock = {}
	localClock.localClock = os.clock
	localClock.allowsShellReload = true
	localClock.usesLegacySpeed = true
	local allowsShellReload = {}
	allowsShellReload.localClock = serverTime
	allowsShellReload.allowsShellReload = false
	allowsShellReload.usesLegacySpeed = false
	local isEffectOn = {}
	local function reloadDelay(gunName, lastGun)
		local delayTable
		if gunName ~= nil and delayTable[gunName] and delayTable[lastGun] then
			delayTable = { 0.5 }
		else
			delayTable = { 0.1 }
		end
		return delayTable[1]
	end
	local function readEffectValue(parent, name)
		local effect = parent:FindFirstChild(name)
		if effect then
			if effect:IsA("BoolValue") then
				return effect.Value
			end
			if effect:IsA("ObjectValue") then
				return effect.Value ~= nil
			end
		end
		return nil
	end
	local function isHumanoidAlive(character)
		local humanoid = character:FindFirstChild("Humanoid")
		local alive = humanoid ~= nil
		if humanoid ~= nil then
			local isHumanoid = humanoid:IsA("Humanoid")
			if not isHumanoid then
				return isHumanoid
			end
			alive = humanoid.Health > 0
			if humanoid.Health > 0 then
				return humanoid:GetState() ~= Enum.HumanoidStateType.Dead
			end
		end
		return alive
	end
	local function playNoAmmo(character)
		local noAmmo = character:FindFirstChild("NoAmmo")
		if noAmmo and noAmmo:IsA("Sound") then
			noAmmo:Play()
		end
	end
	local function legacyShotDelay(config)
		if config.usesLegacySpeed and mod_isFxReduced.isLegacyShooting() then
			return 1.25
		end
		return nil
	end
	local function shouldBlockShot(config, bodyEffects, handle, ammo)
		if isFixedAmmoPlace then
			return true
		end
		if bodyEffects:FindFirstChild("Block") then
			mod_play.play(handle, legacyShotDelay(config))
		elseif ammo ~= 0 then
			return true
		end
		playNoAmmo(handle)
		return false
	end
	local function isFlintlockAllowed(tool)
		local serverAim = attributes.isTruthy(services.Workspace:GetAttribute("SERVER_AIM"))
		if tool.Name ~= "[Flintlock]" then
			return serverAim
		end
		if serverAim then
			return serverAim
		end
		return (attributes.isTruthy(services.Workspace:GetAttribute("FlintlockDisabled")))
	end
	local function shouldReload(config, character, tool, ammo)
		local reloadState = readEffectValue(character, "Reload")
		if reloadState ~= false then
			if reloadState == nil then
				return true
			end
			if not config.allowsShellReload then
				return true
			end
			local reload = character:FindFirstChild("Reload")
			local needsReload = reload == nil
			if not (reload == nil) then
				needsReload = reload:GetAttribute("ShellReload") ~= tool.Name
				if not needsReload then
					return ammo <= 0
				end
			end
			return needsReload
		end
		return false
	end
	local function isEffectBlocking(effects, character, bodyEffects, tool, ammo)
		if character:FindFirstChild("FULLY_LOADED_CHAR") == nil then
			return true
		end
		for _, part in blockingParts do
			if character:FindFirstChild(part) then
				return true
			end
		end
		for _, attribute in basketballAttributes do
			if attributes.isTruthy(character:GetAttribute(attribute)) then
				return true
			end
		end
		for _, effect in effects do
			if readEffectValue(bodyEffects, effect) ~= false then
				return true
			end
		end
		return shouldReload(effects, bodyEffects, tool, ammo)
	end
	local function isRecentShot(part, gunName, now, lastGunAttr, lastShotAttr)
		local lastGun = part:GetAttribute(lastGunAttr)
		local lastShotAt = attributes.attribute(part, lastShotAttr)
		local lastGunName = if type(lastGun) ~= "string" then nil else lastGun
		return lastGun ~= gunName and lastShotAt ~= nil and now - lastShotAt < reloadDelay(lastGunName, gunName)
	end
	local function isCoolingDown(config, character, tool)
		local cooldownSetting = attributes.child(tool, "ShootingCooldown")
		if not cooldownSetting then
			return false
		end
		local now = config.localClock()
		local localLastShot = attributes.attribute(tool, "LocalLastShotAt")
		if localLastShot and now - localLastShot < cooldownSetting * weaponNumbers.delay(tool.Name) then
			return true
		end
		local recentLocal = isRecentShot(character, tool.Name, now, "LocalLastFiredGun", "LocalLastGunShotAt")
		if recentLocal then
			return recentLocal
		end
		return (isRecentShot(character, tool.Name, serverTime(), "LastFiredGun", "LastGunShotAt"))
	end
	isEffectOn.isEffectOn = function(parent, name)
		return parent ~= nil and readEffectValue(parent, name) == true
	end
	isEffectOn.basic = function(character)
		if not character then
			return false
		end
		if not isHumanoidAlive(character) then
			return false
		end
		local tool = character:FindFirstChildWhichIsA("Tool")
		if not tool then
			return false
		end
		local handle = tool:FindFirstChild("Handle")
		local ammo = attributes.child(tool, "Ammo")
		if not handle then
			return false
		end
		if not handle:IsA("BasePart") then
			return false
		end
		if ammo and ammo <= 0 then
			return false
		end
		local bodyEffects = character:FindFirstChild("BodyEffects")
		for _, effect in blockingReloadStates do
			if isEffectOn.isEffectOn(bodyEffects, effect) then
				return false
			end
		end
		return not tool:GetAttribute("Cooldown")
	end
	local function canFireWith(config, character)
		if character then
			if not isHumanoidAlive(character) then
				return false
