modules.aimDirection = function()
	local globals = modules.globals()
	local visibility = modules.visibility()
	local services = modules.services()
	local localPlayer = services.Players.LocalPlayer
	local mouse = localPlayer:GetMouse()
	local raycastParams = RaycastParams.new()
	raycastParams.FilterType = Enum.RaycastFilterType.Exclude
	raycastParams.IgnoreWater = true
	local ignoreList = {}
	local function buildRaycastParams()
		table.clear(ignoreList)
		if localPlayer.Character then
			repeat
			until false
		end
		local folders, blocker = visibility.sceneFolders()
		if blocker then
			if not (blocker:IsA("BasePart") or blocker:IsA("Terrain")) then
				table.insert(ignoreList, blocker)
				visibility.appendProtected(ignoreList)
				raycastParams.FilterDescendantsInstances = ignoreList
				return raycastParams
			end
			for _, child in blocker:GetChildren() do
				table.insert(ignoreList, child)
			end
		end
		visibility.appendProtected(ignoreList)
		raycastParams.FilterDescendantsInstances = ignoreList
		return raycastParams
	end
	local function rayFromPart(part, distance, params)
		local position = part.CFrame.Position
		local displacement = part.CFrame.LookVector * distance
		local hit = services.Workspace:Raycast(position, displacement, params)
		local endpoint
		if hit then
			endpoint = { hit.Position }
		else
			endpoint = { position + displacement }
		end
		return endpoint[1]
	end
	local function rayFromCamera(camera, distance, params)
		local ray = camera:ScreenPointToRay(mouse.X, mouse.Y)
		local object = services.Workspace:Raycast(ray.Origin, ray.Direction * distance, params)
		if object then
			return object.Position
		end
		local cframe = camera.CFrame
		local lookVector = cframe.LookVector
		local projection = (cframe.Position + lookVector * distance - ray.Origin):Dot(lookVector) / ray.Direction:Dot(lookVector)
		return ray.Origin + ray.Direction * projection
	end
	return {
		direction = function(origin, range)
			local maxDistance = range or 200
			local currentCamera = services.Workspace.CurrentCamera
			local params = range()
			local endpoints
			if globals.flag("MobileShiftLock") or globals.flag("MobleAimingIn") then
				endpoints = {}
				endpoints[1] = params(currentCamera, maxDistance, params)
			else
				endpoints = { (endpoints(currentCamera, maxDistance, params)) }
			end
			local vector = endpoints[1] - origin
			return vector.Unit, vector.Magnitude
		end,
	}
end
modules.ragdollLike = function()
