	local function constrainToBounds(humanoid, object, direction, crossFn)
		local boundsCFrame
		if humanoid then
			boundsCFrame = humanoid:GetAttribute("BoundsCFrame")
			humanoid = humanoid:GetAttribute("BoundsSize")
		else
			boundsCFrame = humanoid
		end
		if typeof(boundsCFrame) ~= "CFrame" then
			return true
		end
		if typeof(humanoid) ~= "Vector3" then
			return true
		end
