		local localPosition = boundsCFrame:PointToObjectSpace(object.Position)
		local localDirection = boundsCFrame:VectorToObjectSpace(direction)
		local scaledDirection = localDirection * math.max(crossFn, 10 / math.max(direction.Magnitude, 1))
		local hitX = crossFn(localPosition.X, scaledDirection.X, localDirection.X, halfBounds.X)
		local hitY = crossFn(localPosition.Y, scaledDirection.Y, localDirection.Y, halfBounds.Y)
		local hitZ = crossFn(localPosition.Z, scaledDirection.Z, localDirection.Z, halfBounds.Z)
