			if not stopped then
				stopped = attributes.isTruthy(character:GetAttribute("RankedRecovering"))
				if not stopped then
					stopped = daHoodState.isEffectOn(character:FindFirstChild("BodyEffects"), "K.O")
					if not stopped then
