		scope:add(character:GetAttributeChangedSignal("RankedRoundId"):Connect(function()
			if character:GetAttribute("RankedRoundId") ~= roundId then
				scope:destroy()
			end
		end))
		scope:add(gun.tool:GetPropertyChangedSignal("Enabled"):Connect(function()
			if not gun.tool.Enabled then
