end
modules.soundPlayer = function()
	local services = modules.services()
	local urlsModule = modules.urls()
	local activeSounds = {}
	local function scheduleCleanup(sound)
		task.delay(math.max(sound.TimeLength, 3), function()
			sound:Destroy()
		end)
	end
	local function advanceSequence(handle)
		local sequence = handle:GetAttribute("SequenceSFX")
		if type(sequence) ~= "string" then
			return
		end
		local currentSequence = handle:GetAttribute("CurrentSequence")
		local sequenceType = type(currentSequence)
		local nextSequence = 1
		if sequenceType == "number" then
			nextSequence = currentSequence + 1
		end
		handle:SetAttribute("CurrentSequence", nextSequence)
		local ids = urlsModule.urls(sequence)
		if 0 < #ids then
			handle.SoundId = ids[nextSequence % #ids + 1] or "rbxassetid://nil"
		end
	end
	local function playDefault(parent, sound)
		local copy = sound:Clone()
		copy:SetAttribute("SequenceSFX", nil)
		local defaultId = sound:GetAttribute("DefaultSoundId")
		local defaultSpeed = sound:GetAttribute("DefaultPlaybackSpeed")
		if type(defaultId) == "string" then
			copy.SoundId = defaultId
		end
		if type(defaultSpeed) == "number" then
			copy.PlaybackSpeed = defaultSpeed
		end
		copy.Name = "DefaultShoot"
		copy.Parent = parent
		services.CollectionService:AddTag(copy, "GunSounds")
		copy:Play()
		scheduleCleanup(copy)
	end
	local function playSequence(parent, sound, isMachineGun)
		advanceSequence(sound)
		if isMachineGun then
			local object = sound:Clone()
			object.Name = "MG"
			object.Parent = parent
			object:Play()
			scheduleCleanup(object)
		else
			sound:Play()
		end
	end
	local function playShoot(handle, isMachineGun, includeDefault)
		local shootSound = handle:FindFirstChild("ShootSound")
		if not shootSound then
			return
		end
		if shootSound:IsA("Sound") then
			if includeDefault then
				playDefault(handle, shootSound)
			else
				playSequence(handle, shootSound, isMachineGun)
			end
		end
	end
	return {
		isThrottled = function(handle)
			return activeSounds[handle] == true
		end,
		play = function(handle, soundName, isMachineGun)
			if activeSounds[handle] then
				return
			end
			activeSounds[handle] = true
			task.delay(0.021, function()
				activeSounds[handle] = nil
			end)
			task.spawn(playShoot, handle, soundName ~= "Brainrot", isMachineGun)
		end,
	}
end
modules.urls = function()
