modules.emit = function()
	local function findMesh(tool)
		if tool then
			tool = tool:FindFirstChild("Default")
			if tool then
				return (tool:FindFirstChild("Mesh"))
			end
		end
		return tool
	end
	local function getEmitCount(emitter)
		local count = emitter:GetAttribute("EmitCount")
		if type(count) ~= "number" then
			return 1
		end
		return count
	end
	local function emitFrom(emitter, parent, useOriginal, keepAlive)
		local object
		if useOriginal then
			object = emitter
		else
			object = emitter:Clone()
		end
		object.Parent = parent
		object:Emit(getEmitCount(emitter))
		if not keepAlive then
			task.delay(object.Lifetime.Max, function()
				object:Destroy()
			end)
		end
	end
	local function emitAll(particles, parent, isLeftHand, isDual)
		for _, particle in particles:GetChildren() do
			if particle:IsA("ParticleEmitter") then
				isDual(particle, parent, isLeftHand, isDual)
			end
		end
	end
	local function findMuzzleEmitter(handle, name)
		local mesh = findMesh(handle.handle.Parent)
		if mesh then
			local emitter = mesh:FindFirstChild(name)
			if emitter then
				if handle.isLeftHand then
					local leftMesh = mesh:FindFirstChild("DualWieldLeftHandMesh")
					if leftMesh then
						local matched = leftMesh:FindFirstChild(name)
						if not matched then
							matched = emitter
						end
						if matched ~= emitter then
							return matched, true
						end
						return emitter, false
					end
					if emitter ~= emitter then
						return emitter, true
					end
				end
				return emitter, false
			end
		end
		local fallback = handle.handle:FindFirstChild(name)
		if handle.isLeftHand then
			if mesh then
				local leftMesh = mesh:FindFirstChild("DualWieldLeftHandMesh")
				if leftMesh then
					local matched = leftMesh:FindFirstChild(name)
					if not matched then
						matched = fallback
					end
					if matched ~= fallback then
						return matched, true
					end
					return fallback, false
				end
			end
			if fallback ~= fallback then
				return fallback, true
			end
		end
		return fallback, false
	end
	local function chooseParticles(info, name, emitter, isDual)
		if isDual then
			return emitter
		end
		local particles = info.particles
		local muzzle = particles:FindFirstChild("Muzzle")
		if muzzle then
			muzzle = muzzle:FindFirstChild("Different_GunMuzzle")
		end
		local found = particles:FindFirstChild(name)
		if muzzle and found then
			found = found:FindFirstChild("Different_GunMuzzle")
			if found then
				return (found:FindFirstChild(info.toolName))
			end
		end
		return found
	end
	local function emitRandom(info)
		local children = info.particles:GetChildren()
		if #children == 0 then
			return
		end
		local object = children[math.random(#children)]:Clone()
		object.Parent = info.originAttachment
		if object:IsA("ParticleEmitter") then
			object:Emit(object.Rate)
		end
	end
	return {
		emit = function(info)
			local name = if info.isLeftHand then "LeftMuzzle" else "Muzzle"
			if info.particles:FindFirstChild(name) or info.isLeftHand then
				local emitter, isDual = findMuzzleEmitter(info, name)
				if not emitter then
					return
				end
				local particles = chooseParticles(info, name, emitter, isDual)
				if particles then
					emitAll(particles, emitter, info.isLeftHand, isDual)
				end
			else
				emitRandom(info)
			end
		end,
	}
end
