modules.hitboxExpander_bi = function()
	local body = modules.body()
	local settings = modules.settings()
	local hitboxExpander = modules.hitboxExpander()
	local targeting = modules.targeting()
	local services = modules.services()
	modules.unnamed_o()
	local localPlayer = services.Players.LocalPlayer
	local expanders = {}
	local function getExpandSize(part)
		local sizeSetting = settings.table("Combat", "HitboxExpander", "Size")
		if not sizeSetting then
			return nil
		end
		local sizeX = sizeSetting.X
		local sizeY = sizeSetting.Y
		local sizeZ = sizeSetting.Z
		if type(sizeX) ~= "number" then
			return nil
		end
		if type(sizeY) ~= "number" then
			return nil
		end
		if type(sizeZ) ~= "number" then
			return nil
		end
		local scale = Vector3.new(math.max(sizeX, 0), math.max(sizeY, 0), math.max(sizeZ, 0))
		if settings.string("Multiply", "Combat", "HitboxExpander", "Type") ~= "Normal" then
			return part.Size * scale
		end
		return scale
	end
	local function onPlayerRemoving(player)
		local expander = expanders[player]
		expanders[player] = nil
		if expander then
			hitboxExpander.untrack(expander)
			expander:Destroy()
		end
	end
	local function clearAll()
		for player in expanders do
			onPlayerRemoving(player)
		end
	end
	local function weldTo(part, target)
		part.CFrame = target.CFrame
		local weldConstraint = Instance.new("WeldConstraint")
		weldConstraint.Part0 = target
		weldConstraint.Part1 = part
		weldConstraint.Parent = part
	end
	local function createExpander(parent, part)
		local expander = Instance.new("Part")
		expander.Name = hitboxExpander.NAME
		expander.Transparency = 1
		expander.CanCollide = false
		expander.CanTouch = false
		expander.CanQuery = true
		expander.Massless = true
		expander.Anchored = false
		expander.CastShadow = false
		expander.Size = part.Size
		weldTo(expander, part)
		expander.Parent = parent
		return expander
	end
	local function ensureExpander(player, character, rootPart, rootSize)
		local existing = expanders[player]
		if existing and existing.Parent ~= character then
			onPlayerRemoving(player)
		end
		local expander = existing[player] or hitboxExpander.expander(character) or createExpander(character, rootPart)
		expanders[player] = expander
		hitboxExpander.track(expander)
		local currentSize = expander.Size
		repeat
			if currentSize ~= rootSize then
				expander.Size = rootSize
			end
			rootSize = expander:FindFirstChildOfClass("WeldConstraint")
			currentSize = not existing
		until existing
		if rootSize then
			if rootSize.Part0 == rootPart then
				return
			end
			rootSize:Destroy()
		end
		weldTo(expander, rootPart)
	end
	local function updatePlayer(player)
		local character = player.Character
		local rootPart
		if character then
			rootPart = body.root(character)
			if rootPart then
				local rootSize = rootPart(rootPart)
				if rootSize and player ~= localPlayer then
					ensureExpander(player, character, rootPart, rootSize)
				else
					onPlayerRemoving(player)
				end
				return
			end
		else
			rootPart = character
		end
		local fallback = rootPart
		if character then
			if rootPart then
				if fallback then
					if player == localPlayer then
						onPlayerRemoving(player)
					else
						ensureExpander(player, character, rootPart, fallback)
					end
				else
					onPlayerRemoving(player)
				end
			else
				onPlayerRemoving(player)
			end
		else
			onPlayerRemoving(player)
		end
	end
	local function refresh()
		if settings.bool(false, "Combat", "HitboxExpander", "Enabled") then
			if settings.bool(true, "Combat", "HitboxExpander", "Target Only") then
				local currentTarget = targeting.current()
				for player in currentTarget do
					if player ~= currentTarget then
						onPlayerRemoving(player)
					end
				end
				if currentTarget then
					updatePlayer(currentTarget)
				end
			else
				for _, player in services.Players:GetPlayers() do
					updatePlayer(player)
				end
			end
		else
			local first = next(expanders)
			if expanders and first then
				clearAll()
			end
		end
	end
	return {
		name = "HitboxExpander",
		start = function(scope)
			scope:add(services.RunService.Heartbeat:Connect(function(delta)
				delta = delta + delta
				if 0.1 <= delta then
					delta = 0
					refresh()
				end
			end))
			scope:add(services.Players.PlayerRemoving:Connect(onPlayerRemoving))
			scope:add(scope)
		end,
	}
end
modules.reportSystem = function()
	local settings = modules.settings()
	local services = modules.services()
	modules.unnamed_o()
	local localPlayer = services.Players.LocalPlayer
	local seen = {}
	local lastReportTime = -math.huge
	local function isEnabled()
		return settings.bool(false, "Utilities", "Report System", "Enabled")
	end
	local function getAction(setting)
		return settings.bool(false, "Utilities", "Report System", "On Report", setting)
	end
	local function notify(message)
		local smallNotice = shared.SmallNotice
		if type(smallNotice) ~= "function" or not pcall(smallNotice, message) then
			pcall(services.StarterGui.SetCore, services.StarterGui, "SendNotification", { Title = "Atomic", Text = message, Duration = 5 })
		end
	end
	local function fireReport(reporterId)
		local mainEvent = services.ReplicatedStorage:FindFirstChild("MainEvent")
		if mainEvent and mainEvent:IsA("RemoteEvent") then
			mainEvent:FireServer("REPORT_PLAYER", reporterId, "AimManipulation")
		end
	end
	local function formatReporter(player, reporterId)
		if player then
			return string.format("%s (@%s)", tostring(player.DisplayName), tostring(player.Name))
		end
		local label
		if reporterId then
			label = string.format("User %s", tostring(reporterId))
		else
			label = "Someone"
		end
		return label
	end
	local function handleReport(key, reportSettings)
		if seen[key] then
			return
		end
		if not reportSettings() then
			return
		end
		seen[key] = true
		local players
		if reportSettings then
			players = {}
			players[1] = services.Players:GetPlayerByUserId(reportSettings)
		else
			players = { nil }
		end
		local reporter = players[1]
		local label = formatReporter(reporter, reportSettings)
		if reporter("Notify") then
			notify(string.format("%s reported you", tostring(label)))
		end
		if reporter("Report Back") and reporter then
			fireReport(reporter)
		end
		if reporter("Kick") then
			task.delay(0.5, function()
				localPlayer:Kick(string.format("Atomic: %s reported you.", tostring(label)))
			end)
		end
	end
	local function watchReports(scope)
		local dataFolder = localPlayer:WaitForChild("DataFolder", 30)
		if not dataFolder then
			return
		end
		local reporters = dataFolder:WaitForChild("Reporters", 30)
		if reporters then
			for _, object in reporters:GetChildren() do
				seen[string.format("reporter:%s", tostring(object.Name))] = true
			end
			scope:add(reporters.ChildAdded:Connect(function(object)
				lastReportTime = os.clock()
				handleReport(string.format("reporter:%s", tostring(object.Name)), tonumber(object.Name))
			end))
		end
		local reportedCount = dataFolder:FindFirstChild("ReportedCount")
		if reportedCount and reportedCount:IsA("IntValue") then
			scope:add(reportedCount.Changed:Connect(function(newCount)
				local previous = newCount
				if not (newCount <= previous) then
					task.delay(0.5, function()
						local elapsed = os.clock() - previous
						if not (1 < elapsed) then
							return
						end
						handleReport(string.format("count:%s", tostring(newCount)), nil)
					end)
				end
			end))
		end
	end
	return {
		name = "ReportSystem",
		start = function(scope)
			scope:add(task.spawn(watchReports, scope))
		end,
	}
end
modules.silentAim = function()
	local nativeHit = modules.unnamed_bn()
	local gameSupport = modules.unnamed_aq()
