			local activation = keybind.activation(scope, "Combat", "SilentAim", "Activation")
			if gameSupport.current().isCompensated then
				planning.set(function(packet)
					local planned = silentAimScatter.plan(packet, activation)
					if planned then
						return planned
					end
					return nativeHit.plan(packet)
				end)
			else
				planning.set(function(packet)
					return silentAimPlan.plan(packet, packet)
				end)
			end
			scope:add(function()
				planning.set(nil)
