modules.unnamed_bn = function()
	local body = modules.body()
	modules.unnamed_bf()
	local visibility = modules.visibility()
	local forecast = modules.forecast()
	local services = modules.services()
	local hitPackets = modules.hitPackets()
	local nativeModule = modules.native()
	local localPlayer = services.Players.LocalPlayer
	local solution = {}
	solution.solution = function(target)
		local predictionResult = forecast.forecast(target)
		local offset, radius = nativeModule.native(predictionResult)
		return { offset = offset, radius = radius, forecast = predictionResult }
	end
	solution.nativeHit = function(shot, offset)
		local instance = visibility.cast(shot.origin, (shot.direction + offset).Unit * shot.range, shot.shooter)
		if instance then
			local owner, character = body.ownerOf(instance.Instance)
			if not owner then
				return nil, nil
			end
			if owner == localPlayer then
				return nil, nil
			end
			if character then
				if visibility.isClear(shot.origin, instance.Position, shot.shooter, character) then
					return instance, character
				end
				return nil, nil
			end
		end
		return nil, nil
	end
	solution.plan = function(packet)
		if packet.isSeeded then
			return nil
		end
		return function(offset)
			local hit, targetPart = solution.nativeHit(packet, offset)
			if not hit then
				return nil
			end
			if not targetPart then
				return nil
			end
			return hitPackets.pellet("Compensated", packet, targetPart, hit, solution.solution(targetPart))
		end
	end
	return solution
end
