modules.unnamed_bk = function()
	local body = modules.body()
	local visibility = modules.visibility()
	local weaponNumbers = modules.weaponNumbers()
	local partPriority = {}
	partPriority.Max = "Head"
	partPriority.Normal = "UpperTorso"
	local function getOverride(weaponName)
		local override = weaponNumbers.value("Damage Overrider", weaponName)
		return if type(override) ~= "string" then nil else override
	end
	return {
		credit = function(weapon, shooter, targetPart, origin, hitPart)
			local preferred
			if hitPart then
				preferred = partPriority[getOverride(weapon.Name) or ""]
			else
				preferred = nil
			end
			local partName = preferred
			if partName then
				local replacement = body.part(targetPart, partName)
				if replacement then
					if replacement == hitPart then
						return hitPart
					end
					return if visibility.reach(origin, replacement.Position, shooter, targetPart) then replacement else hitPart
				end
			end
			return hitPart
		end,
		nearest = function(weapon, targetPart, point)
			local preferred = partPriority[getOverride(weapon.Name) or ""]
			if preferred then
				local part = body.part(targetPart, preferred)
				if part then
					return part
				end
			end
			local bestDistance = math.huge
			local bestPart = nil
			for _, candidate in body.PARTS do
				local part = body.part(targetPart, candidate)
				if not part then
					continue
				end
				local magnitude = (part.Position - point).Magnitude
				if magnitude < bestDistance then
					bestDistance = magnitude
					bestPart = part
				end
			end
			if bestPart then
				return bestPart
			end
			return (body.root(targetPart))
		end,
	}
end
modules.native = function()
	modules.forecast()
	return {
		native = function(uncertainty)
			local radius = math.max(22 - uncertainty.uncertainty, 12)
			local vector = uncertainty.displacement
			local magnitude = vector.Magnitude
			if magnitude <= radius then
				return Vector3.zero, radius
			end
			return vector / magnitude * (magnitude - radius), radius
		end,
	}
end
modules.silentAimPlan = function()
	local body = modules.body()
	local credit = modules.unnamed_bk()
	local silentAimTarget = modules.silentAimTarget()
	modules.unnamed_bf()
	modules.keybind()
	local visibility = modules.visibility()
	local prediction = modules.prediction()
	local hitPackets = modules.hitPackets()
	local function predictHit(shot, blocker, targetPart, contact)
		local lead = prediction.generic("SilentAim", targetPart.AssemblyLinearVelocity)
		if lead == Vector3.zero then
			return contact.Position
		end
		local predicted = contact.Position + lead
		local candidates
		if hitPackets.isInRange(shot, shot.origin, predicted) and visibility.isClear(shot.origin, predicted, shot.shooter, blocker) then
			candidates = { predicted }
		else
			candidates = { contact.Position }
		end
		return candidates[1]
	end
	local function makeAim(shot, targetPart, instance, aimPoint)
		local visual = hitPackets.hitOf(instance)
		visual.position = aimPoint
		return {
			aimPosition = aimPoint,
			visual = visual,
			packet = {
				origin = shot.origin,
				position = aimPoint,
				instance = credit.credit(shot.tool, shot.shooter, targetPart, shot.origin, instance.Instance),
				normal = instance.Normal,
			},
			entry = nil,
		}
	end
	return {
		plan = function(shot, activation)
			local target, rootPart = silentAimTarget.target(shot, activation)
			if not target or not rootPart then
				return nil
			end
			if body.hasForceField(target) then
				return nil
			end
			local contact = silentAimTarget.contact(shot, target, silentAimTarget.candidates(shot, target))
			if not contact then
				return nil
			end
			local aimPoint = target(shot, target, rootPart, contact)
