				return adjusted(shot, offset, adjusted, if shifted ~= aimPoint and hitPackets.isInRange(shot, shot.origin, shifted) and visibility.isClear(shot.origin, shifted, shot.shooter, offset) then shifted else aimPoint)
			end
		end,
	}
end
