		local policy = packetOrigin.packetOrigin
		local findResult = policy.policy
		local candidatePoint = policy.position ~= packetOrigin.origin
		for _, insertList in insertList do
			if blockedCheck(insertList, packetOrigin.shooter) then
				continue
			end
			if policy.position ~= packetOrigin.origin and rangeCheck(packetOrigin, policy.position, insertList, insertIndex) then
				return { point = insertList, center = historyBuffer, budget = offsetDirections, origin = policy.position, policy = findResult }
			end
			if rangeCheck(packetOrigin, packetOrigin.origin, insertList, insertIndex) then
				return {
					point = insertList,
					center = historyBuffer,
					budget = offsetDirections,
					origin = packetOrigin.origin,
					policy = "Muzzle",
				}
			end
		end
		return nil
	end
	local function cachedSnapCheck(candidatePoint, candidateDistance, insertList)
		if target.target ~= candidatePoint then
			return false, nil
		end
		local findResult = insertList - target.at
		local insertIndex = not target
		local magnitude3 = (nil % nil - target.anchor).Magnitude
		if not target.snap then
			local historyBuffer = findResult <= 0.3
			if findResult <= 0.3 then
				historyBuffer = insertIndex < 2
				if not target < 2 then
					return magnitude3 < 1.25, nil
				end
			end
			return historyBuffer, nil
		end
		local offsetDirections = findResult <= 0.05
		if findResult <= 0.05 then
			offsetDirections = insertIndex < 1
			if not target < 1 then
				offsetDirections = magnitude3 < 0.9
				if magnitude3 < 0.9 then
					return offsetDirections, ({ target.snap })[1]
				end
			end
		end
		return offsetDirections, ({ nil })[1]
	end
	local function cacheSnapshot(findResult, candidatePoint, insertList, insertIndex, historyBuffer)
		target.target = findResult
		target.origin = candidatePoint
		target.anchor = insertList
		target.at = insertIndex
		target.snap = historyBuffer
		return historyBuffer
	end
	return {
		find = function(origin, insertIndex, object, raySample, offsetDirections)
			local findResult = os.clock()
			local position = object.Position
			local candidatePoint, insertList = cachedSnapCheck(insertIndex, origin.origin, findResult)
			if candidatePoint then
				return insertList
			end
			local historyBuffer = offsetDirections - 2
			local insertByDistance = position + raySample
			if historyBuffer <= 0 or origin.range + historyBuffer < (insertByDistance - origin.origin).Magnitude then
				return cacheSnapshot(insertIndex, origin.origin, position, findResult, nil)
			end
			table.clear(insertList)
			local historyScan = table.clear
			repeat
				historyScan(insertIndex)
				insertByDistance(insertByDistance, historyBuffer, insertByDistance)
				raySample(origin, insertByDistance, historyBuffer)
				historyScan = not not insertByDistance
			until insertByDistance
			historyScan(insertIndex, insertByDistance, historyBuffer)
			sampleList(origin, insertByDistance, historyBuffer)
			return cacheSnapshot(insertIndex, origin.origin, position, findResult, pickCandidate(origin, insertIndex, insertByDistance, historyBuffer))
		end,
		scatter = function(shooter, findResult, point, vector)
			if not (vector.Magnitude < 0.001) then
				local candidatePoint = point.point + vector
				if point.budget < (candidatePoint - point.center).Magnitude then
					return point.point
				end
				if blockedCheck(candidatePoint, shooter.shooter) then
					return point.point
				end
				if rangeCheck(shooter, point.origin, candidatePoint, findResult) then
					return candidatePoint
				end
			end
			return point.point
		end,
	}
end
modules.skinChanger = function()
	local skins = modules.skins()
	local settings = modules.settings()
	local skinMount = modules.skinMount()
	modules.scope()
	local skinApply = modules.skinApply()
	local services = modules.services()
	modules.unnamed_o()
	local mod_choice = modules.unnamed_by()
	local skinState = {}
	local trackedTools = {}
	local function chooseSkin(object)
		local skinState = mod_choice.choice(skins.toolKey(object.Name))
		if skinState then
			return skinState
		end
		local enabled = settings.get("Weapon", "Skin Modifier")
		if type(enabled) == "table" then
			if enabled.Enabled ~= true then
				return nil
			end
			if type(enabled.Settings) ~= "table" then
				return nil
			end
			if enabled.Settings[object.Name] then
				return nil, "humanoid"
			end
		end
		return nil
	end
	local function isKnife(object)
		return string.find(string.lower(object.Name), "knife", 1, true) ~= nil
	end
	local function restoreSkin(skinState)
		local restore = skinState[skinState]
		if restore then
			skinState[skinState] = nil
			restore.restore()
		end
	end
	local applyDeferred = nil
	local function refreshTool(skinState)
		task.defer(applyDeferred, skinState)
	end
	applyDeferred = function(object)
		if not trackedTools[object] then
			return
		end
		local trackedTools = chooseSkin(object)
		local skinState = isKnife(object)
		local chooseSkin
		if trackedTools and not skinState then
			chooseSkin = {}
			chooseSkin[1] = skins.find(object.Name, trackedTools)
		else
			chooseSkin = { nil }
		end
		local skinName = chooseSkin[1]
		local isKnife
		if skinName then
			isKnife = { skinName.skinName }
		else
			isKnife = {}
			local restoreSkin
			if trackedTools and skinState then
				restoreSkin = skinApply.resolve(trackedTools)
			else
				restoreSkin = nil
			end
			isKnife[1] = restoreSkin
		end
		local fn = isKnife[1]
		local isIntact = skinState[object]
		if isIntact and fn and isIntact.skinName == fn and isIntact.isIntact() then
			return
		end
		restoreSkin(object)
		if not fn then
			return
		end
		local function applyDeferred()
			refreshTool(object)
		end
		local refreshTool
		if skinName then
			refreshTool = { (skinMount.apply(object, skinName, applyDeferred)) }
		else
			refreshTool = { (skinApply.apply(object, fn, applyDeferred)) }
		end
		local watchTool = refreshTool[1]
		if watchTool then
			skinState[object] = watchTool
		end
	end
	local function watchTool(skinState, isA)
		if not isA:IsA("Tool") then
			return
		end
		if trackedTools[isA] then
			return
		end
		local scope = skinState:child()
		trackedTools[isA] = scope
	end
	local function watchContainer(scope, getChildren)
		for _, skinState in getChildren:GetChildren() do
			watchTool(scope, skinState)
		end
		scope:add(getChildren.ChildAdded:Connect(function(skinState)
			watchTool(scope, skinState)
		end))
	end
	local function fn()
		for skinState in trackedTools do
			refreshTool(skinState)
		end
	end
	return {
		name = "SkinChanger",
		start = function(scope)
			local localPlayer = services.Players.LocalPlayer
			local backpack = localPlayer:FindFirstChildOfClass("Backpack")
			if backpack then
				watchContainer(scope, backpack)
			end
			if localPlayer.Character then
				watchContainer(scope, localPlayer.Character)
			end
			scope:add(localPlayer.ChildAdded:Connect(function(isA)
				if isA:IsA("Backpack") then
					watchContainer(scope, isA)
				end
			end))
			scope:add(localPlayer.CharacterAdded:Connect(function(skinState)
				watchContainer(scope, skinState)
			end))
			scope:add(settings.changed:connect(fn))
			mod_choice.start(scope, fn)
		end,
	}
end
modules.skins = function()
	local services = modules.services()
	local skinAssets = modules.skinAssets()
	local skinEntry = {}
	skinEntry["[Bat]"] = "Bats"
	skinEntry["[Wallet]"] = "Wallets"
	local normalizedName = {}
	local meshCache = {}
	local toolKey = {}
	local function normalizeKey(skinEntry)
		return (string.gsub(string.lower(skinEntry), "[%s%-_]", ""))
	end
	toolKey.toolKey = function(skinEntry)
		if string.sub(skinEntry, 1, 1) == "[" then
			return skinEntry
		end
		return string.format("[%s]", tostring(skinEntry))
	end
	local function findSkinModules()
		return services.ReplicatedStorage:FindFirstChild("SkinModules")
	end
	local function findSkinAssets()
		return services.ReplicatedStorage:FindFirstChild("SkinAssets")
	end
	local function findMesh(skinEntry)
		if not skinEntry then
			return nil
		end
		local normalizedName = meshCache[skinEntry]
		if normalizedName and normalizedName.Parent then
			return normalizedName
		end
		local findFirstChild = findSkinModules()
		if findFirstChild then
			findFirstChild = findFirstChild:FindFirstChild("Meshes")
		end
		for object in string.gmatch(skinEntry, "[^/]+") do
			if findFirstChild then
				findFirstChild = findFirstChild:FindFirstChild(object)
			end
		end
		if findFirstChild then
			meshCache[skinEntry] = findFirstChild
		end
		return findFirstChild
	end
	local function buildTextureInfo(texture)
		if type(texture) == "string" then
			return { TextureID = texture }
		end
		local skinEntry = texture.texture
		if texture.mesh then
			skinEntry = findMesh(texture.mesh)
			if not skinEntry then
				return nil
			end
		end
		local normalizedName = findMesh(texture.launcher)
		if texture.launcher and not normalizedName then
			return nil
		end
		return {
			TextureID = skinEntry,
			CFrame = texture.cframe,
			LauncherMesh = normalizedName,
			LauncherCFrame = texture.launcherCFrame,
		}
	end
	local function buildNormalizeIndex(normalizedName, findSkinModules)
		local skinEntry = normalizedName[normalizedName]
		if skinEntry then
			return skinEntry
		end
		local meshCache = {}
		for normalizeKey in findSkinModules do
			meshCache[normalizeKey(normalizeKey)] = normalizeKey
		end
		normalizedName[normalizedName] = meshCache
		return meshCache
	end
	toolKey.all = function()
		return skinAssets
	end
	toolKey.find = function(normalizedName, findSkinModules)
		local skinEntry = toolKey.toolKey(normalizedName)
		local meshCache = skinAssets[skinEntry]
		if meshCache then
			local normalizeKey
			if meshCache[findSkinModules] then
				normalizeKey = { findSkinModules }
			else
				normalizeKey = { buildNormalizeIndex(skinEntry, meshCache)[normalizeKey(findSkinModules)] }
			end
			local findSkinAssets = normalizeKey[1]
			if not findSkinAssets then
				return nil
			end
			local findMesh = buildTextureInfo(meshCache[findSkinAssets])
			if findMesh then
				return { toolKey = skinEntry, skinName = findSkinAssets, info = findMesh }
			end
		end
		return nil
	end
	toolKey.folderMesh = function(skinEntry, normalizedName)
		local object = skinEntry[skinEntry]
		local findFirstChild
		if object then
			findFirstChild = findSkinModules()
			if findFirstChild then
				findFirstChild = findFirstChild:FindFirstChild(object)
				if findFirstChild then
					return (findFirstChild:FindFirstChild(normalizedName))
				end
			end
		else
			findFirstChild = object
		end
		return findFirstChild
	end
	toolKey.isFolderSkin = function(skinEntry)
		return skinEntry[skinEntry] ~= nil
	end
	toolKey.handleParticles = function(object)
		local findFirstChild = findSkinAssets()
		if findFirstChild then
			findFirstChild = findFirstChild:FindFirstChild("GunHandleParticle")
			if findFirstChild then
				return (findFirstChild:FindFirstChild(object))
			end
		end
		return findFirstChild
	end
	toolKey.meshAnimations = function(object)
		local findFirstChild = findSkinAssets()
		if findFirstChild then
			findFirstChild = findFirstChild:FindFirstChild("SkinScriptsStorage")
			if findFirstChild then
				return (findFirstChild:FindFirstChild(object))
			end
		end
		return findFirstChild
	end
	toolKey.normalize = normalizeKey
	toolKey.knives = function()
		local findFirstChild = findSkinModules()
		if findFirstChild then
			return (findFirstChild:FindFirstChild("Knives"))
		end
		return findFirstChild
	end
	toolKey.asset = function(object)
		local findFirstChild = findSkinAssets()
		if findFirstChild then
			return (findFirstChild:FindFirstChild(object))
		end
		return findFirstChild
	end
	toolKey.shootSound = function(object, meshCache)
		local findFirstChild = findSkinAssets()
		if findFirstChild then
			local gunShootSounds = findFirstChild:FindFirstChild("GunShootSounds")
			if gunShootSounds then
				local skinEntry = gunShootSounds:FindFirstChild(object)
				if skinEntry then
					local normalizedName = skinEntry:FindFirstChild(meshCache)
					if normalizedName and normalizedName:IsA("StringValue") then
						return ({ normalizedName })[1]
					end
				end
			end
		end
		return ({ nil })[1]
	end
	return toolKey
end
