modules.skinMount = function()
	local skins = modules.skins()
	local scope = modules.scope()
	local function setProperty(resourceScope, object, propertyName, propertyValue)
		local previous = object[propertyName]
		object[propertyName] = propertyValue
		resourceScope:add(function()
			if object.Parent then
				object[propertyName] = previous
			end
		end)
	end
	local function setAttribute(resourceScope, attributeHost, attributeName, attributeValue)
		local previous = attributeHost:GetAttribute(attributeName)
		attributeHost:SetAttribute(attributeName, attributeValue)
		resourceScope:add(function()
			if not attributeHost.Parent then
				return
			end
			attributeHost:SetAttribute(attributeName, previous)
		end)
	end
	local function stash(resourceScope, container)
		local children, state, control = container:GetChildren()
		local object = state
		for _, child in children, object, control do
			object = child
			if pcall(function()
				object.Parent = nil
			end) then
				resourceScope:add(function()
					if container.Parent and object.Parent == nil then
						object.Parent = container
					end
				end)
			end
		end
	end
	local function findDefaultMesh(container, fallbackContainer)
		local default = container:FindFirstChild("Default")
		if default and default:IsA("MeshPart") then
			return default
		end
		local meshPart = fallbackContainer:FindFirstChildOfClass("MeshPart")
		if meshPart then
			return meshPart
		end
		return container:FindFirstChildOfClass("MeshPart")
	end
	local function findShootSound(firstPart, secondPart)
		local parts = { firstPart, secondPart }
		local iterator = coroutine.wrap(lph_generic_for)
		iterator(parts, nil, nil)
		local nextPart = iterator
		while true do
			local ok, index, part = nextPart()
			if not ok then
				break
			end
			for _, childName in { "Shoot", "ShootSound" } do
				local sound = part:FindFirstChild(childName)
				if sound and sound:IsA("Sound") then
					return sound
				end
			end
			nextPart = nextPart
		end
		return nil
	end
	local function resolvePart(instance)
		if instance:IsA("BasePart") then
			return instance
		end
		if not instance:IsA("Model") then
			return nil
		end
		local primaryPart = instance.PrimaryPart
		if primaryPart then
			return primaryPart
		end
		return (instance:FindFirstChildWhichIsA("BasePart", true))
	end
	local function applyTransform(root, primaryPart, transform)
		local parts = root:GetDescendants()
		table.insert(parts, root)
		for _, part in parts do
			if not part:IsA("BasePart") then
				continue
			end
			part.Anchored = false
			part.CanCollide = false
			part.CanQuery = false
			part.CanTouch = false
			part.Massless = true
			part.CFrame = transform * part.CFrame
		end
		for _, candidate in parts do
			if not (candidate:IsA("BasePart") and candidate ~= primaryPart and #candidate:GetJoints() == 0) then
				continue
			end
			local weldConstraint = Instance.new("WeldConstraint")
			weldConstraint.Part0 = primaryPart
			weldConstraint.Part1 = candidate
			weldConstraint.Parent = primaryPart
		end
	end
	local function mount(resourceScope, targetPart, templateMesh, offset)
		local mesh = templateMesh:Clone()
		local meshPart = resolvePart(mesh)
		if not meshPart then
			mesh:Destroy()
			return nil
		end
		if not offset then
			offset = CFrame.identity
		end
		applyTransform(mesh, meshPart, targetPart.CFrame * offset * meshPart.CFrame:Inverse())
		local weld = Instance.new("Weld")
		weld.Part0 = targetPart
		weld.Part1 = meshPart
		weld.C0 = offset
		weld.Parent = meshPart
		mesh.Name = "Mesh"
		mesh.Parent = targetPart
		resourceScope:add(mesh)
		return mesh
	end
	local function attachParticles(resourceScope, parent, holder)
		local particleHost = skins.handleParticles(holder)
		if not particleHost then
			return
		end
		for _, template in particleHost:GetChildren() do
			local emitter = template:Clone()
			emitter.Name = "ParticleEmitter"
			if emitter:IsA("ParticleEmitter") then
				emitter.Enabled = true
			end
			emitter.Parent = parent
			resourceScope:add(emitter)
		end
	end
	local function applyTexture(resourceScope, meshPart, toolContext)
		stash(resourceScope, meshPart)
		local textureIds
		if skins.isFolderSkin(toolContext.toolKey) then
			textureIds = {}
			textureIds[1] = skins.folderMesh(toolContext.toolKey, toolContext.skinName)
		else
			textureIds = { toolContext.info.TextureID }
		end
		local textureId = textureIds[1]
		if type(textureId) ~= "string" then
			return textureId
		end
		setProperty(resourceScope, meshPart, "TextureID", textureId)
		setProperty(resourceScope, meshPart, "Transparency", 0)
		return nil
	end
	local function mountLauncher(resourceScope, container, toolContext)
		local launcherMesh = toolContext.info.LauncherMesh
		local launcher = container:FindFirstChild("Launcher")
		if typeof(launcherMesh) ~= "Instance" then
			return nil
		end
		if not launcher then
			return nil
		end
		if not launcher:IsA("BasePart") then
			return nil
		end
		stash(resourceScope, launcher)
		local launcherMount = mount(resourceScope, launcher, launcherMesh, toolContext.info.LauncherCFrame)
		if launcherMount then
			setProperty(resourceScope, launcher, "Transparency", 1)
		end
		return launcherMount
	end
	local function applyShootSound(resourceScope, partA, partB, toolContext)
		local shootSound = findShootSound(partA, partB)
		local soundAsset = skins.shootSound(toolContext.toolKey, toolContext.skinName)
		if not shootSound then
			return
		end
		if not soundAsset then
			return
		end
		setProperty(resourceScope, shootSound, "SoundId", soundAsset.Value)
		setAttribute(resourceScope, shootSound, "SequenceSFX", soundAsset:GetAttribute("SequenceSFX"))
	end
	local function pinSkinName(resourceScope, attributeHost, skinName)
		setAttribute(resourceScope, attributeHost, "SkinName", skinName)
		resourceScope:add(attributeHost:GetAttributeChangedSignal("SkinName"):Connect(function()
			if attributeHost:GetAttribute("SkinName") ~= skinName then
				attributeHost:SetAttribute("SkinName", skinName)
			end
		end))
	end
	local function restoreParent(resourceScope, parent, object)
		if object.Parent == parent and pcall(function()
			object.Parent = nil
		end) then
			resourceScope:add(function()
				if parent.Parent and object.Parent == nil then
					object.Parent = parent
				end
			end)
		end
	end
	local function watchTexture(resourceScope, meshPart, onChange, mountedMesh)
		resourceScope:add(meshPart:GetPropertyChangedSignal("TextureID"):Connect(onChange))
		resourceScope:add(meshPart:GetPropertyChangedSignal("Transparency"):Connect(onChange))
		resourceScope:add(meshPart.ChildAdded:Connect(function(object)
			if object.Name == "Mesh" and object ~= mountedMesh then
				task.defer(restoreParent, resourceScope, meshPart, object)
			end
		end))
	end
	return {
		setProperty = setProperty,
		setAttribute = setAttribute,
		stash = stash,
		mount = mount,
		pinSkinName = pinSkinName,
		apply = function(container, toolContext, unused)
			local handle = container:FindFirstChild("Handle")
			if not handle then
				return nil
			end
			if not handle:IsA("BasePart") then
				return nil
			end
			local meshPart = findDefaultMesh(container, handle)
			if not meshPart then
				return nil
			end
			local resources = scope.new()
			local textureResult = applyTexture(resources, meshPart, toolContext)
			local launcherMount = mountLauncher(resources, container, toolContext)
			if not skins.isFolderSkin(toolContext.toolKey) then
				attachParticles(resources, meshPart, toolContext.skinName)
			end
			applyShootSound(resources, container, handle, toolContext)
			pinSkinName(resources, handle, toolContext.skinName)
			local originalTextureId = meshPart.TextureID
			local transparency = meshPart.Transparency
			local function isIntact()
				if textureResult and textureResult.Parent ~= meshPart then
					return false
				end
				return not (launcherMount and launcherMount.Parent == nil)
			end
			watchTexture(resources, meshPart, function()
				if isIntact() then
					if meshPart.TextureID ~= originalTextureId then
						meshPart.TextureID = originalTextureId
					end
					if meshPart.Transparency ~= transparency then
						meshPart.Transparency = transparency
					end
				else
					isIntact()
				end
			end, textureResult)
			return {
				skinName = toolContext.skinName,
				isIntact = function()
					return isIntact() and meshPart.TextureID == originalTextureId and meshPart.Transparency == transparency
				end,
				restore = function()
					resources:destroy()
				end,
			}
		end,
	}
end
modules.skinApply = function()
	local skins = modules.skins()
	local skinMount = modules.skinMount()
	local scope = modules.scope()
	local smallPart = Vector3.new(0.001, 0.001, 0.001)
	local function makeSkinProfile(offsetVector, seed, angles, equipAnimation, equipSound)
		return {
			offset = CFrame.new(offsetVector) * CFrame.Angles(math.rad(angles.X), math.rad(angles.Y), math.rad(angles.Z)),
			equipAnimation = equipAnimation,
			equipSound = equipSound,
		}, (bit32.bxor(seed, 136255778))
	end
	local tacticalAngles = Vector3.new(89.05, 96.63, 180)
	local gpKnife = makeSkinProfile(Vector3.new(0, -0.32, -1.07), 207984528, Vector3.new(90, -97.4, 90), "rbxassetid://14014278925", "rbxassetid://4604390759")
	local goldenagetanto = {}
	goldenagetanto.goldenagetanto = makeSkinProfile(Vector3.new(0, -0.2, -1.2), 207984528, Vector3.new(90, 263.7, 180), "rbxassetid://13473404819", "rbxassetid://5917819099")
	goldenagetanto.gpoknife = gpKnife
	goldenagetanto.gpoknifeprestige = gpKnife
	goldenagetanto.heaven = makeSkinProfile(Vector3.new(-0.02, -0.82, 0.2), 207984528, Vector3.new(64.42, 3.79, 0), "rbxassetid://14500266726", "rbxassetid://14489860007")
	goldenagetanto.lovekukri = makeSkinProfile(Vector3.new(-0.14, 0.14, -1.62), 207984528, Vector3.new(-90, 180, -4.97))
	goldenagetanto.purpledagger = makeSkinProfile(Vector3.new(-0.13, -0.24, -1.8), 207984528, tacticalAngles, "rbxassetid://17824999722", "rbxassetid://17822743153")
	goldenagetanto.bluedagger = makeSkinProfile(Vector3.new(-0.13, -0.24, -1.8), 207984528, tacticalAngles, "rbxassetid://17824995184", "rbxassetid://17822737046")
	goldenagetanto.greendagger = makeSkinProfile(Vector3.new(-0.13, -0.24, -1.07), 207984528, tacticalAngles, "rbxassetid://17825004320", "rbxassetid://17822741762")
	goldenagetanto.reddagger = makeSkinProfile(Vector3.new(-0.13, -0.24, -1.07), 207984528, tacticalAngles, "rbxassetid://17825008844", "rbxassetid://17822952417")
	local abilityCache = {}
	local knownAnimations = nil
	local function unavailable()
		error("not lifted: this function's code did not come out of the dump")
	end
	local apply = {
		resolve = function(knife)
			local found = skins.find("[Knife]", knife)
			local candidates
			if found then
				candidates = { found.skinName }
			else
				candidates = { nil }
			end
			local resolvedName = candidates[1]
			local fallback = unavailable()
			if not fallback then
				return nil
			end
			if resolvedName then
				return resolvedName
			end
			return fallback.Name
		end,
	}
	local function findAnimation(container, matcher)
		if container then
			for _, animation in container:GetDescendants() do
				if animation:IsA("Animation") and animation.AnimationId ~= "" and matcher(skins.normalize(animation.Name)) then
					return animation.AnimationId
				end
			end
		end
		return nil
	end
	local function findChildByName(container, name)
		if container then
			for _, object in container:GetChildren() do
				if skins.normalize(object.Name) == name then
					return object
				end
			end
		end
		return nil
	end
	local function getSlashProfile(skinName)
		local normalized = skins.normalize(skinName)
		local cached = abilityCache[normalized]
		if cached then
			return cached
		end
		local slash = {}
		local animation = findChildByName(skins.asset("KnifeSkinAnimation"), normalized)
		if animation and animation:IsA("Animation") then
			if animation.AnimationId ~= "" then
				slash.slash = animation.AnimationId
			end
		end
		local scripts = findChildByName(skins.asset("SkinScripts"), normalized)
		if scripts then
			for _, sound in scripts:GetDescendants() do
				if not (sound:IsA("Sound") and sound.SoundId ~= "") then
					continue
				end
				local soundName = skins.normalize(sound.Name)
				if not slash.equipSound and string.find(soundName, "equip", 1, true) then
					slash.equipSound = sound.SoundId
					continue
				end
				if not (slash.attackSound or not string.find(soundName, "attack", 1, true)) then
					slash.attackSound = sound.SoundId
				end
			end
		end
		local storage = findChildByName(skins.asset("SkinScriptsStorage"), normalized)
		slash.equip = findAnimation(storage, function(name)
			return string.find(name, "equip", 1, true) ~= nil
