		while true do
			local ok, skinKey, allowed = nextSkin()
			if not ok then
				break
			end
			local entry
			if type(savedData[skinKey]) == "table" then
				entry = { savedData[skinKey] }
			else
				entry = { {} }
			end
			local counts = entry[1]
			for countKey in allowed do
				counts[countKey] = math.max(tonumber(counts[countKey]) or 0, 999)
