	}
end
modules.unnamed_bA = function()
	local daHoodState = modules.daHoodState()
	local attributes = modules.attributes()
	local cooldownPadding = modules.unnamed_ai()
	local blockingEffects = {}
	blockingEffects[1] = "K.O"
	blockingEffects[2] = "Grabbed"
	blockingEffects[3] = "Reload"
	blockingEffects[4] = "Dead"
	return {
		equipped = function(character)
			local tool = character:FindFirstChildOfClass("Tool")
			if tool then
				local profile = cooldownPadding.profile(tool.Name)
				if profile then
					return tool, profile
				end
			end
			return nil, nil
		end,
		available = function(character, tool)
			local handle = tool:FindFirstChild("Handle")
			if tool.Parent ~= character then
				return false
			end
			if not tool.Enabled then
				return false
			end
			if not handle then
				return false
			end
			if not handle:IsA("BasePart") then
				return false
			end
			if not character then
				local ammo = attributes.child(tool, "Ammo")
				return ammo ~= nil and ammo > 0 and ammo < math.huge and daHoodState.basic(character)
			end
			local humanoid = character:FindFirstChildOfClass("Humanoid")
			if not humanoid then
				return false
			end
			if humanoid.Health <= 0 then
				return false
			end
			if humanoid:GetState() == Enum.HumanoidStateType.Dead then
				return false
			end
			local bodyEffects = character:FindFirstChild("BodyEffects")
			for _, effectName in blockingEffects do
				if daHoodState.isEffectOn(bodyEffects, effectName) then
					return false
				end
			end
			return not tool:GetAttribute("Cooldown")
		end,
	}
end
modules.dasHood_bU = function()
	local aimAssist = modules.aimAssist()
	local avatar = modules.avatar()
	local mod_current = modules.unnamed_aq()
