modules.dasHood = function()
	local mod_check = modules.check()
	modules.unnamed_aq()
	local mod_bind = modules.unnamed_bR()
	local services = modules.services()
	local mod_modifiers = modules.unnamed_bP()
	local function getMainEvent()
		local mainEvent = services.ReplicatedStorage:FindFirstChild("MainEvent")
		return if mainEvent and mainEvent:IsA("RemoteEvent") then mainEvent else nil
	end
	return {
		name = "Das Hood",
		specificSection = "Das Hood",
		isCompensated = false,
		beamColor = Color3.new(1, 0.545098, 0.14902),
		checksClientAmmo = true,
		localClock = os.clock,
		canShoot = function(character)
			return mod_check.check(character)
		end,
		spread = function(object)
			return mod_modifiers.offset("Tactical", object.CFrame, mod_modifiers.modifiers(), 1)
		end,
		send = function(shots)
			local fireServer = getMainEvent()
			if not fireServer then
				return
			end
			for _, origin in shots.shots do
				fireServer:FireServer("ShootGun", shots.handle, origin.origin, origin.instance, origin.origin, origin.position, services.Workspace:GetServerTimeNow())
			end
		end,
		gripChanged = nil,
		emulator = mod_bind,
	}
end
modules.check = function()
	local mod_play = modules.play()
	local services = modules.services()
	local noAmmoModule = modules.unnamed_bF()
	local blockingObjects = {}
	blockingObjects[1] = "FORCEFIELD"
	blockingObjects[2] = "GRABBING_CONSTRAINT"
	blockingObjects[3] = "Christmas_Sock"
	local blockingValues = {}
	blockingValues[1] = "Cuff"
	blockingValues[2] = "Attacking"
	blockingValues[3] = "K.O"
	local deadValues = {}
	deadValues[1] = "Reload"
	deadValues[2] = "Dead"
	local function readValue(container, name)
		local found = container:FindFirstChild(name)
		if found and found:IsA("ValueBase") then
			return true, found.Value
		end
		return false, nil
	end
	local function hasAnyTrue(container, names)
		for _, name in names do
			local found, flag = readValue(container, name)
			if not found then
				return true
			end
			if flag == true then
				return true
			end
		end
		return false
	end
	local function isAlive(character)
		local humanoid = character:FindFirstChild("Humanoid")
		return humanoid ~= nil and humanoid:IsA("Humanoid") and humanoid.Health > 0 and humanoid:GetState() ~= Enum.HumanoidStateType.Dead
	end
	local function hasAnyChild(container, names)
		for _, name in names do
			if container:FindFirstChild(name) then
				return true
			end
		end
		return false
	end
	local function isGrabbed(container)
		local found, grabbed = readValue(container, "Grabbed")
		local flag = not found
		if found then
			flag = grabbed ~= nil
			if grabbed ~= nil then
				return grabbed ~= false
			end
		end
		return flag
	end
	return {
		check = function(character)
			if not character then
				return false
			end
			while true do
				local alive = isAlive(character)
				if alive then
					break
				end
				if not alive then
					return false
				end
			end
			local bodyEffects = character:FindFirstChild("BodyEffects")
			if not bodyEffects then
				return false
			end
			local tool = character:FindFirstChildWhichIsA("Tool")
			if not tool then
				return false
			end
			local handle = tool:FindFirstChild("Handle")
			local ammo = tool:FindFirstChild("Ammo")
			if not handle then
				return false
			end
			if not ammo then
				return false
			end
			if bodyEffects:FindFirstChild("Block") then
				mod_play.play(handle)
				noAmmoModule.noAmmo(handle)
				return false
			end
			if ammo:IsA("ValueBase") then
				local ammoValue = ammo.Value
				if ammoValue == 0 then
				end
			end
			if not character:FindFirstChild("FULLY_LOADED_CHAR") then
				return false
			end
			if hasAnyChild(character, blockingObjects) then
				return false
			end
			if hasAnyTrue(bodyEffects, blockingValues) then
				return false
			end
			if isGrabbed(bodyEffects) then
				return false
			end
			if hasAnyTrue(bodyEffects, deadValues) then
				return false
			end
			if tool:GetAttribute("Cooldown") then
				return false
			end
			if services.Workspace:FindFirstChild("Ticking") then
				return false
			end
			if character:GetAttribute("LastGunShot") ~= tool.Name and character:GetAttribute("ShotgunDebounce") then
				return false
			end
			character:SetAttribute("LastGunShot", tool.Name)
			return true
		end,
	}
end
modules.play = function()
	local globals = modules.globals()
	local services = modules.services()
	local shootNames = {}
	shootNames[1] = "Shoot"
	shootNames[2] = "AimShoot"
	shootNames[3] = "ShootLeft"
	shootNames[4] = "ShootRight"
	shootNames[5] = "MinigunShoot"
	shootNames[6] = "TommyShoot"
	local autoAimWeapons = {}
	autoAimWeapons["[Shotgun]"] = true
	autoAimWeapons["[Drum-Shotgun]"] = true
	autoAimWeapons["[Rifle]"] = true
	autoAimWeapons["[TacticalShotgun]"] = true
	autoAimWeapons["[AR]"] = true
	autoAimWeapons["[AUG]"] = true
	autoAimWeapons["[AK47]"] = true
	autoAimWeapons["[LMG]"] = true
	autoAimWeapons["[SilencerAR]"] = true
	local localPlayer = services.Players.LocalPlayer
	local animationCache = setmetatable({}, { __mode = "k" })
	local function getAnimator(character)
		local humanoid = character:FindFirstChild("Humanoid")
		if humanoid then
			local animator = humanoid:FindFirstChild("Animator")
			if animator and animator:IsA("Animator") then
				return animator
			end
		end
		return nil
	end
	local function getAnimations(animator)
		local cached = animationCache[animator]
		if cached then
			return cached
		end
		local animations = services.ReplicatedStorage:FindFirstChild("Animations")
		if animations then
			local gunCombat = animations:FindFirstChild("GunCombat")
			if gunCombat then
				local loaded = {}
				for _, name in shootNames do
					local animation = gunCombat:FindFirstChild(name)
					if not animation then
						return nil
					end
					if not animation:IsA("Animation") then
						return nil
					end
					loaded[name] = animator:LoadAnimation(animation)
				end
				animationCache[animator] = loaded
				return loaded
			end
		end
		return nil
	end
	local function isSmallGunAiming(character)
		local clientAnimations = services.ReplicatedStorage:FindFirstChild("ClientAnimations")
		if clientAnimations then
			local smallGunAim = clientAnimations:FindFirstChild("SmallGunAim")
			if smallGunAim then
				if smallGunAim:IsA("Animation") then
					if smallGunAim.AnimationId == "" then
						return false
					end
					for _, track in character:GetPlayingAnimationTracks() do
						local animationData = track.Animation
						if animationData.IsPlaying and animationData and animationData.AnimationId == smallGunAim.AnimationId then
							return true
						end
					end
				end
				return false
			end
		end
		return false
	end
	local function chooseShootNames(tool, character)
		if globals.flag("Aimed") then
			if tool:GetAttribute("Minigun") then
				return { "MinigunShoot" }
			end
			if tool:GetAttribute("Tommy") then
				return { "TommyShoot" }
			end
			return { "AimShoot" }
		end
		if autoAimWeapons[tool.Name] or isSmallGunAiming(character) then
			if tool:GetAttribute("Minigun") then
				return { "MinigunShoot" }
			end
			if tool:GetAttribute("Tommy") then
				return { "TommyShoot" }
			end
			return { "AimShoot" }
		end
		if tool:GetAttribute("DualWield") then
			return { "ShootLeft", "ShootRight" }
		end
		if tool:GetAttribute("Tommy") then
			return { "TommyShoot" }
		end
		return { "Shoot" }
	end
	return {
		play = function(tool)
			local character = localPlayer.Character
			if character then
				local animator = getAnimator(character)
				if animator then
					local animations = getAnimations(animator)
					if animations then
						for _, name in chooseShootNames(tool, animator) do
							animations[name]:Play()
						end
					end
				end
			end
		end,
	}
end
modules.unnamed_bF = function()
	local globals = modules.globals()
	local sequenceWeaponNames = {}
	sequenceWeaponNames["[Double-Barrel SG]"] = true
	sequenceWeaponNames["[Shotgun]"] = true
	sequenceWeaponNames["[TacticalShotgun]"] = true
	sequenceWeaponNames["[Drum-Shotgun]"] = true
	local randomSoundIds = {}
	randomSoundIds[1] = 125391056005695
	randomSoundIds[2] = 132466522418892
	randomSoundIds[3] = 129999172684348
	local function advanceSequence(shootSound)
		local sequence = shootSound:GetAttribute("SequenceSFX")
		if not sequence then
			return
		end
		local current = shootSound:GetAttribute("CurrentSequence")
		local nextIndex
		if type(current) ~= "number" then
			nextIndex = 1
		else
			nextIndex = current + 1
		end
		shootSound:SetAttribute("CurrentSequence", nextIndex)
		local ids = {}
		for id in string.gmatch(tostring(sequence), "%d+") do
			table.insert(ids, id)
		end
		if 0 < #ids then
			shootSound.SoundId = "rbxassetid://" .. ids[nextIndex % #ids + 1]
		end
	end
	local function playShootSound(tool)
		local shootSound = tool:FindFirstChild("ShootSound")
		if not shootSound then
			return
		end
		if not shootSound:IsA("Sound") then
			return
		end
		advanceSequence(shootSound)
		local clone = shootSound:Clone()
		clone.Name = "MG"
		clone.Parent = tool
		if globals.globals().MuteGunsSounds ~= true then
			clone:Play()
			task.delay(math.max(clone.TimeLength, 3), function()
				if clone.Parent then
					clone:Destroy()
				end
			end)
			return
		end
		clone.Volume = 0
		clone:Play()
		task.delay(math.max(clone.TimeLength, 3), function()
			if clone.Parent then
				clone:Destroy()
			end
		end)
	end
	local function shouldPlaySound(object)
		if not globals.flag("MuteShootSounds") then
			return true
		end
		if object then
			object = object.Parent
		end
		return object ~= nil and object:FindFirstChildOfClass("Humanoid") ~= nil
	end
	local function spawnShootSound(tool, character)
		task.spawn(function()
			if shouldPlaySound(character) then
				playShootSound(tool)
			end
		end)
	end
	local function playDummySound(parent)
		local sound = Instance.new("Sound")
		sound.Name = "ShootSound"
		sound.SoundId = "rbxassetid://" .. randomSoundIds[math.random(1, #randomSoundIds)]
		sound.Parent = parent
		sound.Ended:Once(function()
			sound:Destroy()
		end)
		sound:Play()
	end
	return {
		shoot = function(tool, toolName, skinName, character)
			if sequenceWeaponNames[toolName] then
				if not tool:GetAttribute("PlayingSound") then
					tool:SetAttribute("PlayingSound", true)
					task.delay(0.075, function()
						tool:SetAttribute("PlayingSound", nil)
					end)
					spawnShootSound(tool, character)
				end
			elseif skinName == "Toilet" then
				playDummySound(tool)
			else
				spawnShootSound(tool, character)
			end
		end,
		noAmmo = function(tool)
			local noAmmo = tool:FindFirstChild("NoAmmo")
			if noAmmo and noAmmo:IsA("Sound") then
				noAmmo:Play()
			end
		end,
	}
end
modules.unnamed_bR = function()
	local mod_bind = modules.bind()
	modules.unnamed_aq()
	local weaponProfile = modules.unnamed_bO()
	return {
		supports = function(weaponName)
			return weaponProfile.profile(weaponName) ~= nil
		end,
		bind = function(resourceScope, tool, handle)
			local profile = weaponProfile.profile(tool.Name)
			if not profile then
				return false
			end
			mod_bind.bind(resourceScope, tool, handle, profile)
			return true
		end,
	}
end
modules.bind = function()
	local firingState = modules.firingState()
	local mod_direction = modules.direction()
	local mod_check = modules.check()
	local mod_current = modules.unnamed_aq()
	local globals = modules.globals()
	local mod_fitRange = modules.unnamed_bd()
	local hitboxExpander = modules.hitboxExpander()
	local mod_plan = modules.unnamed_bf()
	modules.scope()
	local mod_entries = modules.unnamed_be()
	local wallSampler = modules.wallSampler()
	local services = modules.services()
	local mod_fire = modules.fire()
	local mod_modifiers = modules.unnamed_bP()
	local attributes = modules.attributes()
	local weaponNumbers = modules.weaponNumbers()
	local weaponProfile = modules.unnamed_bO()
	local beamColor = Color3.new(1, 0.545098, 0.14902)
	local localPlayer = services.Players.LocalPlayer
	local function getMainEvent()
		local mainEvent = services.ReplicatedStorage:FindFirstChild("MainEvent")
		local candidates
		if mainEvent and mainEvent:IsA("RemoteEvent") then
			candidates = { mainEvent }
		else
			candidates = { nil }
		end
		return candidates[1]
	end
	local function fireRemote(tool, payload)
		local remote = tool.tool:FindFirstChild("RemoteEvent")
		if not remote then
			return
		end
		if remote:IsA("RemoteEvent") then
			if payload then
				remote:FireServer(payload)
			else
				remote:FireServer()
			end
		end
	end
	local function syncGrip(tool)
		tool.tool.Grip = tool.grip
	end
	local function getAmmo(tool)
		local ammo = attributes.child(tool.tool, "Ammo")
		if ammo then
			return ammo
		end
		return 0
	end
	local function getRange(tool)
		local range = attributes.child(tool.tool, "Range")
		if range then
			return range
		end
		return 0
	end
	local function canFire(cooldown)
		if services.Lighting:GetAttribute("NoCooldown") then
			return true
		end
		local required = cooldown.cooldown * weaponNumbers.delay(cooldown.tool.Name)
		return os.clock() - cooldown.lastActivation >= required
	end
	local function planShot(tool, shooter, origin, direction, range)
		local makePlan = mod_plan.plan
		local plan = {
			isSeeded = false,
			seededOffsets = nil,
			shooter = shooter,
			tool = tool.tool,
			handle = tool.handle,
			origin = origin,
			packetOrigin = wallSampler.native(origin),
		}
		plan.direction = direction
		plan.range = range
		return makePlan(plan)
	end
	local function safeCall(fn, arg1, arg2, arg3)
		if not fn then
			return nil
		end
		local ok, returned = pcall(fn, arg1, arg2, arg3)
		return if ok then returned else nil
	end
	local function buildShot(tool, range)
		local shot = { tool = tool.tool, handle = tool.handle, range = range, toolRange = getRange(tool) }
		return tool.profile, nil, "kind"
	end
	local packetSeed = 22945686
	local function fireShot(tool, shooter, origin, aimPosition, range, visual)
		local fire = mod_fire.fire
		local shot = { shooter = shooter, tool = tool.tool, handle = tool.handle, origin = origin }
		local finalAim
		if visual then
			finalAim = visual.aimPosition
		else
			finalAim = aimPosition
		end
		shot.aimPosition = finalAim
		shot.range = range
		shot.beamColor = beamColor
		local forced
		if visual then
			forced = visual.visual
		else
			forced = visual
		end
		shot.forced = forced
		local position = fire(shot)
		if not position then
			return false
		end
		if visual then
			local packet = visual.packet
			if packet then
				local n = packetSeed + 218596107 ~= 19452570
				return null_stub(nil, unpack(n, 1, n.n))
			end
			local entry = visual.entry
			if not entry then
				return true
			end
			mod_entries.record(entry, tool.tool, packet ~= nil, function()
				return finalAim(tool)
			end)
		else
			buildShot(tool, range, {
				origin = origin,
				position = position.position,
				instance = hitboxExpander.remap(position.instance),
				normal = nil,
				pellet = nil,
			})
		end
		return true
	end
	packetSeed = 266018909
	local function fireSemi(tool, shooter)
		syncGrip(tool)
		local origin = weaponProfile.origin(tool.tool, tool.handle, tool.profile)
		local direction = mod_direction.direction(origin)
		local range = mod_fitRange.range(getRange(tool))
		local visual = safeCall(planShot(tool, shooter, origin, direction, range), Vector3.zero, 1, 1)
		return fireShot(tool, shooter, origin, origin + direction * weaponProfile.SEMI_AIM_DISTANCE, range, visual)
	end
	local function fireAutomatic(tool, shooter)
		local origin = weaponProfile.origin(tool.tool, tool.handle, tool.profile)
		local range = mod_fitRange.range(getRange(tool))
		local spread = weaponNumbers.spread(tool.tool.Name)
		local pattern = tool.profile.pattern
		local planFn = planShot(tool, shooter, origin, mod_direction.direction(origin), range)
		for pelletIndex = 1, weaponProfile.PELLETS do
			local offsets
			if pattern then
				offsets = {}
				offsets[1] = mod_modifiers.offset(pattern, tool.handle.CFrame, tool.modifiers, spread)
			else
				offsets = { Vector3.zero }
			end
			local offset = offsets[1]
			syncGrip(tool)
			if not fireShot(tool, shooter, origin, origin + (mod_direction.direction(origin) + offset).Unit * range, range, offsets(planFn, offset, pelletIndex, weaponProfile.PELLETS)) then
				return false
			end
		end
		return true
	end
	local function onActivated(tool)
		local character = localPlayer.Character
		if not canFire(tool) then
			return
		end
		if getAmmo(tool) < 1 then
			return
		end
		if globals.flag("GUN_COMBAT_TOGGLE") then
			return
		end
		if not character then
			return
		end
		if mod_check.check(character) then
			tool.lastActivation = os.clock()
			fireRemote(tool, "Shoot")
			local fired
			if tool.profile.kind ~= "Semi" then
				fired = fireAutomatic(tool, character)
			else
				fired = fireSemi(tool, character)
			end
			if not fired then
				return
			end
			fireRemote(tool)
		end
	end
	local function watchSpreadModifications(resourceScope, modifiers)
		local onClientEvent = getMainEvent()
		if not onClientEvent then
			return
		end
		resourceScope:add(onClientEvent.OnClientEvent:Connect(function(channel, axis, amount)
			if channel ~= "SpreadModifications" then
				return
			end
			if not services.Players:GetAttribute("VIP_OWNER") then
				return
			end
			if type(amount) ~= "number" then
				return
			end
			local axes = modifiers.modifiers
			if axis == "X" then
				axes.X = amount
			elseif axis == "Y" then
				axes.Y = amount
			elseif axis == "Z" then
				axes.Z = amount
			end
		end))
	end
	return {
		bind = function(resourceScope, tool, handle, profile)
			local toolState = {}
			toolState.tool = tool
			toolState.handle = handle
			toolState.profile = profile
			toolState.cooldown = attributes.child(tool, "ShootingCooldown") or 0
			toolState.grip = tool.Grip
			toolState.modifiers = mod_modifiers.modifiers()
			toolState.lastActivation = 0
			resourceScope:add(tool.Equipped:Connect(function()
				task.defer(syncGrip, toolState)
			end))
			resourceScope:add(tool:GetPropertyChangedSignal("Grip"):Connect(function()
				syncGrip(toolState)
			end))
			resourceScope:add(tool.Activated:Connect(function()
				onActivated(toolState)
			end))
			resourceScope:add(tool:GetPropertyChangedSignal("Grip"):Connect(function()
				local fireServer = getMainEvent()
				if fireServer then
					fireServer:FireServer("CHECKER_4")
