modules.direction = function()
	local globals = modules.globals()
	local services = modules.services()
	local mouse = services.Players.LocalPlayer:GetMouse()
	return {
		direction = function(origin)
			local currentCamera = services.Workspace.CurrentCamera
			if globals.flag("MobileShiftLock") and currentCamera then
				local cframe = currentCamera.CFrame
				return (cframe.Position + cframe.LookVector * 60 - origin).Unit
			end
			local aimPoint
			if mouse.Target then
				aimPoint = mouse.Hit.Position
			elseif currentCamera then
				local ray = currentCamera:ScreenPointToRay(mouse.X, mouse.Y)
				aimPoint = ray.Origin + ray.Direction * 1000
			else
				aimPoint = mouse.Hit.Position
			end
			return (aimPoint - origin).Unit
		end,
	}
end
