	end
	local function orientHole(hole, hit, skinName)
		local rule = defaultModule.holeRule(skinName)
		if rule ~= nil then
			local ruleType = type(rule)
			if ruleType ~= "string" then
				if typeof(rule) == "table" then
					local cframe = hole.CFrame
					if ruleType then
						hole.CFrame = cframe * rule.offset * toAngles(rule.angles)
						return
					end
				end
				hole.CFrame = hole.CFrame * toAngles(rule)
			elseif rule == "Position" then
				hole.Position = hit.Position
			else
				hole.CFrame = hit.CFrame
			end
		elseif hole:IsA("Part") then
			hole.CFrame = hit.CFrame
		end
