			return
		end
		if object.Parent:FindFirstChildOfClass("Humanoid") then
			return
		end
		local part = Instance.new("Part")
		task.delay(5, function()
			part:Destroy()
		end)
		part.Transparency = 1
		part.Name = "BULLETHOLE"
		part.Size = bulletHoleSize
		part.CanCollide = false
		part.CanTouch = false
		part.CanQuery = false
		part.Anchored = true
		local clone = impactTemplate:Clone()
		impactState.clone = clone
		clone.Parent = part
