modules.animate = function()
	local globals = modules.globals()
	local services = modules.services()
	local function sampleKeypoints(sequence, elapsed)
		local keypoints = sequence.Keypoints
		for index = 1, #keypoints - 1 do
			local fromPoint = keypoints[index]
			local toPoint = keypoints[index + 1]
			if fromPoint.Time <= elapsed and elapsed < toPoint.Time then
				return fromPoint.Value:Lerp(toPoint.Value, (elapsed - fromPoint.Time) / (toPoint.Time - fromPoint.Time))
			end
		end
		return keypoints[#keypoints].Value
	end
	local function applyTrailColors(instance)
		if not instance:GetAttribute("SpecialEffects") then
			return
		end
		for _, child in instance:GetDescendants() do
			local sequence = child:GetAttribute("ColorRandom")
			if not (child:IsA("Trail") and typeof(sequence) == "ColorSequence") then
				continue
			end
			child.Color = ColorSequence.new(sampleKeypoints(sequence, math.random()))
		end
	end
	local function configureImpact(parent, hit)
		local impact = parent:FindFirstChild("Impact")
		if hit.instance then
			local partParent = hit.instance.Parent
		end
		if impact and hit.normal then
			return "GetChildren", "Value"
		end
		local children, startIndex, limit = parent:GetChildren()
		coroutine.wrap(lph_generic_for)(children, startIndex, limit)
		while true do
			if startIndex:IsA("BasePart") then
				startIndex.Transparency = 1
			end
		end
	end
	return {
		animate = function(rayPart, origin, hit, parent)
			local magnitude = (hit.position - origin).Magnitude
			local duration = magnitude / 725
			rayPart.Anchored = true
			rayPart.CanCollide = false
			rayPart.CanQuery = false
			rayPart.CFrame = CFrame.lookAt(origin, hit.position)
			local endCFrame = rayPart.CFrame * CFrame.new(0, 0, -magnitude)
			rayPart.Parent = parent
			services.Debris:AddItem(rayPart, duration + 5)
			applyTrailColors(rayPart)
			local tween = services.TweenService:Create(rayPart, TweenInfo.new(0.05, Enum.EasingStyle.Linear), { CFrame = rayPart.CFrame * CFrame.new(0, 0, -0.1) })
			tween:Play()
			task.wait(0.05)
			if not rayPart.Parent then
				return
			end
			if tween.PlaybackState ~= Enum.PlaybackState.Completed then
				tween:Pause()
			end
			if globals.flag("Reduce_Lag") and not rayPart:GetAttribute("NoSlow") then
				rayPart.CFrame = endCFrame
			elseif rayPart:GetAttribute("LOWGFX") then
				rayPart.CFrame = endCFrame
			else
				local returnTween = services.TweenService:Create(rayPart, TweenInfo.new(duration, Enum.EasingStyle.Linear), { CFrame = endCFrame })
				returnTween:Play()
				task.wait(duration)
				if returnTween.PlaybackState ~= Enum.PlaybackState.Completed then
					task.wait(0.05)
				end
			end
			if not rayPart.Parent then
				return
			end
			configureImpact(rayPart, hit)
			for _, child in rayPart:GetDescendants() do
				if child:IsA("ParticleEmitter") then
					child.Enabled = false
				end
			end
		end,
	}
end
