modules.unnamed_b5 = function()
	local profiles = {}
	profiles["[Revolver]"] = {
		muzzleOffset = CFrame.new(-1, 0.4, 0),
		pellets = 1,
		cooldownPadding = 0,
	}
	profiles["[Double-Barrel SG]"] = {
		muzzleOffset = CFrame.new(0, 0.35, -2.2),
		pellets = 5,
		cooldownPadding = 0.0585,
	}
	profiles["[TacticalShotgun]"] = {
		muzzleOffset = CFrame.new(0, 0.25, -2.5),
		pellets = 5,
		cooldownPadding = 0.0095,
	}
	return {
		SEMI_AIM_DISTANCE = 200,
		profile = function(name)
			return profiles[name]
		end,
		cooldown = function(profile, base, multiplier)
			return (base + profile.cooldownPadding) * multiplier
		end,
		origin = function(handle, object, profile)
			local default = handle:FindFirstChild("Default")
			if default then
				local mesh = default:FindFirstChild("Mesh")
				if mesh then
					local muzzle = mesh:FindFirstChild("Muzzle")
					if muzzle and muzzle:IsA("Attachment") then
						return muzzle.WorldPosition
					end
				end
			end
			return (object.CFrame * profile.muzzleOffset).Position
		end,
	}
end
