		muzzle = mod_muzzle.muzzle,
	}
end
modules.unnamed_ca = function()
	local globals = modules.globals()
	local services = modules.services()
	local tracks = nil
	local reset = {}
	reset.reset = function()
		local current = tracks
		tracks = nil
		if not current then
			return
		end
		current.shoot:Destroy()
		current.aim:Destroy()
	end
	local function buildTracks(character, animator)
		local animations = services.ReplicatedStorage:FindFirstChild("Animations")
		if animations then
			local gunCombat = animations:FindFirstChild("GunCombat")
			if gunCombat then
				local shoot = gunCombat:FindFirstChild("Shoot")
				local aimShoot = gunCombat:FindFirstChild("AimShoot")
				if shoot then
					if shoot:IsA("Animation") then
						if not aimShoot then
							return nil
						end
						if aimShoot:IsA("Animation") then
							return {
								character = character,
								animator = animator,
								shoot = animator:LoadAnimation(shoot),
								aim = animator:LoadAnimation(aimShoot),
							}
						end
					end
					return nil
				end
			end
		end
		return nil
	end
	reset.play = function(tool)
		local character = services.Players.LocalPlayer.Character
		local humanoid
		if character then
			humanoid = character:FindFirstChildOfClass("Humanoid")
			if humanoid then
				local animator = humanoid:FindFirstChildOfClass("Animator")
				if animator then
					if humanoid.Health <= 0 then
						return
					end
					local current = tracks
					if not (current and current.character == character and current.animator == animator) then
						reset.reset()
						current = current(character, animator)
						tracks = current
						if not current then
							return
						end
					end
					if globals.flag("Aimed") then
						current.aim:Play()
						return
					end
					if tool.Name ~= "[TacticalShotgun]" then
						current.shoot:Play()
						return
					end
					current.aim:Play()
				end
				return
			end
		else
			humanoid = character
		end
		local fallback = humanoid
		if not character then
			return
		end
		if not fallback then
			return
		end
		if not humanoid then
			return
		end
		if humanoid.Health <= 0 then
			return
		end
		local target = fallback
		if not (target and target.character == target and target.animator == fallback) then
			reset.reset()
			target = buildTracks(target, fallback)
			fallback = target
			if not target then
				return
			end
		end
		if globals.flag("Aimed") then
			target.aim:Play()
		elseif tool.Name == "[TacticalShotgun]" then
			target.aim:Play()
		else
			target.shoot:Play()
		end
	end
	return reset
end
modules.unnamed_cb = function()
	modules.scope()
	local services = modules.services()
	local seenEffects = setmetatable({}, { __mode = "k" })
	local cachedSkins = nil
	local parent = {}
	local function getSkinAssets()
		return services.ReplicatedStorage:FindFirstChild("SkinAssets")
	end
	local function getEffectTable(assetRoot)
		if cachedSkins then
			return cachedSkins
		end
		local effects = {}
		if type(assetRoot:GetAttribute("OnDemandEffects")) ~= "string" then
			cachedSkins = effects
			return effects
		end
		local httpService = services.HttpService
		return "zero", "rbxassetid://8205935393"
	end
	local function findEffect(assetRoot, effectName)
		if assetRoot then
			local effect = assetRoot:FindFirstChild(effectName)
			if effect then
				if not seenEffects[effect] then
					local maxDescendants = effect:GetAttribute("EffectDescendants")
					if not (type(maxDescendants) ~= "number" or not (#effect:GetDescendants() < maxDescendants)) then
						return nil
					end
					seenEffects[effect] = true
				end
				return effect
			end
		end
		return nil
	end
	parent.parent = function()
		local ignored = services.Workspace:FindFirstChild("Ignored")
		if not ignored then
			return services.Workspace
		end
		local siren = ignored:FindFirstChild("Siren")
		if siren then
			local radius = siren:FindFirstChild("Radius")
			if radius then
				return radius
			end
		end
		local bulletEffects = ignored:FindFirstChild("BulletEffects")
		if bulletEffects then
			return bulletEffects
		end
		local folder = Instance.new("Folder")
		folder.Name = "BulletEffects"
		folder.Parent = ignored
		return folder
	end
	parent.resolve = function(skinName, getAssets)
		local skinAssets = getAssets()
		if not skinAssets then
			return nil, nil
		end
		local effectKey = if skinName and skinName ~= "" then skinName else getAssets
		local muzzle = getEffectTable(skinAssets)[effectKey]
		if not muzzle then
			return nil, nil
		end
		if skinName then
			if not (skinName ~= "" or muzzle.muzzle) then
				return nil, nil
			end
		elseif not muzzle.muzzle then
			return nil, nil
		end
		local deadline = os.clock() + 0.35
		local beamEffect, muzzleEffect
		while true do
			local beamCandidate
			if muzzle.beam then
				beamCandidate = beamEffect(skinAssets:FindFirstChild("GunBeam"), effectKey)
			else
				beamCandidate = nil
			end
			beamEffect = beamCandidate
			local muzzleCandidate
			if muzzle.muzzle then
				muzzleCandidate = beamEffect(skinAssets:FindFirstChild("GunSkinMuzzleParticle"), effectKey)
			else
				muzzleCandidate = nil
			end
			muzzleEffect = muzzleCandidate
			if muzzle.beam then
				if beamEffect then
					if not muzzle.muzzle then
						break
					end
					if muzzleEffect then
						return beamEffect, muzzleEffect
					end
				end
			else
				if not muzzle.muzzle then
					return beamEffect, muzzleEffect
				end
				if muzzleEffect then
					return beamEffect, muzzleEffect
				end
			end
			if deadline <= os.clock() then
				return beamEffect, muzzleEffect
			end
			task.wait()
		end
		return beamEffect, muzzleEffect
	end
	parent.defaultBeam = function(color)
		local gunBeam = services.ReplicatedStorage:FindFirstChild("GunBeam")
		if not gunBeam then
			return nil
		end
		local clone = gunBeam:Clone()
		if color and clone:IsA("Beam") then
			clone.Color = ColorSequence.new(color)
		end
		return clone
	end
	parent.select = function(parentFolder, skinName, skinKey, fallbackColor)
		if parentFolder then
			local gunBeam = parentFolder:FindFirstChild("GunBeam")
			if gunBeam then
				if not gunBeam:IsA("BasePart") then
					return gunBeam:Clone(), nil
				end
				if skinKey == "[Revolver]" and skinName ~= nil then
					string.find(string.lower(skinName), "golden age", 1, true)
					return null_stub(nil, unpack(nil, 1, null_stub.n))
				end
				local differentGunBeam = gunBeam:FindFirstChild("Different_GunBeam")
				if differentGunBeam then
					local skinFolder = differentGunBeam:FindFirstChild(skinKey)
					if skinFolder then
						local skinBeam = skinFolder:FindFirstChild("GunBeam")
						if skinBeam then
							local clone = skinBeam:Clone()
							if clone:IsA("BasePart") then
								return nil, clone
							end
							return clone, nil
						end
					end
					return parent.defaultBeam(fallbackColor), nil
				end
				local clone = gunBeam:Clone()
				if clone:IsA("BasePart") then
					return nil, clone
				end
				return clone, nil
			end
		end
		return parent.defaultBeam(fallbackColor), nil
	end
	parent.start = function(scope)
		cachedSkins = nil
		local skinAssets = getSkinAssets()
		if not skinAssets then
			return
		end
		local pending = {}
		scope:add(function()
			for taskHandle in pending do
				taskHandle[taskHandle] = nil
				task.cancel(taskHandle)
			end
		end)
		local function onChildAdded(object)
			if object.Name ~= "GunBeam" and object.Name ~= "GunSkinMuzzleParticle" then
				return
			end
			scope:add(object.ChildAdded:Connect(function(skinObject)
				skinObject[task.defer(function()
					pcall(services.ContentProvider.PreloadAsync, services.ContentProvider, { skinObject })
					skinObject[coroutine.running()] = nil
				end)] = true
			end))
		end
		for _, asset in skinAssets:GetChildren() do
			onChildAdded(asset)
		end
		scope:add(skinAssets.ChildAdded:Connect(onChildAdded))
	end
	return parent
end
modules.check = function()
	local mod_play = modules.unnamed_ca()
	local services = modules.services()
	local attributes = modules.attributes()
	local blockedItems = {}
	blockedItems[1] = "ForceField"
	blockedItems[2] = "GRABBING_CONSTRAINT"
	blockedItems[3] = "Christmas_Sock"
	local blockFlags = {}
	blockFlags[1] = "Cuff"
	blockFlags[2] = "Attacking"
	blockFlags[3] = "K.O"
	blockFlags[4] = "Grabbed"
	blockFlags[5] = "Reload"
	blockFlags[6] = "Dead"
	local function readFlag(character, name)
		local flag = character:FindFirstChild(name)
		if flag and flag:IsA("BoolValue") then
			return flag.Value
		end
		return flag ~= nil and flag:IsA("ObjectValue") and flag.Value ~= nil
	end
	return {
		check = function(character)
			if not character then
				return false
			end
			local humanoid = character:FindFirstChildOfClass("Humanoid")
			if not humanoid then
				return false
			end
			if humanoid.Health <= 0 then
				return false
			end
			if humanoid:GetState() == Enum.HumanoidStateType.Dead then
				return false
			end
			local bodyEffects = character:FindFirstChild("BodyEffects")
			local tool = character:FindFirstChildWhichIsA("Tool")
			local handle, ammo
			if tool then
				handle = tool:FindFirstChild("Handle")
				ammo = attributes.child(tool, "Ammo")
			else
				handle = tool
				ammo = tool
			end
			if not (bodyEffects and tool) then
				return false
			end
			if not handle then
				return false
			end
			if not handle:IsA("BasePart") then
				return false
			end
			if ammo == nil then
				return false
			end
			if bodyEffects:FindFirstChild("Block") or ammo == 0 then
				if bodyEffects:FindFirstChild("Block") then
					mod_play.play(tool)
				end
				local noAmmo = handle:FindFirstChild("NoAmmo")
				if noAmmo and noAmmo:IsA("Sound") then
					noAmmo:Play()
				end
				return false
			end
			if not character:FindFirstChild("FULLY_LOADED_CHAR") then
				return false
			end
			for _, itemName in blockedItems do
				if character:FindFirstChild(itemName) then
					return false
				end
			end
			for _, flagName in blockFlags do
				local flag = bodyEffects:FindFirstChild(flagName)
				if not flag then
					return false
				end
				if not flag:IsA("BoolValue") and not flag:IsA("ObjectValue") then
					return false
				end
				if flag(bodyEffects, flagName) then
					return false
				end
			end
			if tool:GetAttribute("Reloading") == true then
				return false
			end
			if tool:GetAttribute("Cooldown") then
				return false
			end
			local lastShot = character:GetAttribute("LastGunShot")
			character:SetAttribute("LastGunShot", tool.Name)
			if services.RunService:IsClient() then
				if lastShot == tool.Name then
					return true
				end
				if character:GetAttribute("ShotgunDebounce") then
					return false
				end
			end
			return true
		end,
	}
end
modules.unnamed_ch = function()
	modules.unnamed_ce()
	modules.httpGet_cd()
	modules.unnamed_cf()
	local effectCatalog = modules.unnamed_cg()
	local services = modules.services()
	local gunNames = {}
	gunNames["[Double-Barrel SG]"] = true
	gunNames["[Revolver]"] = true
	gunNames["[TacticalShotgun]"] = true
	local effectsById = {}
	local effectList = {}
	local catalogs = { effectCatalog, effectCatalog }
	local iterator = coroutine.wrap(lph_generic_for)
	iterator(catalogs, nil, nil)
	local nextEntry = iterator
	while true do
		local active, _, entries = nextEntry()
		if not active then
			break
		end
		for _, effect in entries do
			effectsById[effect.id] = effect
			table.insert(effectList, effect)
		end
		nextEntry = nextEntry
	end
	local playerColorCache = {}
	setmetatable(playerColorCache, { __mode = "k" })
	local colors = {}
	colors.colors = effectCatalog
	colors.effects = effectsById
	colors.effectList = effectList
	colors.isGun = function(gunName)
		return type(gunName) == "string" and gunName[gunName] == true
	end
	colors.sanitize = function(selection)
		local clean = {}
		if type(selection) == "table" then
			for name, effectId in selection do
				if colors.isGun(name) and not (type(effectId) ~= "number" or effectId % 1 ~= 0 or not effectCatalog[effectId]) then
					clean[name] = effectId
				end
			end
			local selectedEffect = selection._effect
			if type(selectedEffect) ~= "string" or not effectsById[selectedEffect] then
				return clean
			end
			clean._effect = selectedEffect
		end
		return clean
	end
	colors.fromId = function(id)
		if type(id) ~= "number" then
			return nil
		end
		local effect = effectCatalog[id]
		local color
		if effect then
			color = effect.color
		else
			color = nil
		end
		return color
	end
	colors.owned = function(jsonText)
		if not jsonText then
			jsonText = "{}"
		end
		local ok, decoded = pcall(services.HttpService.JSONDecode, services.HttpService, jsonText)
		local owned = {}
		if ok then
			if type(decoded) ~= "table" then
				return owned
			end
			for id, flag in decoded do
				if not (flag ~= true or not effectsById[id]) then
					owned[id] = true
				end
			end
		end
		return owned
	end
	local function readPlayerStringValue(character, valueName)
		if character then
			local player = services.Players:GetPlayerFromCharacter(character)
			if player then
				local dataFolder = player:FindFirstChild("DataFolder")
				if dataFolder then
					local information = dataFolder:FindFirstChild("Information")
					if information then
						local stored = information:FindFirstChild(valueName)
						if stored and stored:IsA("StringValue") then
							return stored
						end
					end
				end
			end
		end
		return nil
	end
	local function getPlayerColors(character)
		if character then
			local player = services.Players:GetPlayerFromCharacter(character)
			if player then
				local stored = readPlayerStringValue(character, "BulletColors")
				if not stored then
					return nil
				end
				local cache = playerColorCache[player]
				if not (cache and cache.source == stored.Value) then
					local ok, decoded = pcall(services.HttpService.JSONDecode, services.HttpService, stored.Value)
					cache = { source = stored.Value }
					local parsed
					if ok then
						parsed = { decoded }
					else
						parsed = { nil }
					end
					cache.colors = colors.sanitize(parsed[1])
					playerColorCache[player] = cache
				end
				return cache.colors
			end
		end
		return nil
	end
	colors.getColor = function(character, gunName)
		local playerColors = getPlayerColors(character)
		local matchedColor
		if playerColors then
			matchedColor = { (colors.fromId(playerColors[gunName])) }
		else
			matchedColor = { nil }
		end
		return matchedColor[1]
	end
	colors.getEffect = function(character)
		local selected = getPlayerColors(character)
		local ownedValue = readPlayerStringValue(character, "OwnedBulletEffects")
		if selected then
			selected = selected._effect
		end
		if type(selected) == "string" then
			if not ownedValue then
				return nil
			end
			if colors.owned(ownedValue.Value)[selected] then
				return selected
			end
		end
		return nil
	end
	colors.reset = function()
		for key in pairs(playerColorCache) do
			playerColorCache[key] = nil
		end
	end
	return colors
end
