modules.unnamed_cj = function()
	modules.scope()
	local services = modules.services()
	local mod_muzzle = modules.unnamed_ci()
	return {
		isLegacy = function()
			local legacySpread = services.Players.LocalPlayer:FindFirstChild("DataFolder")
			if legacySpread then
				legacySpread = legacySpread:FindFirstChild("Information")
				if legacySpread then
					legacySpread = legacySpread:FindFirstChild("LegacySpread")
				end
			end
			return legacySpread ~= nil and legacySpread:IsA("BoolValue") and legacySpread.Value
		end,
		supports = function(name, tool)
			if not mod_muzzle.profile(name) then
				return false
			end
			if tool then
				for _, valueName in { "Ammo", "Range", "ShootingCooldown", "Damage" } do
					local attribute = tool:FindFirstChild(valueName)
					if not attribute then
						return false
					end
					if not (attribute:IsA("NumberValue") or attribute:IsA("IntValue")) then
						return false
					end
				end
			end
			return true
		end,
		watch = function(scope, onChanged)
			local localPlayer = services.Players.LocalPlayer
			local seen = {}
			local function onDescendant(object)
				if object.Name ~= "LegacySpread" then
					return
				end
				if not object:IsA("BoolValue") then
					return
				end
				if seen[object] then
					return
				end
				seen[object] = true
				scope:add(object.Changed:Connect(onChanged))
				onChanged()
			end
			for _, descendant in localPlayer:GetDescendants() do
				onDescendant(descendant)
			end
			scope:add(localPlayer.DescendantAdded:Connect(function(object)
				onDescendant(object)
				if object.Parent and object.Parent:IsA("Tool") then
					onChanged()
				end
			end))
			scope:add(localPlayer.DescendantRemoving:Connect(function(object)
				if object.Name == "LegacySpread" then
					task.defer(onChanged)
				end
			end))
		end,
	}
end
modules.unnamed_ci = function()
	local profiles = {}
	local revolverProfile = {}
	revolverProfile.offset = CFrame.new(-1, 0.4, 0)
	revolverProfile.pellets = 1
	profiles["[Revolver]"] = revolverProfile
	profiles["[Double-Barrel SG]"] = { offset = CFrame.new(0, 0.35, -2.2), pellets = 5 }
	profiles["[TacticalShotgun]"] = { offset = CFrame.new(0, 0.25, -2.5), pellets = 5 }
	local profile = {}
	profile.profile = function(name)
		return profiles[name]
	end
	profile.origin = function(handle, object, muzzleProfile)
		local default = handle:FindFirstChild("Default")
		if default then
			local mesh = default:FindFirstChild("Mesh")
			if mesh then
				local muzzle = mesh:FindFirstChild("Muzzle")
				if muzzle and muzzle:IsA("Attachment") then
					return muzzle.WorldPosition
				end
			end
		end
		return (object.CFrame * muzzleProfile.offset).Position
	end
	profile.muzzle = function(object, handle)
		local muzzleProfile = profile.profile(object.Name)
		local origin
		if muzzleProfile then
			origin = {}
			origin[1] = profile.origin(object, handle, muzzleProfile)
		else
			origin = { nil }
		end
		return origin[1]
	end
	return profile
end
