modules.direction = function()
	local globals = modules.globals()
	local services = modules.services()
	local mod_cast = modules.unnamed_ck()
	local mouse = services.Players.LocalPlayer:GetMouse()
	return {
		direction = function(character, aimPosition)
			local currentCamera = services.Workspace.CurrentCamera
			local orbedSniper = character:FindFirstChild("[Orbed Sniper]")
			local isScoped = orbedSniper ~= nil and orbedSniper:GetAttribute("Scoped") == true
			local ray
			if globals.flag("MobileShiftLock") or globals.flag("ControllerShiftLock") or globals.flag("MobileMouseAim") or globals.flag("PCShiftLocked") and services.UserInputService.TouchEnabled or isScoped then
				ray = Ray.new(currentCamera.CFrame.Position, currentCamera.CFrame.LookVector)
			else
				ray = currentCamera:ScreenPointToRay(mouse.X, mouse.Y)
			end
			local object = mod_cast.ray(character, ray.Origin, ray.Direction * 2000)
			local hitPosition = ray.Origin + ray.Direction * 2000
			if object then
				hitPosition = object.Position
			end
			local delta = hitPosition - aimPosition
			if delta.Magnitude < 0.001 then
				return currentCamera.CFrame.LookVector
			end
			return delta.Unit
		end,
	}
end
modules.unnamed_ck = function()
	local services = modules.services()
	local cachedIgnored = nil
	local cachedFolder = nil
	local raycastParams = RaycastParams.new()
	raycastParams.FilterType = Enum.RaycastFilterType.Exclude
	raycastParams.IgnoreWater = true
	local ignoredList = table.create(2)
	local params = {}
	params.params = function(character)
		local ignored = services.Workspace:FindFirstChild("Ignored")
		if character ~= character or cachedFolder ~= ignored then
			table.clear(ignoredList)
			table.insert(ignoredList, character)
			if ignored then
				table.insert(ignoredList, ignored)
			end
			raycastParams.FilterDescendantsInstances = ignoredList
			cachedIgnored = character
			cachedFolder = ignored
		end
		return raycastParams
	end
	params.ray = function(character, origin, direction)
		return services.Workspace:Raycast(origin, direction, params.params(character))
	end
	params.cast = function(character, origin, target, distance)
		local vector = target - origin
		local direction = Vector3.new(0, 0, -1)
		if 0.001 < vector.Magnitude then
			direction = vector.Unit
		end
		local object = params.ray(character, origin, direction * distance)
		if object then
			return { position = object.Position, instance = object.Instance, normal = object.Normal }
		end
		return { position = origin + direction * distance, instance = nil, normal = nil }
	end
	return params
end
modules.select = function()
	local services = modules.services()
	local limbNames = {}
	local rootPartName = "HumanoidRootPart"
	limbNames[1] = "LowerTorso"
	limbNames[2] = rootPartName
	limbNames[3] = "Torso"
	limbNames[4] = "UpperTorso"
	limbNames[5] = "Head"
	local localPlayer = services.Players.LocalPlayer
	local mouse = localPlayer:GetMouse()
	local function hasAimLock(player)
		if localPlayer:GetAttribute("AimLock") == true then
			return true
		end
		if player:GetAttribute("AimLock") == true then
			return true
		end
		local ownedGamepasses = localPlayer:FindFirstChild("DataFolder")
		if ownedGamepasses then
			ownedGamepasses = ownedGamepasses:FindFirstChild("OwnedGamepasses")
			if ownedGamepasses then
				ownedGamepasses = ownedGamepasses:FindFirstChild("AimLock")
			end
		end
		return ownedGamepasses ~= nil and ownedGamepasses:IsA("BoolValue") and ownedGamepasses.Value
	end
	local function findLimb(character, partName)
		local limb = character:FindFirstChild(partName)
		if limb and limb:IsA("BasePart") then
			return limb
		end
		for _, fallbackName in limbNames do
			local fallback = character:FindFirstChild(fallbackName)
			if fallback and fallback:IsA("BasePart") then
				return fallback
			end
		end
		return nil
	end
	local function isTargetValid(character)
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if not humanoid then
			return false
		end
		if humanoid.Health <= 0 then
			return false
		end
		local bodyEffects = character:FindFirstChild("BodyEffects")
		for _, flagName in { "K.O", "Dead" } do
			if bodyEffects then
				local flag = bodyEffects:FindFirstChild(flagName)
				if flag and flag:IsA("BoolValue") and flag.Value then
					return false
				end
			end
		end
		return true
	end
	return {
		select = function(player, aimPosition, range, allowWideFov)
			if not hasAimLock(player) then
				return nil
			end
			local currentCamera = services.Workspace.CurrentCamera
			local fov = localPlayer:GetAttribute("AimLockFov")
			if allowWideFov and fov == nil then
				fov = player:GetAttribute("AimLockFov")
			end
			local fovNumber = tonumber(fov)
			if not fovNumber then
				fovNumber = 130
			end
			local fovRadius
			if allowWideFov then
				fovRadius = math.clamp(fovNumber, 10, 2000) * 5
			else
				fovRadius = math.max(10, fovNumber * 5)
			end
			local targetLimb = localPlayer:GetAttribute("TargetLimb") or "HumanoidRootPart"
			if localPlayer:GetAttribute("AimbotInfRange") == true then
				range = 5000
			end
			local mousePosition = Vector2.new(mouse.X, mouse.Y)
			local closestDistance = math.huge
			local players, playerCount, playerIndex = services.Players:GetPlayers()
			local bestPart = nil
			for _, candidate in players, playerCount, playerIndex do
				local character = candidate.Character
				if not (candidate ~= localPlayer and character and isTargetValid(character)) then
					continue
				end
				local limb = findLimb(character, tostring(isTargetValid))
				if not (limb and (limb.Position - aimPosition).Magnitude <= range) then
					continue
				end
				local screenPoint, onScreen = currentCamera:WorldToViewportPoint(limb.Position)
				local distance = (mousePosition - Vector2.new(screenPoint.X, screenPoint.Y)).Magnitude
				if onScreen and distance <= fovRadius and distance < closestDistance then
					closestDistance = distance
					bestPart = limb
				end
			end
			return bestPart
		end,
	}
end
modules.unnamed_cn = function()
	local globals = modules.globals()
	local services = modules.services()
	local color3 = Color3.new(1, 0.94902, 0.352941)
	local color32 = Color3.new(1, 0.545098, 0.14902)
	local localPlayer = services.Players.LocalPlayer
	local function readInfoValue(name)
		local information = localPlayer:FindFirstChild("DataFolder")
		if information then
			information = information:FindFirstChild("Information")
			if information then
				return (information:FindFirstChild(name))
			end
		end
		return information
	end
	local function parseColor(text)
		if type(text) ~= "string" then
			return nil
		end
		local ok, color = pcall(Color3.fromHex, text)
		local parsed
		if ok then
			parsed = { color }
		else
			parsed = { nil }
		end
		return parsed[1]
	end
	local function getEquipSkins(object)
		local equipSkins = readInfoValue("EquipSkins")
		if not equipSkins then
			return nil
		end
		equipSkins:IsA("StringValue")
		while true do
			null_stub(nil)
			local jsonDecode = services.HttpService.JSONDecode
			local httpService2 = services.HttpService
			local skinValue = equipSkins.Value
			if nil <= "number" then
				break
			end
			type.Name = nil
			if not (nil <= nil) then
			end
			if nil < 99 then
			end
		end
	end
	local function applyPartColor(part, color)
		if part:IsA("MeshPart") then
			part.TextureID = ""
			part.Color = color
			part.Material = Enum.Material.SmoothPlastic
		elseif part:IsA("BasePart") then
			part.Color = color
			part.Material = Enum.Material.SmoothPlastic
		elseif part:IsA("SpecialMesh") then
			part.TextureId = ""
			part.VertexColor = Vector3.new(color.R, color.G, color.B)
		end
	end
	return {
		beamColor = function(tool)
			local tracerColor = parseColor(localPlayer:GetAttribute("SkinTracerColor"))
			if tracerColor then
				return tracerColor
			end
			if type(tool:GetAttribute("SkinName")) == "string" then
				return nil
			end
			tracerColor("DH")
			services.ReplicatedStorage:GetAttribute("DH_ENABLED")
			return color32
		end,
		apply = function(object)
			if object.Parent ~= localPlayer.Character then
				return
			end
			local tracer = getEquipSkins(object)
			if not tracer then
				return
			end
			local tracerColor = tracer.tracer
			if tracerColor == nil then
				localPlayer:SetAttribute("SkinTracerColor", tracerColor)
			elseif type(tracerColor) == "string" then
				localPlayer:SetAttribute("SkinTracerColor", tracerColor)
			end
			local componentMap = tracer.components
			local default = object:FindFirstChild("Default")
			if type(componentMap) ~= "table" then
				return
			end
			if not default then
				return
			end
			local parts = default:GetDescendants()
			table.insert(parts, 1, default)
			local colorCounts = {}
			for _, part in parts do
				if not (part:IsA("BasePart") or part:IsA("SpecialMesh")) then
					continue
				end
				local studioId = part:GetAttribute("SkinStudioId")
				if not studioId then
					local name
					if part == default then
						name = object.Name
					else
						name = part.Name
					end
					studioId = name
				end
				local key = string.format("%s::%s", tostring(part.ClassName), tostring(tostring(studioId)))
				colorCounts[key] = (colorCounts[key] or 0) + 1
				local partColor = tracerColor(componentMap[string.format("%s::%s", tostring(key), tostring(colorCounts[key]))])
				if partColor then
					colorCounts(part, partColor)
				end
			end
		end,
	}
end
modules.unnamed_co = function()
	local arguments = {}
	arguments.arguments = function(shot)
		if shot.isShotgun then
			return table.pack("ShootGun", shot.handle, shot.origin, shot.shots, nil, nil, nil, shot.range, shot.damage)
		end
		local pellet = shot.shots[1]
		return table.pack("ShootGun", shot.handle, shot.origin, nil, pellet.Result1, pellet.Result2, pellet.Result3, shot.range, shot.damage, pellet.RawAimPosition, pellet.AimLockPart)
	end
	arguments.send = function(mainEvent, shot)
		local packed = arguments.arguments(shot)
		mainEvent:FireServer(table.unpack(packed, 1, packed.n))
	end
	return arguments
end
modules.unnamed_cq = function()
	local mod_isLegacy = modules.unnamed_cj()
	local mod_patterns = modules.unnamed_cp()
	local offset = {}
	local function randomOffset()
		local spread = math.random() * 0.05
		if math.random() <= 0.5 then
			return -math.random() * 0.05
		end
		return spread
	end
	offset.offset = function(scale)
		return Vector3.new(randomOffset(), randomOffset(), randomOffset()) * scale
	end
	offset.pattern = function(weaponName)
		if mod_isLegacy.isLegacy() then
			local pattern = mod_patterns.patterns[weaponName]
			if not pattern then
				return nil
			end
			if #pattern ~= 0 then
				return pattern[math.random(#pattern)]
			end
		end
		return nil
	end
	offset.pellet = function(pattern, index, direction, scale)
		if pattern then
			local point = pattern[index]
			if point then
				local unit = direction.Unit
				local crossBase = unit:Cross(Vector3.new(0, 1, 0))
				local cross = Vector3.new(1, 0, 0)
				if 0.01 < crossBase.Magnitude then
					cross = crossBase.Unit
				end
				local up = cross:Cross(unit).Unit
				return (cross * point.X + up * (point.Y + point.Z)) * mod_patterns.scale * scale
			end
		end
		return offset.offset(scale)
	end
	return offset
end
