modules.draw = function()
	modules.unnamed_ca()
	local services = modules.services()
	local playEffects = modules.unnamed_cr()
	modules.unnamed_ck()
	local mod_draw = modules.draw()
	local serverTime = services.Workspace:GetServerTimeNow()
	local soundCooldowns = setmetatable({}, { __mode = "k" })
	return {
		draw = function(soundState, timestamp, object, flags, extra)
			if not object.Parent then
				return
			end
			mod_draw.draw(soundState, timestamp, object, flags, extra)
			if 0.95 < services.Workspace:GetServerTimeNow() - timestamp then
				playEffects.play(timestamp)
			end
			if not (object:FindFirstChild("ShootSound") and not soundState[object]) then
				return
			end
			soundState[object] = true
			task.spawn(playEffects.play, object)
			task.delay(0.05, function()
				soundState[object] = nil
			end)
		end,
	}
end
modules.unnamed_cr = function()
	modules.scope()
	local services = modules.services()
	local urlModule = modules.urls()
	local activeScope = nil
	local scopeConnection = nil
	local hookInstalled = false
	local silentShotEnabled = false
	local clonedSounds = {}
	local function reset()
		if scopeConnection then
			scopeConnection:Disconnect()
			scopeConnection = nil
		end
		activeScope = nil
		hookInstalled = false
		silentShotEnabled = false
		for sound, delayThread in clonedSounds do
			clonedSounds[sound] = nil
			task.cancel(delayThread)
			sound:Destroy()
		end
	end
	local function isSilentShotEnabled()
		if not services.RunService:IsClient() then
			return false
		end
		if hookInstalled then
			return silentShotEnabled
		end
		local folder = services.Players.LocalPlayer:FindFirstChild("DataFolder")
		local silentShotFlag
		if folder then
			folder = folder:FindFirstChild("Information")
			if folder then
				silentShotFlag = folder:FindFirstChild("SilentShot")
				if silentShotFlag and silentShotFlag:IsA("BoolValue") then
					silentShotEnabled = silentShotFlag.Value == true
					local scope = silentShotFlag
					if scope and not scope:isDestroyed() then
						hookInstalled = true
						scopeConnection = scope:add(silentShotFlag.Changed:Connect(function()
							silentShotEnabled = silentShotFlag.Value == true
						end))
					end
					return silentShotEnabled
				end
				return false
			end
		end
		silentShotFlag = folder
		if silentShotFlag and silentShotFlag:IsA("BoolValue") then
			silentShotEnabled = silentShotFlag.Value == true
			local scope = silentShotFlag
			if scope and not scope:isDestroyed() then
				hookInstalled = true
				scopeConnection = scope:add(silentShotFlag.Changed:Connect(function()
					silentShotEnabled = silentShotFlag.Value == true
				end))
			end
			return silentShotEnabled
		end
		return false
	end
	local function advanceSequence(sound)
		local sequenceName = sound:GetAttribute("SequenceSFX")
		if type(sequenceName) ~= "string" then
			return
		end
		local currentSequence = sound:GetAttribute("CurrentSequence")
		local nextSequence = 1
		if type(currentSequence) == "number" then
			nextSequence = currentSequence + 1
		end
		local urlCount = #urlModule.urls(sequenceName)
		if not (0 < urlCount) then
			return
		end
		sound:SetAttribute("CurrentSequence", nextSequence)
	end
	return {
		start = function(scope)
			reset()
			activeScope = scope
			scope:add(function()
				if activeScope == scope then
					reset()
				end
			end)
		end,
		play = function(object, cloneSound)
			local shootSound = object:FindFirstChild("ShootSound")
			if isSilentShotEnabled() then
				return
			end
			if not shootSound then
				return
			end
			if not shootSound:IsA("Sound") then
				return
			end
			advanceSequence(shootSound)
			if cloneSound ~= false then
				local soundClone = shootSound:Clone()
				soundClone.Name = "MG"
				soundClone.Parent = object
				soundClone:Play()
				clonedSounds[soundClone] = task.delay(1.5, function()
					clonedSounds[soundClone] = nil
					soundClone:Destroy()
				end)
			else
				shootSound:Play()
			end
		end,
	}
end
modules.draw = function()
	local mod_apply = modules.unnamed_cn()
	local mod_defaultBeam = modules.unnamed_cb()
	local mod_draw = modules.draw()
	local mod_colors = modules.unnamed_ch()
	local mod_emit = modules.emit()
	local mod_render = modules.render()
	local services = modules.services()
	local mod_activate = modules.unnamed_cz()
	modules.unnamed_ck()
	local function deflectCollider(hit)
		if not hit.instance then
			return
		end
		if hit.instance.Name ~= "SVJCollider" then
			return
		end
		local svjCarRemote = services.ReplicatedStorage:FindFirstChild("SVJCarRemote")
		if svjCarRemote and svjCarRemote:IsA("RemoteEvent") then
			svjCarRemote:FireServer("Deflect", hit.instance)
		end
	end
	local function resolveBeamColor(shooter, handle)
		local customColor = mod_colors.getColor(shooter, handle.Name)
		local halloweenColor = handle:GetAttribute("HalloweenBeamColor")
		local fallbackColor = mod_apply.beamColor(handle)
		if typeof(halloweenColor) ~= "Color3" then
			halloweenColor = fallbackColor
		end
		if customColor then
			return customColor, customColor
		end
		return halloweenColor, customColor
	end
	local function configureBeam(beam, attachment0, attachment1, parent)
		if not beam then
			return
		end
		if beam:IsA("Beam") then
			beam.Attachment0 = attachment0
			beam.Attachment1 = attachment1
		end
		beam.Name = "NewGunBeam"
		beam.Parent = parent
	end
	return {
		draw = function(shooter, tool, handle, origin, hit)
			if not handle.Parent then
				return
			end
			deflectCollider(hit)
			local finalColor, colorOverride = resolveBeamColor(shooter, handle)
			local effect = mod_colors.getEffect(shooter)
			local skinName = handle:GetAttribute("SkinName")
			local effectName = if type(skinName) == "string" then skinName else nil
			local beamSet = nil
			local beamVariant = nil
			if not effect then
				local resolvedSet, resolvedVariant = mod_defaultBeam.resolve(effectName, tool.Name)
				beamSet = resolvedSet
				beamVariant = resolvedVariant
				if handle.Parent ~= tool then
					return
				end
			end
			local parent = mod_defaultBeam.parent()
			local raysPart = Instance.new("Part")
			raysPart:SetAttribute("OwnerCharacter", shooter.Name)
			raysPart.Name = "BULLET_RAYS"
			raysPart.Anchored = true
			raysPart.CanCollide = false
			raysPart.Size = Vector3.zero
			raysPart.Transparency = 1
			raysPart.CFrame = CFrame.lookAt(origin, hit.position)
			raysPart.Material = Enum.Material.SmoothPlastic
			if colorOverride then
				raysPart:SetAttribute("BulletColorOverride", true)
			end
			raysPart.Parent = parent
			services.Debris:AddItem(raysPart, 1)
			local attachment = Instance.new("Attachment")
			attachment.Parent = raysPart
			local attachment2 = Instance.new("Attachment")
			attachment2.Position = Vector3.new(0, 0, -(hit.position - origin).Magnitude)
			attachment2.Parent = raysPart
			local beam, secondary, hasMuzzle
			if effect then
				beam = mod_draw.draw(raysPart, attachment, attachment2, handle, effect, parent)
				secondary = nil
				hasMuzzle = true
			else
				hasMuzzle = mod_emit.emit(beamVariant, tool, handle, attachment, finalColor)
				local chosenBeam, chosenSecondary = mod_defaultBeam.select(beamSet, effectName, tool.Name, finalColor)
				beam = chosenBeam
				secondary = chosenSecondary
				if finalColor then
					mod_activate.effect(beam, finalColor)
					mod_activate.apply(secondary, finalColor, true, false)
				end
			end
			task.spawn(mod_render.render, {
				shooter = shooter,
				tool = tool,
				handle = handle,
				origin = origin,
				hit = hit,
				parent = parent,
				rays = raysPart,
				beamSet = beamSet,
				color = finalColor,
				hasMuzzle = hasMuzzle,
			}, secondary)
			if beam then
				if beam:IsA("Beam") then
					beam.Attachment0 = attachment
					beam.Attachment1 = attachment2
				end
				if not effect then
					if tool.Name ~= "[Orbed Sniper]" then
						if tool.Name == "[Quested Rifle]" then
							mod_draw.draw(beam, raysPart, handle, origin, hit.position, hit.instance, colorOverride)
						end
					else
						mod_draw.draw(beam, raysPart, handle, origin, hit.position, hit.instance, colorOverride)
					end
				end
			end
			if not colorOverride then
				configureBeam(beam, attachment, attachment2, raysPart)
				return
			end
			if not effect then
				mod_activate.apply(raysPart, colorOverride)
				mod_activate.apply(secondary, colorOverride)
				mod_activate.apply(beam, colorOverride)
			end
			configureBeam(beam, attachment, attachment2, raysPart)
		end,
	}
end
