modules.apply = function()
	modules.services()
	local pumpkin = {}
	pumpkin.pumpkin = utf8.char(127875)
	pumpkin.candycorn = utf8.char(127852)
	pumpkin.mist = utf8.char(128123)
	pumpkin.witchlight = utf8.char(128302)
	pumpkin.web = utf8.char(128376, 65039)
	pumpkin.hearth = utf8.char(128293)
	pumpkin.blood = utf8.char(129656)
	local seed = 245608254
	local function createTrailAnchor(rays, distance, index, count)
		local attachment = Instance.new("Attachment")
		local mixed = bit32.band(seed, 4294967295)
		local low = bit32.band(mixed, 65535)
		local high = 18473 * bit32.rshift(mixed, 16)
		local combined = bit32.band(18473 * low + bit32.lshift(bit32.band(high + 7704 * low, 65535), 16), 4294967295) % 4294967296
		local floored
		if combined ~= combined then
			floored = 0
		else
			floored = combined - combined % 1
		end
		local anchorIndex = floored
		attachment.Name = string.format("TrailEmojiAnchor%s", tostring(index))
		attachment.Position = Vector3.new(0, 0, -distance * (index / (count + 1)))
		attachment.Parent = rays.rays
		local instanceClass = Instance
		return instanceClass, nil, "current"
	end
	seed = 271687508
	return {
		apply = function(effect)
			local style = effect.effect.style
			if style and pumpkin[style] then
				local magnitude = (effect.finish.WorldPosition - effect.start.WorldPosition).Magnitude
				if magnitude < 10 then
