end
modules.unnamed_cs = function()
	modules.httpGet_cd()
	return {
		add = function(start, config)
			local beam = Instance.new("Beam")
			beam.Name = config.name
			beam.FaceCamera = true
			beam.Attachment0 = config.first or start.start
			beam.Attachment1 = config.last or start.finish
			beam.Width0 = config.width
			beam.Width1 = config.width * 0.45
			beam.Color = config.colors
			beam.Transparency = NumberSequence.new(config.opacity)
			beam.LightEmission = 1
			beam.LightInfluence = 0
			beam.Brightness = 3
			beam.Segments = 12
			beam.Parent = start.rays
			table.insert(start.layers, { beam = beam, opacity = config.opacity })
			return beam
		end,
		offset = function(rays, config)
			local attachment = Instance.new("Attachment")
			attachment.Name = config.name
			attachment.Position = config.anchor.Position + Vector3.new(config.x, 0, config.z or 0)
			attachment.Parent = rays.rays
			return attachment
		end,
		fade = function(effect)
			task.spawn(function()
				task.wait(effect.effect.life * 0.4)
				local startValue = 1
				local limit = 5
				local current = startValue - 1
				local step = limit + 0
				local direction = 1
				local position = current + direction
				if position <= step then
					local opacity = position
					local nextOpacity = position
					while effect.rays.Parent do
						for _, layer in effect.layers do
							layer.beam.Transparency = NumberSequence.new(layer.opacity + (1 - layer.opacity) * opacity / 5)
						end
						local previous = nextOpacity
						direction = direction
						task.wait(effect.effect.life * 0.6 / 5)
						local advanced = previous + direction
						if direction <= 0 then
							if advanced >= step then
								opacity = advanced
								nextOpacity = advanced
								continue
							end
						elseif advanced <= step then
							opacity = advanced
							nextOpacity = advanced
							continue
						end
						effect.rays:Destroy()
						return
					end
				else
					effect.rays:Destroy()
				end
			end)
		end,
	}
end
