modules.apply = function()
	local moduleTable = modules
	local offset = moduleTable.unnamed_cs()
	local palette = {}
	local red, green
	if moduleTable then
		red = 255
		green = 238
	end
	local firstColor = Color3.fromRGB(red, green, 173)
	local secondColor = Color3.fromRGB(255, 133, 53)
	local packed = table.pack(Color3.fromRGB(255, 211, 78))
	palette[1] = firstColor
	palette[2] = secondColor
	table.move(packed, 1, packed.n, 3, palette)
	local witchlight = {}
	witchlight.witchlight = true
	witchlight.frosted = true
	witchlight.pumpkin = true
	witchlight.hearth = true
	witchlight.blood = true
	local function applyCandyCorn(effect, beam)
		beam.Transparency = NumberSequence.new(0.88)
		effect.layers[1].opacity = 0.88
		local indices
		if effect.reduced then
			indices = { 2 }
		else
			indices = { 1, 2, 3 }
		end
		for _, index in indices do
			local offsetAmount = (index - 2) * effect.effect.width * 0.8
			local startAnchor = offset.offset(effect, {
				name = string.format("CandyCornStart%s", tostring(index)),
				anchor = effect.start,
				x = offsetAmount,
			})
			local endAnchor = offset.offset(effect, {
				name = string.format("CandyCornEnd%s", tostring(index)),
				anchor = effect.finish,
				x = offsetAmount,
			})
			offset.add(effect, {
				name = string.format("CandyCornStripe%s", tostring(index)),
				width = effect.effect.width * 0.38,
				opacity = 0.08,
				colors = ColorSequence.new(palette[index]),
				first = startAnchor,
				last = endAnchor,
			}).Width1 = effect.effect.width * 0.08
		end
	end
	local function applyMist(effect)
		local sides
		if effect.reduced then
			sides = { -1 }
		else
			sides = { -1, 1 }
		end
		for index, side in sides do
			local startAnchor = offset.offset(effect, {
				name = string.format("GraveMistStart%s", tostring(index)),
				anchor = effect.start,
				x = side * effect.effect.width * 0.8,
			})
			local endAnchor = offset.offset(effect, {
				name = string.format("GraveMistEnd%s", tostring(index)),
				anchor = effect.finish,
				x = -side * effect.effect.width * 0.8,
			})
			local wisp = offset.add(effect, {
				name = string.format("GraveMistWisp%s", tostring(index)),
				width = effect.effect.width * 1.2,
				opacity = 0.82,
				colors = ColorSequence.new(effect.lastColor, effect.firstColor),
				first = startAnchor,
				last = endAnchor,
			})
			wisp.CurveSize0 = side * effect.effect.curve * 1.8
			wisp.CurveSize1 = -side * effect.effect.curve * 1.8
		end
	end
	local function applyWeb()
		return "Color", "model"
	end
	return {
		apply = function(effect, beam)
			local style = effect.effect.style
			if style == "candycorn" then
				applyCandyCorn(effect, beam)
			elseif style == "mist" then
				applyMist(effect)
			elseif style ~= "web" then
				if style and witchlight[style] then
					local accent = offset.add(effect, {
						name = "HalloweenAccent",
						width = effect.effect.width * 0.34,
						opacity = 0.16,
						colors = ColorSequence.new(effect.lastColor, effect.firstColor),
					})
					accent.CurveSize0 = -effect.effect.curve * 0.65
					accent.CurveSize1 = effect.effect.curve * 0.65
				end
			else
				applyWeb(effect, beam)
			end
		end,
	}
end
modules.draw = function()
	local globals = modules.globals()
	local services = modules.services()
	local defaultSequence = ColorSequence.new(Color3.fromRGB(189, 220, 255), Color3.fromRGB(142, 134, 255))
	local function resolveSequence(color)
		local sequence
		if color then
			sequence = ColorSequence.new(color)
		else
			sequence = defaultSequence
		end
		return sequence
	end
	local function createPart(name, parent, position)
		local part = Instance.new("Part")
		part.Name = name
		part.Size = Vector3.new(0.04, 0.04, 0.04)
		part.Transparency = 1
		part.Anchored = true
		part.CanCollide = false
		part.CanTouch = false
		part.CanQuery = false
		part.Position = position
		part.Parent = parent
		return part
	end
	local function emitSparkles(config)
		local particleEmitter = Instance.new("ParticleEmitter")
		particleEmitter.Name = "LaserSparkles"
		particleEmitter.Texture = "rbxasset://textures/particles/sparkles_main.dds"
		particleEmitter.Color = resolveSequence(config.color)
		particleEmitter.LightEmission = 0.85
		particleEmitter.Rate = 0
		particleEmitter.Lifetime = config.lifetime
		particleEmitter.Speed = config.speed
		particleEmitter.Drag = 5
		local spread = config.spread or 180
		particleEmitter.SpreadAngle = Vector2.new(spread, spread)
		particleEmitter.EmissionDirection = Enum.NormalId.Front
		particleEmitter.Rotation = NumberRange.new(0, 360)
		local createSequence = NumberSequence.new
		local keypoints = {}
		local firstKeypoint = NumberSequenceKeypoint.new(0, config.size)
		local secondKeypoint = NumberSequenceKeypoint.new(0.25, config.size * 0.8)
		local packed = table.pack(NumberSequenceKeypoint.new(1, 0))
		keypoints[1] = firstKeypoint
		keypoints[2] = secondKeypoint
		table.move(packed, 1, packed.n, 3, keypoints)
		particleEmitter.Size = createSequence(keypoints)
		particleEmitter.Transparency = NumberSequence.new(0.1, 1)
		particleEmitter.Parent = config.parent
		particleEmitter:Emit(config.count)
