	local function configureBeam(beam, color)
		beam.Color = resolveSequence(color)
		beam.Texture = "rbxassetid://124838228841932"
		beam.TextureMode = Enum.TextureMode.Wrap
		beam.TextureLength = 2.5
		beam.TextureSpeed = 4
		beam.Width0 = 0.18
		beam.Width1 = 0.075
		beam.FaceCamera = true
		beam.LightEmission = 0.85
		beam.Transparency = NumberSequence.new(0.32, 0.6)
	end
	local function createCoreBeam(beam, parent, color)
		local coreBeam = Instance.new("Beam")
		coreBeam.Name = "LaserCore"
		coreBeam.Attachment0 = beam.Attachment0
		coreBeam.Attachment1 = beam.Attachment1
		local coreColor
		if color then
			coreColor = ColorSequence.new(color)
		else
			coreColor = ColorSequence.new(Color3.fromRGB(225, 244, 255))
		end
		coreBeam.Color = coreColor
		coreBeam.Width0 = 0.035
		coreBeam.Width1 = 0.015
		coreBeam.FaceCamera = true
		coreBeam.LightEmission = 1
		coreBeam.Transparency = NumberSequence.new(0.05, 0.3)
		coreBeam.Parent = parent
	end
	local function createShotImages(parent, origin, direction)
		for index = 1, 5 do
			local attachment = Instance.new("Attachment")
			attachment.Name = string.format("LaserImagePoint%s", tostring(index))
			attachment.Parent = parent
			attachment.WorldPosition = origin + direction * (index / 6)
			local billboardGui = Instance.new("BillboardGui")
			billboardGui.Name = string.format("LaserShotImage%s", tostring(index))
			billboardGui.Adornee = attachment
			billboardGui.Size = UDim2.fromScale(0.65, 0.65)
			billboardGui.LightInfluence = 0
			billboardGui.MaxDistance = 160
			billboardGui.AlwaysOnTop = false
			billboardGui.Parent = parent
			local imageLabel = Instance.new("ImageLabel")
			imageLabel.Name = "ShotArtwork"
			imageLabel.BackgroundTransparency = 1
			imageLabel.Size = UDim2.fromScale(1, 1)
			imageLabel.Image = "rbxassetid://124838228841932"
			imageLabel.ImageColor3 = Color3.new(1, 1, 1)
			imageLabel.ScaleType = Enum.ScaleType.Fit
			imageLabel.Parent = billboardGui
			services.TweenService:Create(imageLabel, TweenInfo.new(0.12, Enum.EasingStyle.Linear, Enum.EasingDirection.Out, 0, false, 0.04), { ImageTransparency = 1 }):Play()
		end
	end
	local function createTrail(createPartFn, parent, destination, colorResolver)
		local rotation = CFrame.lookAt(parent, destination)
		local trailPart = createPartFn("LaserTrail", createPartFn.Parent, parent)
		trailPart.CFrame = rotation
		createShotImages(createPartFn, parent, destination - parent)
		local leftAttachment = Instance.new("Attachment")
		leftAttachment.Position = Vector3.new(-0.09, 0, 0)
		leftAttachment.Parent = trailPart
		local rightAttachment = Instance.new("Attachment")
		rightAttachment.Position = Vector3.new(0.09, 0, 0)
		rightAttachment.Parent = trailPart
		local ribbon = Instance.new("Trail")
		ribbon.Name = "LaserRibbon"
		ribbon.Attachment0 = leftAttachment
		ribbon.Attachment1 = rightAttachment
		ribbon.Color = colorResolver(colorResolver)
		ribbon.Texture = "rbxassetid://124838228841932"
		ribbon.Lifetime = 0.1
		ribbon.FaceCamera = true
		ribbon.LightEmission = 0.8
		ribbon.Transparency = NumberSequence.new(0.3, 1)
		ribbon.WidthScale = NumberSequence.new(1, 0)
		ribbon.Parent = trailPart
		local tweenDuration = math.clamp((destination - parent).Magnitude / 2200, 0.045, 0.12)
		services.TweenService:Create(trailPart, TweenInfo.new(tweenDuration, Enum.EasingStyle.Linear), { CFrame = CFrame.new(destination) * rotation.Rotation }):Play()
		services.Debris:AddItem(trailPart, tweenDuration + 0.12)
		local spawnAttachment = Instance.new("Attachment")
		spawnAttachment.Parent = createPartFn
		spawnAttachment.WorldCFrame = rotation
		colorResolver({
			parent = spawnAttachment,
			count = 4,
			lifetime = NumberRange.new(0.06, 0.12),
			speed = NumberRange.new(2, 5),
			size = 0.14,
			spread = 28,
			color = colorResolver,
		})
	end
	local function createImpact(object, color)
		createPart("LaserImpact", object.Parent, color)
		return nil, "random", "GetPropertyChangedSignal"
	end
	return {
		draw = function(beam, sourceObject, unusedParam, origin, destination, configureBeamFn, color)
			if not beam:IsA("Beam") then
				return
			end
			configureBeamFn(beam, color)
			services.Debris:AddItem(sourceObject, 0.18)
			local currentCamera = services.Workspace.CurrentCamera
			if globals.flag("Reduce_Lag") then
				return
			end
			if 32 <= sourceObject then
				return
			end
			if currentCamera and 350 < (currentCamera.CFrame.Position - origin).Magnitude then
				return
			end
			sourceObject = sourceObject + 1
			task.delay(0.42, function()
				sourceObject = sourceObject - 1
