			local playerScope = playerScopes[player]
			playerScopes[player] = nil
			if playerScope then
				playerScope:destroy()
			end
		end
		local function addPlayer(player)
			if player == services.Players.LocalPlayer then
				return
			end
			if playerScopes[player] then
				return
