			if instance:IsA("Model") and services.Players:GetPlayerFromCharacter(instance) then
				return
			end
			if (tagName ~= "Loot" or instance:IsA("BasePart")) and (tagName ~= "NPCs" or instance:IsA("Model")) then
				targets.retain(instance, tagName, tag, nil)
