		local tag = "folder:" .. kind
		local currentFolder = nil
		local folderScope = nil
		local watcherScope = nil
		local function refresh()
			local workspace = services.Workspace
			local testZone = workspace:FindFirstChild("TestZone")
			local folder = workspace:FindFirstChild(folderName)
			if not folder then
				if testZone then
					folder = testZone:FindFirstChild(folderName)
				else
					folder = testZone
				end
			end
			if folder == currentFolder then
				return
			end
			if folderScope then
				local oldScope = folderScope
				if folder == currentFolder then
					return
				end
				oldScope:destroy()
				folderScope = nil
			end
			currentFolder = folder
			if not folder then
				return
			end
			local newScope = scope.new()
			folderScope = newScope
