			trackPlayers(scope, targets)
			trackTagged(scope, targets, "GroundLoot", "Loot")
			trackTagged(scope, targets, "GunBot", "NPCs")
			trackFolder(scope, targets, "Cars", "Vehicles")
			trackFolder(scope, targets, "Dummies", "NPCs")
