			local function warnOnce(kind, message)
				local text = tostring(message)
				if warnings[kind] == text then
					return
				end
				warnings[kind] = text
				warn(string.format("Atomic Urban Aim [%s]: %s", tostring(kind), tostring(text)))
			end
			local function tryCreate()
				if virtualInput then
					return
				end
				if scope:isDestroyed() then
					return
				end
				if os.clock() < nextCheck then
					return
				end
				nextCheck = os.clock() + 2
				local ok, created = pcall(nextCheck)
				if ok then
					if created then
						local checkOk, checkResult = pcall(created, created)
						if checkOk then
							if checkResult ~= true then
								warnOnce("Validate", "CreateVirtualInput returned an incompatible object")
								return
							end
						else
							local classOk, className = pcall(checkOk, created)
							if not classOk then
								classOk("IsA", checkResult)
								classOk("ClassName", className)
								return
							end
							if className == "VirtualInput" then
								warnOnce("IsA", string.format("Recovered using ClassName=VirtualInput; %s", tostring(tostring(checkResult))))
							else
								warnOnce("IsA", checkResult)
								warnOnce("Validate", "CreateVirtualInput returned an incompatible object")
								return
							end
						end
						created = created
					else
						warnOnce("CreateVirtualInput", "Native look input is unavailable; aim assistance cannot steer")
					end
				else
					warnOnce("CreateVirtualInput", created)
				end
			end
			local function available()
				tryCreate()
				local hasInput = virtualInput ~= nil
				if not (virtualInput ~= nil) then
					return hasInput
				end
				return not scope:isDestroyed()
