				move = function(delta)
					if delta.X ~= delta.X then
						return false
					end
					if delta.Y ~= delta.Y then
						return false
					end
					if delta.Magnitude >= math.huge then
						return false
					end
					if not available() then
						return false
					end
					if os.clock() < blockedUntil then
						return false
					end
					if services.UserInputService.MouseBehavior ~= Enum.MouseBehavior.LockCenter then
						return false
					end
					if services.GuiService.MenuIsOpen then
						return false
					end
					if services.UserInputService:GetFocusedTextBox() then
						return false
					end
					local input = virtualInput
					if not input then
						return false
					end
					local sent, err = pcall(sendDelta, input, delta)
					if not sent then
						blockedUntil = os.clock() + 0.25
						warnOnce("SendMouseDelta", blockedUntil)
					end
					return sent
				end,
				status = function()
					if not available() then
						return "native input unavailable"
					end
					if os.clock() < blockedUntil then
						return "native input blocked"
					end
					return nil
				end,
			}
		end,
	}
end
