modules.measure = function()
	local mod_isBodyPart = modules.unnamed_cP()
	local function isFiniteVector(vector)
		return vector.X == vector.X and vector.Y == vector.Y and vector.Z == vector.Z and vector.Magnitude < math.huge
	end
	return {
		measure = function(kind)
			local rootPart = kind.root
			local character = kind.model
			if rootPart and character then
				if not rootPart:IsDescendantOf(character) then
					return nil, nil
				end
				if not isFiniteVector(rootPart.Position) then
					return nil, nil
				end
				local inverseCFrame = rootPart.CFrame:Inverse()
				local minX = math.huge
				local minY = math.huge
				local minZ = math.huge
				local maxX = -math.huge
				local maxY = -math.huge
				local maxZ = -math.huge
				local hasHead = false
				local hasUpperTorso = false
				local hasLowerTorso = false
				for _, part in kind.parts do
					if not part:IsDescendantOf(character) then
						return nil, nil
					end
					if not mod_isBodyPart.isBodyPart(part) then
						return nil, nil
					end
					if part.Name == "Head" then
						hasHead = true
					end
					if part.Name == "UpperTorso" then
						hasUpperTorso = true
					end
					if part.Name == "LowerTorso" then
						hasLowerTorso = true
					end
					local partCFrame = inverseCFrame * part.CFrame
					local halfSize = part.Size * 0.5
					local rightVector = partCFrame.RightVector
					local upVector = partCFrame.UpVector
					local lookVector = partCFrame.LookVector
					local extent = Vector3.new(math.abs(rightVector.X) * halfSize.X + math.abs(upVector.X) * halfSize.Y + math.abs(lookVector.X) * halfSize.Z, math.abs(rightVector.Y) * halfSize.X + math.abs(upVector.Y) * halfSize.Y + math.abs(lookVector.Y) * halfSize.Z, math.abs(rightVector.Z) * halfSize.X + math.abs(upVector.Z) * halfSize.Y + math.abs(lookVector.Z) * halfSize.Z)
					local cornerMin = partCFrame.Position - extent
					local cornerMax = partCFrame.Position + extent
					if not isFiniteVector(cornerMin) then
						return nil, nil
					end
					if not isFiniteVector(cornerMax) then
						return nil, nil
					end
					if 64 < cornerMin.Magnitude then
						return nil, nil
					end
					if 64 < cornerMax.Magnitude then
						return nil, nil
					end
					minX = math.min(minX, cornerMin.X)
					minY = math.min(minY, cornerMin.Y)
					minZ = math.min(minZ, cornerMin.Z)
					maxX = math.max(maxX, cornerMax.X)
					maxY = math.max(maxY, cornerMax.Y)
					maxZ = math.max(maxZ, cornerMax.Z)
				end
				if not hasHead then
					return nil, nil
				end
				if not hasUpperTorso then
					return nil, nil
				end
				while hasLowerTorso do
					local vectorType = Vector3
					if hasHead then
						local minCorner = vectorType.new(minX, minY, minZ)
						local maxCorner = Vector3.new(maxX, maxY, maxZ)
						local size = maxCorner - minCorner
						if size.X <= 0 then
							return nil, nil
						end
						if size.Y <= 0 then
							return nil, nil
						end
						if size.Z <= 0 then
							return nil, nil
						end
						if 64 < math.max(size.X, size.Y, size.Z) then
							return nil, nil
						end
						return rootPart.CFrame * CFrame.new((minCorner + maxCorner) * 0.5), size
					end
				end
			end
			return nil, nil
		end,
	}
end
modules.espBox = function()
	modules.enclose()
	local corners = {}
	corners[1] = Vector3.new(-1, -1, -1)
	corners[2] = Vector3.new(1, -1, -1)
	corners[3] = Vector3.new(-1, 1, -1)
	corners[4] = Vector3.new(1, 1, -1)
	corners[5] = Vector3.new(-1, -1, 1)
	corners[6] = Vector3.new(1, -1, 1)
	corners[7] = Vector3.new(-1, 1, 1)
	local lastCorner = table.pack(Vector3.new(1, 1, 1))
	corners[8] = lastCorner[1]
	local edgeStarts = { 1, 1, 1, 2, 2, 3, 3, 4, 5, 5, 6, 7 }
	local edgeEnds = {}
	edgeEnds[1] = 2
	edgeEnds[2] = 3
	edgeEnds[3] = 5
	edgeEnds[4] = 4
	edgeEnds[5] = 6
	edgeEnds[6] = 4
	edgeEnds[7] = 7
	edgeEnds[8] = 8
	edgeEnds[9] = 6
	edgeEnds[10] = 7
	edgeEnds[11] = 8
	edgeEnds[12] = 8
	local projectedCorners = table.create(8, Vector3.zero)
	local depths = table.create(8, 0)
	local minX = 0
	local minY = 0
	local minZ = 0
	local function projectPoint(camera, point)
		local worldToViewportPoint = camera.WorldToViewportPoint
		local projected = null_stub(worldToViewportPoint, point)
		upval0["nil"] = "max"
		if projected.Y ~= projected.Y then
			return null_stub(nil, nil)
		end
		return "Tool", "clock"
	end
	return {
		box = function(viewportContext, pointToWorldSpace, scale)
			local camera = viewportContext.ViewportSize
			if not (0 < camera.X) then
				return nil, nil
			end
			if not (camera.X < math.huge) then
				return nil, nil
			end
			if not (0 < camera.Y) then
				return nil, nil
			end
			if not (camera.Y < math.huge) then
				return nil, nil
			end
			local nearPlanes = table.pack(0.05, math.abs(camera.NearPlaneZ))
			local nearLimit = math.max(unpack(nearPlanes, 1, nearPlanes.n))
			local cameraCFrame = camera.CFrame
			for index, corner in corners do
				local worldPoint = pointToWorldSpace:PointToWorldSpace(scale * corner * 0.5)
				local depth = (worldPoint - cameraCFrame.Position):Dot(cameraCFrame.LookVector)
				if depth ~= depth then
					return nil, nil
				end
				local absDepth = math.abs(depth)
				if math.huge <= absDepth then
					return nil, nil
				end
				projectedCorners[index] = worldPoint
				depths[index] = depth
				if nearLimit <= depth and not projectPoint(camera, worldPoint) then
					return nil, nil
				end
			end
			for edgeIndex, startIndex in edgeStarts do
				local endIndex = edgeEnds[edgeIndex]
				local depthStart = depths[startIndex]
				local depthEnd = depths[endIndex]
				if depthStart < nearLimit and depthEnd >= nearLimit then
					local t = (nearLimit - depthStart) / (depthEnd - depthStart)
					if not projectPoint(camera, projectedCorners[startIndex]:Lerp(projectedCorners[endIndex], t)) then
						return nil, nil
					end
					continue
				end
				if depthEnd < nearLimit then
					if not (depthStart >= nearLimit) then
						continue
					end
				else
					continue
				end
				local t = (nearLimit - depthStart) / (depthEnd - depthStart)
				if not projectPoint(camera, projectedCorners[startIndex]:Lerp(projectedCorners[endIndex], t)) then
					return nil, nil
				end
			end
			if minX == math.huge then
				return nil, nil
			end
			if minY <= 0 then
				return nil, nil
			end
			if minZ <= 0 then
				return nil, nil
			end
			local viewportWidth = camera.X
		end,
	}
end
modules.enclose = function()
	return {
		enclose = function(minPoint, maxPoint)
			local width = maxPoint.X - minPoint.X
			local height = maxPoint.Y - minPoint.Y
			if not (0 < width) then
				return nil, nil
			end
			if not (0 < height) then
				return nil, nil
			end
			if not (width < math.huge) then
				return nil, nil
			end
			if not (height < math.huge) then
				return nil, nil
			end
			local center = (minPoint + maxPoint) * 0.5
			if not (math.abs(center.X) < math.huge) then
				return nil, nil
			end
			if not (math.abs(center.Y) < math.huge) then
				return nil, nil
			end
			local scale = math.ceil(math.max((width + 2) / 1, (height + 2) / 2))
			local size = Vector2.new(1 * scale, 2 * scale)
			if not (0 < size.X) then
				return nil, nil
			end
			if not (0 < size.Y) then
				return nil, nil
			end
			if not (size.X < math.huge) then
				return nil, nil
			end
			if not (size.Y < math.huge) then
				return nil, nil
			end
			local topLeft = center - size * 0.5
			return Vector2.new(math.floor(topLeft.X), math.floor(topLeft.Y)), size
		end,
	}
end
modules.start = function()
	local settings = modules.settings()
