			local snapshot = mod_current.current()
			if not snapshot then
				return
			end
			local espByObject = {}
			local entryByObject = {}
			local function removeEntry(entry)
				if entryByObject[entry.object] ~= entry then
					return
				end
				entryByObject[entry.object] = nil
				local esp = espByObject[entry.object]
				espByObject[entry.object] = nil
				if esp then
					esp.destroy()
				end
			end
			scope:add(snapshot.removed:connect(function(entry)
				if not scope:isDestroyed() then
					removeEntry(entry)
				end
			end))
			scope:add(function()
				for _, esp in espByObject do
