				end
				table.clear(espByObject)
				table.clear(entryByObject)
			end)
			local accumulator = 0.1
			scope:add(services.RunService.Heartbeat:Connect(function(deltaTime)
				accumulator = accumulator + deltaTime
				if accumulator < 0.1 then
					return
				end
				accumulator = 0
				for object, entry in snapshot.entries do
					if entry.kind ~= "Players" and not espByObject[object] then
						espByObject[object] = mod_new.new(removeEntry, entry)
						entryByObject[object] = entry
					end
				end
				local espEnabled = settings.bool(false, "Visual", "ESP", "Enabled") and isActive.isActive() and settings.bool(true, "Visual", "ESP", "Urban Reload", "Enabled")
				local nameColors = configRead.current()
				for _, esp in espByObject do
					esp.update(nameColors, espEnabled)
				end
			end))
		end,
	}
end
