					local currentCamera = services.Workspace.CurrentCamera
					if not isEnabled then
						billboardGui.Enabled = false
						return
					end
					if not position then
						billboardGui.Enabled = false
						return
					end
					if not currentCamera then
						billboardGui.Enabled = false
						return
					end
					if not espDistance.esp(entry.kind, "Enabled", true) then
						billboardGui.Enabled = false
						return
					end
					local magnitude = (position - currentCamera.CFrame.Position).Magnitude
					if espDistance.distance(entry.kind) < magnitude then
						billboardGui.Enabled = false
						return
					end
					local details, textColor, visible = mod_describe.describe(entry, colors.nameColor)
					local labelColor = textColor
					local labelText = details
					if not visible then
						billboardGui.Enabled = false
					end
					if espDistance.esp(entry.kind, "Distance", true) then
						labelText = labelText .. "\n" .. mod_number.number(magnitude) .. " studs"
					end
					if entry.kind == "NPCs" then
						local subject = targeting.subject()
						if subject == entry.model then
							labelColor = colors.targetColor
						end
					end
					text.Text = labelText
					text.TextColor3 = labelColor
					if worldPosition then
						worldPosition.WorldPosition = position
						billboardGui.Adornee = worldPosition
					end
					local rootPart = entry.root
					if not rootPart then
						billboardGui.Enabled = false
						return
					end
					billboardGui.Adornee = rootPart
				end,
				destroy = function()
					uiScope:destroy()
				end,
			}
		end,
	}
end
modules.watch = function()
	modules.currentGame()
	local mod_alive = modules.unnamed_c_()
	local scope = modules.scope()
	local mod_aRMOR_CAPACITY_50 = modules.unnamed_c0()
	return {
		watch = function(parentScope, character, tracker)
			local currentHumanoid
			local healthScope
			local function updateArmor()
				local armorValue = math.max(0, mod_aRMOR_CAPACITY_50.number(character, "Armor", 0))
				tracker.armor(armorValue / mod_aRMOR_CAPACITY_50.ARMOR_CAPACITY, armorValue)
			end
			local function refreshHumanoid()
				local humanoid = character:FindFirstChildOfClass("Humanoid")
				if humanoid == currentHumanoid then
					return
				end
				if healthScope then
					healthScope:destroy()
					healthScope = nil
				end
				currentHumanoid = humanoid
				if humanoid then
					local humanoidScope = scope.new()
					healthScope = humanoidScope
					local function onHealthChanged()
						local health, maxHealth = mod_alive.read(character, humanoid)
						if health and maxHealth then
							tracker.health(health / maxHealth, health)
						else
							tracker.health(0, 0)
						end
					end
					humanoidScope:add(humanoid.HealthChanged:Connect(onHealthChanged))
					humanoidScope:add(humanoid:GetPropertyChangedSignal("MaxHealth"):Connect(onHealthChanged))
					onHealthChanged()
				else
					tracker.health(0, 0)
				end
			end
			parentScope:add(function()
				if healthScope then
					healthScope:destroy()
				end
			end)
			parentScope:add(character.ChildAdded:Connect(refreshHumanoid))
			parentScope:add(character.ChildRemoved:Connect(refreshHumanoid))
			parentScope:add(character:GetAttributeChangedSignal("Armor"):Connect(updateArmor))
			refreshHumanoid()
			updateArmor()
		end,
	}
end
