modules.new = function()
	local mod_new = modules.new()
	local mod_turn = modules.turn()
	local settings = modules.settings()
	modules.currentGame()
	modules.scope()
	local services = modules.services()
	local mod_adapter = modules.unnamed_dl()
	return {
		new = function(scope)
			local localPlayer = services.Players.LocalPlayer
			local mobile = mod_new.new(scope)
			local status = "waiting for native camera"
			local function checkReady(character)
				if scope:isDestroyed() then
					return "aim controller closed"
				end
				if settings.string("Camera", "Combat", "AimAssist", "Method") ~= "Camera" then
					return "native mouse input unavailable"
				end
				if not character then
					return "native weapon not ready"
				end
				if character ~= localPlayer.Character then
					return "native weapon not ready"
				end
				if not mod_adapter.ready(character) then
					return "native weapon not ready"
				end
				if not mod_adapter.equipped(character) then
					return "native weapon not ready"
				end
				local currentCamera = services.Workspace.CurrentCamera
				local humanoid = character:FindFirstChildOfClass("Humanoid")
				if not currentCamera then
					return "native player camera unavailable"
				end
				if currentCamera.CameraType ~= Enum.CameraType.Custom then
					return "native player camera unavailable"
				end
				if currentCamera.CameraSubject ~= humanoid then
					return "native player camera unavailable"
				end
				local mobileAvailable = mobile.mobile()
				if mobileAvailable == nil then
					return "mobile controls unavailable"
				end
				local cameraMode
				if localPlayer.CameraMode ~= Enum.CameraMode.LockFirstPerson then
					if (currentCamera.CFrame.Position - currentCamera.Focus.Position).Magnitude < 1 then
						cameraMode = "First Person"
					elseif mobileAvailable then
						cameraMode = "Shift Locked"
					else
						cameraMode = "Third Person"
						if services.UserInputService.MouseBehavior == Enum.MouseBehavior.LockCenter then
							cameraMode = "Shift Locked"
						end
					end
				else
					cameraMode = "First Person"
				end
				if settings.bool(true, "Combat", "AimAssist", "Checks", cameraMode) then
					return nil
				end
				return "camera mode excluded"
			end
			return {
				priority = Enum.RenderPriority.Camera.Value + 1,
				prepare = function() end,
				ready = function(character)
					status = checkReady(character)
					return status == nil
				end,
				steer = function(pitch, yaw, state, character)
					status = checkReady(localPlayer.Character)
					if status then
						return false
					end
					if character then
						return false
					end
					local camera = services.Workspace.CurrentCamera
					local direction = mobile.direction(camera)
					if direction then
						local targetCFrame = mod_turn.turn(camera.CFrame, direction, pitch, yaw)
						if targetCFrame then
							camera.CFrame = targetCFrame
							return true
						end
					end
					status = "native aim ray unavailable"
					return false
				end,
				release = function() end,
				status = function()
					status = checkReady(localPlayer.Character)
					return status
				end,
			}
		end,
	}
end
modules.new = function()
	local scope = modules.scope()
	local services = modules.services()
	local defaultColor = Color3.fromRGB(85, 170, 255)
	local function observeChild(parentScope, root, childName, onChange)
		local nameConnections = {}
		local currentChild, childScope
		local function refresh()
			if childScope:isDestroyed() then
				return
			end
			local child = root:FindFirstChild(childName)
			if child == currentChild then
				return
			end
			local previousScope = childScope
			childScope = nil
			currentChild = child
			if previousScope then
				previousScope:destroy()
			end
			if not child then
				onChange(nil, nil)
				return
			end
			childScope = scope.new()
			onChange(child, childScope)
		end
		local function onChildAdded(child)
			if childScope:isDestroyed() then
				return
			end
			if child.Parent ~= root then
				return
			end
			if not nameConnections[child] then
				nameConnections[child] = child:GetPropertyChangedSignal("Name"):Connect(refresh)
			end
			refresh()
		end
		parentScope:add(function()
			if childScope then
				childScope:destroy()
			end
			for _, connection in nameConnections do
				connection:Disconnect()
			end
			table.clear(nameConnections)
			onChange(nil, nil)
		end)
		parentScope:add(root.ChildAdded:Connect(onChildAdded))
		parentScope:add(root.ChildRemoved:Connect(function(child)
			local connection = nameConnections[child]
			nameConnections[child] = nil
			if connection then
				connection:Disconnect()
			end
			refresh()
		end))
		for _, child in root:GetChildren() do
			onChildAdded(child)
		end
		refresh()
	end
	return {
		new = function(parentScope)
			local localPlayer = services.Players.LocalPlayer
			local mouse = localPlayer:GetMouse()
			local playerGui
			local mainScreen
			local bottomLeft
			local shiftLockButton
			observeChild(parentScope, localPlayer, "PlayerGui", function(gui, guiScope)
				playerGui = gui
				if not gui then
					return
				end
				if guiScope and gui:IsA("PlayerGui") then
					observeChild(guiScope, gui, "Main Screen", function(screen, screenScope)
						mainScreen = screen
						if screen and screenScope then
							observeChild(screenScope, screen, "BottomLeft", function(bottom, bottomScope)
								bottomLeft = bottom
								if bottom and bottomScope then
									observeChild(bottomScope, bottom, "MobileShiftlock", function(button)
										shiftLockButton = nil
										if button and button:IsA("ImageButton") then
											shiftLockButton = button
										end
									end)
								end
							end)
						end
					end)
				end
			end)
			local function isMobileShiftLock()
				local button = shiftLockButton
				if parentScope:isDestroyed() then
					return nil
				end
				if button and button.Parent == bottomLeft and bottomLeft and bottomLeft.Parent == mainScreen and mainScreen and mainScreen.Parent == playerGui and playerGui and playerGui.Parent == localPlayer then
					return button.ImageColor3 == defaultColor
				end
				if services.UserInputService.TouchEnabled then
					return nil
				end
				return false
			end
			return {
				mobile = isMobileShiftLock,
				ray = function(camera)
					local mode = isMobileShiftLock()
					if mode ~= nil then
						if mode then
							return Ray.new(camera.CFrame.Position, camera.CFrame.LookVector)
						end
						return mouse.UnitRay
					end
					return nil
				end,
				direction = function(camera)
					local mode = isMobileShiftLock()
					if mode == nil then
						return nil
					end
					if mode then
						return camera.CFrame.LookVector
					end
					return mouse.UnitRay.Direction
				end,
			}
		end,
	}
end
modules.turn = function()
	local maxAngle = math.rad(80)
	local fullTurn = math.pi * 2
	local function isFinite(number)
		return number == number and math.abs(number) < math.huge
	end
	local function isFiniteVector(vector)
		return isFinite(vector.X) and isFinite(vector.Y) and isFinite(vector.Z)
	end
	return {
		turn = function(object, vector, target, limit)
			if not isFiniteVector(object.Position) then
				return nil
			end
			if not isFiniteVector(vector) then
				return nil
			end
			if not isFiniteVector(target) then
				return nil
			end
			if not isFinite(limit) then
				return nil
			end
			local orientationX, orientationY, orientationZ = object:ToOrientation()
			if not isFinite(orientationX) then
				return nil
			end
			if not isFinite(orientationY) then
				return nil
			end
			if not isFinite(orientationZ) then
				return nil
			end
			local toTarget = target - object.Position
			if toTarget.Magnitude < 1e-6 then
				return nil
			end
			if vector.Magnitude < 1e-6 then
				return nil
			end
			if limit == 0 then
				return object
			end
			local adjusted = CFrame.Angles(0, 0, orientationZ):VectorToWorldSpace(object:VectorToObjectSpace(vector.Unit))
			local planarLength = math.sqrt(adjusted.Y * adjusted.Y + adjusted.Z * adjusted.Z)
			if planarLength < 1e-6 then
				return nil
			end
			if 0 <= adjusted.Z then
				return nil
			end
			local unit = toTarget.Unit
			local pitch = math.asin(math.clamp(unit.Y / planarLength, -1, 1))
			local currentPitch = math.atan2(adjusted.Y, -adjusted.Z)
			local pitchDelta = math.clamp(pitch - currentPitch, -limit, limit)
			local adjustedZ = adjusted.Y * math.sin(pitchDelta) + adjusted.Z * math.cos(pitchDelta)
			local yawDelta = (math.atan2(-unit.X, -unit.Z) - math.atan2(-adjusted.X, -adjustedZ) - orientationY + math.pi) % fullTurn - math.pi
			local blend = math.clamp(limit, -1, 2)
			local targetCFrame = CFrame.fromOrientation(math.clamp(orientationX + (pitchDelta - orientationX) * blend, -limit, limit), orientationY + yawDelta * blend, orientationZ)
			return CFrame.new(object.Position) * targetCFrame
		end,
	}
end
modules.unnamed_dl = function()
	modules.hoodGame()
	local mod_data = modules.unnamed_dj()
	local services = modules.services()
	local urbanRules = modules.urbanRules()
	local gunNames = {}
	gunNames["[Revolver]"] = true
	gunNames["[DoubleBarrel]"] = true
	gunNames["[Shotgun]"] = true
	gunNames["[Silencer]"] = true
	gunNames["[TacticalShotgun]"] = true
	gunNames["[SMG]"] = true
	gunNames["[Flintlock]"] = true
	local equipped = {}
	local function isFinite(number)
		return number == number and math.abs(number) < math.huge
	end
	local function readNumber(root, name)
		local numberValue = root:FindFirstChild(name)
		if numberValue and (numberValue:IsA("NumberValue") or numberValue:IsA("IntValue")) then
			local number = numberValue.Value
			if isFinite(number) then
				return number
			end
		end
		return nil
	end
	local function readAmmo(tool)
		if gunNames[tool.Name] then
			local gunData = tool:FindFirstChild("GunData") or mod_data.data(tool)
			local toolScript = tool:FindFirstChild("Script")
			local handle = tool:FindFirstChild("Handle")
			if not gunData then
				return nil
			end
			if not gunData:IsA("ModuleScript") then
				return nil
			end
			if not toolScript then
				return nil
			end
			if not toolScript:IsA("Script") then
				return nil
			end
			if not handle then
				return nil
			end
			if not handle:IsA("BasePart") then
				return nil
			end
			local ammo = toolScript:FindFirstChild("Ammo")
			local maxAmmo = readNumber(toolScript, "MaxAmmo")
			if not ammo then
				return nil
			end
			if not ammo:IsA("NumberValue") and not ammo:IsA("IntValue") then
				return nil
			end
			if not maxAmmo then
				return nil
			end
			if maxAmmo <= 0 then
				return nil
			end
			local clientAmmo = readNumber(ammo, "CLIENT")
			if clientAmmo and 0 <= clientAmmo then
				return clientAmmo
			end
		end
		return nil
	end
	equipped.equipped = function(character)
		local tool = character:FindFirstChildOfClass("Tool")
		if tool and readAmmo(tool) ~= nil then
			return tool
		end
		return nil
	end
	equipped.ready = function(character)
		return services.Players.LocalPlayer.Character == character and urbanRules.alive(character) and not urbanRules.knocked(character)
	end
	equipped.canShoot = function(character, tool)
		if services.Players.LocalPlayer.Character ~= character then
			return false
		end
		if tool.Parent ~= character then
			return false
		end
		if equipped.equipped(character) ~= tool then
			return false
		end
		if not urbanRules.canInteract(character) then
			return false
		end
		if not (tool.Name ~= "[Flintlock]" or not urbanRules.inBox(character)) then
			return false
		end
		local ammo = readAmmo(tool)
		return ammo ~= nil and ammo > 0
	end
	equipped.muzzle = function(tool)
		local handle = tool:FindFirstChild("Handle")
		if handle then
			if not handle:IsA("BasePart") then
				return nil
			end
			local muzzlePosition = handle.Position
			local muzzleOffset = handle:GetAttribute("Muzzle")
			if typeof(muzzleOffset) == "CFrame" then
				muzzlePosition = handle.CFrame * muzzleOffset.Position
			end
			if isFinite(muzzlePosition.X) and isFinite(muzzlePosition.Y) and isFinite(muzzlePosition.Z) then
				return muzzlePosition
			end
		end
		return nil
	end
	equipped.stance = function(character)
		local bodyEffects = character:FindFirstChild("BodyEffects")
		if bodyEffects then
			local reloadingCLIENT = bodyEffects:FindFirstChild("Reloading_CLIENT")
			if reloadingCLIENT then
				if reloadingCLIENT:IsA("BoolValue") and reloadingCLIENT.Value then
					return "Reloading"
				end
				local attackingCLIENT = bodyEffects:FindFirstChild("Attacking_CLIENT")
				if attackingCLIENT and attackingCLIENT:IsA("BoolValue") and attackingCLIENT.Value then
					return "Shooting"
				end
				return "Normal"
			end
		end
		if bodyEffects then
			local attackingCLIENT = bodyEffects:FindFirstChild("Attacking_CLIENT")
			if attackingCLIENT and attackingCLIENT:IsA("BoolValue") and attackingCLIENT.Value then
				return "Shooting"
			end
		end
		return "Normal"
	end
	local isReady = { name = "HoodCustoms", equipped = equipped.equipped }
	isReady.isReady = equipped.ready
	isReady.isKnocked = urbanRules.knocked
	isReady.isAlly = urbanRules.ally
	isReady.stance = equipped.stance
	isReady.canShoot = equipped.canShoot
	isReady.activate = function(activate)
		activate:Activate()
	end
	isReady.deactivate = function(deactivate)
		deactivate:Deactivate()
	end
	isReady.muzzle = equipped.muzzle
	isReady.isSilentReady = function()
		local character = services.Players.LocalPlayer.Character
		if character then
			character = equipped.equipped(character)
		end
		return character ~= nil and mod_data.owns(character)
	end
	equipped.adapter = isReady
	return equipped
end
modules.unnamed_dj = function()
	modules.scope()
	local services = modules.services()
	local records = {}
	local get = {}
	get.get = function(instance)
		return records[instance]
	end
	get.set = function(instance, record)
		records[instance] = record
	end
	get.owns = function(tool)
		local record = records[tool]
		local owns = record ~= nil
		if record ~= nil then
			owns = record.ready
			if owns then
				owns = tool.Name == record.name
				if tool.Name == record.name then
					local ownerDestroyed = record.owner:isDestroyed()
					owns = not ownerDestroyed
					if not ownerDestroyed then
						owns = record.data.Parent == record.holder
						if record.data.Parent == record.holder then
							owns = record.data.Name == "GunData"
							if record.data.Name == "GunData" then
								owns = tool:FindFirstChild("GunData") == nil
								if owns then
									return null_stub(0.5, unpack(owns, 1, owns.n))
								end
							end
						end
					end
				end
			end
		end
		return owns
	end
	get.data = function(instance)
		local record = records[instance]
		if record and get.owns(instance) then
			return record.data
		end
		return nil
	end
	return get
end
modules.urbanRules = function()
	local services = modules.services()
	local inBox = {}
	local function isFiniteNumber(number)
		return number == number and math.abs(number) < math.huge
	end
	local function getBodyEffects(character)
		local bodyEffects = character:FindFirstChild("BodyEffects")
		if bodyEffects and bodyEffects:IsA("Folder") then
			return bodyEffects
		end
		return nil
	end
	local function readNumberValue(root, name)
		if root then
			local numberValue = root:FindFirstChild(name)
			if numberValue and (numberValue:IsA("NumberValue") or numberValue:IsA("IntValue")) then
				local number = numberValue.Value
				if isFiniteNumber(number) then
					return number
				end
			end
		end
		return nil
	end
	local function readBoolValue(root, name)
		if root then
			local boolValue = root:FindFirstChild(name)
			if boolValue and boolValue:IsA("BoolValue") then
				return boolValue.Value
			end
		end
		return nil
	end
	local function findWorkspaceChild(name)
		local players = services.Workspace:FindFirstChild("Players")
		if players then
			return players:FindFirstChild(name)
		end
		return players
	end
	inBox.inBox = function(character)
		local inBoxFolder = findWorkspaceChild("InBox")
		return inBoxFolder ~= nil and character:IsDescendantOf(inBoxFolder)
	end
	inBox.playable = function(character)
		local charactersFolder = findWorkspaceChild("Characters")
		if not (charactersFolder and character:IsDescendantOf(charactersFolder)) then
			return "FindFirstChild", "cframe"
		end
		local fullyloadedchar = character:FindFirstChild("FULLY_LOADED_CHAR")
		local rootPart = character:FindFirstChild("HumanoidRootPart")
