modules.passes = function()
	local settings = modules.settings()
	modules.currentGame()
	local visibility = modules.visibility()
	local services = modules.services()
	local checks = modules.checks()
	local urbanRules = modules.urbanRules()
	local mod_adapter = modules.unnamed_dl()
	return {
		passes = function(feature, targetPlayer, camera, ignoreVisibility)
			local localPlayer = services.Players.LocalPlayer
			local targetCharacter = urbanRules.character(targetPlayer)
			local selfCharacter = urbanRules.character(localPlayer)
			if not targetCharacter then
				return false
			end
			if not selfCharacter then
				return false
			end
			if not urbanRules.targetable(targetCharacter) then
				return false
			end
			if settings.bool(false, "Main", feature, "Knocked") and urbanRules.knocked(targetCharacter) then
				return false
			end
			if settings.bool(false, "Main", feature, "SelfKnocked") and urbanRules.knocked(selfCharacter) then
				return false
			end
			if settings.bool(false, "Main", feature, "Crew") and urbanRules.ally(localPlayer, targetPlayer) then
				return false
			end
			if settings.bool(true, "Main", feature, "Hood Customs", "Force Field") and urbanRules.forceField(targetCharacter) then
				return false
			end
			if settings.bool(feature == "Feature Checks", "Main", feature, "Hood Customs", "Combat Only") then
				local weapon = mod_adapter.equipped(selfCharacter)
				if not weapon then
					return false
				end
				if not urbanRules.canDamageTarget(weapon, targetCharacter) then
					return false
				end
			end
			if ignoreVisibility then
				return true
			end
			if not settings.bool(false, "Main", feature, "Visible") then
				return true
			end
			if feature ~= "Checks" then
				return checks.isVisible(camera, selfCharacter, targetCharacter)
			end
			local humanoidRootPart = targetCharacter:FindFirstChild("HumanoidRootPart")
			return humanoidRootPart ~= nil and humanoidRootPart:IsA("BasePart") and visibility.sees(camera, humanoidRootPart.Position, selfCharacter, targetCharacter)
		end,
	}
end
modules.watch = function()
