modules.unnamed_dp = function()
	local finite = {}
	finite.finite = function(number)
		return number == number and math.abs(number) < math.huge
	end
	finite.number = function(root, name)
		if root then
			local numberValue = root:FindFirstChild(name)
			if numberValue and (numberValue:IsA("NumberValue") or numberValue:IsA("IntValue")) then
				local number = numberValue.Value
				if finite.finite(number) then
					return number
				end
			end
		end
		return nil
	end
	finite.effects = function(character)
		local bodyEffects = character:FindFirstChild("BodyEffects")
		if character.Parent and bodyEffects and bodyEffects:IsA("Folder") then
			return bodyEffects
		end
		return nil
	end
	finite.knocked = function(character)
		local bodyEffects = finite.effects(character)
		if bodyEffects then
			local ko = bodyEffects:FindFirstChild("K.O")
			if ko and ko:IsA("BoolValue") then
				return ko.Value
			end
		end
		return nil
	end
	finite.preview = function(character, health, damage)
		local parent = character.Parent
		local armor = finite.number(character, "Armor")
		local ko = character:FindFirstChild("K.O")
		if not (parent and armor) then
			return nil, false, false
		end
		if not ko then
			return nil, false, false
		end
		if not ko:IsA("BoolValue") then
			return nil, false, false
		end
		if not finite.finite(health) then
			return nil, false, false
		end
		if not finite.finite(damage) then
			return nil, false, false
		end
		if damage < 0 then
			return nil, false, false
		end
		if ko.Value or parent:FindFirstChild("GRABBING_CONSTRAINT") then
			if health - damage < 0.5 then
				return health, false, false
			end
			if 0 < armor then
				return health - damage / 10, false, true
			end
		else
			if 0 < armor then
				damage = damage / 10
			end
			if health - damage <= 5 then
				return 0.5, true, true
			end
		end
		return health - damage, false, true
	end
	return finite
end
modules.start = function()
	local scope = modules.scope()
	local function observeChildren(parentScope, root, callback, watchValues)
		local childScopes = {}
		local function removeChild(child)
			local childScope = childScopes[child]
			childScopes[child] = nil
			if childScope then
				childScope:destroy()
			end
		end
		local function addChild(child)
			if parentScope:isDestroyed() then
				return
			end
			if child.Parent ~= root then
				return
			end
			if childScopes[child] then
				return
			end
			local childScope = scope.new()
			childScopes[child] = childScope
			childScope:add(child:GetPropertyChangedSignal("Name"):Connect(callback))
			if watchValues and (child:IsA("NumberValue") or child:IsA("IntValue")) then
				childScope:add(child:GetPropertyChangedSignal("Value"):Connect(callback))
			end
		end
		parentScope:add(function()
			for child in childScopes do
				removeChild(child)
			end
		end)
		parentScope:add(root.ChildAdded:Connect(function(child)
			addChild(child)
			callback()
		end))
		parentScope:add(root.ChildRemoved:Connect(function(child)
			removeChild(child)
			callback()
		end))
		for _, child in root:GetChildren() do
			addChild(child)
		end
	end
	return {
		start = function(parentScope, character, callback)
			local function onAncestryChanged()
				if not parentScope:isDestroyed() then
					callback()
				end
			end
			local bodyEffectsFolder, effectsScope
			local function refresh()
				if parentScope:isDestroyed() then
					return
				end
				local bodyEffects = character:FindFirstChild("BodyEffects")
				local folder = nil
				if bodyEffects then
					if bodyEffects:IsA("Folder") then
						folder = bodyEffects
					end
				end
				if folder ~= bodyEffectsFolder then
					local previousScope = effectsScope
					effectsScope = nil
					bodyEffectsFolder = folder
					if previousScope then
						previousScope:destroy()
					end
					if not folder then
						onAncestryChanged()
						return
					end
					local newScope = scope.new()
					effectsScope = newScope
					observeChildren(newScope, folder, onAncestryChanged, true)
				end
				onAncestryChanged()
			end
			parentScope:add(function()
				if not effectsScope then
					return
				end
				effectsScope:destroy()
				effectsScope = nil
			end)
			parentScope:add(character.AncestryChanged:Connect(onAncestryChanged))
			observeChildren(parentScope, character, refresh, false)
			refresh()
		end,
	}
end
modules.watch = function()
	local scope = modules.scope()
	local function isFiniteNumber(number)
		return number == number and math.abs(number) < math.huge
	end
	local function readNumberValue(root, name)
		if root then
			local numberValue = root:FindFirstChild(name)
			if numberValue and (numberValue:IsA("NumberValue") or numberValue:IsA("IntValue")) then
				local number = numberValue.Value
				if isFiniteNumber(number) then
					return number
				end
			end
		end
		return nil
	end
	local function observeChildren(parentScope, root, callback, watchValues)
		local childScopes = {}
		local function removeChild(child)
			local childScope = childScopes[child]
			childScopes[child] = nil
			if childScope then
				childScope:destroy()
			end
		end
		local function addChild(child)
			if parentScope:isDestroyed() then
				return
			end
			if child.Parent ~= root then
				return
			end
			if childScopes[child] then
				return
			end
			local childScope = scope.new()
			childScopes[child] = childScope
			childScope:add(child:GetPropertyChangedSignal("Name"):Connect(callback))
			if watchValues and (child:IsA("NumberValue") or child:IsA("IntValue")) then
				childScope:add(child:GetPropertyChangedSignal("Value"):Connect(callback))
			end
		end
		parentScope:add(function()
			for child in childScopes do
				removeChild(child)
			end
		end)
		parentScope:add(root.ChildAdded:Connect(function(child)
			addChild(child)
			callback()
		end))
		parentScope:add(root.ChildRemoved:Connect(function(child)
			removeChild(child)
			callback()
		end))
		for _, child in root:GetChildren() do
			addChild(child)
		end
	end
	return {
		watch = function(parentScope, character, tracker)
			if parentScope:isDestroyed() then
				return
			end
			local bodyEffectsFolder, effectsScope
			local function onAncestryChanged()
				if parentScope:isDestroyed() then
					return
				end
				local folder = bodyEffectsFolder
				if character.Parent and folder and folder.Parent == character then
					local healthValue = readNumberValue(folder, "Health_CLIENT")
					local maxHealth = readNumberValue(folder, "MaxHealth")
					if healthValue ~= nil and maxHealth ~= nil and not (maxHealth <= 0) then
						local clamped = math.clamp(healthValue, 0, maxHealth)
						tracker.health(clamped / maxHealth, clamped)
						return
					end
					tracker.health(0, 0)
					if parentScope:isDestroyed() then
						return
					end
					local armorValue = readNumberValue(folder, "Armor")
					if armorValue ~= nil then
						local clampedArmor = math.clamp(armorValue, 0, 200)
						tracker.armor(clampedArmor / 200, clampedArmor)
					else
						tracker.armor(0, 0)
					end
				else
					tracker.health(0, 0)
					if not parentScope:isDestroyed() then
						tracker.armor(0, 0)
					end
				end
			end
			local function refresh()
				if parentScope:isDestroyed() then
					return
				end
				local bodyEffects = character:FindFirstChild("BodyEffects")
				local folder = nil
				if bodyEffects then
					if bodyEffects:IsA("Folder") then
						folder = bodyEffects
					end
				end
				if folder ~= bodyEffectsFolder then
					local previousScope = effectsScope
					effectsScope = nil
					bodyEffectsFolder = folder
					if previousScope then
						previousScope:destroy()
					end
					if not folder then
						onAncestryChanged()
						return
					end
					local newScope = scope.new()
					effectsScope = newScope
					observeChildren(newScope, folder, onAncestryChanged, true)
				end
				onAncestryChanged()
			end
			parentScope:add(function()
				local previousScope = effectsScope
				effectsScope = nil
				bodyEffectsFolder = nil
				if previousScope then
					previousScope:destroy()
				end
			end)
			parentScope:add(character.AncestryChanged:Connect(onAncestryChanged))
			observeChildren(parentScope, character, refresh, false)
			refresh()
		end,
	}
end
