			local bulletRays = replicatedStorage:FindFirstChild("BULLET_RAYS")
			local bulletDeflect = replicatedStorage:FindFirstChild("BulletDeflect")
			local hitSound = replicatedStorage:FindFirstChild("HitSound")
			local flintlockExplosion = replicatedStorage:FindFirstChild("FlintlockExplosion")
			local bloodParticle = replicatedStorage:FindFirstChild("Assets")
			if bloodParticle then
				bloodParticle = bloodParticle:FindFirstChild("Particles")
				if bloodParticle then
					bloodParticle = bloodParticle:FindFirstChild("BloodParticle")
					if mainModule then
						if not mainModule:IsA("ModuleScript") then
							return nil
						end
						if not ignored then
							return nil
						end
						if not bulletRays then
							return nil
						end
						if not bulletRays:IsA("BasePart") then
							return nil
						end
						if not bulletDeflect then
							return nil
						end
						if not bulletDeflect:IsA("Sound") then
							return nil
						end
						if not hitSound then
							return nil
						end
						if not hitSound:IsA("Sound") then
							return nil
						end
						if not flintlockExplosion then
							return nil
						end
						if not flintlockExplosion:IsA("BasePart") then
							return nil
						end
						if not bloodParticle then
							return nil
						end
						if not bloodParticle:IsA("BasePart") then
							return nil
						end
						local startAttachment = bulletRays:FindFirstChild("START_ATTACHMENT")
						local endAttachment = bulletRays:FindFirstChild("END_ATTACHMENT")
						local gunBeam = bulletRays:FindFirstChild("GunBeam")
						if startAttachment and startAttachment:IsA("Attachment") and endAttachment and endAttachment:IsA("Attachment") and gunBeam and gunBeam:IsA("Beam") then
							return {
								storage = replicatedStorage,
								world = workspace,
								main = mainModule,
								ignored = ignored,
								rays = bulletRays,
								deflect = bulletDeflect,
								hit = hitSound,
								blood = bloodParticle,
								flintlock = flintlockExplosion,
							}
						end
					end
					return nil
				end
			end
			if mainModule then
				if not mainModule:IsA("ModuleScript") then
					return nil
				end
				if not ignored then
					return nil
				end
				if not bulletRays then
					return nil
				end
				if not bulletRays:IsA("BasePart") then
					return nil
				end
				if not bulletDeflect then
					return nil
				end
				if not bulletDeflect:IsA("Sound") then
					return nil
				end
				if not hitSound then
					return nil
				end
				if not hitSound:IsA("Sound") then
					return nil
				end
				if not flintlockExplosion then
					return nil
				end
				if not flintlockExplosion:IsA("BasePart") then
					return nil
				end
				if not bloodParticle then
					return nil
				end
				if not bloodParticle:IsA("BasePart") then
					return nil
				end
				local startAttachment = bulletRays:FindFirstChild("START_ATTACHMENT")
				local endAttachment = bulletRays:FindFirstChild("END_ATTACHMENT")
				local gunBeam = bulletRays:FindFirstChild("GunBeam")
				if startAttachment and startAttachment:IsA("Attachment") and endAttachment and endAttachment:IsA("Attachment") and gunBeam and gunBeam:IsA("Beam") then
					return {
						storage = replicatedStorage,
						world = workspace,
						main = mainModule,
						ignored = ignored,
						rays = bulletRays,
						deflect = bulletDeflect,
						hit = hitSound,
						blood = bloodParticle,
						flintlock = flintlockExplosion,
					}
				end
			end
			return nil
		end,
	}
end
modules.new = function()
	local services = modules.services()
	local specialSkins = {}
	specialSkins.Arctic = true
	specialSkins["Blacksteel Dragon"] = true
	specialSkins["Black Cat"] = true
	specialSkins.Cupid = true
	local function findStringValue(parent, name)
		if parent then
			local child = parent:FindFirstChild(name)
			if child and child:IsA("StringValue") then
				return child
			end
		end
		return nil
	end
	local function decodeJson(text)
		local ok, decoded = pcall(services.HttpService.JSONDecode, services.HttpService, text)
		if ok and type(decoded) == "table" then
			return decoded
		end
		return nil
	end
	return {
		new = function(tool)
			local cachedBeamsRaw = ""
			local cachedEquippedRaw = ""
			local equippedMap = {}
			local beamsByName = {}
			local cachedSelected, cachedEquippedMap
			return {
				get = function(weaponName, fallbackSkin)
					local dataFolder = tool:FindFirstChild("DataFolder")
					local inventoryData
					if dataFolder then
						inventoryData = dataFolder:FindFirstChild("InventoryData")
					else
						inventoryData = dataFolder
					end
					local equippedValue = findStringValue(dataFolder, "EquippedBulletBeams")
					local beamsValue = findStringValue(inventoryData, "BulletBeams")
					local equippedRaw = ""
					if equippedValue then
						equippedRaw = equippedValue.Value
					end
					local beamsRaw = ""
					if beamsValue then
						beamsRaw = beamsValue.Value
					end
					local selectedEquipped
					if not (equippedValue == beamsRaw and equippedRaw == equippedValue) then
						selectedEquipped = equippedValue
						table.clear(equippedMap)
						local decoded = decodeJson(equippedRaw)
						if decoded then
							for name, entry in decoded do
								if type(name) == "string" then
									if type(entry) ~= "string" then
										if type(entry) == "number" then
											equippedMap[name] = entry
										end
									else
										equippedMap[name] = entry
									end
								end
							end
						end
					end
					if equippedMap ~= cachedEquippedMap or selectedEquipped ~= cachedSelected then
						cachedEquippedMap = equippedMap
						cachedSelected = selectedEquipped
						table.clear(beamsByName)
						local decodedBeams = decodeJson(beamsRaw)
						if not decodedBeams then
							local mappedName = equippedMap[weaponName]
							if mappedName ~= nil and beamsByName[mappedName] ~= nil then
								local skinName = beamsByName[mappedName]
								if skinName ~= "None" then
									return skinName
								end
							end
							if specialSkins[fallbackSkin] then
								return fallbackSkin
							end
							return "None"
						end
						local iterator = coroutine.wrap(lph_generic_for)
						iterator(decodedBeams, nil, nil)
						local active, key, object = iterator()
						if active then
							local currentKey = key
							local currentObject = object
							while type(currentObject) ~= "table" do
								local more, nextKey, nextObject = iterator()
								if more then
									currentKey = nextKey
									currentObject = nextObject
									continue
								end
								local mappedName = equippedMap[weaponName]
								if mappedName ~= nil and beamsByName[mappedName] ~= nil then
									local skinName = beamsByName[mappedName]
									if skinName ~= "None" then
										return skinName
									end
								end
								if specialSkins[fallbackSkin] then
									return fallbackSkin
								end
								return "None"
							end
							repeat
								local name = currentObject.Name
								if type(name) == "string" then
									beamsByName[currentKey] = name
								end
								repeat
									local more, nextKey, nextObject = iterator()
									if not more then
										cachedEquippedMap = -1
										break
									end
									currentKey = nextKey
									currentObject = nextObject
								until type(currentObject) == "table"
							until cachedEquippedMap == -1
						end
					end
					local mappedName = equippedMap[weaponName]
					if mappedName ~= nil and beamsByName[mappedName] ~= nil then
						local skinName = beamsByName[mappedName]
						if skinName ~= "None" then
							return skinName
						end
					end
					if specialSkins[fallbackSkin] then
						return fallbackSkin
					end
					return "None"
				end,
			}
		end,
	}
end
modules.new = function()
	local scope = modules.scope()
	local mod_delay = modules.unnamed_dz()
	local services = modules.services()
	local cellOffsets = {}
	local topLeft = Vector2.new(0, 0)
	local topRight = Vector2.new(512, 0)
	local bottomLeft = Vector2.new(0, 512)
	local packed = table.pack(Vector2.new(512, 512))
	cellOffsets[1] = topLeft
	cellOffsets[2] = topRight
	cellOffsets[3] = bottomLeft
	table.move(packed, 1, packed.n, 4, cellOffsets)
	return {
		new = function(ownerScope)
			local animations = {}
			local function addAnimation(tool, image)
				local animationScope = scope.new()
				local function onDestroying()
					animationScope:destroy()
				end
				ownerScope:add(onDestroying)
				local tweenService = services.TweenService
				local function schedule(delaySeconds, callback)
					mod_delay.delay(animationScope, delaySeconds, callback)
				end
				local entry = {
					image = image,
					count = 0,
					playing = false,
					cell = Random.new():NextInteger(1, #cellOffsets),
					close = onDestroying,
					dead = function()
						return animationScope:isDestroyed()
					end,
					spawn = function(taskFn)
						mod_delay.spawn(animationScope, taskFn)
					end,
					delay = schedule,
				}
				entry.pre = (not not entry)(schedule, image, TweenInfo.new(0.1), { ImageTransparency = 0.45, Size = UDim2.fromScale(0.25, 0.25) })
				entry.preOut = tweenService:Create(image, TweenInfo.new(0.1), { ImageTransparency = 1, Size = UDim2.fromScale(0, 0) })
				entry.main = tweenService:Create(image, TweenInfo.new(0.125), { ImageTransparency = 0.45, Size = UDim2.fromScale(1, 1) })
				entry.mainOut = tweenService:Create(image, TweenInfo.new(0.125), { ImageTransparency = 1 })
				animations[tool] = entry
				animationScope:add(entry.pre)
				animationScope:add(entry.preOut)
				animationScope:add(entry.main)
				animationScope:add(entry.mainOut)
				animationScope:add(function()
					animations[tool] = nil
					ownerScope:forget(onDestroying)
				end)
				animationScope:add(tool.Destroying:Connect(function()
					animationScope:destroy()
				end))
				animationScope:add(image.Destroying:Connect(onDestroying))
				return entry
			end
			return function(tool)
				local handle = tool:FindFirstChild("Handle")
				if ownerScope:isDestroyed() then
					return
				end
				if not handle then
					return
				end
				local particleFolder = handle:FindFirstChild("SHOOT_BBGUI_PARTICLE")
				if particleFolder then
					for _, emitter in particleFolder:GetChildren() do
						if not emitter:IsA("ParticleEmitter") then
							continue
						end
						local defaultEmit = 1
						local emitCount = emitter:GetAttribute("EmitCount")
						if type(emitCount) ~= "number" then
							emitCount = defaultEmit
						end
						emitter:Emit(emitCount)
					end
				end
				local shootBBGUI = handle:FindFirstChild("ShootBBGUI")
				if shootBBGUI then
					local shoot = shootBBGUI:FindFirstChild("Shoot")
					if shoot then
						if not shoot:IsA("ImageLabel") then
							return
						end
						local existing = animations[tool]
						if existing then
							if existing.image == shoot then
								existing.count = math.min(existing.count + 0.6, 1)
								if existing.pre.PlaybackState == Enum.PlaybackState.Playing then
									existing.pre:Cancel()
								end
								if existing.preOut.PlaybackState == Enum.PlaybackState.Playing then
									existing.preOut:Cancel()
								end
								if existing.main.PlaybackState == Enum.PlaybackState.Playing then
									existing.main:Cancel()
								end
								if existing.mainOut.PlaybackState == Enum.PlaybackState.Playing then
									existing.mainOut:Cancel()
								end
								shoot.Size = UDim2.fromScale(0, 0)
								shoot.ImageTransparency = 1
								if not existing.playing then
									existing.playing = true
									local anim = existing
									anim.spawn(function()
										local current = anim
										while true do
											current.count = current.count - 0.015
											task.wait(0.015)
											if current.count <= 0 or current.dead() then
												break
											end
											current = current
										end
										current.playing = false
									end)
									if 0.6 < anim.count then
										return
									end
									anim.delay(0.1, function()
										if anim.dead() then
											return
										end
										if not shoot.Parent then
											return
										end
										local cellData, cellIndex, cellCount
										repeat
											cellData = anim
											cellIndex = anim.cell
											cellCount = #cellOffsets
										until true
										cellData.cell = cellIndex % cellCount + 1
										shoot.ImageRectOffset = cellOffsets[anim.cell]
										shoot.Size = UDim2.fromScale(0, 0)
										shoot.ImageTransparency = 1
										anim.pre:Play()
										anim.delay(0.1, function()
											if anim.dead() then
												return
											end
											if anim.main.PlaybackState == Enum.PlaybackState.Playing then
												return
											end
											if anim.mainOut.PlaybackState ~= Enum.PlaybackState.Playing then
												anim.preOut:Play()
											end
										end)
									end)
									anim.delay(0.275, function()
										if anim.dead() then
											return
										end
										while not (0.6 < anim.count) do
											anim.main:Play()
											task.wait(0.275)
											if not anim.dead() then
												if anim.main.PlaybackState == Enum.PlaybackState.Playing then
													return
												end
												if anim.mainOut.PlaybackState == Enum.PlaybackState.Playing then
													return
												end
												anim.mainOut:Play()
											end
											return
										end
									end)
								end
								return
							end
							existing.close()
						end
						local entry = addAnimation(tool, shoot)
						entry.count = math.min(entry.count + 0.6, 1)
						if entry.pre.PlaybackState == Enum.PlaybackState.Playing then
							entry.pre:Cancel()
						end
						if entry.preOut.PlaybackState == Enum.PlaybackState.Playing then
							entry.preOut:Cancel()
						end
						if entry.main.PlaybackState == Enum.PlaybackState.Playing then
							entry.main:Cancel()
						end
						if entry.mainOut.PlaybackState == Enum.PlaybackState.Playing then
							entry.mainOut:Cancel()
						end
						shoot.Size = UDim2.fromScale(0, 0)
						shoot.ImageTransparency = 1
						if entry.playing then
							return
						end
						entry.playing = true
						local anim = entry
						anim.spawn(function()
							local current = anim
							while true do
								current.count = current.count - 0.015
								task.wait(0.015)
								if current.count <= 0 or current.dead() then
									break
								end
								current = current
							end
							current.playing = false
						end)
						if 0.6 < anim.count then
							return
						end
						anim.delay(0.1, function()
							if anim.dead() then
								return
							end
							if not shoot.Parent then
								return
							end
							local cellData, cellIndex, cellCount
							repeat
								cellData = anim
								cellIndex = anim.cell
								cellCount = #cellOffsets
							until true
							cellData.cell = cellIndex % cellCount + 1
							shoot.ImageRectOffset = cellOffsets[anim.cell]
							shoot.Size = UDim2.fromScale(0, 0)
							shoot.ImageTransparency = 1
							anim.pre:Play()
							anim.delay(0.1, function()
								if anim.dead() then
									return
								end
								if anim.main.PlaybackState == Enum.PlaybackState.Playing then
									return
								end
								if anim.mainOut.PlaybackState ~= Enum.PlaybackState.Playing then
									anim.preOut:Play()
								end
							end)
						end)
						anim.delay(0.275, function()
							if anim.dead() then
								return
							end
							while not (0.6 < anim.count) do
								anim.main:Play()
								task.wait(0.275)
								if not anim.dead() then
									if anim.main.PlaybackState == Enum.PlaybackState.Playing then
										return
									end
									if anim.mainOut.PlaybackState == Enum.PlaybackState.Playing then
										return
									end
									anim.mainOut:Play()
								end
								return
							end
						end)
					end
				end
			end
		end,
	}
end
modules.unnamed_dz = function()
	local scope = modules.scope()
	return {
		new = function(parentScope, instance)
			local ownedScope = scope.new()
			local function onDestroying()
				ownedScope:destroy()
			end
			parentScope:add(onDestroying)
			ownedScope:add(function()
				parentScope:forget(onDestroying)
			end)
			ownedScope:add(instance)
			ownedScope:add(instance.Destroying:Connect(function()
				ownedScope:destroy()
			end))
			return ownedScope
		end,
		spawn = function(parentScope, callback)
			local thread = task.spawn(function()
				if not parentScope:isDestroyed() then
					callback()
				end
				parentScope:forget(coroutine.running())
			end)
			if coroutine.status(thread) ~= "dead" then
				parentScope:add(thread)
			end
		end,
		delay = function(parentScope, delaySeconds, callback)
			parentScope:add(task.delay(delaySeconds, function()
				if not parentScope:isDestroyed() then
					callback()
				end
				parentScope:forget(coroutine.running())
			end))
		end,
	}
end
modules.unnamed_dB = function()
	modules.unnamed_dx()
	modules.scope()
	local mod_delay = modules.unnamed_dz()
	local services = modules.services()
	return {
		explode = function(scope, storage, position)
			if scope:isDestroyed() then
				return
			end
			local explosion = storage.flintlock:Clone()
			mod_delay.new(scope, explosion)
			services.Debris:AddItem(explosion, 3)
			local parent = storage.ignored
			explosion.Position = position
			explosion.Parent = parent
			local attachment = explosion:FindFirstChild("Attachment")
			if not attachment then
				return
			end
			for _, emitter in attachment:GetChildren() do
				if emitter:IsA("ParticleEmitter") then
					emitter:Emit(10)
				end
			end
		end,
		boost = function(scope, character, tool, fromPosition, toPosition, raycastParams)
			if scope:isDestroyed() then
				return
			end
			local workspace = services.Workspace
			local humanoid = character:FindFirstChildOfClass("Humanoid")
			local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
			local script = tool:FindFirstChild("Script")
			local canReload
			if script then
				canReload = script:FindFirstChild("CAN_RELOAD")
			else
				canReload = script
			end
			if not humanoid or not humanoidRootPart then
				return
			end
			if not humanoidRootPart:IsA("BasePart") then
				return
			end
			if not canReload then
				return
			end
			if not canReload:IsA("BoolValue") then
				return
			end
			local direction = toPosition - fromPosition
			if direction.Magnitude < 1e-6 then
				return
			end
			local hit = workspace:Raycast(fromPosition, direction.Unit * 200, raycastParams)
			local endPosition = fromPosition + direction.Unit * 200
			if hit then
				endPosition = hit.Position
			end
			local push = endPosition - humanoidRootPart.Position
			local currentCamera = workspace.CurrentCamera
			if currentCamera and services.UserInputService.MouseBehavior == Enum.MouseBehavior.LockCenter then
				local rightVector = currentCamera.CFrame.RightVector
				push = push - rightVector * push:Dot(rightVector)
			end
			if push.Magnitude < 1e-6 then
				return
			end
			local pushDirection = -push.Unit
			return pushDirection.X, nil, "width"
		end,
	}
end
modules.unnamed_dC = function()
	modules.unnamed_dx()
	modules.scope()
	local mod_delay = modules.unnamed_dz()
	local services = modules.services()
	local excludedLimbs = {}
	excludedLimbs.Head = true
	excludedLimbs.RightHand = true
	excludedLimbs.LeftHand = true
	excludedLimbs.LeftFoot = true
	excludedLimbs.RightFoot = true
	local function setMotorsEnabled(root, enabled)
		for _, joint in root:GetDescendants() do
			if not joint:IsA("Motor6D") then
				continue
			end
			local parent = joint.Parent
			if parent then
				local parent2 = parent.Parent
				if parent2 and not excludedLimbs[parent.Name] and joint.Name ~= "Handle.R" and not (string.find(joint.Name, "Wing", 1, true) or not parent2:FindFirstChildOfClass("Humanoid")) then
					joint.Enabled = enabled
				end
			end
		end
	end
	local function playTween(effectScope, instance, tweenInfo, goal)
		local tween = services.TweenService:Create(instance, tweenInfo, goal)
		effectScope:add(tween)
		tween:Play()
	end
	return {
		knock = function(character)
			setMotorsEnabled(character, false)
		end,
		restore = function(character)
			setMotorsEnabled(character, true)
		end,
		impact = function(scope, storage, parent, position, isDeflect)
			if scope:isDestroyed() then
				return
			end
			local effect = storage.hit
			if isDeflect then
				effect = storage.deflect
			end
			local sound = effect:Clone()
			mod_delay.new(scope, sound)
			services.Debris:AddItem(sound, 3)
			sound.Parent = parent
			sound:Play()
			if isDeflect then
				return
			end
			local bloodParticle = storage.blood:Clone()
			mod_delay.new(scope, bloodParticle)
			services.Debris:AddItem(bloodParticle, 1)
			local ignored = storage.ignored
			bloodParticle.Position = position
			bloodParticle.Parent = ignored
			local blood = bloodParticle:FindFirstChild("Blood")
			if not blood then
				return
			end
			for _, emitter in blood:GetChildren() do
				if emitter:IsA("ParticleEmitter") then
					emitter:Emit(10)
				end
			end
		end,
		diedFirst = function(scope, character)
			local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
			local indicatorTemplate = services.ReplicatedStorage:FindFirstChild("DiedFirstIndicator")
			if scope:isDestroyed() then
				return
			end
			if not humanoidRootPart then
				return
			end
			if not humanoidRootPart:IsA("BasePart") then
				return
			end
			if not indicatorTemplate then
				return
			end
			if not indicatorTemplate:IsA("BillboardGui") then
				return
			end
			local attachment = Instance.new("Attachment")
			local tracked = mod_delay.new(scope, attachment)
			attachment.Parent = services.Workspace.Terrain
			attachment.WorldPosition = humanoidRootPart.Position
			services.Debris:AddItem(attachment, 2.5)
			local indicator = indicatorTemplate:Clone()
			indicator.Adornee = attachment
			indicator.Parent = attachment
			local container = indicator:FindFirstChild("Container")
			local accentFrame, label, stroke, uiScale
			if container then
				accentFrame = container:FindFirstChild("Accent")
				label = container:FindFirstChild("Label")
				stroke = container:FindFirstChild("UIStroke")
				uiScale = container:FindFirstChild("UIScale")
			else
				accentFrame = container
				label = container
				stroke = container
				uiScale = container
			end
			if container and container:IsA("Frame") and accentFrame and accentFrame:IsA("Frame") and label and label:IsA("TextLabel") then
				if stroke then
					if not stroke:IsA("UIStroke") then
						tracked:destroy()
						return
