			if math.abs(modifier) ~= math.huge then
				return math.clamp(modifier, 0, 100) / 100
			end
		end
		return 1
	end
	return {
		spread = function(weaponKey)
			return readModifier("Spread Modifier", weaponKey)
		end,
		delay = function(weaponKey)
			return readModifier("Delay Modifier", weaponKey)
		end,
		recoil = function(weaponKey)
			return readModifier("Recoil Modifier", weaponKey)
		end,
	}
end
modules.new = function()
	local shotPattern = modules.shotPattern()
