	modules.unnamed_dN()
	local urbanRules = modules.urbanRules()
	local function readNumberValue(parent, name)
		if parent then
			local numberStat = parent:FindFirstChild(name)
			if numberStat and (numberStat:IsA("NumberValue") or numberStat:IsA("IntValue")) then
				local number = numberStat.Value
				if not (number ~= number or not (math.abs(number) < math.huge)) then
					return number
