				owner.emptySound(isNotifying)
				owner.remote:FireServer("GunEmpty")
				schedule(0.5, function()
					isNotifying = false
				end)
			end
			local function markReloading(boolValue, duration)
				if duration <= 0 then
					return
				end
				boolValue.Value = true
				local function resetReloading()
					ownerScope:forget(resetReloading)
					if boolValue.Parent and boolValue.Value then
						boolValue.Value = false
					end
				end
				ownerScope:add(resetReloading)
				schedule(duration, resetReloading)
			end
			return {
				fire = function(tool)
					local character = player.Character
					local weaponStats = mod_get.get(tool.Name)
					if ownerScope:isDestroyed() or not character or not weaponStats then
						return false
					end
					if tool.Parent ~= character then
						return false
					end
					if not owner.owns(tool) then
						return false
					end
					if not (tool.Name ~= "[Flintlock]" or not urbanRules.inBox(character)) then
						return false
					end
					local bodyEffects = character:FindFirstChild("BodyEffects")
					local upperTorso = character:FindFirstChild("UpperTorso")
					local movement = character:FindFirstChild("Movement")
					local ammoValue = tool:FindFirstChild("Script")
					if ammoValue then
						ammoValue = ammoValue:FindFirstChild("Ammo")
					end
					local ammoClient = readNumberValue(ammoValue, "CLIENT")
					local reloadingValue
					if bodyEffects then
						reloadingValue = bodyEffects:FindFirstChild("Reloading_CLIENT")
						bodyEffects = bodyEffects:FindFirstChild("Attacking_CLIENT")
					else
						reloadingValue = bodyEffects
					end
					if not (upperTorso and upperTorso:IsA("BasePart") and movement and ammoClient and reloadingValue and reloadingValue:IsA("BoolValue") and not reloadingValue.Value) then
						return false
					end
					if not bodyEffects then
						return false
					end
					if not bodyEffects:IsA("BoolValue") then
						return false
