					end
					if not urbanRules.canInteract(character) then
						return false
					end
					local camera = world.CurrentCamera
					local players = camera:FindFirstChild("Players")
					local ignored = camera:FindFirstChild("Ignored")
					local muzzle = shotPattern.muzzle(tool)
					local aimPoint = owner.rawAim()
					if not (camera and players and ignored) then
						return false
