						return false
					end
					if not aimPoint then
						return false
					end
					if not shotPattern.finite(aimPoint) then
						return false
					end
					local resolvedAim = owner.resolve(muzzle)
					if resolvedAim and shotPattern.finite(resolvedAim) then
