						if not rayResult then
							continue
						end
						local hitModel = shotPattern.hitModel(rayResult.Instance)
						if not hitModel then
							continue
						end
						table.insert(hits, { PELLET = pelletIndex, MODEL = hitModel, PART = rayResult.Instance, POSITION = endPoint })
						local targetEffects = hitModel:FindFirstChild("BodyEffects")
						local hasDeflect = targetEffects ~= nil and targetEffects:FindFirstChild("BULLET_DEFLECT") ~= nil
						owner.impact(rayResult, tracer, muzzle, hasDeflect)
						if not (hasDeflect or not readNumberValue(targetEffects, "Health_CLIENT") or not urbanRules.canDamageTarget(tool, hitModel)) then
							owner.predict(shotIndex, hitModel, weaponStats.damage)
						end
					end
					if tool.Name == "[Flintlock]" then
						owner.flintlock(character, tool, muzzle, aimPoint, rayParams)
					end
					owner.flash(tool)
					local shotReport = { ORIGIN = muzzle, AIM = aimPoint, INDEX = shotIndex, HITS = hits }
					owner.remote:FireServer("Shoot", shotReport)
					local gunFired = owner.gunFired
					if gunFired then
						gunFired(tool)
					else
						owner.binded:Fire("GunFired")
					end
					schedule(1.5, function()
						owner.settle(shotIndex)
					end)
					return true
				end,
			}
		end,
	}
end
modules.shotPattern = function()
	local offsets = {}
	local zeroOffset = Vector2.new(0, 0)
	local rightOffset = Vector2.new(1.5, 0)
	local leftOffset = Vector2.new(-1.5, 0)
	local upOffset = Vector2.new(0, 3)
	local makeVector = Vector2.new
	local initialX = 0
	local pattern
	local isFiniteVector
	repeat
		local packed = table.pack(makeVector(initialX, -3))
		offsets[1] = zeroOffset
		offsets[2] = rightOffset
		offsets[3] = leftOffset
		offsets[4] = upOffset
		table.move(packed, 1, packed.n, 5, offsets)
		makeVector = math.rad(8)
		pattern = {}
		pattern.range = 200
		local isFiniteNumber = function(number)
			return number == number and math.abs(number) < math.huge
		end
		isFiniteVector = function(vector)
			return isFiniteNumber(vector.X) and isFiniteNumber(vector.Y) and isFiniteNumber(vector.Z)
		end
	until makeVector
	pattern.finite = isFiniteVector
	pattern.pellets = function(origin, aim, isShotgun, directions, spreadScale)
		table.clear(directions)
		if isShotgun then
			if not spreadScale then
				spreadScale = 1
			end
			if spreadScale == 0 then
				local unit = (aim - origin).Unit
				for index = 1, #directions do
					directions[index] = unit
				end
			else
				local cframe = CFrame.new(origin, aim)
				local cosine = math.cos(aim)
				local sine = math.sin(aim)
				for index, offset in directions do
					local yaw = math.rad((offset.X * cosine - offset.Y * sine) * spreadScale)
					local pitch = math.rad((offset.X * sine + offset.Y * cosine) * spreadScale)
					directions[index] = (cframe.LookVector + cframe.RightVector * math.tan(yaw) + cframe.UpVector * math.tan(pitch)).Unit
				end
			end
		else
			directions[1] = (aim - origin).Unit
		end
	end
	pattern.muzzle = function(tool)
		local handle = tool:FindFirstChild("Handle")
		if handle then
			if not handle:IsA("BasePart") then
				return nil
			end
			local origin = handle.Position
			local muzzleOffset = handle:GetAttribute("Muzzle")
			if typeof(muzzleOffset) == "CFrame" then
				origin = handle.CFrame * muzzleOffset.Position
			end
			if pattern.finite(origin) then
				return origin
			end
		end
		return nil
	end
	pattern.hitModel = function(instance)
		local maxDepth = 5 + 0
		if 1 <= maxDepth then
			local depth = 1
			while instance do
				if instance:IsA("Model") and instance:FindFirstChildOfClass("Humanoid") then
					return instance
				end
				instance = instance.Parent
				local nextDepth = depth + 1
				if not (nextDepth <= maxDepth) then
					return nil
				end
				depth = nextDepth
			end
		end
		return nil
	end
	return pattern
end
