modules.new = function()
	modules.scope()
	local services = modules.services()
	local urbanRules = modules.urbanRules()
	local function trySetParent(instance, parent)
		return pcall(function()
			instance.Parent = parent
		end)
	end
	local function canEquip(character, humanoid)
		local inventoryGui = services.Players.LocalPlayer:FindFirstChildOfClass("PlayerGui")
		if inventoryGui then
			inventoryGui = inventoryGui:FindFirstChild("Inventory")
		end
		local isAlive = humanoid.Health > 0
		if humanoid.Health > 0 then
			isAlive = urbanRules.canInteract(character)
			if isAlive then
				if inventoryGui then
					local isScreenGui = inventoryGui:IsA("ScreenGui")
					if isScreenGui then
						inventoryGui = not inventoryGui.Enabled
					else
						inventoryGui = isScreenGui
					end
				end
				return not inventoryGui
			end
		end
		return isAlive
	end
	return {
		new = function(scope, inputScope, inputCallback)
			local localPlayer = services.Players.LocalPlayer
			local currentPlan = nil
			local heartbeatConnection = nil
			local positions = {}
			local function clearHeartbeat()
				if not heartbeatConnection then
					return
				end
				heartbeatConnection:forget(heartbeatConnection)
				heartbeatConnection:Disconnect()
				heartbeatConnection = nil
			end
			local function releasePosition(instance)
				local written = positions[instance]
				if written then
					positions[instance] = nil
					if instance:GetAttribute("position") == written.written then
						pcall(function()
							instance:SetAttribute("position", written.original)
						end)
					end
					if written.destroying then
						heartbeatConnection:forget(written.destroying)
						written.destroying:Disconnect()
					end
				end
			end
			local function restoreAll()
				for instance in positions do
					releasePosition(instance)
				end
			end
			local function commit(shouldRestore)
				local plan = currentPlan
				if not plan then
					return
				end
				clearHeartbeat()
				local backpack = localPlayer:FindFirstChildOfClass("Backpack")
				local destination = localPlayer
				if backpack then
					destination = backpack
				end
				for _, tool in plan.tools do
					if tool.Parent ~= plan.holder then
						continue
					end
					if not trySetParent(tool, destination) then
						trySetParent(tool, localPlayer)
					end
					if not (tool.Parent ~= localPlayer or not inputCallback) then
						inputCallback(tool)
					end
				end
				currentPlan = nil
				plan.holder:Destroy()
				local equipped = plan.equipped
				if equipped and localPlayer.Character == plan.character and not (equipped.Parent ~= backpack or not equipped.Enabled or plan.humanoid.Parent ~= plan.character) and not (plan.character:FindFirstChildOfClass("Tool") or not canEquip(plan.character, plan.humanoid)) then
					plan.humanoid:EquipTool(equipped)
				end
				clearHeartbeat(shouldRestore)
			end
			local function writePosition(instance, index)
				local written = positions[instance]
				if not written then
					local record = {}
					record.original = instance:GetAttribute("position")
					record.written = index
					record.destroying = nil
					positions[instance] = record
					record.destroying = heartbeatConnection:add(instance.Destroying:Connect(function()
						positions[instance] = nil
						if not record.destroying then
							return
						end
						heartbeatConnection:forget(record.destroying)
						record.destroying:Disconnect()
					end))
					written = record
					written.written = index
					instance:SetAttribute("position", index)
					return
				end
				if instance:GetAttribute("position") ~= written.written then
					written.original = instance:GetAttribute("position")
				end
				written.written = index
				instance:SetAttribute("position", index)
			end
			local function onHeartbeat()
				local plan = currentPlan
				if not plan then
					return
				end
				if heartbeatConnection:isDestroyed() then
					commit(false)
				elseif localPlayer.Character ~= plan.character then
					commit(false)
				elseif localPlayer:FindFirstChildOfClass("Backpack") ~= plan.backpack then
					commit(false)
				elseif canEquip(plan.character, plan.humanoid) then
					if plan.character:FindFirstChildOfClass("Tool") ~= nil then
						commit(false)
					else
						plan.phase = plan.phase + 1
						if plan.phase < 2 then
							return
						end
						if plan.phase == 2 then
							for slot, tool in plan.tools do
								local index = slot
								if tool.Parent ~= plan.holder then
									continue
								end
								local fallbackIndex = -1
								if not (index <= 9) then
