						else
							commit(true)
						end
					end
				else
					commit(false)
				end
			end
			local function cancel()
				commit(false)
			end
			scope:add(function()
				cancel()
				restoreAll()
			end)
			return {
				isBusy = function()
					return currentPlan ~= nil
				end,
				begin = function(character, backpack, tools, equipped)
					local humanoid = character:FindFirstChildOfClass("Humanoid")
					if currentPlan then
						return false
					end
					if heartbeatConnection:isDestroyed() then
						return false
					end
					if #tools < 2 then
						return false
					end
					if not humanoid then
						return false
					end
					if localPlayer.Character ~= character then
						return false
					end
					if localPlayer:FindFirstChildOfClass("Backpack") ~= backpack then
						return false
					end
					if not canEquip(character, humanoid) then
						return false
					end
					local folder = Instance.new("Folder")
					currentPlan = {
						character = character,
						backpack = backpack,
						humanoid = humanoid,
						tools = tools,
						equipped = equipped,
						holder = folder,
						phase = 0,
					}
					humanoid:UnequipTools()
					for _, tool in tools do
						if tool.Parent == backpack then
							trySetParent(tool, folder)
						elseif tool.Parent == character then
							trySetParent(tool, folder)
						end
					end
					heartbeatConnection = scope:add(services.RunService.Heartbeat:Connect(onHeartbeat))
					return true
				end,
				cancel = cancel,
				restore = restoreAll,
				release = releasePosition,
			}
		end,
	}
end
modules.inventoryPlan = function()
	local settings = modules.settings()
	local function normalizeName(name)
		if name ~= "[Double-Barrel SG]" then
			return name
		end
		return "[DoubleBarrel]"
	end
	return {
		read = function()
			if not settings.bool(false, "Utilities", "Inventory Sorter", "Enabled") then
				return nil, nil
			end
			local configured = settings.table("Utilities", "Inventory Sorter", "Settings")
			local configuredType = type(configured)
			if configuredType ~= "table" then
				return nil, nil
			end
			local plan = {}
			local iterator = configuredType ~= "0"
			if configuredType ~= "0" then
				iterator = ipairs
				configured = configured
			end
			for _, entry in iterator(configured) do
				if not (type(entry) ~= "string" or entry == "") then
					table.insert(plan, normalizeName(entry))
				end
			end
			if #plan == 0 then
				return nil, nil
			end
			return plan, table.concat(plan, "\000")
		end,
		plan = function(tools, planText)
			local selected = {}
			local ordered = table.create(#tools)
			local iterator = coroutine.wrap(lph_generic_for)
			iterator(planText, nil, nil)
			local unused
			local garbage = { [5] = nil, [6] = unused, [7] = nil, [8] = nil, [9] = nil }
			local nextEntry = iterator
			while true do
				local active, key, name = nextEntry()
				if not active then
					break
				end
				for _, tool in tools do
					if not (selected[tool] or tool.Name ~= normalizeName(name)) then
						selected[tool] = true
						table.insert(ordered, tool)
						break
					end
				end
				garbage = garbage
				unused = unused
				nextEntry = nextEntry
			end
			local first = garbage[5]
			local third = garbage[7]
			local second = garbage[6]
			local fifth = garbage[9]
			local fourth = garbage[8]
			for _, tool in tools do
				if not selected[tool] then
					table.insert(ordered, tool)
				end
			end
			return ordered
		end,
	}
