	local settings = modules.settings()
	return {
		get = function(toolName)
			if settings.bool(false, "Weapon", "Skin Modifier", "Enabled") then
				local toolKey = mod_find.key(toolName)
				if not toolKey then
					return nil
				end
				local hoodCustoms = settings.get("Weapon", "Skin Modifier", "Hood Customs")
				local selectedSkin = hoodCustoms.get("Weapon", "Skin Modifier", "Settings")
				if not (type(hoodCustoms) ~= "table" or hoodCustoms.Settings == nil) then
					selectedSkin = hoodCustoms.Settings
				end
				if type(selectedSkin) ~= "table" then
					return nil
				end
				local chosen = selectedSkin[toolKey]
				if not (chosen ~= nil or toolKey ~= "[DoubleBarrel]") then
					chosen = selectedSkin["[Double-Barrel SG]"]
				end
				if type(chosen) ~= "string" then
					return nil
				end
				local trimmed = string.match(chosen, "^%s*(.-)%s*$") or ""
				local lowered = string.lower(trimmed)
				if lowered == "" then
					return nil
				end
				if lowered == "none" then
					return nil
				end
				if lowered ~= "default" then
					return trimmed
				end
			end
			return nil
		end,
	}
end
modules.unnamed_d5 = function()
