modules.unnamed_d4 = function()
	local mount = {}
	mount.NAME = "__AtomicHoodSkin"
	local function isDescendant(root, instance)
		return instance ~= nil and instance:IsDescendantOf(root)
	end
	local function prepareModel(tool, clone, target)
		local handle = clone:FindFirstChild("Handle")
		if not handle then
			clone:Destroy()
			return nil
		end
		if not handle:IsA("BasePart") then
			clone:Destroy()
			return nil
		end
		local parts = {}
		local adjacency = {}
		local joints = {}
		for _, part in clone:GetDescendants() do
			if part:IsDescendantOf(clone) then
				if part:IsA("LuaSourceContainer") or part:IsA("Sound") then
					if part:IsA("Sound") then
						part.PlayOnRemove = false
					end
					part:Destroy()
				elseif part:IsA("Constraint") then
					part:Destroy()
				elseif part:IsA("BodyMover") then
					part:Destroy()
				elseif part:IsA("Explosion") then
					part:Destroy()
				elseif part:IsA("BasePart") then
					table.insert(parts, part)
					adjacency[part] = {}
				end
			end
			if not true then
				break
			end
		end
		for _, joint in clone:GetDescendants() do
			if joint:IsA("JointInstance") or joint:IsA("WeldConstraint") then
				local part0 = joint.Part0
				local part1 = joint.Part1
				if isDescendant(clone, part0) then
					if isDescendant(clone, part1) then
						if part0 and part1 and adjacency[part0] and adjacency[part1] then
							table.insert(joints, joint)
							table.insert(adjacency[part0], part1)
							table.insert(adjacency[part1], part0)
						end
					else
						joint:Destroy()
					end
				else
					joint:Destroy()
				end
			elseif not (joint:IsA("Beam") or joint:IsA("Trail")) then
				continue
			else
				local attachment0 = joint.Attachment0
				local attachment1 = joint.Attachment1
				if attachment0 and not attachment0:IsDescendantOf(clone) then
					joint:Destroy()
				elseif attachment1 and not attachment1:IsDescendantOf(clone) then
					joint:Destroy()
				end
			end
		end
		local offset = target.CFrame * handle.CFrame:Inverse()
		for _, part in parts do
			part.Anchored = false
			part.CanCollide = false
			part.CanQuery = false
			part.CanTouch = false
			part.Massless = true
			part.CFrame = offset * part.CFrame
		end
		local visited = {}
		local function floodFill(part)
			local queue = {}
			queue[1] = part
			visited[part] = true
			while 0 < #queue do
				for _, neighbor in adjacency[table.remove(queue)] do
					if not visited[neighbor] then
						visited[neighbor] = true
						table.insert(queue, neighbor)
					end
				end
			end
		end
		floodFill(handle)
		for _, part in parts do
			if visited[part] then
				continue
			end
			local weld = Instance.new("WeldConstraint")
			weld.Part0 = handle
			weld.Part1 = part
			weld.Parent = handle
			table.insert(joints, weld)
			floodFill(part)
		end
		Instance.new("Weld").Name = "__AtomicHoodSkinJoint"
	end
	mount.create = function(tool, model, handle, target)
		if target.Parent == tool then
			if target.Name ~= "Handle" then
				return nil
			end
			local ok, clone = pcall(function()
				return model:Clone()
			end)
			if not ok then
				return nil
			end
			if not clone then
				return nil
			end
			local prepared, mounted = pcall(model, tool, clone, target)
			if not prepared then
				clone:Destroy()
				return nil
			end
			if mounted then
				return mounted
			end
			clone:Destroy()
		end
		return nil
	end
	return mount
end
modules.new = function()
	local scope = modules.scope()
	local mod_data = modules.unnamed_dj()
	local services = modules.services()
	local urbanRules = modules.urbanRules()
	local function shouldObserve(object)
		if object.Name ~= "[Shotgun]" then
			local silencer = object.Name == "[Silencer]"
			if not (object.Name == "[Silencer]") then
				return silencer
			end
		end
		return mod_data.get(object) == nil
	end
	local function styleOrDefault(style)
		if style then
			return style
		end
		return "None"
	end
	return {
		new = function(scopeModule, unusedConfig)
			local localPlayer = services.Players.LocalPlayer
			local userInputService = services.UserInputService
			local activeTools = {}
			local records = {}
			local pending = {}
			local touches = {}
			local triggers = {}
			local touchCount = 0
			local heartbeatAccum = 0
			local generation = 0
			local focused = true
			local stopped = false
			local scheduled = nil
			local equipping = nil
			local scheduleApply = nil
			local function isActive(tool)
				local isStopped = stopped
				local active = not isStopped
				if not isStopped then
					local destroyed = scopeModule:isDestroyed()
					active = not destroyed
					if not destroyed then
						return activeTools[tool.tool] == tool
					end
				end
				return active
			end
			local function release(tool)
				local stop = activeTools[tool]
				records[tool] = nil
				activeTools[tool] = nil
				pending[tool] = nil
				if stop then
					stop.stop()
				end
			end
			local function observe(tool)
				if stopped then
					return
				end
				if scopeModule:isDestroyed() then
					return
				end
				if shouldObserve(tool) then
					if activeTools[tool] then
						return
					end
					local toolScope = scopeModule.new()
					local entry = {}
					entry.tool = tool
					entry.stop = function()
						toolScope:destroy()
					end
					entry.held = false
					entry.unknownTouch = userInputService.TouchEnabled
					activeTools[tool] = entry
					toolScope:add(tool.Activated:Connect(function()
						if isActive(entry) then
							entry.held = true
						end
					end))
					toolScope:add(tool.Deactivated:Connect(function()
						if not isActive(entry) then
							return
						end
						entry.held = false
						entry.unknownTouch = false
						scheduleApply()
					end))
					toolScope:add(tool.Equipped:Connect(function()
						local record = records[tool]
						if isActive(entry) and record and tool.Parent == localPlayer.Character and record.style == styleOrDefault(tool:GetAttribute("SKIN")) then
							records[tool] = nil
						end
					end))
					toolScope:add(tool.AncestryChanged:Connect(function()
						if not isActive(entry) then
							return
						end
						if tool.Parent == localPlayer.Character then
							return
						end
						records[tool] = nil
						pending[tool] = nil
						entry.held = false
					end))
					toolScope:add(tool.Destroying:Connect(function()
						if activeTools[tool] ~= entry then
							return
						end
						release(tool)
					end))
				else
					release(tool)
				end
			end
			local function isOnlyTool(character, tool)
				if character:FindFirstChildOfClass("Tool") ~= tool then
					return false
				end
				for _, child in character:GetChildren() do
					if child:IsA("Tool") and child ~= tool then
						return false
					end
				end
				return true
			end
			local function matchesRecord(record)
				local object = record.record.tool
				local matched = shouldObserve(object)
				if matched then
					matched = object.Name == record.name
					if object.Name == record.name then
						matched = localPlayer.Character == record.character
						if localPlayer.Character == record.character then
							local findFirstChildOfClass = localPlayer.FindFirstChildOfClass
						end
					end
				end
				return matched
			end
			local function recordMatches(record)
				return isActive(record.record) and matchesRecord(record) and styleOrDefault(record.record.tool:GetAttribute("SKIN")) == record.style
			end
			local function canApply(entry, character, humanoid)
				local allowed = focused
				if focused then
					local held = entry.held
					allowed = not held
					if not held then
						local touchFlag = entry.unknownTouch
						allowed = not touchFlag
						if not touchFlag then
							allowed = touchCount == 0
							if touchCount == 0 then
								allowed = next(triggers) == nil
								if allowed then
									local pressed1 = userInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
									allowed = not pressed1
									if not pressed1 then
										local pressed2 = userInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
										allowed = not pressed2
										if not pressed2 then
											allowed = entry.tool.Enabled
											if allowed then
												allowed = humanoid.Health > 0
												if humanoid.Health > 0 then
													local sit = humanoid.Sit
													allowed = not sit
													if not sit then
														local platformStand = humanoid.PlatformStand
														allowed = not platformStand
														if not platformStand then
															return (urbanRules.canInteract(character))
														end
													end
												end
											end
										end
									end
								end
							end
						end
					end
				end
				return allowed
			end
			local function canApplyTool(tool)
				if not stopped then
					if scopeModule:isDestroyed() then
						return false
					end
					if not shouldObserve(tool) then
						return true
					end
					if tool.Parent ~= localPlayer.Character then
						return true
					end
					observe(tool)
					local entry = activeTools[tool]
					local character = localPlayer.Character
					local humanoid
