							object.Parent = record.backpack
						end) and matchesRecord(record) and object.Parent == record.backpack and record.character:FindFirstChildOfClass("Tool") == nil and record.client.Value == originalValue and canApply(record.record, record.character, record.humanoid) then
							if not stopped and not scopeModule:isDestroyed() then
								if originalValue ~= generation then
									equipping = nil
									if stopped then
										table.clear(touches)
										table.clear(triggers)
									end
									return
								end
								if not recordMatches(record) then
									equipping = nil
									if stopped then
										table.clear(touches)
										table.clear(triggers)
									end
									return
								end
							end
							pcall(function()
								record.humanoid:EquipTool(object)
							end)
						end
						equipping = nil
						if not stopped then
							return
						end
						table.clear(touches)
						table.clear(triggers)
					else
						records[object] = nil
					end
				else
					records[object] = nil
				end
			end
			local function processPending(currentGeneration)
				if scheduled == coroutine.running() then
					scheduled = nil
				end
				if stopped then
					return
				end
				if scopeModule:isDestroyed() then
					return
				end
				if currentGeneration ~= generation then
					return
				end
				for _, record in records do
					applyRecord(record, currentGeneration)
				end
				local changed = false
				for tool in pending do
					if shouldObserve(tool) then
