					end
				end
				if changed and touches and not stopped and not (scopeModule:isDestroyed() or currentGeneration ~= generation) then
					touches()
				end
			end
			scheduleApply = function()
				if not stopped and not (scopeModule:isDestroyed() or scheduled) then
					if not (next(records) ~= nil or next(pending) ~= nil) then
						return
					end
					scheduled = task.defer(processPending, generation)
				end
			end
			scopeModule:add(function()
				stopped = true
				generation = generation + 1
				scheduled = nil
				table.clear(records)
				table.clear(pending)
				for tool in activeTools do
					release(tool)
				end
				if not equipping then
					table.clear(touches)
					table.clear(triggers)
				end
			end)
			scopeModule:add(localPlayer.CharacterRemoving:Connect(function()
				if stopped then
