								record.character = character
								record.backpack = backpack
								record.humanoid = humanoid
								record.handle = handle
								record.data = gunData
								record.scriptObject = scriptObject
								record.ammo = ammo
								record.client = client
								record.original = originalStyle
								record.style = styleOrDefault(recordMap)
								recordMap[tool] = record
								if not currentGeneration then
									scheduleApply()
									return
								end
								applyRecord(record, currentGeneration)
							else
								recordMap[tool] = nil
							end
							return
						end
					else
						ammo = scriptObject
					end
					local client2 = ammo
					if entry and character and tool.Parent == character and isOnlyTool(character, tool) and backpack and humanoid and handle and handle:IsA("BasePart") and gunData then
						if gunData:IsA("ModuleScript") then
							if scriptObject then
								if scriptObject:IsA("Script") then
									if ammo then
										if ammo:IsA("NumberValue") or ammo:IsA("IntValue") then
											if client2 then
												if client2:IsA("NumberValue") or client2:IsA("IntValue") then
													local existing = recordMap[tool]
													local originals
													if existing then
														originals = { existing.original }
													else
														originals = { styleOrDefault(activeMap) }
													end
													local originalStyle = originals[1]
													if styleOrDefault(recordMap) == originalStyle then
														record = recordMap
														if record then
															record[tool] = nil
															return
														end
													else
														record = {}
													end
													record.record = entry
													record.name = tool.Name
													record.character = character
													record.backpack = backpack
													record.humanoid = humanoid
													record.handle = handle
													record.data = gunData
													record.scriptObject = scriptObject
													record.ammo = ammo
													record.client = client2
													record.original = originalStyle
													record.style = styleOrDefault(recordMap)
													recordMap[tool] = record
													if currentGeneration then
														applyRecord(record, currentGeneration)
													else
														scheduleApply()
													end
												else
													recordMap[tool] = nil
												end
											else
												recordMap[tool] = nil
											end
										else
											recordMap[tool] = nil
										end
									else
										recordMap[tool] = nil
									end
								else
									recordMap[tool] = nil
								end
							else
								recordMap[tool] = nil
							end
						else
							recordMap[tool] = nil
						end
					else
						recordMap[tool] = nil
					end
				end,
				release = release,
			}
		end,
	}
end
modules.hoodCopy_ea = function()
	local aimAssist = modules.aimAssist()
	local mod_current = modules.unnamed_aq()
	local display = modules.display()
	local esp = modules.esp()
	local featureRunner = modules.featureRunner()
	local hoodCopy = modules.hoodCopy()
	local gunEmulation = modules.gunEmulation()
	local hitboxExpander_bi = modules.hitboxExpander_bi()
	local inventorySorter = modules.inventorySorter()
	local macro = modules.macro()
	local movement = modules.movement()
	local safety = modules.safety()
	local silentAim = modules.silentAim()
	local targeting_aO = modules.targeting_aO()
	local triggerBot_bC = modules.triggerBot_bC()
	modules.unnamed_o()
	local features = {}
	features[1] = targeting_aO
	features[2] = gunEmulation
	features[3] = silentAim
	features[4] = aimAssist
	features[5] = triggerBot_bC
	features[6] = hitboxExpander_bi
	features[7] = movement
	features[8] = macro
	features[9] = inventorySorter
	features[10] = safety
	features[11] = esp
	features[12] = display
	return {
		name = "Hood Copy",
		start = function(scope)
			mod_current.set(hoodCopy)
			scope:add(function()
				mod_current.set(nil)
			end)
			featureRunner.start(scope, features)
		end,
	}
end
modules.hoodCopy = function()
	local daHoodState = modules.daHoodState()
	local daHoodGuns = modules.daHoodGuns()
	local mod_current = modules.unnamed_aq()
	local beamColor = Color3.new(1, 0.545098, 0.14902)
	local config = table.clone(daHoodGuns)
	config.name = "Hood Copy"
	config.isCompensated = false
	config.beamColor = beamColor
	config.checksClientAmmo = true
	config.emulatesFlintlock = false
	config.localClock = mod_current.serverClock
	config.canShoot = daHoodState.checkClassic
	config.rollSpread = nil
	config.wallShot = nil
	config.start = nil
	return config
end




local function start()
	local runtime = modules.scope().new()
	local gameId, gameName = modules.gameDetect().resolve()
	if not gameId then
		gameId, gameName = modules.gameDetect().resolveWait(10)
	end
	modules.boot().start(runtime, gameName or "Unknown")
	local animations = modules.daHoodAnimations()
	local launchers = {
		UrbanReload = function() return modules.urbanReload() end,
		DaHood      = function() return modules.daHood() end,
		DasHood     = function() return modules.dasHood_bU() end,
		DesHood     = function() return modules.desHood_b9() end,
		ZeeHood     = function() return modules.zeeHood_cJ() end,
		DerHood     = function() return modules.derHood() end,
		HoodCustoms = function() return modules.hoodCustoms() end,
		HoodCopy    = function() return modules.hoodCopy_ea() end,
		DaUphill    = function() return animations.DaUphill end,
		DaStrike    = function() return animations.DaStrike end,
		DaDownhill  = function() return animations.DaDownhill end,
	}
	local launch = launchers[gameId]
	if launch then
		local feature = launch()
		if feature and type(feature.start) == "function" then
			feature.start(runtime:child())
		end
	end
	return runtime
end
return start()